ClinicalChunks.register("data/templates-046.js",[{"id":"templates-d1e3522ef00ad133629c","key":"v1-c9ccc21dfe2a3058|templates-d1e3522ef00ad133629c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高尔夫球肘","category":"门诊病历模板","raw":{"name":"高尔夫球肘","category":"门诊病历模板","case":{"case_name":"门诊病历891","templates":{"主诉":"反复肘内侧疼痛1周","现病史":"患者1周前无明显诱因出现高尔夫球肘相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复肘内侧疼痛1周，为排除局部感染、贫血及凝血异常，完善血常规检查；完善尿常规、便常规检查了解泌尿系统及消化道情况，排除隐匿性失血与肾脏损害；外用及口服非甾体药物需经肝肾代谢，完善肝肾功能、电解质检查评估用药安全性，完善血糖、血脂检查了解代谢状况；患者为前臂屈肌总腱起点慢性劳损所致，需完善肘关节X线片检查，了解肱骨内上髁有无骨质增生、钙化及骨性关节炎改变，排除骨性病变；为明确屈肌总腱有无增厚、撕裂，并鉴别尺神经卡压所致内侧疼痛，完善肘关节超声检查；必要时完善肘关节MRI检查明确肌腱及尺侧副韧带损伤程度；患者肘内侧疼痛可沿尺神经走行放射，如伴前臂尺侧及小指麻木，完善颈椎MRI检查明确有无颈椎间盘突出、椎管狭窄所致神经根受压；患者中老年，需评估心肺基础状况，完善心电图检查排除心肌缺血、心律失常所致牵涉痛，完善胸部X线片检查排除肺部感染、结核及肿瘤；完善腹部超声检查了解肝胆胰脾肾情况，排除内脏疾病所致牵涉痛；如保守治疗效果欠佳需行手术治疗，入院后完善凝血功能、感染筛查，复查心电图、胸部X线片等术前必查项目。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 高尔夫球肘\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 外用非甾体抗炎药：双氯芬酸二乙胺乳胶剂（扶他林）2g，涂于肘关节内侧肱骨内上髁压痛点，每日3-4次，疗程7-14天；症状较轻者首选。\n2. 口服非甾体抗炎药：塞来昔布胶囊0.2g qd，餐后口服，疗程5-7天（短期患者，注意胃肠道及心血管风险，消化性溃疡病史者慎用）。\n3. 局部封闭治疗（疼痛明显、上述治疗无效时）：醋酸曲安奈德注射液20mg+2%利多卡因注射液1ml，肱骨内上髁压痛点局部注射，每次1次，间隔2-4周可重复1次，同一部位注射不超过3次。\n【一般治疗及生活指导】\n1. 休息与制动：急性期暂停高尔夫、网球等挥杆运动及提重物、拧毛巾等反复屈腕旋前动作，必要时佩戴肱骨内上髁束带（护肘）以分散肌腱止点应力。\n2. 冷敷与理疗：疼痛明显时可局部冰敷15-20分钟/次，每日3-4次；可配合局部理疗（超声波、冲击波等）促进炎症吸收。\n3. 康复锻炼：疼痛缓解后逐步进行前臂屈肌群牵伸及腕屈肌离心训练，循序渐进，避免过早恢复患者度运动。\n4. 禁忌：避免长时间肘关节内侧受压（如伏案支撑），避免反复抓握、屈腕负重及突然发力动作，以防复发。\n【随诊要求】\n1. 用药后1-2周复诊，评估疼痛缓解程度及前臂屈腕功能恢复情况，调整治疗方案。\n2. 行局部封闭治疗者，2-4周后复诊评估疗效，必要时可重复注射1次（同一部位累计不超过3次）。\n3. 保守治疗6周以上症状无明显缓解，或出现肘关节活动受限、夜间痛加重者，应及时复诊，行肘关节X线或MRI检查排除其他病变，必要时转骨科评估手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1023,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2c2b150e30625bc18d9a209961618414aa40d47422575a5afbdc9d80fbb12204","pinyin":"gaoerfuqiuzhou","initials":"gefqz","setting":"out","caseName":"门诊病历891","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历891",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-40de07ffa7e81fbcdf23","key":"v1-c9ccc21dfe2a3058|templates-40de07ffa7e81fbcdf23","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腱鞘囊肿","category":"门诊病历模板","raw":{"name":"腱鞘囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历892","templates":{"主诉":"发现腕背肿块1周","现病史":"患者1周前无明显诱因出现腱鞘囊肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者发现腕背肿块1周，为排除局部感染、贫血及凝血异常，完善血常规检查；完善尿常规、便常规检查了解泌尿系统及消化道情况，排除隐匿性失血与肾脏损害；如考虑手术切除囊肿，麻醉及用药需经肝肾代谢，完善肝肾功能、电解质检查评估手术与用药安全性，完善血糖、血脂检查了解代谢状况及有无糖尿病所致结缔组织病变；肿块位于腕背，需与腱鞘巨细胞瘤、脂肪瘤、骨囊肿鉴别，完善腕关节超声检查，明确肿块大小、边界、内部回声及其与肌腱、腱鞘的关系；必要时完善腕关节MRI检查，进一步明确肿块性质与腕关节周围软组织情况；完善腕关节X线片检查了解腕骨骨质有无破坏、骨性突起，排除骨性病变；如肿块张力高、性质难以判断，完善腕关节穿刺抽液检查，明确囊液性质以鉴别腱鞘囊肿、腱鞘巨细胞瘤及感染性病变，必要时送细胞学检查排除肿瘤；患者需评估心肺基础状况，完善心电图检查排除心律失常、心肌缺血，完善胸部X线片检查排除肺部感染、结核及肿瘤；完善腹部超声检查了解肝胆胰脾肾情况，排除内脏疾病所致全身表现；如囊肿较大、反复发作或影响腕关节活动需手术切除，入院后完善凝血功能、感染筛查，复查心电图等术前必查项目。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 腱鞘囊肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部囊内注射（首选非手术疗法）：无菌操作下穿刺抽尽囊液后，向囊内注入醋酸曲安奈德注射液10～20mg（与2%盐酸利多卡因注射液1～2ml混合），每1～2周1次，一般1～3次为1疗程，总疗程不超过3个月，注射后局部加压包扎1～2天。\n2. 疼痛明显时口服非甾体抗炎药：塞来昔布胶囊0.2g qd，或布洛芬缓释胶囊0.3g bid，餐后服用，连用3～5天，症状缓解即停。\n3. 囊肿伴红、肿、热、痛等感染征象者：头孢呋辛酯片0.25g bid×5天（青霉素过敏者改用阿奇霉素片0.5g qd×5天），抗感染期间暂停囊内注射。\n【一般治疗及生活指导】\n1. 休息与活动：避免患处关节（腕、指、踝等）反复屈伸、扭转及过度负重，如减少长时间使用鼠标、拧毛巾、提重物等动作，以防囊肿增大及复发。\n2. 局部护理：避免反复按压、挤压或暴力撞击囊肿，防止囊壁破裂致囊液外渗引发局部无菌性炎症；保持局部皮肤清洁干燥。\n3. 饮食：正常均衡饮食即可，无需特殊忌口，可适当增加优质蛋白及富含维生素C的食物以促进组织修复。\n4. 禁忌：禁止自行用针挑破或用力挤破囊肿，亦不宜盲目热敷及暴力按摩；急性疼痛期减少患处活动。\n【随诊要求】\n1. 囊内注射治疗后2～4周复诊，评估囊肿消退情况；注射3次后囊肿无明显缩小或反复复发者，复诊评估手术切除指征。\n2. 囊肿短期内迅速增大、疼痛加重、关节活动受限，或患处出现红、肿、热、痛等感染征象时，随时就诊。\n3. 行手术切除者，按医嘱定期门诊复查伤口愈合及复发情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1024,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"13ea8e98e6a59a43557b6e93d0973b9acb066d24569cea76e95fe617f84971b8","pinyin":"jianqiaonangzhong","initials":"jqnz","setting":"out","caseName":"门诊病历892","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历892",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-46c78b7e6c6d81abca1c","key":"v1-c9ccc21dfe2a3058|templates-46c78b7e6c6d81abca1c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"滑膜炎","category":"门诊病历模板","raw":{"name":"滑膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历893","templates":{"主诉":"反复关节肿胀疼痛1周","现病史":"患者1周前无明显诱因出现滑膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复关节肿胀疼痛1周，需完善血常规检查排除感染、贫血所致关节症状，完善尿常规、便常规检查了解泌尿系统及消化道情况；患者自服药物效果欠佳，住院期间用药需经肝肾代谢，完善肝肾功能、电解质检查评估用药安全性，完善血糖、血脂检查了解代谢状况；为明确关节腔内有无积液、滑膜增厚程度及血流信号，完善关节超声检查，必要时行关节腔穿刺检查，明确积液性质以鉴别感染性关节炎与痛风性关节炎；如关节肿胀反复发作、病因难以明确，病情稳定后行关节镜下滑膜活检检查，明确滑膜病理性质以鉴别结核性、类风湿性及色素沉着绒毛结节性滑膜炎；完善关节X线片检查了解关节间隙、骨质破坏及骨赘形成情况，明确关节结构损害程度；反复关节肿痛需排除炎性关节病，完善类风湿因子检查鉴别类风湿关节炎，完善HLA-B27检查鉴别强直性脊柱炎等脊柱关节病；为判断有无神经源性关节损害及周围神经病变，完善肌电图检查明确神经传导情况；患者需评估心肺基础状况及手术耐受性，完善心电图检查排除心律失常、心肌缺血，完善胸部X线片检查排除肺部感染、结核及肿瘤；完善腹部超声检查了解肝胆胰脾肾情况，排除内脏疾病所致关节表现；如考虑关节镜下滑膜切除或需长期应用糖皮质激素、免疫抑制剂，入院后完善凝血功能、感染筛查、结核筛查等术前及用药前必查项目。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 滑膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 塞来昔布胶囊0.2g qd po×7天（餐后服，疼痛明显者首日可加服0.2g），用于抗炎镇痛、消肿。\n2. 双氯芬酸二乙胺乳胶剂（扶他林）适量外用患处 tid×7天，与口服药间隔使用，减轻局部肿痛。\n3. 滑膜炎片3片 tid po×7天，活血利水消肿，辅助缓解关节积液。\n4. 伴明显关节积液、反复肿胀者，可在严格无菌操作下行关节腔穿刺抽液并注射曲安奈德20mg（1次），需排除感染后方可注射。\n【一般治疗及生活指导】\n1. 急性期患肢制动休息，减少负重行走，避免上下楼、深蹲、久站及跑跳等冲击性活动；必要时卧床并抬高患肢高于心脏水平，利于消肿。\n2. 急性期（48小时内）局部冰敷，每次15-20分钟，每日3-4次，禁止热敷及强力按摩推拿，以免加重炎症。\n3. 清淡饮食，控制体重，避免动物内脏、海鲜、啤酒等高嘌呤食物，减少痛风性滑膜炎发作；适当补充优质蛋白及钙、维生素D。\n4. 症状缓解后循序渐进恢复活动，注意保暖，避免受凉及关节反复劳损。\n【随诊要求】\n1. 用药3-5天后复诊，评估疼痛、肿胀缓解情况；若症状无缓解或加重，或出现关节红肿发热加剧、全身发热，应立即复诊或急诊就诊。\n2. 行关节腔穿刺注射者1-2周复诊，观察有无感染、积液复发；积液反复出现者建议行关节彩超或MRI检查明确病因（如半月板损伤、类风湿、痛风等）。\n3. 慢性滑膜炎（如骨关节炎性）症状缓解后每3-6个月复查评估，遵医嘱规范随访，避免自行停药或长期反复关节腔注射。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1025,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"22ff57c309736b42ae29b35b11f7d521cd989828278db2fa000731d2633cf881","pinyin":"huamoyan","initials":"hmy","setting":"out","caseName":"门诊病历893","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历893",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a700a72ca603dd9f91ba","key":"v1-c9ccc21dfe2a3058|templates-a700a72ca603dd9f91ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"滑囊炎","category":"门诊病历模板","raw":{"name":"滑囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历894","templates":{"主诉":"反复关节周围肿痛1周","现病史":"患者1周前无明显诱因出现滑囊炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复关节周围肿痛1周、逐渐加重并伴轻度乏力，需完善血常规检查了解白细胞及中性粒细胞水平，排除感染性滑囊炎、化脓性关节炎及贫血所致乏力；关节肿痛需与痛风等代谢性关节病鉴别，完善尿常规检查了解尿酸盐及肾脏受累情况，完善便常规检查了解有无消化道隐性失血，为后续非甾体抗炎药用药安全提供依据；患者自服药物效果欠佳、门诊拟予非甾体抗炎药或糖皮质激素治疗，完善肝肾功能检查评估药物代谢与排泄能力，排除肝肾功能不全；完善血糖、血脂检查了解有无糖尿病、高脂血症等代谢异常，评估代谢性关节病基础；关节周围肿痛伴乏力需排除电解质紊乱所致肌肉无力，完善电解质检查；完善心电图检查评估心脏基础情况、排除心律失常，为用药前安全评估提供依据；滑囊炎需与肺部感染、结核等可致关节症状的疾病鉴别，完善胸部X线片检查；完善腹部超声检查了解肝胆胰脾肾情况，排除内脏疾病所致牵涉痛，并作为用药前基线评估。门诊随诊，必要时行关节超声及关节腔穿刺进一步明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 滑囊炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（NSAIDs）为一线首选：布洛芬缓释胶囊 0.3g bid 餐后口服×7天，或塞来昔布胶囊 0.2g qd 口服×7天（胃肠道不适或炎症较重者优先选用，疗程不超过2周）。\n2. 外用NSAIDs：双氯芬酸二乙胺乳胶剂（扶他林）适量涂于患处 bid×7天，可单用或与口服药联用以减少全身用药。\n3. 糖皮质激素囊内注射（急性渗出明显或经口服药治疗1周无效者）：复方倍他米松注射液1ml＋2%利多卡因1ml 行囊内注射1次，2~4周后复诊评估，同一部位注射不超过3次。\n4. 合并感染（局部红肿热痛加剧伴发热）者：头孢呋辛酯片 0.25g bid 口服×5~7天，必要时外科切开引流。\n\n【一般治疗及生活指导】\n1. 制动休息：急性期减少患处活动，避免反复摩擦、压迫及剧烈运动；肘部滑囊炎避免以肘支撑，膝前滑囊炎避免长时间跪姿或久蹲，踝部滑囊炎减少行走负重。\n2. 局部理疗：急性期（48小时内）局部冷敷，每次15~20分钟，每日3~4次；48小时后改为热敷或红外线理疗，促进炎性渗出吸收。\n3. 去除诱发因素：避免长期重复性动作及局部压迫，运动前充分热身并佩戴护膝、护肘等护具，调整坐姿与劳动体位。\n4. 饮食控制：清淡饮食，限制高嘌呤食物（动物内脏、海鲜、啤酒）及辛辣刺激饮食，肥胖者控制体重以减轻关节负荷。\n\n【随诊要求】\n1. 口服药物7天后复诊评估疗效，症状缓解不明显或停药后反复发作者及时复诊调整方案。\n2. 治疗期间若出现局部红肿热痛明显加重、皮温升高伴发热等感染征象，应立即就诊。\n3. 接受囊内激素注射者于注射后2~4周复诊评估，同一部位全年注射不超过3次。\n4. 反复发作或合并痛风、类风湿关节炎、糖尿病等基础疾病者，建议转风湿免疫科或专科门诊长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1026,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fa1ad484ca0c09fe7494bd4bc4e8b2a4bd5cb7ee08a22a009434501c8b82b050","pinyin":"huanangyan","initials":"hny","setting":"out","caseName":"门诊病历894","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历894",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3133151443e14ff4e38d","key":"v1-c9ccc21dfe2a3058|templates-3133151443e14ff4e38d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"关节炎","category":"门诊病历模板","raw":{"name":"关节炎","category":"门诊病历模板","case":{"case_name":"门诊病历895","templates":{"主诉":"双膝关节肿痛2个月，晨僵1个月。","现病史":"患者2个月前无明显诱因出现双膝关节隐痛，活动后加重、休息减轻，晨起关节僵硬约30分钟，活动后可缓解；近1个月双膝肿胀，上下楼梯及下蹲困难，无发热、无皮疹、无口腔溃疡、无眼干口干，无腰痛。曾于外院查血尿酸正常，服用布洛芬可暂时缓解疼痛。今日来我院门诊就诊。发病以来精神可，食欲、睡眠、大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 122/78mmHg。神志清楚，查体合作。双膝关节对称性肿胀，皮温略高，皮肤无发红，浮髌试验（+/-），双膝屈伸活动受限（屈曲约100°），关节局部压痛（+），未及明显骨摩擦感；双腕、双手近端指间关节无肿胀压痛。脊柱无畸形，活动正常。心肺听诊未闻及明显异常。","辅助检查":"【必做】血常规、血沉、CRP、类风湿因子、抗CCP抗体、血尿酸；【影像学】双膝关节X线片（关节间隙、骨质破坏、骨赘增生）；【其他】关节超声（滑膜增生、关节积液评估）、抗核抗体（疑系统性自身免疫病时）。","初步诊断":"1. 关节炎（性质待查：骨关节炎/类风湿关节炎等待鉴别）\n（注：需结合实验室及影像学检查明确关节炎类型，必要时请风湿免疫科会诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（首选，镇痛抗炎）：塞来昔布胶囊200mg po qd，或依托考昔片60mg po qd，餐后服用，疗程7-14天，疼痛缓解后即停药；既往有消化性溃疡病史者联用奥美拉唑肠溶胶囊20mg po qd护胃。\n2. 外用非甾体抗炎药（轻中度疼痛首选或与口服药联用）：双氯芬酸二乙胺乳胶剂（扶他林）适量外涂患处，bid-tid，连续使用不超过2周。\n3. 软骨保护剂：硫酸氨基葡萄糖胶囊0.75g po bid，餐后服用，连用8-12周为一疗程，每年可重复1-2个疗程。\n4. 若关节急性红肿热痛剧烈、高度怀疑痛风性关节炎：秋水仙碱片首剂1.0mg，1小时后0.5mg，12小时后改为0.5mg bid，连用3-5天（肾功能不全者减量），同时查血尿酸以明确诊断，待急性期缓解后再制定降尿酸方案。\n\n【一般治疗及生活指导】\n1. 急性期休息制动：疼痛明显时减少负重活动，避免长时间站立、上下楼梯、爬山及深蹲，必要时使用拐杖或护膝分担关节负荷；注意关节保暖，避免受凉。\n2. 控制体重：超重或肥胖者减重5%-10%，可显著减轻膝、髋关节负荷并缓解疼痛。\n3. 功能锻炼：疼痛缓解后进行低冲击运动，如游泳、骑固定自行车、平地散步，每次30分钟；加强股四头肌力量训练（直腿抬高、靠墙静蹲），以增强关节稳定性。\n4. 饮食调整：均衡饮食，适当增加奶制品、豆制品等含钙食物摄入，必要时补充钙剂及维生素D；避免高嘌呤饮食（动物内脏、海鲜、浓肉汤、啤酒）以预防痛风发作。\n\n【随诊要求】\n1. 用药2周后复诊，评估疼痛缓解情况及有无胃肠道不适等药物不良反应。\n2. 连续规范治疗4周疼痛无明显缓解，或出现关节红肿热痛加重、夜间静息痛、晨僵超过1小时者，应及时复诊以排查类风湿关节炎、痛风等继发病因。\n3. 长期服用NSAIDs或氨基葡萄糖者，每3个月复查血常规、肝肾功能；出现黑便、上腹不适等消化道症状随时就诊。\n4. 保守治疗效果不佳、关节畸形或活动受限明显者，转骨科专科评估关节腔注射或手术治疗；每年复查X线（必要时MRI）评估关节退变进展。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1027,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cdb24b3940dc288336074922ec724c1fb58f2d7fbf658095a72de0b7d3d4a7d4","pinyin":"guanjieyan","initials":"gjy","setting":"out","caseName":"门诊病历895","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历895",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d01934a0ef44aea1db2b","key":"v1-c9ccc21dfe2a3058|templates-d01934a0ef44aea1db2b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"关节脱位","category":"门诊病历模板","raw":{"name":"关节脱位","category":"门诊病历模板","case":{"case_name":"门诊病历896","templates":{"主诉":"外伤后关节畸形伴疼痛2小时","现病史":"患者于2小时前跌倒（外伤机制：肩关节最常见，多为前脱位（>95%，外展外旋位跌倒、手撑地，肱骨头向前脱出）；肘关节多为后脱位（跌倒手撑地、肘伸直位）；髋关节多为后脱位（车祸、屈髋屈膝位、膝撞仪表盘、坐位受伤，为强大暴力所致；小儿则为牵拉所致，如牵拉肘即桡骨头半脱位，多见于<5岁，前臂被牵拉后哭闹、不愿用臂）；下颌关节脱位多见于打哈欠或大笑时）后出现：关节畸形（关节外形改变，肩关节呈方肩畸形（肱骨头脱出、肩峰突出、三角肌下空虚，为特征）；肘关节可见肘后三角关系改变）、弹性固定（关节固定于半屈曲位，被动活动时有弹性抵抗，为特征）、关节盂空虚（肩关节盂内空虚，可触及肱骨头（前脱位时位于腋下或喙突下））、剧痛（活动时加重）、肿胀（关节囊撕裂出血所致）、功能障碍（不能活动）、神经血管损伤（肩关节可伤及腋神经（三角肌感觉障碍，臂外侧麻木，此点重要，复位前后均需评估）、臂丛及血管（腋动脉损伤少见，表现为手凉、苍白，属急症）；肘关节可伤及正中神经或尺神经）、合并骨折（肩关节常见肱骨大结节撕脱，亦可有关节盂唇损伤、肱骨外科颈骨折）。并询问院前是否已尝试复位，切勿多次暴力复位。今日来我院急诊或骨科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P88次/分，R20次/分，BP118/74mmHg。关节明显畸形（肩关节呈方肩畸形，三角肌轮廓消失）、弹性固定、压痛、活动受限、关节盂空虚（肩关节）、肿胀；血管神经检查：肩关节注意腋神经（观察三角肌收缩及臂外侧感觉有无麻木）、肘关节注意桡神经、尺神经及正中神经（手部感觉运动）、血管（桡动脉搏动及远端血运、手温及颜色）；合并骨折（注意骨擦感，勿强行检查）；记录脱位方向（为前脱位）；复位前应全面评估神经血管作为基线，此点重要，并与复位后对比；双侧关节对比检查。","辅助检查":"【必做】肩关节X线（正位+侧位，判断脱位方向（肩前脱位时肱骨头位于盂下或喙突下）、合并骨折（大结节撕脱、外科颈骨折、关节盂骨折，以及Hill-Sachs损伤或骨性Bankart损伤，为复发因素）；复位后X线（确认复位及关节对位，此点重要，必须复查））。【CT】（复杂骨折，如Bankart骨折、关节盂大块骨折，术前评估；复位后关节内碎块，必要时进行）。【MRI】（观察软组织，如肩袖、盂唇（Bankart损伤，用于评估复发脱位），择期进行，适用于反复脱位者）。【神经血管】（复位前后查体并记录，注意腋神经有无麻木，评估损伤）。【其他】复位后评估制动方案及随访计划（评估复发风险，与年龄及损伤有关：首次脱位且年轻（<30岁）者复发率高（可达80%），若从事运动，需评估手术，此点重要）。","初步诊断":"1. 关节脱位（左肩关节前脱位；合并骨折及神经血管损伤待排；首次脱位）\n（注：治疗应及时复位（越早越易，宜在肌肉痉挛前），由专业人员操作，切勿暴力：①手法复位（肩前脱位可采用牵引-反牵引法或Stimson法（俯卧位，患肢下垂，以重物牵引，肌肉放松后可自行复位）、Hippocrates足蹬法（传统方法，以足跟蹬于腋下牵引旋转，易致骨折，已少用），刺激运动法（Kocher法，通过旋转复位，有骨折风险，年轻患者慎用）；复位成功时可闻及弹响，关节活动恢复，方肩消失。肘关节脱位行牵引复位（屈肘牵引）；髋关节脱位需在麻醉下复位（Allis法，因肌肉强大，需全麻或镇静使肌肉松弛，此点重要，强行复位可致股骨颈骨折）。复位后必须复查X线确认）。②复位后处理（制动：肩关节以肩吊带或绷带固定于内收内旋位3~4周（首次脱位者用于防复发，尤其年轻患者，此点重要；固定时间存在争议，年轻者3~4周，老年者宜早活动以防冻结肩）；肘关节屈肘90°固定2~3周；髋关节牵引制动3~4周；冰敷消肿、镇痛、抗炎（非甾体抗炎药））。③神经血管损伤（复位前评估、复位后复查：腋神经损伤多为牵拉所致，多可自行恢复（观察4~6周，行肌电图，若无恢复则手术探查）；血管损伤如腋动脉损伤致手部缺血，属急症，需血管外科处理）。④合并骨折（大结节撕脱：复位后多随复位而对位良好，予保守治疗（肩吊带），移位明显者手术固定；Bankart骨折：关节盂大块骨折需手术，以防复发，此点重要）。⑤复发预防（年轻（<25~30岁）首次外伤性前脱位者复发率高（70~90%，尤其运动者），固定后应行康复（肩袖及肩胛肌力训练，以稳定关节、防再脱位，此点重要）；反复复发（习惯性脱位，多伴盂唇Bankart损伤）者行手术（关节镜盂唇修复，效果良好，可防复发，此点重要），需评估）。⑥康复（制动期后行功能锻炼，循序渐进：肩关节可做钟摆运动、爬墙运动，肘关节行屈伸锻炼，以防僵硬；待肌力及活动度恢复后再恢复活动，防再伤）。急诊或骨科处理要点：及时专业复位、X线确认、评估神经血管；年轻首次脱位者需固定并康复，复发者手术，以防再脱位，此点重要。）","处理方案":"【药物治疗】\n1. 镇痛抗炎：塞来昔布胶囊0.2g qd口服，疗程5～7天；或布洛芬缓释胶囊0.3g bid口服，疗程5～7天，疼痛缓解后及时停用。\n2. 活血化瘀、消肿止痛中成药：云南白药胶囊0.25g tid口服，疗程7天；或三七伤药片3片（0.3g/片）tid口服，疗程7天。\n3. 局部外用：双氯芬酸二乙胺乳胶剂（扶他林）适量涂于患处周围皮肤并轻柔按摩，每日2～3次，疗程5～7天，皮肤破损处禁用。\n【一般治疗及生活指导】\n1. 复位后患肢制动固定：肩关节脱位以三角巾悬吊固定于内收内旋位3～4周，肘关节脱位屈肘90°位石膏或支具固定3周，固定期间严禁患肢负重、提物及剧烈活动，避免再次脱位。\n2. 固定期间每日坚持未固定关节的主动活动及患肢手指（趾）握拳、屈伸练习，防止关节僵硬与肌肉萎缩；拆除固定后循序渐进进行关节屈伸、旋转功能锻炼，避免过早暴力牵拉。\n3. 饮食：多食富含优质蛋白（瘦肉、蛋、奶）、钙质（牛奶、豆制品）及维生素C的食物，促进韧带及软组织修复；忌烟酒及辛辣刺激饮食。\n4. 密切观察患肢远端血运与感觉，若出现指（趾）端发绀、麻木、剧痛、活动障碍或固定物松动、皮肤压疮，应及时返诊。\n【随诊要求】\n1. 复位后即刻行X线复查确认复位成功、关节对位及固定位置良好；固定期间每1～2周门诊复诊1次，复查X线观察关节位置及软组织修复情况。\n2. 拆除固定后（约3～4周）复诊，评估关节稳定性与活动度，由医师指导个体化功能锻炼方案；若发生习惯性脱位（同一关节反复脱位≥2次），需转骨科专科评估是否行韧带修复或关节稳定重建手术。\n3. 伤后肿胀明显者嘱抬高患肢，24小时内冷敷、24小时后热敷；若出现患肢麻木、无力、皮温降低、远端动脉搏动减弱等神经血管损伤表现，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1028,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"07151ae99d9bce26370406c4c1115130f2ca7748e5b483c23e3b0be156c57a58","pinyin":"guanjietuowei","initials":"gjtw","setting":"out","caseName":"门诊病历896","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历896",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-639e94da494688c0afce","key":"v1-c9ccc21dfe2a3058|templates-639e94da494688c0afce","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"关节损伤","category":"门诊病历模板","raw":{"name":"关节损伤","category":"门诊病历模板","case":{"case_name":"门诊病历897","templates":{"主诉":"关节肿痛伴活动受限1周","现病史":"患者1周前无明显诱因出现关节损伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者关节肿痛伴活动受限1周、逐渐加重并伴轻度乏力，完善血常规检查排除感染性关节炎、贫血所致乏力；关节肿痛需鉴别炎症性与退行性病变，完善血沉、CRP检查了解炎症活动程度；完善血钙磷碱性磷酸酶检查了解骨代谢状况，排除骨质疏松、骨肿瘤及甲状旁腺功能异常所致骨病；患者关节肿痛需与类风湿关节炎、强直性脊柱炎等鉴别，完善类风湿因子、HLA-B27检查明确诊断方向；首选X线片检查了解关节间隙、骨质结构及有无骨折脱位；对X线片难以显示的隐匿性骨折、骨挫伤及软组织损伤，进一步完善CT检查明确骨质细节，完善MRI检查明确关节软骨、韧带、肌腱及骨髓水肿情况；患者活动受限、骨量可能下降，完善骨密度检查评估骨质情况、指导抗骨质疏松治疗；完善关节超声检查了解关节积液、滑膜增生及周围软组织情况，必要时引导穿刺；患者活动受限伴乏力，需完善肌电图检查评估神经肌肉功能，排除周围神经或肌肉源性损害所致无力。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙磷碱性磷酸酶\n\n【影像学检查】\nX线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 关节损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（抗炎镇痛）：塞来昔布胶囊 0.2g bid 口服×7天；或双氯芬酸钠缓释片 75mg qd 口服×7天（饭后服，既往消化道溃疡者慎用）。\n2. 活血化瘀、消肿止痛中成药：三七伤药片 3片 tid 口服×7天；或云南白药胶囊 0.25g qid 口服×5天。\n3. 外用药物：双氯芬酸二乙胺乳胶剂 适量涂于患处，tid×7天；急性肿胀明显者加用七叶皂苷钠凝胶外用。\n4. 软骨修复及营养关节：盐酸氨基葡萄糖胶囊 0.75g bid 口服×4周（用于关节软骨挫伤、退变基础者）。\n\n【一般治疗及生活指导】\n1. 制动休息：伤后48小时内遵循RICE原则：患肢抬高、冰敷（每次15-20分钟，间隔2小时，每日3-4次）、弹力绷带适度加压包扎、减少负重行走；必要时使用护膝、护踝或支具固定制动1-2周。\n2. 活动指导：急性期（1周内）避免患关节负重及剧烈运动，避免深蹲、跳跃、跑动；1周后疼痛缓解可逐步开始关节无负重屈伸活动训练，循序渐进恢复。\n3. 饮食指导：多摄入优质蛋白（瘦肉、蛋、奶）、富含维生素C及钙质的食物（新鲜蔬果、豆制品），戒烟限酒，避免辛辣刺激性饮食。\n4. 禁忌：急性期（48小时内）禁忌热敷、红外理疗及暴力按摩推拿，以免加重肿胀出血；禁忌自行强行活动或过早负重。\n\n【随诊要求】\n1. 用药3-5天后复诊，评估疼痛、肿胀缓解情况并调整用药；症状明显缓解者继续完成疗程，症状无改善或加重者及时复诊。\n2. 伤后1-2周复查X线片（必要时行MRI），明确有无隐匿性骨折、软骨或韧带损伤。\n3. 如出现患关节肿胀持续加重、剧烈疼痛、活动受限加重、关节不稳或\"卡锁\"现象，应立即复诊。\n4. 急性期症状缓解后（约2-4周）复诊，评估关节功能恢复情况，制定康复锻炼计划；恢复正常活动前需经医师评估确认。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1029,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e206d3500a2498b767f17f8d077ae86b0a9a4f1682a5400ef7155462b3135757","pinyin":"guanjiesunshang","initials":"gjss","setting":"out","caseName":"门诊病历897","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历897",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-951c6abef62cc84a4f96","key":"v1-c9ccc21dfe2a3058|templates-951c6abef62cc84a4f96","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨折","category":"门诊病历模板","raw":{"name":"骨折","category":"门诊病历模板","case":{"case_name":"门诊病历898","templates":{"主诉":"外伤后局部肿痛伴活动受限2小时","现病史":"患者于2小时前跌倒（老年人髋部及桡骨远端骨质疏松性骨折，多为摔倒手撑地所致Colles骨折，可见餐叉样畸形）、高能量损伤（车祸或高处坠落所致股骨、骨盆、脊柱骨折，常为多发伤并可伴休克）、运动损伤（胫骨、踝部扭转）或病理性骨折（肿瘤转移或骨质疏松患者轻微外伤甚或无外伤即可发生骨折，若为骨转移所致骨折，老年人尤应警惕）、疲劳性骨折（应力性骨折，常见于运动员的胫骨、跖骨，由反复应力累积所致）等机制受伤后出现局部疼痛（多为剧痛，活动后加重）、肿胀（由软组织损伤或出血引起，可见瘀斑，数小时后逐渐明显）、畸形（因骨折移位出现成角、短缩或旋转，为骨折特征性表现，可与健侧对比）、异常活动（骨折端在非关节部位出现异常活动，为骨折特征，但勿故意检查，以免加重损伤）、骨擦音（骨折端相互摩擦产生，勿故意检查）及功能障碍（患肢不能负重或活动）。需注意是否合并开放骨折（皮肤有破口，骨折端外露或与外界相通，属急症，有感染风险，可致破伤风或骨髓炎，清创时机至关重要）、神经血管损伤（肢体远端麻木、苍白、无脉，属急症。骨筋膜室综合征多见于前臂或小腿，表现为剧痛与体征不符、筋膜室张力高、被动牵拉痛，属急症，可致缺血坏死，需急诊切开减压；神经损伤可累及桡神经、尺神经、正中神经或腓总神经，需评估远端感觉与运动）及休克（股骨、骨盆或多发骨折可致失血，股骨骨折内出血可达1000ml，骨盆骨折出血更多，表现为面色苍白、心率增快、血压下降，属急症）。同时需明确骨折部位（上肢、下肢、脊柱或骨盆，脊柱骨折可合并脊髓损伤致瘫痪，属急症，勿随意搬动）及院前固定情况（是否已固定、搬运是否得当，脊柱损伤须平托搬运）。今日来我院急诊/骨科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P92次/分（因失血而增快），R20次/分，BP110/70mmHg（股骨、骨盆骨折失血或休克时可降低）。神志清楚（休克时可表现为淡漠）。局部检查：肿胀、瘀斑及畸形（成角、短缩），压痛（沿骨折线局限分布，最痛处有助于定位），异常活动及骨擦音（轻查即可，勿反复检查）；皮肤有无开放伤口（骨折端外露时需仔细评估）；血管：评估肢体远端桡动脉或足背动脉搏动、毛细血管充盈时间、皮肤温度与色泽，警惕骨筋膜室综合征，注意筋膜室张力；神经：评估远端感觉与运动，判断相应神经有无损伤；脊柱：检查棘突压痛，警惕脊髓损伤，评估感觉运动平面及肛门括约肌功能，属急症；骨盆：行挤压试验以评估骨盆骨折，勿反复检查；全身情况：评估失血程度，监测心率、血压，警惕休克及多发伤。","辅助检查":"【必做】X线：正侧位以确诊骨折，观察骨折线、移位及成角，明确部位（干骺端、骨干或关节内，有助于分类），摄片需包含邻近关节（上下关节，以排除关节内骨折或脱位），必要时加摄健侧对比（儿童需注意骨骺）；复位后复查X线评估对位情况。【CT】用于复杂骨折或关节内骨折（胫骨平台、髋臼、脊柱），评估骨折块、关节面及三维形态；骨盆、脊柱的隐匿骨折X线阴性而高度可疑时，可行CT。【MRI】用于隐匿骨折（应力性骨折早期X线可阴性，MRI敏感）及软骨、韧带合并伤。【血液】血常规（评估失血及血红蛋白）、血型及交叉配血（股骨、骨盆或多发骨折需备血手术）、凝血功能、电解质、肌酸激酶（挤压伤可致横纹肌溶解）、肾功能（挤压伤时肌红蛋白可损伤肾脏）及血糖。【超声】创伤重点超声评估（FAST），用于多发伤时排查腹部出血，属急诊项目。","初步诊断":"1. 骨折（部位：左胫骨中段，关节外；类型：闭合性、斜形，轻度移位；及移位程度；合并伤：神经、血管、筋膜室或脊髓损伤，均需评估）\n（注：治疗原则为复位加固定加康复；开放性骨折、血管损伤或骨筋膜室综合征属急症，处理如下：①急救：固定（夹板或石膏固定骨折上下关节，减轻疼痛、防止再损伤）、抬高患肢及冰敷以减轻肿胀、止痛；开放骨折以无菌敷料覆盖，勿回纳外露的骨折端（以防污染），属急症，需在6~8小时内清创以防感染，并做破伤风预防（TAT或TIG，开放伤者尤为重要），同时使用抗生素（如头孢类）预防骨髓炎；血管损伤致肢体缺血属急症，需探查修复，宜在6小时内完成；骨筋膜室综合征属急症，需在4~6小时内切开减压，以防缺血坏死，勿延误。②复位：手法复位（闭合复位，在麻醉下进行，可选用局部麻醉、神经阻滞或全麻，以利肌肉放松，达到对位对线；儿童骨骼有可塑形能力，轻度成角可接受，解剖复位并非必须）；手术复位（切开复位内固定，可选用钢板螺钉或髓内钉，适用于移位明显、关节内、不稳定、多发或开放骨折；开放骨折可先以外固定支架固定，待软组织恢复后再行内固定；内固定有助于早期活动，防止关节僵硬，股骨骨折以髓内钉为标准术式）。③固定：石膏或夹板固定，适用于闭合复位后，固定4~8周（儿童时间较短），期间随访X线观察骨痂生长；手术者采用内固定或外固定。④康复：功能锻炼，早期行肌肉等长收缩以防萎缩，并活动非固定关节；骨折愈合后逐步行负重训练；防止关节僵硬与肌萎缩，物理治疗十分重要。⑤并发症：骨不连或延迟愈合（吸烟可影响愈合，应戒烟）、感染（开放骨折可致骨髓炎）、深静脉血栓（下肢及骨盆骨折制动者需预防，高危者可用低分子肝素抗凝）、骨筋膜室综合征（已如前述）及脂肪栓塞（多见于股骨、骨盆骨折，伤后24~72小时出现呼吸窘迫及瘀点，属急症），并需观察骨筋膜室情况。⑥随访：复查X线（复位后第2周、4~6周、8~12周，观察骨痂及愈合评估）；结合临床（无痛、可活动）与影像判断愈合后拆除固定，逐步负重；儿童需随访骨骺，评估损伤对生长的影响。骨科处理：按部位与类型行复位固定，配合康复及并发症监测；开放性骨折、血管损伤及骨筋膜室综合征属急诊，须高度重视。）","处理方案":"【药物治疗】\n1. 镇痛：塞来昔布胶囊0.2g qd，或洛索洛芬钠片60mg tid，饭后服用，疼痛缓解后停药，疗程3~7天；有消化性溃疡史或对本类药物过敏者禁用。\n2. 活血化瘀、促进骨折愈合：接骨七厘片1.05g tid×4周，或伤科接骨片4片 tid×3~4周，用药期间避免与其它活血类药物同服。\n3. 补钙与维生素D：碳酸钙D3片（含元素钙600mg）0.6g qd，联合骨化三醇软胶囊0.25μg bid，疗程3个月，促进骨痂钙化。\n4. 消肿：迈之灵片150mg bid×2周，伤后早期与抬高患肢配合使用。\n\n【一般治疗及生活指导】\n1. 制动休息：患肢行石膏/夹板或支具外固定并严格制动，抬高患肢高于心脏水平以利消肿；伤后48小时内局部冷敷、48小时后改热敷，每次15~20分钟，每日2~3次。\n2. 饮食指导：进食高蛋白、高钙、富含维生素C及D的食物（瘦肉、蛋、奶、豆制品、鱼虾、深色蔬菜等），多饮水，忌烟酒及辛辣刺激性食物，少饮浓茶、咖啡以免影响钙吸收。\n3. 活动指导：固定期间进行未固定关节的主动活动及固定部位肌肉等长收缩锻炼，每日2~3次，每次10~15分钟；禁止患肢过早负重及剧烈运动，负重时机以复查X线示骨痂生长良好后遵医嘱逐步开始，一般需6~8周。\n4. 护理与禁忌：保持石膏/夹板清洁干燥、避免受压变形；每日观察患肢末梢皮温、颜色、感觉及活动度，出现剧烈疼痛、麻木、发凉、肿胀进行性加重或固定松动时立即就诊；严禁自行拆除固定物。\n\n【随诊要求】\n1. 伤后1~2周复查X线片评估骨折对位及固定情况；4~6周、3个月各复查X线片观察骨痂生长与愈合情况，由医师决定拆除外固定及开始负重的时间。\n2. 保守治疗期间若出现患肢剧烈疼痛、末梢麻木发凉、皮色改变、肿胀加重或石膏/夹板松动断裂等，随时复诊。\n3. 骨折达临床愈合后遵医嘱行系统功能锻炼，必要时转康复科指导；行内固定手术者按医嘱定期随访，术后1、3、6个月复查X线片。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1030,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e6edb08dbfab38c2f8145f524d509c90054db62038de001fcdcbbc687f10b026","pinyin":"guzhe","initials":"gz","setting":"out","caseName":"门诊病历898","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历898",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-28187ecfd851323ed386","key":"v1-c9ccc21dfe2a3058|templates-28187ecfd851323ed386","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脱位","category":"门诊病历模板","raw":{"name":"脱位","category":"门诊病历模板","case":{"case_name":"门诊病历899","templates":{"主诉":"反复脱位相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现脱位相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复脱位相关不适1周、加重1天，首先完善X线片检查明确脱位部位、方向及有无合并骨折，为复位方案提供依据；对X线片显示不清或复位后仍怀疑关节内骨折、游离体者，进一步完善CT检查明确骨性结构细节；患者反复脱位提示关节囊、韧带及盂唇等软组织松弛，完善MRI检查明确关节囊韧带损伤、盂唇撕裂及软骨损伤情况；完善血常规检查排除感染、贫血所致全身不适；完善血沉、CRP检查了解有无感染性关节炎或关节内炎症活动；完善血钙磷碱性磷酸酶检查了解骨代谢情况，排除骨质疏松、骨软化等致反复脱位的骨性因素；完善骨密度检查评估骨量，明确有无骨质疏松；完善关节超声检查了解关节积液、滑膜及周围软组织情况；反复脱位伴乏力需排除神经肌肉源性关节不稳，完善肌电图检查评估神经肌肉功能；完善类风湿因子、HLA-B27检查以鉴别类风湿关节炎及强直性脊柱炎等可破坏关节结构而致反复脱位的疾病。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙磷碱性磷酸酶\n\n【影像学检查】\nX线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 脱位\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1．非甾体抗炎药（NSAIDs）止痛：塞来昔布胶囊 0.2g bid 口服×5~7天（餐后服，消化性溃疡病史者慎用，可改用对乙酰氨基酚片 0.5g 疼痛时口服）。\n2．肌肉松弛剂：盐酸乙哌立松片 50mg tid 口服×7天，缓解复位后关节周围肌肉痉挛及酸痛。\n3．外用消肿止痛：双氯芬酸二乙胺乳胶剂（扶他林软膏）适量涂于患处 tid×7天，皮肤破损处禁用。\n4．活血化瘀中成药：云南白药胶囊 0.25g tid 口服×5天（孕妇禁用）。\n\n【一般治疗及生活指导】\n1．制动休息：复位后按医嘱行三角巾悬吊或夹板、石膏外固定3~4周（肩关节脱位常规悬吊制动3周），患肢抬高，避免负重及长时间下垂。\n2．功能锻炼：固定期间每日行未固定关节的主动活动及固定部位肌肉等长收缩，防止肌肉萎缩；去除固定后逐步进行关节屈伸、旋转功能训练，循序渐进、以不引起明显疼痛为度，严禁暴力牵拉。\n3．饮食调理：多进食高蛋白、高钙、富含维生素C和D的食物（牛奶、鱼虾、瘦肉、鸡蛋、新鲜蔬果），多饮水，戒烟戒酒，保证充足睡眠以促进软组织修复。\n4．禁忌事项：急性期禁忌对患处行暴力按摩、推拿或强行活动；4周内避免提重物、剧烈运动及患肢过度外展外旋，防止再脱位。\n\n【随诊要求】\n1．复位后1周内复诊，复查X线片确认关节对位良好、无合并骨折及再脱位。\n2．去除外固定后（约3~4周）复诊，由医师评估关节稳定性后开始系统功能锻炼。\n3．如出现患肢剧烈疼痛、肿胀明显加重、肢端麻木发凉、皮肤苍白或青紫、活动受限加重等异常，应随时急诊复诊。\n4．反复脱位（习惯性脱位）者，建议3个月内至骨科专科门诊评估韧带及关节囊损伤情况，必要时行关节镜或手术修复治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1031,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ddf2cea73314051a689d8a27eb6368baf4facebb4f70e81eb4619d098c2bf81f","pinyin":"tuowei","initials":"tw","setting":"out","caseName":"门诊病历899","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历899",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e0fd78ad33057647fca8","key":"v1-c9ccc21dfe2a3058|templates-e0fd78ad33057647fca8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"扭伤","category":"门诊病历模板","raw":{"name":"扭伤","category":"门诊病历模板","case":{"case_name":"门诊病历900","templates":{"主诉":"反复扭伤相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现扭伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复扭伤相关不适1周、加重1天，完善X线片检查排除骨折、明确有无关节对位异常；若X线片不能排除隐匿性骨折或骨挫伤，进一步完善CT检查明确骨性结构；患者反复扭伤提示韧带、肌腱及软骨损伤可能，完善MRI检查明确韧带撕裂程度、软骨损伤及骨髓水肿情况，为制动或手术方案提供依据；完善关节超声检查动态了解韧带、肌腱连续性及关节积液情况；完善血常规检查排除感染、贫血；完善血沉、CRP检查了解有无炎症反应；完善血钙磷碱性磷酸酶检查了解骨代谢状况，排除骨质疏松等易致反复损伤的因素；完善骨密度检查评估骨量；患者反复扭伤、活动受限伴乏力，需完善肌电图检查评估神经肌肉功能，排除周围神经损伤或肌病所致关节不稳；完善类风湿因子、HLA-B27检查以鉴别类风湿关节炎、强直性脊柱炎等炎性关节病所致关节稳定性下降。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙磷碱性磷酸酶\n\n【影像学检查】\nX线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 扭伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 塞来昔布胶囊0.2g bid×5天，口服抗炎镇痛，饭后服用；有消化性溃疡病史或肾功能不全者慎用，可改用对乙酰氨基酚片0.5g bid×5天。\n2. 双氯芬酸二乙胺乳胶剂（扶他林）外用，取适量涂于患处并轻柔按摩，tid×5-7天，皮肤破损处禁用。\n3. 马栗种子提取物片（威利坦）400mg bid×7天，促进静脉回流、减轻局部肿胀；或七叶皂苷钠片30mg bid×7天。\n\n【一般治疗及生活指导】\n1. 休息与制动：急性期患肢制动休息，避免负重及行走；踝关节扭伤者佩戴护踝或支具，必要时使用拐杖辅助行走3-5天。\n2. 冰敷：伤后48小时内局部冰敷，每次15-20分钟，每日3-4次，冰袋外裹毛巾以防冻伤；48小时后改热敷促进瘀血吸收。\n3. 抬高患肢：休息时将患肢抬高至高于心脏水平，促进静脉和淋巴回流，减轻肿胀。\n4. 禁忌：急性期禁止热敷、按摩推拿及饮酒，以免加重出血肿胀；避免患肢剧烈活动、奔跑跳跃及二次扭伤。\n\n【随诊要求】\n1. 用药3-5天后复诊，评估疼痛、肿胀及关节活动度恢复情况，必要时调整用药。\n2. 若出现患肢剧痛、肿胀进行性加重、无法负重、局部明显畸形或异常活动，提示韧带完全断裂或合并骨折可能，应立即就诊行X线或MRI检查。\n3. 症状缓解后2周内避免剧烈运动，4-6周后复查评估韧带愈合情况；恢复期逐步进行关节功能锻炼及周围肌力训练，防止再扭伤。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1032,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"723884d7462d8d3b539a9108cd376ed9d8cde7b3d9593372824f70fa2cffae40","pinyin":"niushang","initials":"ns","setting":"out","caseName":"门诊病历900","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历900",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-146b1063d4f616dbea0a","key":"v1-c9ccc21dfe2a3058|templates-146b1063d4f616dbea0a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"拉伤","category":"门诊病历模板","raw":{"name":"拉伤","category":"门诊病历模板","case":{"case_name":"门诊病历901","templates":{"主诉":"反复拉伤相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现拉伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者反复拉伤相关不适1周、加重1天，伴轻度乏力，完善血常规检查排除感染、贫血所致乏力；完善尿常规、便常规检查了解泌尿及消化系统有无异常、有无隐性失血，为后续用药提供基线资料；肌肉损伤后可出现肌红蛋白尿及电解质紊乱，完善电解质检查排除电解质紊乱所致肌肉痉挛与损伤；患者拟用非甾体抗炎药及肌肉松弛剂，完善肝肾功能检查评估药物代谢与排泄能力、排除肝肾功能不全；完善血糖、血脂检查了解代谢状况，评估有无糖尿病、高脂血症等影响软组织修复的代谢因素；完善心电图检查评估心脏基础情况、排除心律失常；完善胸部X线片检查排除肺部感染、结核及肋骨骨折等可致胸背牵涉不适的疾病；完善腹部超声检查了解肝胆胰脾肾情况，排除内脏疾病所致牵涉痛。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 拉伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（NSAIDs）：塞来昔布胶囊0.2g qd×5-7天（餐后服），或布洛芬缓释胶囊0.3g bid×5天；疼痛缓解后及时停用，避免长期使用。\n2. 肌肉松弛药：盐酸乙哌立松片50mg tid×5-7天，缓解肌肉痉挛及牵拉痛。\n3. 外用药物：双氯芬酸二乙胺乳胶剂（扶他林）适量涂患处，tid×5-7天；或云南白药气雾剂（红瓶）喷患处，每日3次，用于局部消肿止痛。\n4. 中成药活血化瘀：三七伤药片3片 tid×5天，或舒筋活血片5片 tid×7天（孕妇禁用，经期慎用）。\n\n【一般治疗及生活指导】\n1. 休息制动：伤后24-48小时内患肢减少活动、避免负重及剧烈运动，必要时使用拐杖或支具固定，以防二次损伤；急性期（48小时内）局部冷敷，每次15-20分钟，每日3-4次，减轻肿胀出血。\n2. 抬高患肢：休息时抬高受伤肢体至根据患者具体情况制定个体化方案高于心脏水平，促进静脉回流、减轻肿胀；48小时后可改为局部热敷或红外线理疗，促进淤血吸收。\n3. 饮食：忌辛辣刺激及酒精，多饮水，适量补充高蛋白及富含维生素C的食物（瘦肉、蛋、鱼、新鲜蔬果），促进组织修复。\n4. 康复活动：急性期后（3-5天）在无痛范围内进行轻柔的肌肉等长收缩及关节活动度练习，循序渐进恢复功能，避免突然剧烈牵拉；运动前充分热身，佩戴护具。\n\n【随诊要求】\n1. 用药3-5天后复诊，评估疼痛、肿胀及活动功能改善情况，若症状缓解可调整或停用药物。\n2. 若疼痛持续加重、明显肿胀、皮下瘀斑扩大或关节活动明显受限，应立即复诊，必要时行X线或磁共振（MRI）检查，排除骨折、韧带完全断裂或肌腱撕裂。\n3. 保守治疗2周后症状无明显好转或反复发作者，建议专科（骨科/运动医学科）复诊，评估进一步治疗（如局部封闭、康复理疗或手术）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1033,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3469326798d52517bbb73611a221bf500b8c53d33ce0c2f2a6e5ab310fded38b","pinyin":"lashang","initials":"ls","setting":"out","caseName":"门诊病历901","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历901",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8b543da13a2282f6c148","key":"v1-c9ccc21dfe2a3058|templates-8b543da13a2282f6c148","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"挫伤","category":"门诊病历模板","raw":{"name":"挫伤","category":"门诊病历模板","case":{"case_name":"门诊病历902","templates":{"主诉":"右小腿被重物砸伤后肿痛、活动受限2小时。","现病史":"患者于2小时前搬运货物时被重物砸伤右小腿中段，当即疼痛剧烈，局部迅速肿胀，皮肤无破口，右下肢活动受限，无法站立行走，无昏迷、无恶心呕吐。伤后未行特殊处理，局部未热敷、未按摩，急来我院就诊。发病以来精神紧张，无发热。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 88次/分，R 19次/分，BP 126/80mmHg。神志清楚，查体合作。右小腿中段前外侧可见约8cm×6cm范围皮肤瘀斑、肿胀明显，皮肤完整无破口，局部压痛（++），未触及骨擦感及反常活动，右足趾活动、感觉正常，末梢血运良好，足背动脉搏动正常。余肢体未见异常。","辅助检查":"【必做】右小腿正侧位X线片（排除骨折）；【其他】局部软组织超声（评估血肿范围）、血常规（肿胀明显或疑大血肿时）。","初步诊断":"1. 右小腿软组织挫伤\n（注：已排除骨折（X线阴性）；注意伤后48~72小时肿胀高峰期，如出现剧烈疼痛加重、足趾苍白麻木、张力性水疱及时复诊，警惕骨筋膜室综合征。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药外用药：双氯芬酸二乙胺乳胶剂（扶他林）适量外用涂搽患处，tid，疗程5-7天（皮肤破损处禁用）；\n2. 活血化瘀中成药：云南白药胶囊0.5g po tid（饭后服），或三七伤药片3片 po tid，疗程5-7天；\n3. 口服非甾体抗炎药（疼痛明显时）：塞来昔布胶囊0.2g po qd（饭后服）或布洛芬缓释胶囊0.3g po bid，疗程3-5天，症状缓解即停；\n4. 疼痛剧烈影响睡眠者，可短期加用洛索洛芬钠片60mg po tid，疗程≤3天，注意胃肠道及心血管禁忌。\n【一般治疗及生活指导】\n1. 伤后48小时内局部冷敷（每次15-20分钟，每日3-4次），减轻肿胀出血；48小时后改热敷促进淤血吸收；\n2. 患肢抬高制动，避免剧烈运动及负重，减少活动1-3天，淤血高峰期（伤后2-3天）避免按摩、揉搓患处；\n3. 保持局部皮肤清洁干燥，勿抓挠，防止破损感染；伤及头、胸、腹部者需警惕内脏损伤，出现头晕、胸闷、腹痛等及时就医；\n4. 饮食清淡易消化，忌辛辣刺激及饮酒，多饮水，适当补充富含维生素C及蛋白质的食物。\n【随诊要求】\n1. 伤后3-5天肿胀疼痛无缓解或进行性加重，或出现肢体活动受限、麻木、皮温异常，及时复诊；\n2. 皮下血肿进行性增大或触及波动感，需复诊评估行穿刺抽吸或影像学检查；\n3. 常规伤后1周复诊评估恢复情况；如伤后出现发热、局部红肿热痛加重，警惕继发感染，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1034,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ae6b29702ccc1e70d361209b40756d43817aadea87756e264576ce96471dd069","pinyin":"cuoshang","initials":"cs","setting":"out","caseName":"门诊病历902","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历902",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0a1171374fb64b747e21","key":"v1-c9ccc21dfe2a3058|templates-0a1171374fb64b747e21","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"烫伤","category":"门诊病历模板","raw":{"name":"烫伤","category":"门诊病历模板","case":{"case_name":"门诊病历903","templates":{"主诉":"热液致皮肤红肿水疱1天","现病史":"患者于3小时前被热液（开水、热汤或热油，最为常见，儿童因幼儿好动、热水烫伤为常见意外，老年人则因行动不便而易受伤）或蒸汽烫伤头面颈、躯干、四肢及会阴等部位。评估包括面积（估算可采用中国九分法或手掌法，患者手掌面积约相当于1%体表面积）与深度：Ⅰ度伤及表皮，表现为红斑、疼痛，3~5天愈合，不留瘢痕；浅Ⅱ度伤及真皮浅层，水疱较大、疱皮薄、创底红润、疼痛剧烈，1~2周愈合，不留瘢痕或仅留轻度色素改变；深Ⅱ度伤及真皮深层，水疱较小、创底红白相间、痛觉迟钝，3~4周愈合，可留瘢痕；Ⅲ度伤及全层，形成焦痂，呈蜡白或焦黄色，痛觉消失，不能自愈，需植皮。烫伤多为Ⅰ度或浅Ⅱ度（热液温度及接触时间决定深度，但热油或持续接触可致较深损伤）。伤后处理方面：是否已用流动冷水冲洗（伤后冲洗20~30分钟为黄金处理，可降温、减轻损伤深度，十分重要，冷疗在6小时内有效）；是否涂药（牙膏、酱油、香油等偏方勿用，会污染创面、增加感染风险，这一点很重要）；水疱是否已弄破（勿自行挑破，以防感染）及疼痛程度。全身情况需注意：大面积烫伤（超过10%，儿童及老年人超过5%）可致烫伤休克（创面渗出、体液丢失，表现为口渴、尿少、心率增快，需住院补液，十分重要）；有无发热（提示创面感染）；有无呼吸道症状（面部烫伤或密闭环境蒸汽烫伤可致吸入性损伤，出现声嘶、喘鸣，属急症）。今日来我院急诊/烧伤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P96次/分，R20次/分，BP110/70mmHg。创面：记录部位与面积（按九分法记录百分比）、深度（Ⅰ度表现为红斑、无水疱；浅Ⅱ度表现为水疱，记录大小及完整性，创底红润并有渗出；深Ⅱ度创底红白相间；Ⅲ度形成焦痂、呈蜡白），评估水疱情况，创周有无红肿、渗出及污染（有无异物或牙膏、酱油等涂敷物），疼痛及感觉评估（Ⅲ度创面痛觉消失）。全身情况：有无脱水（见于大面积烫伤）；注意呼吸道情况，面部烫伤者若出现鼻毛烧焦、声嘶、喘鸣，提示吸入性损伤，属急症，可致气道水肿、窒息风险，需警惕气管插管指征并密切监测。","辅助检查":"【必做】血常规（大面积烫伤可致血液浓缩及白细胞变化）、电解质、肾功能（大面积烫伤补液时监测）、血糖、白蛋白（评估渗出丢失）、血气（吸入性损伤或大面积烫伤时评估）、尿常规（监测尿量以指导补液，大面积烫伤需留置导尿记录尿量，评估休克）。【创面】大面积或感染创面行创面培养。【影像】胸部X线，用于评估吸入性损伤及肺炎。【心电图】大面积烫伤或老年患者需监测。【其他】评估破伤风预防（污染创面需用TAT或TIG，十分重要）。","初步诊断":"1. 烫伤（浅Ⅱ度；面积约5%（体表面积）；部位为右前臂及右手背；并评估有无吸入性损伤）\n（注：治疗依深度与面积决定门诊或住院，包括补液、创面处理及防治感染与瘢痕：①冷疗：现场或早期以流动冷水冲洗20~30分钟，伤后6小时内进行可降温、止痛、减轻损伤深度，十分重要；Ⅰ~Ⅱ度小面积烫伤冷疗后症状可缓解。②小面积浅度烫伤可门诊处理：Ⅰ度无需特殊处理，以止痛、冷疗为主；浅Ⅱ度需清创（生理盐水冲洗），水疱处理上，完整的小水疱予以保留（可防感染、保护创面并自行吸收），大水疱则低位剪破引流（需无菌操作，保留疱皮以保护创面）；创面可外用磺胺嘧啶银霜、银敷料或湿润烧伤膏，无菌敷料包扎，每1~2日换药1次；止痛可用布洛芬或对乙酰氨基酚；污染创面需做破伤风预防（TAT）。③大面积烫伤（儿童及老年人超过10~15%、深Ⅱ度以上或位于面颈、手足、会阴等特殊部位）需住院并由烧伤科处理：补液，烫伤休克时静脉补液，晶体液首选乳酸林格液，按二度与三度面积×体重×1.5ml加基础量2000ml计算，前8小时输入半量，监测尿量（维持30~50ml/h并据此调整，十分重要，既防休克也防补液过量致肺水肿）；创面处理包括清创、换药、抗感染以防脓毒症，深度创面需手术切痂植皮（Ⅲ度宜早期切痂加植皮，可防感染、促进愈合、减少瘢痕）；大面积或感染时全身患者广谱抗生素，以防创面脓毒症及败血症（重要死因）；营养支持需高蛋白、高热量（创面修复消耗大，十分重要）；并做好疼痛管理。④吸入性损伤（面部烫伤或密闭环境受伤者）需观察气道水肿，出现声嘶、喘鸣、呼吸困难属急症，可行气管插管或气管切开并转入ICU。⑤并发症：创面感染或脓毒症、瘢痕（深Ⅱ度以上愈合后易瘢痕增生，瘢痕防治包括压力衣及硅酮制剂，烧伤后宜早期开始，十分重要；关节部位瘢痕挛缩可致功能障碍，需康复）、电解质紊乱及应激性溃疡。⑥随访：创面换药并评估愈合情况，深Ⅱ度及Ⅲ度需转烧伤科手术；康复期行瘢痕治疗、压力治疗及功能锻炼，防止挛缩。急诊与烧伤科处理原则：早期冷疗，小面积门诊处理，大面积住院补液，吸入性损伤注意气道；儿童预防方面应加强教育，使热水远离儿童，十分重要。）","处理方案":"【药物治疗】\n1. 磺胺嘧啶银乳膏（10%）：涂于清洁后创面，厚约1-2mm，每日换药1-2次，疗程至创面愈合（约7-14天），用于浅Ⅱ°及以下创面抗菌、保痂；\n2. 头孢呋辛酯片 0.25g bid×5天，口服预防创面感染（青霉素过敏者改阿奇霉素片 0.5g qd×3天）；\n3. 布洛芬缓释胶囊 0.3g bid，疼痛明显时口服，连续使用不超过5天；\n4. 破伤风抗毒素 1500IU 肌注（皮试阴性后），适用于创面污染、深Ⅱ°以上或破伤风疫苗全程接种不详者。\n\n【一般治疗及生活指导】\n1. 创面保持清洁干燥，勿搔抓、勿自行撕扯水疱皮；直径<2cm水疱让其自行吸收，大疱由医生无菌穿刺抽液后保留疱皮覆盖创面；\n2. 患肢抬高（肢体烫伤者），避免创面受压、摩擦及浸水，敷料浸湿渗液后及时更换；\n3. 清淡高蛋白饮食，多食瘦肉、蛋、鱼、新鲜蔬果，忌辛辣刺激、烟酒，保证充足饮水和睡眠；\n4. 愈合期创面注意防晒，避免日光直晒，减少色素沉着及瘢痕增生；忌用偏方（酱油、牙膏、草木灰等）涂抹创面。\n\n【随诊要求】\n1. 用药3天后复诊评估创面愈合及感染情况；\n2. 出现创面红肿扩大、渗液增多变浑浊、恶臭、发热（体温≥38℃）或剧痛加重等感染征象时，立即就诊；\n3. 创面2周未愈合、愈合后瘢痕增生或影响关节功能者，转烧伤整形专科进一步诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1035,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3420aba8bed5d546db5cfa13cda396bc2a839ac389155c81e2825a26edbba1aa","pinyin":"tangshang","initials":"ts","setting":"out","caseName":"门诊病历903","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历903",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-28f129fedea51ed693a6","key":"v1-c9ccc21dfe2a3058|templates-28f129fedea51ed693a6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"挤压伤","category":"门诊病历模板","raw":{"name":"挤压伤","category":"门诊病历模板","case":{"case_name":"门诊病历904","templates":{"主诉":"肢体受压后肿痛1周","现病史":"患者1周前无明显诱因出现挤压伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者肢体受压后肿痛1周，需警惕挤压伤后横纹肌溶解、急性肾损伤及感染，急诊完善血常规检查了解有无感染、贫血及血液浓缩；完善尿常规检查了解有无肌红蛋白尿、血尿及管型，急诊完成；完善便常规检查了解有无应激性溃疡所致消化道出血；肌肉广泛损伤后钾、钠、钙等离子可显著异常，完善电解质检查排除电解质紊乱及高钾血症；完善肝肾功能检查评估有无挤压伤所致肝损伤及急性肾功能衰竭，入院即刻完成并动态复查；完善血糖、血脂检查了解代谢状态，为营养支持及用药提供依据；完善心电图检查了解有无高钾血症相关心律失常及心肌损伤表现，急诊完成；完善胸部X线片检查排除肋骨骨折、肺部感染及胸腔积液；完善腹部超声检查了解肝脾肾等实质脏器有无挫裂伤及腹腔积液情况。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 挤压伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防性抗感染（皮肤软组织挫裂、伤口污染时）：头孢呋辛酯片0.25g bid po×5天，或阿莫西林克拉维酸钾片0.375g tid po×5天（青霉素过敏者改用左氧氟沙星片0.5g qd po×5天）。\n2. 破伤风预防：伤后24小时内，破伤风抗毒素（TAT）1500IU肌注（需皮试，阳性者脱敏注射），或破伤风人免疫球蛋白250IU肌注（无需皮试，优先选用）。\n3. 消肿治疗：七叶皂苷钠片30mg bid po×7天，或迈之灵片（马栗种子提取物）300mg bid po×7天；局部张力高者可加用甘露醇注射液125ml q8h静滴×3天（需住院观察，门诊慎用）。\n4. 镇痛：洛索洛芬钠片60mg tid po×3-5天（餐后服），或布洛芬缓释胶囊0.3g bid po×3-5天；剧痛者可短期联用曲马多缓释片100mg q12h po×3天。\n\n【一般治疗及生活指导】\n1. 休息制动：患肢抬高（高于心脏水平）休息，局部制动，避免患肢负重及剧烈活动；早期（48小时内）予伤处冷敷，每次15-20分钟、每日3-4次，48小时后改热敷促进淤血吸收。\n2. 密切观察：每日观察患肢肿胀程度、皮肤颜色、温度、感觉及远端血运，如出现皮肤张力进行性增高、苍白或发绀、麻木刺痛、脉搏减弱，提示骨筋膜室综合征可能，需立即就医。\n3. 饮食与饮水：多饮水（每日2000-2500ml），予高蛋白、高维生素、易消化饮食，适量补充瘦肉、蛋、奶，促进组织修复；避免辛辣刺激及饮酒。\n4. 禁忌：伤后48小时内禁止热敷、按摩、揉搓及外涂活血化瘀药酒，以免加重肿胀出血；伤口未愈前避免沾水，保持敷料清洁干燥。\n\n【随诊要求】\n1. 2-3天后门诊复诊换药，评估伤口愈合及肿胀消退情况；缝线者按医嘱7-10天拆线。\n2. 伤后48小时内如出现尿量明显减少、尿液呈酱油色或茶色、肌肉剧痛伴乏力恶心，须立即急诊就诊，警惕挤压综合征及急性肾损伤。\n3. 大面积挤压伤者建议伤后3-7天复查血常规、肝肾功能、电解质及肌酸激酶（CK）、尿肌红蛋白，评估有无横纹肌溶解。\n4. 症状缓解后1-2周复诊，复查患肢功能恢复情况，必要时转康复科行功能锻炼；如出现局部红肿热痛加重或发热，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1036,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f97d7c6e68ad6ecc785273552206acc8f55cb2a0550134cdeb72e14b93cb2bbc","pinyin":"jiyashang","initials":"jys","setting":"out","caseName":"门诊病历904","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历904",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ccdfa2aebe524d50495e","key":"v1-c9ccc21dfe2a3058|templates-ccdfa2aebe524d50495e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑挫裂伤","category":"门诊病历模板","raw":{"name":"脑挫裂伤","category":"门诊病历模板","case":{"case_name":"门诊病历905","templates":{"主诉":"头部外伤后意识障碍伴呕吐2小时。","现病史":"患者于2小时前不慎从约2米高处坠落，头部着地，当即意识不清，呼之不应，持续约10分钟后意识渐恢复，但不能回忆受伤经过，伴恶心、呕吐胃内容物2次，非喷射性，无咖啡样物，无四肢抽搐、无大小便失禁。由120送入我院。发病以来未进食。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 96次/分，R 20次/分，BP 138/86mmHg。神志清楚，GCS评分14分（E4V4M6），对答部分切题，反应稍迟钝。双侧瞳孔等大等圆，直径约3mm，对光反射灵敏。右侧顶枕部可见约4cm×3cm头皮血肿，压痛明显，无活动性出血。颈软，无抵抗。双肺呼吸音清。心率96次/分，律齐。四肢肌力Ⅴ级，肌张力正常，病理征阴性。","辅助检查":"【必做】头颅CT平扫（急诊首选，明确有无脑挫裂伤、颅内血肿及颅骨骨折）、血常规、凝血功能；【其他】头颅MRI（CT阴性但症状持续或疑弥漫轴索损伤时，病情稳定后检查）、心电图。","初步诊断":"1. 脑挫裂伤（右侧顶枕部）\n（注：脑挫裂伤属颅脑损伤急症，有迟发血肿可能，建议急诊留观或住院观察，动态复查头颅CT，监测意识、瞳孔及生命体征变化。）","处理方案":"【药物治疗】\n1. 脑保护及神经营养：吡拉西坦片0.8g口服，每日3次，疗程4周；或胞磷胆碱钠胶囊0.2g口服，每日3次，疗程4周。\n2. 改善脑血流、防治脑血管痉挛（伴蛛网膜下腔出血者）：尼莫地平片30mg口服，每日3次，疗程2周，用药期间监测血压。\n3. 对症处理：头痛明显者可予对乙酰氨基酚片0.5g口服，必要时，每日不超过4次；恶心呕吐者予甲氧氯普胺片5mg口服，每日3次，症状缓解后停药。\n\n【一般治疗及生活指导】\n1. 伤后绝对卧床休息1~2周，保持环境安静，抬高床头15°~30°，避免情绪激动、剧烈咳嗽及用力排便。\n2. 饮食宜清淡易消化、富营养，多食鱼、蛋、瘦肉及新鲜蔬果，保证充足饮水，忌烟酒、辛辣刺激及浓茶咖啡。\n3. 3个月内避免重体力劳动、剧烈运动、高空作业及驾车，严防头部再次受撞击。\n4. 保证充足睡眠，避免长时间用脑及熬夜，注意保暖、预防感冒，防止感染诱发颅内压升高。\n\n【随诊要求】\n1. 用药期间若出现剧烈头痛、频繁呕吐、意识障碍加重、抽搐、肢体无力或言语不清，立即急诊就医。\n2. 伤后2周门诊复查头颅CT，评估脑水肿消退及血肿吸收情况；高龄或长期服用抗凝药物者遵医嘱提前复查。\n3. 症状持续或加重者1周内复诊；伤后3个月仍有头痛、头晕、记忆力减退等症状者，建议神经外科或神经内科门诊复查，必要时行头颅MRI及脑电图检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1037,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bb17345341671e3bb99ba0d974f82c92b6b5144826f2514d06ac3cb89e3b4688","pinyin":"naocuolieshang","initials":"ncls","setting":"out","caseName":"门诊病历905","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历905",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9a21f9a84f0d3d73b7ea","key":"v1-c9ccc21dfe2a3058|templates-9a21f9a84f0d3d73b7ea","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颅内血肿","category":"门诊病历模板","raw":{"name":"颅内血肿","category":"门诊病历模板","case":{"case_name":"门诊病历906","templates":{"主诉":"头部外伤后头痛、呕吐3小时，意识障碍加重1小时。","现病史":"患者于3小时前头部外伤（撞击硬物）后出现头痛、恶心，呕吐2次，为胃内容物，当时意识清楚；1小时前头痛加剧，渐出现嗜睡、呼之反应迟钝，家属诉其言语含糊、右侧肢体活动减少。无抽搐，无大小便失禁。既往无高血压病史，未服用抗凝药物。急来我院就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 88次/分，R 18次/分，BP 150/92mmHg。嗜睡状态，GCS评分12分（E3V4M5），呼唤可睁眼，言语含糊。双侧瞳孔等大等圆，直径约3mm，对光反射灵敏。左侧颞部可见头皮挫伤、肿胀，无活动性出血。右侧肢体肌力Ⅳ级，左侧Ⅴ级，右侧巴氏征（+），左侧（-）。颈软。","辅助检查":"【必做】头颅CT平扫（急诊！明确血肿部位、类型（硬膜外/硬膜下/脑内）、大小及中线移位情况）、血常规、凝血功能、血型及交叉配血（术前准备）；【其他】心电图、肝肾功能。","初步诊断":"1. 颅内血肿？（左侧颞部，硬膜外/硬膜下待CT明确）\n（注：颅内血肿可致脑疝危及生命，一旦CT证实占位效应明显或意识障碍进行性加重，需立即请神经外科会诊并急诊手术清除血肿。）","处理方案":"【药物治疗】\n1. 控制血压（防止再出血）：苯磺酸氨氯地平片5mg qd，血压控制在140/90mmHg以下，既往无高血压者维持收缩压100-120mmHg；若血压明显升高可加用缬沙坦胶囊80mg qd。\n2. 预防癫痫发作：丙戊酸钠缓释片500mg bid，疗程3-6个月（血肿累及皮层或术后患者），服药期间监测肝功能。\n3. 营养神经、促血肿吸收：胞磷胆碱钠片0.2g tid，疗程4周；可联用维生素B1片10mg tid、甲钴胺片0.5mg tid。\n4. 对症止痛：头痛明显时予对乙酰氨基酚片0.5g，每日不超过2g，疗程不超过3天；禁用阿司匹林、布洛芬等抗血小板及活血化瘀类药物。\n\n【一般治疗及生活指导】\n1. 休息：急性期绝对卧床休息2-4周，头部抬高15-30°，避免剧烈咳嗽、打喷嚏、用力排便及憋气等增加颅内压的动作；慢性硬膜下血肿钻孔引流术后患者2周内避免头部剧烈晃动。\n2. 饮食：高蛋白、高维生素、低盐低脂易消化饮食，多饮水，多食新鲜蔬菜水果，保持大便通畅，便秘者予乳果糖口服液15ml qd。\n3. 活动禁忌：3个月内避免重体力劳动、剧烈运动及乘坐颠簸车辆；禁烟酒、浓茶、咖啡；保持情绪平稳，避免急躁、屏气用力。\n4. 用药禁忌：禁用阿司匹林、氯吡格雷等抗血小板药及华法林等抗凝药（必须使用者须神经外科医师评估后调整），禁服丹参、三七、水蛭等活血化瘀类中成药。\n\n【随诊要求】\n1. 首诊后2周复查头颅CT评估血肿吸收情况，此后每4周复查1次头颅CT至血肿基本吸收或稳定。\n2. 1个月、3个月、6个月神经外科门诊复诊，评估神经功能（肌力、言语、认知）恢复及癫痫发作情况。\n3. 合并高血压者每日自测血压并记录，血压持续高于140/90mmHg或波动明显时随时复诊调整降压方案。\n4. 随访期间若出现头痛进行性加重、恶心呕吐、意识障碍、肢体无力、言语不清或抽搐发作，立即急诊就诊并复查头颅CT。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1038,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b2ac7f0ebfa24bb4987dd7e6d78322a6b4260b222521cb84a43a8d0b1177cb5b","pinyin":"luneixuezhong","initials":"lnxz","setting":"out","caseName":"门诊病历906","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历906",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-174884f2dc619362ab6b","key":"v1-c9ccc21dfe2a3058|templates-174884f2dc619362ab6b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"颅骨骨折","category":"门诊病历模板","raw":{"name":"颅骨骨折","category":"门诊病历模板","case":{"case_name":"门诊病历907","templates":{"主诉":"头部外伤后头痛伴右耳流血性液体2小时。","现病史":"患者于2小时前车祸致头部外伤，当时短暂意识不清（约数分钟），清醒后头痛明显，伴恶心，家属发现其右外耳道流出少量血性液体，无喷射性呕吐，无四肢抽搐，无大小便失禁。伤后未行特殊处理，急来我院就诊。发病以来精神差，未进食。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 92次/分，R 19次/分，BP 132/84mmHg。神志清楚，GCS 15分。双侧瞳孔等大等圆，对光反射灵敏。右颞部头皮肿胀、压痛，右外耳道可见血性液体流出，鼓膜窥视不清；乳突区无明显瘀斑（Battle征待观察）。鼻无溢液。颈软。四肢肌力Ⅴ级，病理征阴性。","辅助检查":"【必做】头颅CT平扫（薄层骨窗+脑窗，明确颅骨骨折部位、类型及有无合并颅内损伤）、血常规、凝血功能；【其他】颅底骨折伴脑脊液漏时行脑脊液漏出液葡萄糖定性检测；疑颅内感染时腰穿（慎行）。","初步诊断":"1. 颅骨骨折（右颞部，颅底骨折待排除）\n（注：右耳流血性液体需鉴别脑脊液耳漏（颅底骨折），建议急诊留观，预防性抗感染，禁止堵塞外耳道及用力擤鼻，动态观察，必要时请神经外科会诊。）","处理方案":"【药物治疗】\n1. 镇痛：头痛明显者予布洛芬缓释胶囊0.3g bid（饭后口服），疼痛缓解后即停，连续使用不超过5天；禁用阿司匹林及活血抗凝类药物，以免加重出血。\n2. 预防感染：闭合性骨折无颅内损伤者无需常规使用抗生素；开放性骨折或伴脑脊液鼻漏/耳漏者，予头孢呋辛酯片0.25g bid po×5～7天，对青霉素/头孢过敏者改用阿奇霉素片0.5g qd po×3天。\n3. 营养神经：予甲钴胺片0.5mg tid po×4周，促进颅神经及脑组织功能恢复。\n4. 对症处理：伴恶心、呕吐者予甲氧氯普胺片5mg tid po×3天；若出现剧烈头痛、喷射性呕吐、意识障碍等颅高压表现，须转神经外科住院治疗，不可仅在门诊口服脱水药延误病情。\n【一般治疗及生活指导】\n1. 休息：绝对卧床休息1～2周，床头抬高15°～30°，减少头部活动，避免低头、突然转头、用力咳嗽、屏气排便等增高颅内压的动作；3个月内避免剧烈运动及对抗性体育活动。\n2. 观察：家属密切观察患者意识、瞳孔及头痛呕吐变化，记录有无抽搐、言语不清、肢体无力；头痛进行性加重、频繁呕吐、嗜睡或昏迷时立即急诊就诊。\n3. 饮食：清淡易消化、高蛋白高维生素饮食，适量饮水，保持大便通畅（便秘者予乳果糖口服溶液15ml qd），忌辛辣刺激食物；伴脑脊液漏者尤须避免用力擤鼻、挖耳、捂鼻打喷嚏，保持耳鼻部清洁干燥，勿让液体流入耳道。\n4. 禁忌：禁烟酒；勿搔抓、按压或浸湿头皮伤口，拆线前保持敷料干燥清洁；避免服用含活血化瘀成分的中成药。\n【随诊要求】\n1. 1周后门诊复诊，复查头颅CT平扫，观察骨折线变化及有无迟发性颅内血肿；此后遵医嘱于3～6个月复查头颅CT评估骨折愈合情况。\n2. 伴脑脊液漏者，漏液多可于1～2周内自行停止；若持续超过2周或出现发热、头痛加重，及时至神经外科就诊，必要时行漏口修补手术。\n3. 复诊时携带本次CT片，由神经外科/神经内科专科医师评估后决定停药及恢复工作、运动的时间；若出现反复头痛、头晕、癫痫发作或记忆力下降等后遗症表现，应定期神经科随诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1039,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4cb920c4d2286cc3da64a86bdbece5368ffacaf6af73d6deea46f65d7f3593f0","pinyin":"luguguzhe","initials":"lggz","setting":"out","caseName":"门诊病历907","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历907",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e88f5bcdc70388f41aa5","key":"v1-c9ccc21dfe2a3058|templates-e88f5bcdc70388f41aa5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹部损伤","category":"门诊病历模板","raw":{"name":"腹部损伤","category":"门诊病历模板","case":{"case_name":"门诊病历908","templates":{"主诉":"腹部外伤后持续性腹痛2小时。","现病史":"患者于2小时前被车撞伤腹部（方向盘/护栏撞击上腹部），当即感上腹部剧烈疼痛，呈持续性，无放射，伴恶心，呕吐1次胃内容物，无咖啡样物，无便血，无发热。伤后无昏迷史。既往体健。急来我院就诊。发病以来精神紧张，未进食。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 100次/分，R 22次/分，BP 118/74mmHg。神志清楚，痛苦面容，屈曲体位。腹部平坦，上腹部可见皮肤擦伤及皮下瘀斑，全腹压痛，以上腹部为著，伴轻度肌紧张，反跳痛（±），肝浊音界存在，移动性浊音（-），肠鸣音减弱（约2次/分）。骨盆挤压试验（-）。","辅助检查":"【必做】血常规（动态复查）、血型及交叉配血、凝血功能、肝肾功能、血淀粉酶、尿常规；【影像学】腹部超声（FAST：探查腹腔积液/实质脏器损伤）、腹部CT平扫+增强（病情稳定时，评估实质脏器及空腔脏器损伤）；【其他】诊断性腹腔穿刺（腹穿抽得不凝血提示腹腔内出血）。","初步诊断":"1. 腹部闭合性损伤（实质脏器/空腔脏器损伤待排）\n（注：腹部损伤可能累及实质脏器（肝脾肾）或空腔脏器（肠管），有延迟破裂及腹腔感染风险，建议急诊留观或住院，动态监测生命体征、腹部体征及血红蛋白，必要时剖腹探查。）","处理方案":"【药物治疗】\n1. 抗感染（预防/治疗腹腔感染）：二代头孢菌素，头孢呋辛酯片0.25g bid×5天；可疑空腔脏器损伤或腹膜炎高危者联用甲硝唑片0.4g tid×5天。\n2. 对症止痛：非甾体类抗炎药，布洛芬缓释胶囊0.3g bid×3天；疼痛明显时可加用对乙酰氨基酚片0.5g 必要时tid（禁止腹部按压止痛、禁止使用强镇痛药掩盖病情）。\n3. 抑酸护胃（预防应激性溃疡）：质子泵抑制剂，奥美拉唑肠溶胶囊20mg qd×7天，晨起空腹口服。\n4. 促进胃肠功能恢复：双歧杆菌三联活菌胶囊2粒 tid×7天，与抗菌药物间隔2小时以上服用。\n【一般治疗及生活指导】\n1. 休息：伤后1周内以卧床休息为主，避免剧烈运动、提重物及重体力劳动；保持情绪平稳，避免剧烈咳嗽、用力排便等增加腹压动作。\n2. 饮食：伤后24～48小时内进清淡流质（米汤、藕粉、稀粥），忌牛奶、豆浆等产气食物；肠鸣音恢复、无腹胀后逐步过渡至半流质、软食，少量多餐，忌辛辣油腻及饮酒。\n3. 禁忌：伤后1周内禁止腹部按摩、热敷及剧烈腹肌锻炼；禁止饮酒、吸烟；注意保暖，防止呼吸道感染诱发咳嗽加重腹内压。\n4. 观察：每日自测体温，注意腹痛部位、性质及范围变化，警惕进行性腹胀、恶心呕吐、呕血、黑便、血尿等，发现异常及时就诊。\n【随诊要求】\n1. 若出现腹痛进行性加重、全腹压痛反跳痛、肌紧张、发热、呕血便血、休克表现（面色苍白、冷汗、心率增快），立即急诊就诊。\n2. 伤后48～72小时门诊复查血常规、腹部B超（必要时CT），动态评估腹腔积液及实质脏器损伤情况。\n3. 伤后1周门诊复诊，复查腹部体征及肝肾功能；疑胰腺损伤者加查血、尿淀粉酶及脂肪酶。\n4. 实质脏器（如脾、肝）损伤保守治疗者，需绝对卧床2～4周，定期复查B超或CT至损伤稳定，期间避免剧烈活动及对抗性运动至少3个月。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1040,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"29970b6709e6ae334e7b6eb7b38d021e7449aa5a63d5ec810718201be08a0383","pinyin":"fubusunshang","initials":"fbss","setting":"out","caseName":"门诊病历908","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历908",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1084d12c7c65da5167a3","key":"v1-c9ccc21dfe2a3058|templates-1084d12c7c65da5167a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝破裂","category":"门诊病历模板","raw":{"name":"肝破裂","category":"门诊病历模板","case":{"case_name":"门诊病历909","templates":{"主诉":"右上腹外伤后剧痛伴头晕2小时。","现病史":"患者于2小时前右上腹受钝器撞击后即感右上腹剧烈疼痛，持续性，向右肩部放射，伴头晕、心慌、口干、乏力，无恶心呕吐，无呕血便血。伤后精神渐差，由他人急送我院。既往体健，无肝炎肝硬化病史。发病以来未进食、未排尿。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 116次/分，R 24次/分，BP 92/60mmHg。神志清楚，精神萎靡，面色苍白，皮肤湿冷，毛细血管充盈时间延长。腹部膨隆，右上腹及右季肋部压痛明显，肌紧张，反跳痛（+），肝区叩击痛（+），移动性浊音（+），肠鸣音减弱。","辅助检查":"【必做】血常规（血红蛋白动态下降）、血型及交叉配血、凝血功能、肝肾功能、血淀粉酶；【影像学】腹部超声（FAST，见腹腔积液及肝包膜下/实质血肿）、腹部CT增强（病情相对稳定时明确损伤分级）；【其他】诊断性腹腔穿刺（抽出不凝血）。","初步诊断":"1. 肝破裂（失血性休克早期）\n（注：肝破裂可致大出血、失血性休克，属腹部损伤危重症，须立即急诊抢救：建立双通道快速补液、配血输血、抗休克，同时请普外科/肝胆外科会诊，多数需急诊手术或介入止血。）","处理方案":"【药物治疗】\n1. 保肝治疗：还原型谷胱甘肽片0.4g po tid×2周，或（对本品过敏者）多烯磷脂酰胆碱胶囊456mg po tid×2周，促进肝细胞修复。\n2. 止血支持：氨甲环酸片0.5g po tid×5天，抑制纤溶、稳定血肿；同时口服维生素K1片10mg po tid×1周，补充凝血原料。\n3. 预防感染：头孢呋辛酯片0.25g po bid×5天（头孢菌素过敏者改左氧氟沙星片0.5g po qd×5天），防治肝内血肿继发感染。\n4. 镇痛（必要时）：对乙酰氨基酚片0.5g po prn（每日不超过2g），禁用阿司匹林、布洛芬等非甾体抗炎药，以免加重出血。\n\n【一般治疗及生活指导】\n1. 绝对卧床休息1～2周，取平卧位，避免转侧及腹压骤增动作；3个月内禁止重体力劳动、负重及对抗性运动，防止血肿破裂或再出血。\n2. 饮食：高蛋白、高维生素、易消化软食或半流质，少量多餐，禁酒及油腻、辛辣、粗硬食物；保持大便通畅，避免用力排便、剧烈咳嗽、打喷嚏及屏气。\n3. 停用阿司匹林、氯吡格雷等抗血小板药物及活血化瘀类中成药，以免诱发出血；未经医师评估不得自行加用任何伤肝药物。\n4. 自我监测：每日测血压、心率，注意有无面色苍白、头晕、心慌，一旦出现腹痛进行性加重、腹胀、呕血、黑便或晕厥，立即急诊就医。\n\n【随诊要求】\n1. 1周后复查血常规（重点观察血红蛋白动态变化）及肝功能（ALT、AST、胆红素）。\n2. 2周后复查腹部超声，必要时行腹部CT评估肝内血肿及裂口愈合情况；此后每2～4周复查超声1次，直至血肿完全吸收（一般需4～8周）。\n3. 若期间出现发热、右上腹痛加剧或血压下降等表现，随时提前复诊；接受手术或介入治疗者，按医嘱按期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1041,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"95325820c730ddd7fcd86ba41e53d3cfb93dad4ea727f77d10084ce162a40d41","pinyin":"ganpolie","initials":"gpl","setting":"out","caseName":"门诊病历909","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历909",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e8300efbe0be6783f79b","key":"v1-c9ccc21dfe2a3058|templates-e8300efbe0be6783f79b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脾破裂","category":"门诊病历模板","raw":{"name":"脾破裂","category":"门诊病历模板","case":{"case_name":"门诊病历910","templates":{"主诉":"左上腹外伤后疼痛伴头晕1.5小时。","现病史":"患者于1.5小时前摔伤/撞击左上腹后即感左上腹持续性胀痛，向左肩部放射（Kehr征），伴头晕、乏力、心慌、面色苍白，无恶心呕吐，无呕血便血。伤后由家人急送我院。既往体健。发病以来精神差，未进食。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 118次/分，R 24次/分，BP 90/58mmHg。神志清楚，精神萎靡，面色苍白，四肢湿冷。腹部平，左上腹压痛明显，伴轻度肌紧张，反跳痛（±），左季肋部叩击痛（+），移动性浊音（+），肠鸣音减弱。","辅助检查":"【必做】血常规（血红蛋白及红细胞压积动态下降）、血型及交叉配血、凝血功能；【影像学】腹部超声（FAST：脾周及腹腔积液、脾破裂征象）、腹部CT增强（病情稳定时评估脾损伤分级）；【其他】诊断性腹腔穿刺（抽出不凝血）。","初步诊断":"1. 脾破裂（失血性休克早期）\n（注：脾破裂是腹部闭合性损伤最常见需手术的实质脏器损伤，出血凶猛，须立即急诊抗休克、配血输血并请普外科会诊，根据血流动力学及损伤分级决定手术（脾切除/脾修补）或保守治疗；血流动力学不稳定者禁行远途检查，直接送手术室。）","处理方案":"【药物治疗】\n1．预防感染：头孢呋辛酯片 0.25g bid 口服×5天；对头孢类过敏者改用阿奇霉素片 0.5g qd 口服×3天。\n2．镇痛：对乙酰氨基酚片 0.5g 口服，每日2~3次，疼痛时服用；禁用阿司匹林、布洛芬等影响血小板功能及凝血的药物，以防加重出血。\n3．促进止血：氨甲环酸片 0.5g tid 口服×3天（仅限伤后早期、无血栓及栓塞高危因素者；若出血量大、血红蛋白持续下降或血压不稳，应立即住院治疗）。\n4．通便：乳果糖口服溶液 15ml qd 口服，保持大便通畅，避免用力排便诱发腹压骤增致再出血。\n\n【一般治疗及生活指导】\n1．休息：伤后绝对卧床休息1~2周，尤其伤后72小时内严格卧床，避免下床走动、剧烈咳嗽、用力排便等增加腹压的动作；3个月内避免剧烈运动、重体力劳动、骑自行车及驾车（腹部易受撞击或挤压）。\n2．饮食：伤后24~48小时暂禁食或进少量流质，无腹痛腹胀加重后逐步过渡至易消化软食，多食富含膳食纤维食物，忌辛辣刺激及产气食物，保持大便通畅。\n3．禁忌：3个月内避免腹部受压、弯腰负重及对抗性运动；避免服用阿司匹林、氯吡格雷、华法林等抗凝抗血小板药物；注意保暖防感冒，避免剧烈咳嗽。\n4．病情观察：密切观察面色及脉搏，若出现头晕、心悸、冷汗、腹痛突然加重、左肩部放射痛（Kehr征）或晕厥，提示再出血可能，须立即急诊就诊。\n\n【随诊要求】\n1．伤后3~5天门诊复查血常规及腹部超声，评估血红蛋白变化及腹腔积液、脾周血肿情况。\n2．伤后1周、1个月复查腹部超声，必要时行腹部CT，观察脾周血肿吸收及脾脏愈合情况。\n3．伤后3个月复查，确认脾脏愈合、血肿吸收后再逐步恢复正常活动。\n4．随诊期间若腹痛加重、血红蛋白进行性下降或出现面色苍白、血压下降等休克征象，随时急诊就医，必要时转外科手术处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1042,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5c04272cc2e0d714974d1112931e954bd59f107ed834af84dce119ac34288330","pinyin":"pipolie","initials":"ppl","setting":"out","caseName":"门诊病历910","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历910",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1608d3b5f18be5bd5bd2","key":"v1-c9ccc21dfe2a3058|templates-1608d3b5f18be5bd5bd2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胰腺损伤","category":"门诊病历模板","raw":{"name":"胰腺损伤","category":"门诊病历模板","case":{"case_name":"门诊病历911","templates":{"主诉":"上腹疼痛伴腹胀1周","现病史":"患者1周前无明显诱因出现胰腺损伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者上腹疼痛伴腹胀1周、逐渐加重并伴乏力，完善血常规检查了解有无感染、贫血；上腹疼痛需与胰腺损伤、胰腺炎及消化道出血鉴别，完善便常规+潜血检查了解有无消化道出血；完善淀粉酶、脂肪酶检查明确有无胰腺损伤及胰腺炎所致腺体破坏，急诊完成并动态复查；完善肝功能检查评估有无胆道梗阻及肝细胞损伤，明确胰腺损伤是否累及胆道；胰腺位于腹膜后，完善腹部超声检查了解胰腺形态、胰周积液及胆道情况；对超声显示不清或怀疑胰腺断裂、血肿者，进一步完善腹部CT检查明确胰腺损伤分级及有无腹腔积液；患者上腹疼痛伴腹胀需排除胃十二指肠溃疡、胃炎及肿瘤，必要时完善胃镜/肠镜检查明确诊断；完善幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，指导抑酸及根除治疗方案；患者拟行有创诊治，完善凝血功能检查评估凝血状态、排除凝血功能障碍所致出血风险。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胰腺损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抑制胰液分泌：醋酸奥曲肽注射液 0.1mg 皮下注射 每8小时1次，连用5～7天（门诊注射室执行，可减少胰酶分泌、降低胰瘘及假性囊肿风险）。\n2. 抑酸护胃：奥美拉唑肠溶胶囊 20mg 口服 每日2次，或泮托拉唑钠肠溶片 40mg 口服 每日1次，疗程7～14天，抑制胃酸间接减少胰液分泌并预防应激性溃疡。\n3. 抗感染（预防胰腺及胰周感染）：左氧氟沙星片 0.5g 口服 每日1次，联合甲硝唑片 0.4g 口服 每日3次，疗程7天；对喹诺酮过敏者改用头孢地尼胶囊 0.1g 口服 每日3次。\n4. 解痉镇痛及对症：腹痛明显时予山莨菪碱片（654-2）10mg 口服 每日3次，禁用吗啡（诱发Oddi括约肌痉挛、加重胰管高压）；恢复进食后予胰酶肠溶胶囊 0.3g 口服 每日3次，餐后服用，促进消化。\n\n【一般治疗及生活指导】\n1. 急性期（伤后1～3天）暂禁食，予静脉补液维持水电解质及酸碱平衡；腹痛缓解、血淀粉酶下降后逐步过渡为低脂流质、低脂半流质饮食，少量多餐。\n2. 绝对卧床休息，避免搬动及腹部受压，伤后2～4周内避免剧烈运动、负重及腹部撞击（如驾车颠簸、对抗性运动）。\n3. 严格禁酒、禁暴饮暴食，伤后至少4周内低脂饮食，忌油炸、肥肉、浓肉汤等高脂高蛋白食物，以防诱发急性胰腺炎。\n4. 密切观察腹痛、腹胀、恶心呕吐变化，每日监测体温；如出现腹痛持续加重、腹肌紧张、高热寒战或休克征象，立即急诊就诊。\n\n【随诊要求】\n1. 3～5天后门诊复诊，复查血淀粉酶、脂肪酶、血常规及CRP，评估胰腺损伤恢复情况。\n2. 伤后1～2周复查腹部CT或超声，重点观察有无胰腺假性囊肿、胰瘘、胰周积液及感染等迟发并发症。\n3. 症状缓解后仍需定期随访，若再次出现中上腹疼痛、腰背部放射痛、恶心呕吐或发热，随时复诊或急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1043,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e5c45086ad9802a9e4b05f63d2e7fb4cad4df0a5a1176473e3925a87734e5393","pinyin":"yixiansunshang","initials":"yxss","setting":"out","caseName":"门诊病历911","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历911",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-afbc8fe71d443b3ad978","key":"v1-c9ccc21dfe2a3058|templates-afbc8fe71d443b3ad978","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胃肠破裂","category":"门诊病历模板","raw":{"name":"胃肠破裂","category":"门诊病历模板","case":{"case_name":"门诊病历912","templates":{"主诉":"突发腹痛伴腹膜刺激征1天","现病史":"患者1周前无明显诱因出现胃肠破裂相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者突发腹痛伴腹膜刺激征1天，高度怀疑胃肠破裂穿孔，急诊完善血常规检查了解感染程度及有无贫血；完善便常规+潜血检查了解有无消化道出血；急诊完善腹部CT检查明确有无膈下游离气体、腹腔积液及穿孔部位；完善腹部超声检查了解腹腔积液、肝脾胰肾及肠管情况，指导腹腔穿刺定位；完善淀粉酶、脂肪酶检查排除胰腺损伤、胰腺炎所致腹痛；完善肝功能检查评估有无肝胆损伤及肝功能损害；患者腹膜炎需与溃疡穿孔、肿瘤穿孔鉴别，病情稳定后必要时完善胃镜/肠镜检查明确穿孔病因；完善幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染，指导后续根除治疗；患者拟急诊手术，完善凝血功能检查评估凝血功能、排除凝血障碍所致术中出血风险。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胃肠破裂\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（覆盖肠道革兰阴性杆菌及厌氧菌）：头孢克肟胶囊 0.1g bid×7天，联合甲硝唑片 0.4g tid×7天；已手术者予头孢曲松钠 2g 静脉滴注 qd＋甲硝唑氯化钠注射液 0.5g 静脉滴注 bid，疗程7～14天，待体温及血象正常后改口服巩固。\n2. 抑酸治疗：奥美拉唑肠溶胶囊 20mg qd，早餐前30分钟口服，疗程4～6周，促进胃、十二指肠创面愈合及溃疡修复。\n3. 补液及营养支持：口服补液盐Ⅲ 250ml 少量多次分服，记录每日出入量；进食不足或持续胃肠减压者静脉输注葡萄糖氯化钠注射液、氯化钾及复方氨基酸注射液，维持水、电解质及酸碱平衡。\n4. 对症处理：肠痉挛性腹痛明显者予山莨菪碱片 10mg tid（青光眼、前列腺肥大者禁用）；禁用吗啡、哌替啶等强镇痛药，以免掩盖腹膜炎体征。\n\n【一般治疗及生活指导】\n1. 确诊后立即禁食禁水、持续胃肠减压，绝对卧床休息并取半卧位，尽快转急诊外科行剖腹探查、穿孔修补或肠切除吻合术，切忌延误手术时机。\n2. 术后禁食至肠蠕动恢复、肛门排气后，逐步由流质→半流质→少渣软食过渡，少量多餐，避免粗糙、辛辣、油腻、过冷过热食物及暴饮暴食。\n3. 出院后1个月内避免剧烈运动、重体力劳动及腹部挤压碰撞，避免用力咳嗽、用力排便等增加腹压的动作。\n4. 严格禁烟、禁酒，忌浓茶、咖啡等刺激性饮品；停用阿司匹林、布洛芬等非甾体抗炎药及糖皮质激素，防止诱发再穿孔或出血。\n\n【随诊要求】\n1. 出院后1周门诊复查，检查切口愈合、引流情况及有无腹腔感染，复查血常规、电解质、肝肾功能。\n2. 术后4～6周复查胃镜（胃、十二指肠穿孔者），评估创面愈合情况并行幽门螺杆菌检测，阳性者行四联疗法根除。\n3. 术后3个月、6个月复查腹部CT或立位腹平片，评估吻合口愈合及腹腔情况；期间若出现腹痛加剧、发热、呕血、黑便、腹胀或停止排气排便，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1044,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c5643c35f734da95c99b2a18532239cf2c93d069e7054796adefe4c126e6c646","pinyin":"weichangpolie","initials":"wcpl","setting":"out","caseName":"门诊病历912","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历912",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5af29f6a6b423ea65a80","key":"v1-c9ccc21dfe2a3058|templates-5af29f6a6b423ea65a80","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾损伤","category":"门诊病历模板","raw":{"name":"肾损伤","category":"门诊病历模板","case":{"case_name":"门诊病历913","templates":{"主诉":"腰部外伤后疼痛伴全程肉眼血尿1小时。","现病史":"患者于1小时前从高处坠落/腰部受撞击后出现右侧腰部疼痛，持续性胀痛，伴全程肉眼血尿，尿色鲜红，无尿频尿急尿痛，无发热、无恶心呕吐，无昏迷。伤后未行特殊处理，急来我院就诊。发病以来精神可。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.7℃，P 96次/分，R 20次/分，BP 124/80mmHg。神志清楚，查体合作。右侧腰部稍膨隆，右肾区压痛（+），肾区叩击痛（+），右腰部及肋腹部皮肤可见擦伤及瘀斑，无包块触及。腹部平软，无压痛反跳痛，移动性浊音（-）。膀胱区无膨隆。","辅助检查":"【必做】尿常规（红细胞满视野）、血常规（动态复查）、肾功能、血型及交叉配血；【影像学】泌尿系CT平扫+增强（首选，明确肾损伤分级、有无造影剂外溢及合并其他脏器损伤）、腹部超声；【注意】单纯肾挫伤血尿可自行消失，持续血尿或血压下降提示严重损伤。","初步诊断":"1. 肾损伤（右侧，分级待CT）\n（注：肾损伤按CT分级Ⅰ~Ⅴ级，多数Ⅰ~Ⅲ级可保守治疗（绝对卧床2周、补液、抗感染、监测生命体征及血尿）；Ⅳ~Ⅴ级或血流动力学不稳定需介入栓塞或手术，建议请泌尿外科会诊并住院观察。）","处理方案":"【药物治疗】\n1. 病因治疗：立即停用可疑肾毒性药物（非甾体抗炎药、氨基糖苷类、造影剂、含马兜铃酸中草药等）；存在呕吐、腹泻、大汗等血容量不足因素者予口服补液盐Ⅲ250ml tid，必要时生理盐水500ml静滴qd，纠正低血容量，疗程3-5天。\n2. 碱化尿液（适用于药物性、肌红蛋白性及尿酸所致肾损伤）：碳酸氢钠片1.0g po tid×3-7天，使尿pH维持在6.5-7.0，监测血电解质及血气。\n3. 利尿消肿（伴少尿、双下肢水肿或容量负荷过重时）：呋塞米片20mg po qd，据尿量及水肿程度调整剂量，疗程3-5天，注意复查血钾、血钠，防止低钾血症及低血容量。\n4. 降压保肾（合并高血压者）：苯磺酸氨氯地平片5mg po qd，血压目标＜130/80mmHg，疗程按血压控制情况维持，定期监测血肌酐、尿蛋白。\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，避免劳累、剧烈运动及熬夜，保证充分睡眠。\n2. 饮食：低盐饮食（每日食盐＜5g），优质低蛋白饮食（每日0.8g/kg，以鸡蛋、牛奶、瘦肉为来源）；限制高钾食物（香蕉、橙子、土豆、深色蔬菜）；水肿者限制液体摄入，每日入量=前日尿量+500ml。\n3. 禁忌：停用一切肾毒性药物及成分不明的保健品、中草药；避免使用非甾体抗炎药（布洛芬、双氯芬酸等）；禁烟、禁酒。\n4. 自我监测：每日记录尿量、血压、体重，观察尿色变化及水肿消退情况。\n【随诊要求】\n1. 3-5天后复诊复查血肌酐、尿素氮、电解质、尿常规，评估肾功能恢复情况。\n2. 出现少尿（24h尿量＜400ml）、无尿、水肿加重、呼吸困难、心悸肢麻（高钾血症表现）或血肌酐进行性升高者，立即急诊就诊。\n3. 肾功能恢复或稳定后每月复查肾功能、尿常规，随访3-6个月；高血压、糖尿病等基础病者随诊并严格控制原发病。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1045,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1f8a824a0287de4524ecfee111b53d7f64dd67cafc68e74894e4f07c31fe9463","pinyin":"shensunshang","initials":"sss","setting":"out","caseName":"门诊病历913","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历913",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-475c592931e55bd7062f","key":"v1-c9ccc21dfe2a3058|templates-475c592931e55bd7062f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输尿管损伤","category":"门诊病历模板","raw":{"name":"输尿管损伤","category":"门诊病历模板","case":{"case_name":"门诊病历914","templates":{"主诉":"腰部疼痛伴血尿1周","现病史":"患者1周前无明显诱因出现输尿管损伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腰部疼痛伴血尿1周为主诉就诊，需警惕输尿管损伤所致出血与尿路梗阻，入院即刻完善尿常规检查，了解有无镜下或肉眼血尿、有无脓尿，明确泌尿系出血及感染情况；完善血常规检查，评估失血程度及有无贫血，并了解白细胞及中性粒细胞比例以排除合并感染；患者轻度乏力、进食一般，完善便常规及肝肾功能检查，排除消化道隐性出血及肝肾功能不全，为后续用药与可能的手术麻醉提供安全性依据；完善血糖、血脂及电解质检查，了解基础代谢状况，排除糖尿病及水电解质紊乱，评估机体对创伤和手术的耐受能力；查心电图及胸部X线片，评估心脏基础状态与心肺功能，排除心律失常、心肌缺血及肺部感染，为麻醉与手术风险评估提供依据；本次发病以腰腹痛伴血尿为核心表现，腹部超声作为首选筛查手段，了解双肾、输尿管上段有无积水、尿性囊肿及腹膜后积液，明确有无尿路梗阻及损伤侧别；必要时病情稳定后完善腹部增强CT或CT尿路成像，明确输尿管损伤的部位、程度及尿外渗范围，指导是否需手术修复；如影像提示肾积水明显或诊断仍不明确，进一步行膀胱镜及逆行输尿管造影，明确损伤节段并鉴别血凝块堵塞、结石等所致梗阻；此外，根据病情需要选择相应检查，如合并腹膜后感染时完善血培养及尿培养以明确病原并指导抗生素应用，出现肾积水加重时定期复查泌尿系超声评估积水动态变化。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 输尿管损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染（预防泌尿系感染）：头孢呋辛酯片 0.25g bid×5～7天；对头孢菌素过敏者改用左氧氟沙星片 0.5g qd×5天。\n2. 缓解输尿管痉挛、减轻腰痛：黄酮哌酯片（泌尿灵）0.2g tid×5天；或间苯三酚片 80mg tid×5天。\n3. 止血（伴肉眼血尿时）：氨甲环酸片 0.5g tid×3～5天，血尿消失后停药。\n4. 碱化尿液：碳酸氢钠片 1.0g tid×5天，减轻酸性尿液对损伤处黏膜的刺激。\n\n【一般治疗及生活指导】\n1. 休息：损伤后1～2周卧床休息或静养，避免剧烈运动、负重及长时间久坐久站，防止损伤处再出血或移位。\n2. 饮食：清淡易消化饮食，多饮水，每日2000～3000ml，稀释尿液减少刺激并促进血尿排出；忌辛辣、油腻刺激性食物，戒烟酒。\n3. 观察病情：每日注意观察尿液颜色及尿量，少量血尿多可自行缓解；若血尿持续加重或出现腰腹部剧痛、发热、恶心呕吐，提示合并感染或梗阻，应及时就医。\n4. 禁忌：避免憋尿，保持排尿通畅；避免自行服用影响凝血功能的药物（如阿司匹林、华法林等），确需使用须咨询医师。\n\n【随诊要求】\n1. 1～2周后门诊复诊，复查尿常规及泌尿系超声，评估血尿消退及有无肾积水。\n2. 若已留置双J管，遵医嘱于术后4～6周返院行膀胱镜下拔管，拔管后继续随访。\n3. 2～3个月后复查泌尿系CT尿路造影（CTU）或静脉肾盂造影（IVU），评估输尿管损伤愈合情况及有无狭窄。\n4. 随访期间若出现持续肉眼血尿、发热（≥38.5℃）、腰腹痛加剧或尿量减少等异常，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1046,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e5f4abba47ef940838fe18fe6eb2bc5533a906e075c8a12f54d95c2e4deb5006","pinyin":"shuniaoguansunshang","initials":"sngss","setting":"out","caseName":"门诊病历914","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历914",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2af3d58962aeeeb1374a","key":"v1-c9ccc21dfe2a3058|templates-2af3d58962aeeeb1374a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膀胱损伤","category":"门诊病历模板","raw":{"name":"膀胱损伤","category":"门诊病历模板","case":{"case_name":"门诊病历915","templates":{"主诉":"下腹疼痛伴血尿1周","现病史":"患者1周前无明显诱因出现膀胱损伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以下腹疼痛伴血尿1周为主诉就诊，符合膀胱损伤的常见表现，入院即刻完善尿常规检查，了解血尿程度及有无脓尿，明确泌尿系出血与感染情况；完善尿培养检查，明确有无合并尿路感染及病原菌种类，指导抗生素选择；完善肾功能及电解质检查，评估尿液外渗及引流是否影响肾功能，排除肾功能不全与电解质紊乱，为补液及用药提供依据；患者为男性，完善前列腺特异性抗原检查，鉴别前列腺增生或前列腺癌所致下尿路症状与血尿；本次下腹疼痛、血尿明显，首选泌尿系超声检查，了解膀胱充盈情况、膀胱壁连续性、有无盆腔积液及上尿路积水，明确有无尿外渗及尿路梗阻；查KUB平片，了解盆腔有无骨折碎片、异物及阳性结石，排除骨盆骨折或结石所致血尿；必要时急诊完善CT尿路成像，明确膀胱破裂的部位、类型（腹膜内型或腹膜外型）及尿外渗范围，为是否手术修补及留置导尿方案提供直接依据；若影像提示膀胱破裂或排尿困难持续，病情稳定后行尿流动力学检查，评估膀胱储尿与排尿功能，了解有无神经源性膀胱及下尿路梗阻；必要时行膀胱镜检查，直视下明确膀胱黏膜裂伤、血凝块及瘘口位置，同时鉴别膀胱肿瘤所致血尿；完善前列腺液常规检查，排除前列腺炎所致下腹不适与血尿。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 膀胱损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防/控制感染（首选）：头孢呋辛酯片0.25g bid×5~7天（头孢菌素类，青霉素过敏者慎用；肾功能不全者根据患者具体情况制定个体化方案减量）；或左氧氟沙星片0.5g qd×5天（喹诺酮类，孕妇及18岁以下禁用）。\n2. 止血：血尿明显者予氨甲环酸片0.5g tid×3~5天，或云南白药胶囊0.5g tid×3天，血尿转清后停用。\n3. 解痉镇痛：膀胱痉挛、尿频尿急明显者予黄酮哌酯片0.2g tid×5~7天，或索利那新片5mg qd；疼痛明显者加用布洛芬缓释胶囊0.3g bid（餐后服用，按需）。\n4. 促进黏膜修复：维生素C片0.2g tid×7天，配合大量饮水。\n【一般治疗及生活指导】\n1. 休息：伤后3~5天以卧床休息为主，1周内避免剧烈运动、重体力劳动及腹部挤压碰撞，防止继发出血。\n2. 饮食：清淡易消化饮食，每日饮水2000~2500ml，勤排尿、勿憋尿，以增加尿量冲刷膀胱、稀释血尿；忌辛辣刺激、忌饮酒、忌浓茶咖啡。\n3. 护理：保持会阴部清洁干燥，勤换内裤；留置导尿管者保持引流管通畅，妥善固定，避免牵拉、扭曲、受压及返流。\n4. 禁忌：无医生评估前暂停阿司匹林、华法林等抗凝及抗血小板药物；伤后若出现明显腹痛腹胀、排尿困难，未排除膀胱破裂及腹内脏器损伤前应禁食水并尽快就医，禁止驾车。\n【随诊要求】\n1. 治疗期间若出现肉眼血尿加重、尿潴留、腹痛腹胀加剧、发热寒战等，立即急诊就诊。\n2. 留置导尿管者遵医嘱每2周更换导尿管，定期复查尿常规；拔管前先行夹管训练（每2~3小时开放1次）。\n3. 伤后2~4周门诊复查尿常规、泌尿系彩超，评估膀胱损伤愈合及血尿消退情况；持续血尿或排尿异常者转泌尿外科专科诊治，必要时行膀胱镜检查。\n4. 恢复期避免剧烈运动和憋尿，如反复出现血尿、排尿疼痛、尿频尿急等不适，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1047,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"80f4c4230b1f48ac7441627a1b2b127c40637c978a9dd0329b0806e013ade13f","pinyin":"pangguangsunshang","initials":"pgss","setting":"out","caseName":"门诊病历915","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历915",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-61c9a63494cd7321b9b8","key":"v1-c9ccc21dfe2a3058|templates-61c9a63494cd7321b9b8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿道损伤","category":"门诊病历模板","raw":{"name":"尿道损伤","category":"门诊病历模板","case":{"case_name":"门诊病历916","templates":{"主诉":"骑跨伤后尿道口滴血、排尿困难2小时。","现病史":"患者于2小时前骑跨于硬物（如车架、栏杆）上会阴部受撞击，当即感会阴部疼痛，尿道口滴出鲜血，之后出现排尿困难、尿意频繁但排不出尿，无下腹剧痛、无恶心呕吐，无发热。伤后未行特殊处理，急来我院就诊。发病以来精神可。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 92次/分，R 19次/分，BP 124/80mmHg。神志清楚，查体合作。会阴部可见瘀斑、轻度肿胀，尿道口有血性分泌物，无活动性出血。阴茎、阴囊无明显肿胀及血肿。耻骨上区轻压痛、叩诊呈浊音（膀胱充盈），无腹膜刺激征。骨盆挤压试验（-）。","辅助检查":"【必做】尿常规、血常规；【影像学】逆行尿道造影（明确尿道损伤部位及程度，疑尿道断裂时）、骨盆X线片或CT（排除骨盆骨折，因骨盆骨折常合并后尿道损伤）；【注意】诊断明确前禁止试插导尿管（可加重损伤或使不全断裂变成完全断裂）。","初步诊断":"1. 尿道损伤（前尿道，骑跨伤）\n（注：尿道损伤可致尿潴留、尿道狭窄等并发症，建议请泌尿外科会诊：能排尿且无造影剂外溢者可保守；尿道断裂者行尿道会师术或造瘘，留置导尿者妥善固定。）","处理方案":"【药物治疗】\n1. 预防感染（首选第二代头孢菌素）：头孢呋辛酯片0.25g bid×5天；青霉素过敏者改左氧氟沙星片0.5g qd×5天。\n2. 镇痛消肿：布洛芬缓释胶囊0.3g bid×3~5天（餐后服）。\n3. 减轻局部水肿、促进血肿吸收：地奥司明片0.9g bid×7天；肉眼血尿明显者加用氨甲环酸片0.5g tid×3天。\n4. 改善排尿症状：坦索罗辛缓释胶囊0.4mg qd×2周（适用于存在排尿困难者）。\n【一般治疗及生活指导】\n1. 伤后卧床休息1~3天，2~4周内避免久坐、骑跨、剧烈运动及重体力劳动。\n2. 多饮水，每日2000~2500ml，勤排尿以稀释尿液、减少对尿道创面的刺激；忌辛辣刺激饮食，戒烟酒。\n3. 留置导尿管者：引流袋低于膀胱水平，每日清洗尿道口并消毒，定期更换引流袋，保持引流通畅。\n4. 保持大便通畅，避免用力排便；2周内禁止性生活，恢复后动作轻柔。\n【随诊要求】\n1. 3~5天后复诊，复查尿常规，评估血尿及排尿情况。\n2. 2周后复诊行尿道造影或膀胱尿道镜检查，评估尿道愈合情况及有无尿道狭窄。\n3. 拔除导尿管后如出现尿线变细、排尿费力、排尿困难加重，及时返院就诊行尿道扩张评估。\n4. 如出现发热、寒战、会阴部剧痛或引流不畅等感染或梗阻征象，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1048,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8bf2a7a86cd050666e6a03436be1941e13c733765a3e08cf4dd6425330b0bd8c","pinyin":"niaodaosunshang","initials":"ndss","setting":"out","caseName":"门诊病历916","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历916",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7323aa53734c72ce825f","key":"v1-c9ccc21dfe2a3058|templates-7323aa53734c72ce825f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴茎损伤","category":"门诊病历模板","raw":{"name":"阴茎损伤","category":"门诊病历模板","case":{"case_name":"门诊病历917","templates":{"主诉":"阴茎肿痛伴瘀斑1周","现病史":"患者1周前无明显诱因出现阴茎损伤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴茎肿痛伴瘀斑1周为主诉就诊，考虑阴茎损伤（需警惕阴茎折断、皮下血肿及尿道损伤），入院即刻完善血常规检查，了解有无失血性贫血及白细胞升高，评估出血程度并排除继发感染；完善尿常规检查，了解有无血尿，明确是否合并尿道损伤；完善便常规、肝肾功能、血糖及血脂检查，排除消化道隐性出血、肝肾功能不全及糖脂代谢异常，为可能的手术及麻醉提供安全性依据；完善电解质检查，排除水电解质紊乱，评估机体应激状态下的内环境稳定性；查心电图及胸部X线片，评估心肺基础功能，排除心律失常及肺部感染，为急诊手术麻醉风险评估提供依据；本次阴茎肿痛伴瘀斑，完善阴茎彩色多普勒超声检查，了解有无白膜破裂、海绵体血肿范围及阴茎背血管损伤，明确损伤部位与程度；完善腹部超声检查，了解双肾、膀胱及有无尿潴留，排除合并下尿路及上尿路损伤；必要时急诊行阴茎海绵体造影或MRI检查，明确白膜破裂口位置及血肿与尿道的关系，指导手术修补方式；若患者出现排尿困难、尿道口滴血或超声提示尿道连续性中断，进一步行尿道造影，明确尿道损伤部位及有无尿外渗，鉴别单纯海绵体损伤与合并尿道断裂；根据病情需要选择相应检查，如血肿进行性增大或出现感染征象，及时复查血常规及超声评估血肿演变，必要时行血肿穿刺液细菌培养以指导抗感染治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 阴茎损伤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染（开放性损伤、挫裂伤或伤口污染者）：头孢呋辛酯片0.25g口服，每日2次，连用5～7天；伤口污染较重者加用甲硝唑片0.4g口服，每日3次，连用5天。\n2. 止痛消肿：布洛芬缓释胶囊0.3g口服，每日2次，疼痛明显时服用，连用3～5天。\n3. 减轻水肿、促进血肿吸收：迈之灵片（马栗种子提取物）300mg口服，每日2次，连用7天。\n【一般治疗及生活指导】\n1. 休息与体位：急性期卧床休息为主，避免久坐久站；穿宽松棉质内裤并用丁字带或纱布托起阴囊、阴茎，减少下垂牵拉。\n2. 局部冷热敷：伤后24～48小时内局部冷敷（每次15～20分钟，每日3～4次），48小时后改温热敷促进淤血吸收；血肿明显者72小时内禁止热敷，禁止用力按摩揉搓。\n3. 禁忌事项：绝对避免性刺激、手淫及性生活至少2周（缝合或损伤重者延长至4周），夜间阴茎勃起诱发疼痛、继发出血时可采取侧卧屈膝体位缓解；忌烟酒及辛辣刺激饮食，多饮水、多食粗纤维食物保持大便通畅，避免用力排便及骑跨、剧烈运动。\n4. 观察要点：每日观察阴茎肿胀、皮肤颜色及排尿情况，排尿困难时勿用力憋尿。\n【随诊要求】\n伤后3天复诊，评估伤口、血肿及排尿情况；伤后7～10天复诊复查愈合情况并按医嘱拆线；伤后4周复诊行阴茎海绵体彩色多普勒超声，评估有无海绵体损伤及勃起功能；如出现阴茎异常勃起（持续勃起超过4小时）、剧烈疼痛、血尿、排尿困难或伤口红肿流脓，应立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1049,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"298db27672656e5c8f0679253f12bbd815446d9a0dc9285a3c4bdb6847a8dc79","pinyin":"yinjingsunshang","initials":"yjss","setting":"out","caseName":"门诊病历917","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历917",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f196460bf98bcda7d64c","key":"v1-c9ccc21dfe2a3058|templates-f196460bf98bcda7d64c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"手外伤","category":"门诊病历模板","raw":{"name":"手外伤","category":"门诊病历模板","case":{"case_name":"门诊病历918","templates":{"主诉":"右手掌切割伤伴出血、活动受限1小时。","现病史":"患者于1小时前操作刀具时被割伤右手掌，伤口出血较多，自行按压止血后出血减少，自觉右手示指屈曲受限，无麻木感，无昏迷。伤后未行清创缝合，急来我院就诊。发病以来精神紧张。既往无糖尿病、无凝血功能障碍病史。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 88次/分，R 18次/分，BP 120/78mmHg。神志清楚，查体合作。右手掌中部可见长约3cm斜行裂伤，边缘整齐，深达肌腱层，伤口内可见屈指肌腱断端，活动性出血不明显，伤口污染轻。右手示指不能主动屈曲远侧指间关节及近侧指间关节，被动活动正常；示指掌侧及指端感觉正常；右手诸指末梢血运良好，毛细血管充盈正常。","辅助检查":"【必做】手部X线片（排除骨折及异物存留）；【其他】血常规（出血多或疑感染时）、破伤风抗毒素皮试（深部污染伤口）。","初步诊断":"1. 右手掌切割伤伴屈指肌腱断裂（示指）\n（注：肌腱断裂需手术修复，建议尽快清创并一期肌腱吻合（伤后6~8小时内），术后石膏固定于功能位，康复期防治肌腱粘连。）","处理方案":"【药物治疗】\n1. 抗感染：开放性手外伤（污染创口）首选一代头孢菌素，头孢氨苄胶囊0.5g qid×5天；对头孢或青霉素过敏者选用克林霉素胶囊0.3g tid×5天。\n2. 破伤风预防：创口深、污染重或破伤风免疫史不全者，予破伤风抗毒素（TAT）1500IU 肌注一次（需皮试）；或破伤风人免疫球蛋白250IU 肌注一次，无需皮试。\n3. 镇痛：疼痛明显者予布洛芬缓释胶囊0.3g bid×3-5天，或对乙酰氨基酚片0.5g 口服，疼痛时服，每日不超过3次。\n4. 消肿：闭合性损伤肿胀明显者予七叶皂苷钠片30mg bid×5-7天，或地奥司明片0.9g bid×7天。\n\n【一般治疗及生活指导】\n1. 休息与固定：患肢抬高（高于心脏水平）以利消肿，石膏或支具制动1-2周，避免负重提物；遵医嘱按时换药，保持敷料干燥清洁，每日观察指端颜色、温度、感觉及毛细血管充盈情况。\n2. 饮食：高蛋白、高维生素饮食，适量补充瘦肉、鱼、蛋等优质蛋白及富含维生素C的新鲜蔬果，多饮水，忌烟酒及辛辣刺激食物。\n3. 活动：制动期满后，在医师指导下循序渐进进行手指主动/被动屈伸功能锻炼，防止肌腱粘连及关节僵硬；创口愈合前避免患手沾水、接触脏物及重体力劳动。\n4. 禁忌：伤后24小时内禁止热敷、按摩及用力揉搓，以免加重出血肿胀；禁止自行拆除敷料、抓挠创口；禁止吸烟（吸烟收缩血管，影响血运及创口愈合）。\n\n【随诊要求】\n1. 伤后或术后3-5天复诊换药，观察创口有无红肿、渗液、异味等感染征象；无特殊约10-14天复诊拆线。\n2. 若出现患指剧烈疼痛、麻木进行性加重、皮温发凉、指端发绀或发热，应立即复诊。\n3. 合并肌腱、神经损伤者，制动结束后（约3-4周）按时复诊评估功能恢复情况，并行康复理疗，之后定期复查至手部功能基本恢复。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1050,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"279c512f94735842ece2782e1d97bd6241f2112381686e1fb2093240888e1af7","pinyin":"shouwaishang","initials":"sws","setting":"out","caseName":"门诊病历918","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历918",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bdb822db2f6479d15cf9","key":"v1-c9ccc21dfe2a3058|templates-bdb822db2f6479d15cf9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"断指再植","category":"门诊病历模板","raw":{"name":"断指再植","category":"门诊病历模板","case":{"case_name":"门诊病历919","templates":{"主诉":"左手示指离断1小时。","现病史":"患者于1小时前工作时被机器（电锯/冲床）切断左手示指，离断指体完整，创面出血较多，已用干净布加压包扎，离断指体由家属用干净纱布包裹置于塑料袋中低温保存（未直接接触冰块/冰水）。伤后无昏迷，无其他部位外伤。急来我院就诊。既往体健，无糖尿病、血管疾病史，吸烟史10年（每日10支）。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 96次/分，R 19次/分，BP 126/80mmHg。神志清楚，急性痛苦面容。左手示指于近侧指间关节平面完全离断，残端创面整齐，活动性出血不明显（已加压包扎），离断指体外观完整、无碾压碎裂。左手中环小指及拇指活动、感觉、血运正常。","辅助检查":"【必做】手部X线片（残端及离断指体，明确骨损伤平面）、血常规、凝血功能、血型；【其他】心电图、胸片（高龄或全麻术前评估）。","初步诊断":"1. 左手示指完全离断（近侧指间关节平面）\n（注：断指再植有严格时限（一般热缺血6~8小时内），应尽快转送有显微外科条件的医院；离断指体正确保存（干燥冷藏，4℃左右，禁直接浸入液体或冷冻）；吸烟影响血管吻合后通畅率，术后需严格戒烟。）","处理方案":"【药物治疗】\n1. 预防感染：头孢呋辛酯片0.25g bid×7天（头孢过敏者改用克林霉素胶囊0.3g tid×7天），餐后服用。\n2. 抗血小板、抗血管痉挛：阿司匹林肠溶片100mg qd×14天，联合罂粟碱片30mg tid×7天，餐后服用，注意观察有无出血倾向。\n3. 改善微循环：己酮可可碱缓释片400mg bid×7天（或复方丹参滴丸10粒 tid×7天），促进再植指血供恢复。\n4. 镇痛：洛索洛芬钠片60mg tid，疼痛明显时服用，疗程不超过3-5天。\n\n【一般治疗及生活指导】\n1. 患肢严格制动、绝对禁烟（尼古丁引起血管痉挛可致再植指坏死），并抬高患肢（高于心脏水平）以利于静脉回流、减轻肿胀；注意保暖，避免寒冷刺激及情绪激动。\n2. 禁止剧烈活动、提重物及患手负重，避免碰撞、牵拉再植指；保持敷料清洁干燥，勿自行揭开换药。\n3. 每日观察再植指末梢颜色、皮温及张力：若出现指体变苍白、变暗紫、皮温明显下降或肿胀急剧加重，为血管危象表现，须立即返院急诊处理。\n4. 饮食以高蛋白、高维生素、易消化食物为主（如瘦肉、蛋、鱼、新鲜蔬果），忌辛辣刺激性食物及咖啡、浓茶。\n\n【随诊要求】\n1. 术后第1周每2-3天门诊复诊换药、评估再植指血运及伤口情况。\n2. 术后10-14天门诊拆线；术后第4周复查X线片，评估骨折愈合及内固定情况。\n3. 术后3-6个月门诊复查，评估指体成活、感觉恢复及关节功能，并遵医嘱逐步进行主动与被动功能锻炼及康复理疗。\n4. 如出现再植指颜色、皮温异常或伤口红肿、渗液、疼痛加重等，随时急诊或门诊就诊，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1051,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"992d05a41f27471207fdf960d082f135459bac9f66237c34e0080f8cfac3548a","pinyin":"duanzhizaizhi","initials":"dzzz","setting":"out","caseName":"门诊病历919","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历919",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0fa7bf5fa6ebda4f2b33","key":"v1-c9ccc21dfe2a3058|templates-0fa7bf5fa6ebda4f2b33","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"指甲损伤","category":"门诊病历模板","raw":{"name":"指甲损伤","category":"门诊病历模板","case":{"case_name":"门诊病历920","templates":{"主诉":"右拇指指甲被砸伤后疼痛、甲下瘀血2小时。","现病史":"患者于2小时前右拇指被重物砸伤，当即指甲处剧烈疼痛，甲下迅速出现瘀血呈紫黑色，范围约占甲面1/2，指端胀痛明显，无破口、无指骨异常活动感，无麻木，无昏迷。伤后自行冷敷处理，疼痛无明显缓解，今日来我院门诊就诊。发病以来精神可。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 118/76mmHg。神志清楚，查体合作。右拇指甲板完整，甲下可见范围约1/2甲面的暗紫色瘀血，甲周轻度肿胀、压痛（+），无甲缘翘起，甲根无溢脓；指端痛温觉正常，末梢血运良好，毛细血管充盈正常。","辅助检查":"【必做】右拇指X线片（排除末节指骨骨折，甲下血肿伴指端叩击痛明显者应高度警惕）；【其他】一般无需其他化验。","初步诊断":"1. 右拇指甲下血肿（甲板完整）\n（注：甲下血肿占甲面>50%或伴明显搏动性疼痛者可行甲下开窗引流减压；甲根翘起或甲板碎裂伴甲床损伤者需拔甲修补甲床。）","处理方案":"【药物治疗】\n1. 预防感染（首选）：阿莫西林胶囊 0.5g 口服 tid×5天（无青霉素过敏史者；过敏者改用头孢呋辛酯片 0.25g bid×5天或阿奇霉素片 0.5g qd×3天）。\n2. 局部抗感染：碘伏消毒创面后外涂莫匹罗星软膏 bid，覆盖无菌敷料，连续5-7天至创面干燥无渗液。\n3. 止痛：布洛芬缓释胶囊 0.3g 口服 bid，疼痛明显时服用，一般不超过3天（有胃溃疡史者禁用）。\n4. 破伤风预防：伤口深、污染重或利器（铁钉、锈器）所致者，破伤风抗毒素1500IU肌注一次（需皮试）；已规范接种破伤风疫苗且5年内加强者可不注射。\n\n【一般治疗及生活指导】\n1. 休息与活动：患指制动，避免抓握、提物、碰撞及剧烈活动；休息时抬高患肢高于心脏水平，减轻肿胀与疼痛。\n2. 伤口护理：保持创面清洁干燥，每1-2天换药1次，愈合前避免沾水及接触肥皂、洗洁精等化学洗涤剂；勿自行撕扯残留甲片或抠挖甲下血肿，残留甲板由医师处理。\n3. 饮食：适当增加优质蛋白（鸡蛋、牛奶、瘦肉、鱼虾）及富含维生素C（新鲜蔬果）的摄入，促进甲床及甲板再生修复；忌烟酒及辛辣刺激食物。\n4. 禁忌：伤后1-2周内避免患指长时间浸泡水中（游泳、泡浴），避免甲周化妆（涂甲油）及美甲操作，直至甲板完全长出。\n\n【随诊要求】\n1. 伤后2-3天复诊换药，评估创面有无红肿、渗液、脓性分泌物等感染征象。\n2. 甲床损伤者伤后1-2周复诊，评估甲板生长及甲床愈合情况；甲板缺损较大者1-3个月后随访甲板再生形态。\n3. 如出现患指持续跳痛、发热、甲下积脓、甲床发黑或感觉异常，须立即就诊，必要时行拔甲或引流处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1052,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d4410fbc72713a31aa27299a676ad2d558096b14d3100792579ba5a78b6331a0","pinyin":"zhijiasunshang","initials":"zjss","setting":"out","caseName":"门诊病历920","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历920",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-86581ad883324d5d4f64","key":"v1-c9ccc21dfe2a3058|templates-86581ad883324d5d4f64","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脓性指头炎","category":"门诊病历模板","raw":{"name":"脓性指头炎","category":"门诊病历模板","case":{"case_name":"门诊病历921","templates":{"主诉":"左手示指末节红肿、搏动性剧痛2天，加重1天。","现病史":"患者5天前左手示指末节被木刺刺伤，当时未予重视；2天前刺伤处出现红肿、胀痛，1天来疼痛加剧呈搏动性跳痛，患指下垂时疼痛明显加重，夜间痛醒，影响睡眠，伴发热（体温最高38.2℃）、乏力，无寒战。自行口服阿莫西林（剂量不详）无效。今日来我院门诊就诊。发病以来食欲减退。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 38.0℃，P 96次/分，R 19次/分，BP 122/80mmHg。神志清楚，痛苦面容。左手示指末节明显肿胀，皮肤紧张发亮、色暗红，皮温升高，局部压痛（+++），指尖触诊张力高，可见一细小刺伤痕迹，无破溃流脓；左肘部及腋窝淋巴结轻度肿大伴压痛。余手指活动正常，末梢血运良好。","辅助检查":"检查计划：患者左手示指末节5天前被木刺刺伤，2天来红肿、搏动性剧痛并进行性加重，患指下垂时疼痛加重、夜间痛醒，伴发热38.2℃及乏力，口服阿莫西林无效，临床高度考虑指腹密闭腔隙化脓性感染，入院即刻完善血常规检查，了解白细胞计数及中性粒细胞比例有无升高，明确感染严重程度并评估有无全身性炎症反应；完善CRP检查，动态评估炎症活动度，作为疗效判断与抗生素调整的参考；患者已出现发热、食欲减退，完善血糖检查，排除糖尿病等易感因素及感染诱发的糖代谢紊乱；完善肝肾功能及电解质检查，排除肝肾功能不全及水电解质紊乱，为静脉抗生素选择、剂量调整及指神经阻滞麻醉提供安全性依据；因患指为末节密闭腔隙感染，脓液细菌培养+药敏应在切开引流时采集脓液标本，明确致病菌种类及药物敏感性，指导敏感抗生素精准治疗，尤其本例为木刺刺伤需警惕金黄色葡萄球菌及混合菌感染；若查体见末节指骨压痛明显、红肿持续不退或引流后症状无缓解，疑末节指骨骨髓炎时，完善患指X线片检查，，了解末节指骨有无骨质破坏，排除指骨骨髓炎；此外，如出现寒战高热、白细胞显著升高伴全身中毒症状，应完善血培养以排除脓毒症，并复查血常规及CRP动态评估感染控制情况。\n\n（检查清单）\n【必做】血常规（白细胞及中性粒细胞比例升高）、CRP；【其他】脓液细菌培养+药敏（切开引流时采集）、X线片（疑末节指骨骨髓炎时）。","初步诊断":"1. 脓性指头炎（左手示指）\n（注：脓性指头炎为指腹密闭腔隙感染，一旦形成脓肿须尽早切开减压引流（在指神经阻滞麻醉下于指端侧方纵行切开，贯通引流，避免鱼口状切口），否则可致指骨骨髓炎及指端坏死；切开后换药、敏感抗生素治疗。）","处理方案":"【药物治疗】\n1. 青霉素类（首选，覆盖金黄色葡萄球菌等常见致病菌）：阿莫西林克拉维酸钾片0.625g，口服，每12小时1次（bid），疗程7天。\n2. 一代头孢菌素类（青霉素过敏者或替代方案）：头孢氨苄胶囊0.5g，口服，每8小时1次（tid），疗程7天。\n3. 若感染较重、伴明显蜂窝织炎或存在MRSA高危因素（反复皮肤软组织感染、近期住院/接触医疗环境史）：克林霉素胶囊0.3g，口服，每8小时1次（tid），疗程7天；或复方磺胺甲噁唑片（磺胺甲噁唑0.4g/甲氧苄啶0.08g）2片，口服，每12小时1次（bid），疗程7天。\n4. 疼痛明显者对症止痛：布洛芬缓释胶囊0.3g，口服，每12小时1次（bid），疗程3-5天。\n\n【一般治疗及生活指导】\n1. 患指制动、抬高患肢休息，避免下垂及过度活动、负重；未化脓早期可行温盐水或1:5000高锰酸钾溶液浸泡，每日2-3次，每次15-20分钟，促进炎症消散。\n2. 出现波动感或明确化脓时需及时切开引流，切勿自行挤压排脓，以免感染沿腱鞘扩散引起化脓性腱鞘炎甚至脓毒血症。\n3. 清淡饮食，保证足量蛋白质及维生素摄入，多饮水；忌辛辣刺激性食物，禁烟酒。\n4. 保持患指清洁干燥，创面愈合前避免接触水及污染物；合并糖尿病者须严格监测并控制血糖。\n\n【随诊要求】\n1. 口服抗生素3天后症状无缓解或加重（红肿范围扩大、疼痛加剧、出现发热）应立即复诊。\n2. 已行切开引流者：术后24-48小时首次换药，此后每1-2日换药1次至创面愈合；出现引流不畅、脓液增多或性质改变、全身发热时随时复诊。\n3. 完成常规疗程（约7天）后复诊评估感染控制情况；糖尿病患者复诊时同步监测血糖。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1053,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bd39f784a39f4737b9e04f0ebb76be6b18c7d40bc4602be56ec3de0132e1d1be","pinyin":"nongxingzhitouyan","initials":"nxzty","setting":"out","caseName":"门诊病历921","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历921",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5d859f9ea8e3ccde5f9a","key":"v1-c9ccc21dfe2a3058|templates-5d859f9ea8e3ccde5f9a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"足外伤","category":"门诊病历模板","raw":{"name":"足外伤","category":"门诊病历模板","case":{"case_name":"门诊病历922","templates":{"主诉":"左足被重物砸伤后肿痛、行走困难1小时。","现病史":"患者于1小时前被重物砸伤左足背及足趾，当即疼痛剧烈，局部迅速肿胀，皮肤无破口，左足不能负重行走，无麻木、无畸形，无昏迷、无恶心呕吐。伤后自行冰敷，疼痛无明显缓解，急来我院就诊。发病以来精神可，无发热。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 88次/分，R 19次/分，BP 122/80mmHg。神志清楚，查体合作。左足背及第2、3足趾明显肿胀，皮肤可见瘀斑，无破口，局部压痛（++），未触及骨擦感及反常活动；足趾活动可，痛温觉正常，末梢血运良好，足背动脉搏动正常。踝关节活动正常。","辅助检查":"【必做】左足正斜位X线片（排除骨折，足部外伤常规需排除跖骨、趾骨骨折）；【其他】血常规（疑感染或出血多时）。","初步诊断":"1. 左足软组织挫伤\n（注：足部外伤需警惕隐匿性骨折（如第5跖骨基底部骨折、应力性骨折），X线阴性但持续剧痛者建议1~2周后复查或行CT；伤后48小时冰敷、抬高患肢，肿胀消退前避免负重。）","处理方案":"【药物治疗】\n1. 头孢菌素类（预防伤口感染）：头孢呋辛酯片0.25g bid×5天（无过敏史者，服药期间禁酒）。\n2. 非甾体抗炎药（镇痛、消肿）：布洛芬缓释胶囊0.3g bid，餐后口服，疼痛缓解即停，连用不超过5天。\n3. 破伤风预防（伤口深或污染者）：破伤风抗毒素（TAT）1500IU肌注1次（皮试阴性后），或人破伤风免疫球蛋白250IU肌注1次。\n4. 局部消毒换药：碘伏消毒创面后无菌纱布包扎，1次/日（或遵医嘱），至创面愈合。\n\n【一般治疗及生活指导】\n1. 休息与抬高：患足制动休息，休息时抬高患肢（高于心脏水平）以减轻肿胀，3~5天内减少下地负重行走。\n2. 伤口护理：保持伤口敷料清洁干燥，勿沾水，防止污染；勿自行揭开或更换敷料，遵医嘱按时换药。\n3. 饮食：进食高蛋白、高维生素及富含锌的食物（瘦肉、蛋、鱼、新鲜蔬果）促进愈合，忌辛辣刺激食物，戒烟限酒。\n4. 禁忌：创面愈合前禁止泡脚、游泳、长时间行走及剧烈运动；出现石膏或绷带过紧、足趾发麻发凉时立即松解并就诊。\n\n【随诊要求】\n1. 一般伤口2~3天复诊换药，观察创面及肿胀情况；足部伤口约10~14天拆线，按时复诊拆线。\n2. 若出现伤口红肿加剧、渗液或脓性分泌物增多、疼痛加重、发热等感染征象，立即随诊。\n3. 合并骨折或韧带损伤者，遵医嘱定期复查X线，评估愈合情况后逐步恢复负重行走。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1054,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"933d7d3dfbc04631f300ee58d6cef8c1a1054aff8e41d6e74958cf83adf28785","pinyin":"zuwaishang","initials":"zws","setting":"out","caseName":"门诊病历922","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历922",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-15166c33d284b9b6467e","key":"v1-c9ccc21dfe2a3058|templates-15166c33d284b9b6467e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"跟腱断裂","category":"门诊病历模板","raw":{"name":"跟腱断裂","category":"门诊病历模板","case":{"case_name":"门诊病历923","templates":{"主诉":"运动时左足跟部剧痛伴提踵无力2小时。","现病史":"患者于2小时前打篮球起跳落地瞬间感左足跟后方如被踢击样剧痛，闻及断裂声，当即左踝跖屈无力、不能提踵站立，行走困难，局部渐肿胀，无破口、无麻木。伤后自行冰敷，未行特殊处理，急来我院就诊。既往无跟腱炎病史，无激素局部注射史。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 84次/分，R 18次/分，BP 120/78mmHg。神志清楚，查体合作。左足跟腱走行区肿胀、皮下瘀斑，跟腱止点上方约3~5cm处可触及明显凹陷（连续性中断），局部压痛（+）。Thompson试验（+）：挤压小腿腓肠肌时左踝无跖屈活动。左踝主动跖屈力弱，足趾活动、感觉、血运正常。","辅助检查":"【必做】跟腱超声（明确断裂部位及断端间隙）、左踝/跟骨侧位X线片（排除跟骨撕脱骨折及跟腱附着点撕脱）；【其他】MRI（超声不明确或评估陈旧性断裂时）。","初步诊断":"1. 左跟腱断裂（完全性，考虑）\n（注：跟腱断裂需尽早就诊，治疗分保守（石膏/支具固定，适合断端对合好者）与手术（急性期多主张手术修复，术后康复锻炼），建议请骨科/运动医学科会诊；保守或术后均需规范康复，防再断裂及跟腱挛缩。）","处理方案":"【药物治疗】\n1. 塞来昔布胶囊 200mg po qd×7天（抗炎镇痛，饭后服用，既往消化道溃疡或磺胺过敏者禁用）。\n2. 双氯芬酸二乙胺乳胶剂（扶他林）适量涂患处 tid×7天（局部消肿止痛，皮肤破损处禁用）。\n3. 云南白药胶囊 0.25g po qid×3天（活血化瘀、消肿止痛，孕妇禁用）。\n4. 拟行手术者：头孢呋辛酯片 0.5g po bid×3天（术前1天起用至术后2天，预防切口感染，青霉素或头孢过敏者禁用，须皮试阴性后使用）。\n【一般治疗及生活指导】\n1. 严格制动：患肢立即制动，以长腿石膏或可调支具将踝关节固定于跖屈30°位，4-6周内严禁患肢负重行走，避免踝关节背伸活动致断端再损伤。\n2. 抬高患肢：卧床或坐位时患肢垫高至高于心脏水平，伤后48小时内局部冰敷（每次15-20分钟、每日3-4次），以减轻肿胀出血。\n3. 饮食与禁忌：进食高蛋白、富含维生素C及钙质饮食（瘦肉、鱼虾、蛋奶、新鲜蔬果）；戒烟戒酒（吸烟显著延迟肌腱愈合）；避免局部热敷、按摩及剧烈运动。\n4. 防血栓：长期制动期间每日主动活动足趾及健肢各关节，多饮水；若出现小腿胀痛、皮温增高需及时就医，必要时遵医嘱加用抗凝药物预防深静脉血栓。\n【随诊要求】\n每周复诊1次评估肿胀、固定及皮肤情况；术后（或保守治疗）2周复查伤口及踝关节X线，4周复查跟腱超声评估断端对合与愈合情况；6周后改为功能支具并开始循序渐进的被动-主动关节活动度训练；8-12周复查超声或MRI确认跟腱连续性良好后逐步负重行走训练；约6个月后评估跟腱功能，确认后方可恢复跑跳等运动。期间若出现患肢剧烈疼痛、足背麻木、皮温降低或伤口红肿渗液，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1055,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3a46f3bde14dd825fdc2e9694fcb9af30d39709869b7cafa7e87d00a6d37ca7d","pinyin":"genjianduanlie","initials":"gjdl","setting":"out","caseName":"门诊病历923","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历923",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-09bb8aba79c861bad0ed","key":"v1-c9ccc21dfe2a3058|templates-09bb8aba79c861bad0ed","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"踝关节扭伤","category":"门诊病历模板","raw":{"name":"踝关节扭伤","category":"门诊病历模板","case":{"case_name":"门诊病历924","templates":{"主诉":"踝部肿痛伴活动受限2小时","现病史":"患者于3小时前运动（篮球、跑步时最为常见）、下楼梯踩空或在不平路面行走时发生内翻扭伤（足内翻使踝外侧韧带受到牵拉损伤，其中距腓前韧带最先受累、最为常见，占踝扭伤80%以上；外翻扭伤则损伤内侧三角韧带，较少见但多较严重，常合并骨折或腓骨损伤），伤后出现疼痛（位于外踝前下方，即距腓前韧带处，伴压痛，负重或行走时加重）、肿胀（见于外踝，呈进行性加重，数小时后明显）、瘀斑（韧带撕裂出血所致，24~48小时出现，位于外侧，呈青紫）、活动受限（踝关节活动时疼痛）、不能负重（严重者提示韧带完全撕裂或骨折，需评估）、损伤时弹响感或撕裂感（提示韧带撕裂）及跛行。伤后处理方面，是否已行RICE处理（休息、冰敷，48小时内每次15~20分钟、每日4~6次，十分重要；加压可用弹力绷带；并抬高患肢）。有无关节不稳感（有反复扭伤史者提示慢性不稳，多为距腓前韧带陈旧损伤，需评估）。既往有无反复扭伤（反复发作可致习惯性扭伤及韧带松弛，十分重要）及骨折史（第五跖骨基底部为腓骨短肌附着处，可发生撕脱骨折，需X线检查；内踝骨折常与三角韧带损伤相关）。另需按渥太华踝关节规则判断X线指征：外踝或内踝尖骨性压痛、足背或第5跖骨基底压痛、不能负重行走4步。今日来我院急诊/骨科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P82次/分，R18次/分，BP118/74mmHg。踝关节：肿胀（见于外踝，注意程度）、瘀斑及压痛（外踝前下方即距腓前韧带处，以及外踝尖、内踝尖、第5跖骨基底，骨性压痛提示骨折，需按渥太华规则评估）；韧带检查：前抽屉试验（踝前抽屉试验见距骨前移，提示距腓前韧带断裂、关节不稳，为阳性）、内翻应力试验（距骨倾斜提示外侧韧带不稳）；肿胀期检查受限，可在麻醉下或消肿后重复检查；活动度：背伸、跖屈及内、外翻时疼痛受限；负重：不能负重者需评估骨折或韧带完全断裂；血管神经：足背动脉搏动及远端感觉、运动正常；并与对侧对比。","辅助检查":"【必做】X线：正侧位，按渥太华规则（骨性压痛或不能负重）决定是否摄片，以排除骨折（外踝即腓骨远端骨折、内踝骨折、第5跖骨基底撕脱骨折（腓骨短肌附着处）、距骨骨折及儿童骨骺损伤（Salter-Harris分型））；常规扭伤若无骨性压痛且能负重，可不拍片，这一点很重要，可减少不必要的X线检查。【MRI】用于韧带完全撕裂（距腓前韧带、跟腓韧带，需手术评估）、软骨损伤（距骨顶骨软骨损伤，表现为慢性疼痛）及肌腱损伤；不作为急性期常规，用于慢性或疑有严重损伤者。【超声】可动态观察韧带，为可选项。【其他】严重肿胀或疑有骨折而X线不明确时，可行CT，但较少用。","初步诊断":"1. 右踝关节扭伤（内翻性，Ⅱ度：Ⅰ度为韧带牵拉，轻微肿痛、无松弛；Ⅱ度为韧带部分撕裂，明显肿痛、轻度松弛；Ⅲ度为韧带完全撕裂，严重肿痛瘀斑、明显松弛不稳；并已排除骨折）\n（注：治疗上，多数Ⅰ、Ⅱ度可保守治疗并采用RICE原则，Ⅲ度或关节不稳者需专科评估：①RICE为急性期核心：休息（避免负重）、冰敷（48~72小时内每次15~20分钟，每日4~6次，减轻肿胀）、加压（弹力绷带或护踝）及抬高患肢（高于心脏以促进回流、减轻肿胀），均在前72小时内进行。②保护性负重：Ⅱ度可用护踝或支具，部分负重（以可耐受为度）；Ⅲ度需免负重，用拐杖，但时间不宜过长。③药物：非甾体抗炎药（布洛芬或塞来昔布，用于疼痛及炎症，短期使用）及外用药（双氯芬酸凝胶，局部患者）。④固定：Ⅱ度用护踝或绷带固定1~2周；Ⅲ度用石膏或行走靴固定3~4周，以利韧带愈合。⑤康复（十分重要，可防慢性不稳）：早期在无痛范围内行活动度训练（踝泵）；消肿后行肌力训练，其中腓骨肌外翻肌力训练是外侧韧带稳定的关键，可用弹力带进行；本体感觉训练（单足站立、闭眼、平衡板）可防再扭伤，是核心内容，十分重要；渐进负重，4~6周恢复正常活动；运动前应充分康复，以防复发，再伤率较高。⑥Ⅲ度或慢性不稳（韧带完全断裂、前抽屉试验阳性）：多数经保守治疗及康复可愈；运动员或反复不稳者可行手术（韧带修复或重建踝外侧韧带），经评估后手术并恢复运动。⑦并发症：慢性踝关节不稳（反复扭伤所致，最为常见，多因康复不足，十分重要，需规范康复）、距骨骨软骨损伤（持续深部疼痛，可行MRI）及骨折（已排除）。⑧随访：观察肿胀（1~2周消退）及负重情况（渐进），重返运动一般需6~8周，待功能恢复后，以防再伤。骨科/运动医学科处理：多数可保守康复，Ⅲ度或不稳者转专科，重点防慢性不稳，康复是核心。）","处理方案":"【药物治疗】\n1. 非甾体抗炎药（口服）：塞来昔布胶囊 0.2g qd 或双氯芬酸钠缓释胶囊 75mg qd，餐后服用，连用5-7天（消化道溃疡、严重心肾功能不全者慎用）；\n2. 外用非甾体抗炎药：双氯芬酸二乙胺乳胶剂（扶他林）适量涂于患处并轻柔按摩至吸收，tid，连用7-10天；\n3. 活血化瘀中成药：云南白药胶囊 0.5g qid（首日首次可加服保险子1粒），连用5-7天；\n4. 疼痛剧烈影响睡眠者：布洛芬缓释胶囊 0.3g bid 短期加用，连用不超过3天。\n\n【一般治疗及生活指导】\n1. 制动与护具固定：急性期（伤后48小时内）避免负重行走，佩戴踝关节支具或护踝固定，行走时使用拐杖辅助，避免二次损伤；\n2. 冰敷：伤后48小时内冰敷患处，每次15-20分钟，间隔2-3小时，每日3-4次，冰袋与皮肤间垫毛巾防冻伤；\n3. 抬高患肢：休息时抬高患肢高于心脏水平以促进消肿；48小时后可改为温热敷促进局部血液循环；\n4. 禁忌：伤后1周内禁止剧烈运动、跑跳、盘腿及穿高跟鞋，48小时内禁忌热敷、按摩揉搓及饮酒，以免加重肿胀出血。\n\n【随诊要求】\n1. 伤后3-5天门诊复诊，评估肿痛程度及踝关节稳定性；\n2. 若伤后无法负重站立、疼痛剧烈或肿胀进行性加重，应立即复查踝关节X线片（必要时CT/MRI）以排除骨折及韧带完全断裂；\n3. 肿痛消退后（约1-2周）开始踝关节功能康复训练（踝泵、勾绷脚、单足平衡训练），2-4周复诊评估功能恢复情况，6周内避免剧烈运动及运动强度过大。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1056,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9a69231c2c2f1e75f785a6b74d9cb3b4f32b9f0e8c44ddef2f55a73d5affb735","pinyin":"huaiguanjieniushang","initials":"hgjns","setting":"out","caseName":"门诊病历924","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历924",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5ce1cefa7dd796869493","key":"v1-c9ccc21dfe2a3058|templates-5ce1cefa7dd796869493","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"跖骨骨折","category":"门诊病历模板","raw":{"name":"跖骨骨折","category":"门诊病历模板","case":{"case_name":"门诊病历925","templates":{"主诉":"右足扭伤后足背肿痛、不能负重3小时。","现病史":"患者于3小时前行走时不慎扭伤右足，当即感右足背外侧剧痛，渐肿胀，不能负重行走，无破口，无足趾麻木，无昏迷。伤后自行冰敷，疼痛无明显缓解，急来我院就诊。发病以来精神可。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 86次/分，R 18次/分，BP 122/78mmHg。神志清楚，查体合作。右足背外侧肿胀明显，皮肤张力高，可见瘀斑，第5跖骨基底部及足背压痛（++），未触及骨擦感；足趾活动可，末梢血运、感觉正常。","辅助检查":"【必做】右足正斜位X线片（重点观察第5跖骨基底部，需鉴别撕脱骨折与Jones骨折（骨干与基底部交界处，血供差易不愈合））；【其他】足部CT（隐匿性骨折或复杂骨折评估）、血常规。","初步诊断":"1. 右足第5跖骨骨折？（待X线明确）\n（注：第5跖骨基底部撕脱骨折多保守治疗（短腿石膏/行走靴4~6周）；Jones骨折因血供差易骨不连，多需更长时间制动或手术内固定，建议请骨科会诊确定治疗方案。）","处理方案":"【药物治疗】\n1. 止痛消肿：塞来昔布胶囊0.2g bid×5天，疼痛缓解后停用；或洛索洛芬钠片60mg tid×5天，餐后服用，既往消化性溃疡史者慎用。\n2. 促进骨折愈合：碳酸钙D3片（含钙600mg/维生素D3 125IU）1片 qd＋骨化三醇软胶囊0.25μg qd，连用6-8周。\n3. 改善局部肿胀：迈之灵片（马栗种子提取物）150mg bid×7天；必要时联合七叶皂苷钠片30mg bid×5天。\n\n【一般治疗及生活指导】\n1. 患足制动：无移位或轻度移位骨折予小腿石膏托或可调支具固定4-6周；第五跖骨基底部骨折（Jones骨折）需短腿非负重石膏固定并拄双拐。\n2. 抬高患肢与负重管理：伤后2周内患肢抬高高于心脏水平以利消肿，严禁患足负重行走，2周后复查X线对位良好方可逐步部分负重。\n3. 饮食与禁忌：高蛋白、高钙、富含维生素D饮食（牛奶、鱼类、豆制品），戒烟戒酒，避免辛辣刺激及过量咖啡因影响骨愈合。\n4. 功能锻炼：固定期间主动活动足趾及踝关节（背伸跖屈），防止关节僵硬及深静脉血栓，每2小时活动1次，每次5分钟。\n\n【随诊要求】\n1. 伤后2周门诊复查足部正斜位X线，观察骨折对位及固定情况，必要时调整外固定。\n2. 伤后4-6周复查X线评估骨痂生长情况，决定拆除石膏及负重时机；8-12周复查X线确认骨性愈合。\n3. 出现患足剧痛、肿胀进行性加重、足趾发麻发凉、肤色青紫或石膏过紧压迫不适时，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1057,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1f9f4dbc3594ef19b3ec36b9c8baee615c9c1a42c86c0d68b3f1bd4512be3fe","pinyin":"zhiguguzhe","initials":"zggz","setting":"out","caseName":"门诊病历925","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历925",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7500c18f6148998f02e2","key":"v1-c9ccc21dfe2a3058|templates-7500c18f6148998f02e2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"趾骨骨折","category":"门诊病历模板","raw":{"name":"趾骨骨折","category":"门诊病历模板","case":{"case_name":"门诊病历926","templates":{"主诉":"足趾肿痛伴活动受限1周","现病史":"患者1周前无明显诱因出现趾骨骨折相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以足趾肿痛伴活动受限1周为主诉就诊，考虑趾骨骨折，为明确诊断与鉴别其他足趾疼痛性疾病，入院即刻完善足趾正斜位X线片，明确骨折部位、类型、有无移位及关节内受累，指导复位固定方式；若X线显示可疑隐匿性骨折、关节面塌陷或需评估粉碎程度，进一步查CT检查，明确骨折线走行与关节面情况，为手术方案提供依据；若怀疑合并肌腱、韧带损伤或应力性骨折早期X线阴性，病情稳定后完善MRI检查，了解骨髓水肿、软组织及肌腱损伤情况，鉴别痛风性关节炎、骨髓炎等；完善血常规、血沉及CRP检查，排除感染性关节炎及骨髓炎，评估有无继发感染；完善血钙磷碱性磷酸酶检查，了解血钙、血磷水平及碱性磷酸酶活性，排除甲状旁腺功能异常、骨软化等代谢性骨病所致病理性骨折；患者为1周外伤后肿痛，完善骨密度检查，评估骨质疏松程度，了解骨折风险并为抗骨质疏松治疗提供依据；完善关节超声检查，了解关节腔积液、滑膜增厚及软组织肿胀情况，鉴别痛风、假性痛风及软组织感染；若足趾麻木、感觉异常或活动受限明显，完善肌电图检查，评估有无周围神经损伤；完善类风湿因子检查，排除类风湿关节炎所致足趾肿痛；对青年男性反复关节肿痛者，完善HLA-B27检查，鉴别强直性脊柱炎等血清阴性脊柱关节病。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙磷碱性磷酸酶\n\n【影像学检查】\nX线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 趾骨骨折\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 镇痛消炎：塞来昔布胶囊0.2g qd，口服×5～7天（胃溃疡病史者慎用，可改对乙酰氨基酚片0.5g prn）；\n2. 活血化瘀、促进骨折愈合：伤科接骨片4片 tid，口服×4周；或接骨七厘片5片 tid，口服×4周；\n3. 补充钙剂及维生素D：碳酸钙D3片（含钙600mg/维生素D3 125IU）1片 qd，口服×4～6周；\n4. 开放性骨折（皮肤破损）：伤后24小时内肌注破伤风抗毒素1500IU，并口服头孢呋辛酯片0.25g bid×5天（青霉素过敏者改阿奇霉素片0.5g qd×3天）。\n\n【一般治疗及生活指导】\n1. 制动休息：患足穿硬底鞋或予石膏/支具固定患趾4～6周，避免患趾负重、跑跳及久站久行，减少患趾活动；\n2. 抬高患肢：坐卧时患足垫高至高于心脏水平，以利消肿；伤后48小时内局部冰敷，每次15～20分钟、每日3～4次，48小时后改热敷；\n3. 饮食调理：多食鱼、蛋、奶及豆制品等高蛋白、高钙食物，适量补充维生素C促进愈合；\n4. 生活禁忌：戒烟、限酒（吸烟显著延缓骨折愈合），避免穿尖头鞋、高跟鞋挤压患趾，注意患足保暖。\n\n【随诊要求】\n1. 伤后2周门诊复查足部X线，评估骨折对位及愈合情况；若外固定松动或移位，及时调整；\n2. 伤后4～6周复查X线，视骨痂生长情况决定是否去除固定并逐步开始患趾主动活动与负重行走；\n3. 固定期间若出现患趾剧痛、皮肤发白发凉、麻木或肿胀进行性加重，或石膏过紧、渗出异味，须立即返院就诊，不得自行拆除固定。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1058,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"259de5cfc2914280dc28487c0c5a256937cd41cc3af30bab6663a2e36d05d9f1","pinyin":"zhiguguzhe","initials":"zggz","setting":"out","caseName":"门诊病历926","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历926",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-564d41a6fac7a67855eb","key":"v1-c9ccc21dfe2a3058|templates-564d41a6fac7a67855eb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨肿瘤","category":"门诊病历模板","raw":{"name":"骨肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历927","templates":{"主诉":"左股骨远端疼痛2个月，夜间加重伴局部肿胀1个月。","现病史":"患者2个月前无明显诱因出现左膝上方疼痛，为持续性钝痛，活动后加重，1个月来夜间疼痛明显，常痛醒，局部渐肿胀，无发热、无盗汗，无外伤史，体重下降约1.5kg。自行服用布洛芬疼痛可部分缓解。今日来我院门诊就诊。发病以来精神欠佳，食欲减退，大小便正常。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.5℃，P 80次/分，R 18次/分，BP 120/78mmHg。神志清楚，慢性病容。左股骨远端内侧可触及约5cm×4cm质硬肿块，固定，边界欠清，局部皮温稍高，皮肤无红肿、无静脉怒张，肿块压痛（+）；左膝关节活动正常，无关节积液；左腹股沟淋巴结未触及肿大。","辅助检查":"【必做】左股骨正侧位X线片（观察骨质破坏特点：溶骨/成骨、骨膜反应（Codman三角、日光放射状）、软组织肿块）、血常规、血沉、碱性磷酸酶、肝肾功能；【影像学】局部MRI（明确肿瘤范围及软组织浸润）、胸部CT（排查肺转移）；【确诊】CT引导下穿刺活检（病理学确诊，至关重要）。","初步诊断":"1. 左股骨远端骨肿瘤（恶性待排）\n（注：青少年股骨远端干骺端疼痛性肿块伴夜间痛需高度警惕骨肉瘤，应尽快转骨肿瘤专科：完善影像分期+穿刺活检明确病理，勿在确诊前行局部按摩、理疗或不当手术（不当活检可致肿瘤污染扩散）。）","处理方案":"【药物治疗】\n1. 镇痛治疗：伴骨痛者首选非甾体抗炎药，如塞来昔布胶囊0.2g bid（餐后服，注意胃肠道及心血管风险）；疼痛明显或夜间痛者升级为弱阿片类，如盐酸曲马多缓释片50mg q12h，按时给药，疼痛缓解后逐渐减量。\n2. 骨保护治疗：伴溶骨性破坏、恶性骨肿瘤或骨转移者，予唑来膦酸注射液4mg静脉滴注，每4周1次，或地舒单抗注射液120mg皮下注射，每4周1次；用药前查血钙、肾功能及口腔情况，注意低钙血症及颌骨坏死风险。\n3. 钙与维生素D补充：碳酸钙D3片（含元素钙600mg、维生素D3 400IU）1片qd，联合骨化三醇胶丸0.25μg bid，定期监测血钙、尿钙，防治低钙血症。\n4. 化疗（仅限确诊恶性骨肿瘤，如骨肉瘤、尤文肉瘤）：采用以甲氨蝶呤、阿霉素、顺铂为基础的方案（如MAP方案），须住院或在肿瘤专科规范执行，门诊负责确诊前评估、分期及转诊，不实施门诊化疗。\n【一般治疗及生活指导】\n1. 患肢保护：避免患肢负重及剧烈运动，防止病理性骨折；病灶位于下肢者行走时使用双拐或助行器，具体负重时机以影像学评估为准。\n2. 局部禁忌：避免对病灶部位进行按摩、热敷、针灸等刺激，防止外伤及病灶扩大；如为骨样骨瘤等疼痛敏感病灶，注意休息制动。\n3. 饮食指导：高蛋白、高钙、富含维生素D饮食，如牛奶、酸奶、豆制品、瘦肉、鱼虾等，戒烟限酒，保证充足营养支持。\n4. 生活起居：规律作息，避免劳累，保持良好心态；注意防跌倒，居家环境去除障碍物。\n【随诊要求】\n1. 良性骨肿瘤（如骨软骨瘤、骨囊肿等）：每3~6个月门诊复诊，复查X线或CT/MRI，观察病灶大小及形态变化，病变增大或症状加重及时就诊。\n2. 恶性骨肿瘤确诊或术后/化疗后：每1~3个月复诊，复查血常规、肝肾功能、电解质及局部影像学，长期规律随访。\n3. 骨转移瘤：每2~3个月复查全身骨显像（ECT）或PET-CT，评估病灶变化及疗效。\n4. 出现疼痛加剧、夜间痛、局部包块短期内增大、肢体麻木无力、不明原因发热或消瘦等，需随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1059,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dea3d4cff85b50a4ce3cdb339ad0c70e92d4b47888522b878f439a6b0a1d8ebc","pinyin":"guzhongliu","initials":"gzl","setting":"out","caseName":"门诊病历927","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历927",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7976899a7d2795beab34","key":"v1-c9ccc21dfe2a3058|templates-7976899a7d2795beab34","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨囊肿","category":"门诊病历模板","raw":{"name":"骨囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历928","templates":{"主诉":"发现骨内囊性病变1月","现病史":"患儿为儿童或青少年（骨囊肿好发于5~15岁，多见于单房性骨囊肿），于1周前外伤后行X线检查时发现病变，或因轻微外伤后发生病理性骨折而就诊。发现时表现如下：无症状者多见（多数单房性骨囊肿无明显症状，常为偶然经X线发现）；病理性骨折（轻微外伤即可发生骨折，因骨囊肿使骨皮质变薄、骨质脆弱，常为首发表现，十分重要，多为外伤后摄X线时发现囊肿）；疼痛（动脉瘤样骨囊肿可有疼痛、肿胀及膨胀感）及肿胀（表浅骨可呈膨胀性改变）。分型方面：单房性骨囊肿（又称单纯性囊肿，内含浆液）与动脉瘤样骨囊肿（多房、含血性囊腔、呈膨胀性且具侵袭性）。好发部位为肱骨、股骨近端干骺端，随生长可移向骨干。X线表现为透亮囊性病灶，边界清晰，骨皮质变薄、膨胀。需评估骨折风险及有无恶性可能：骨囊肿为良性，但膨胀或骨折可影响功能，需与骨肿瘤鉴别（骨肉瘤为恶性，可见骨膜反应及Codman三角；以及骨纤维结构不良、嗜酸性肉芽肿、骨巨细胞瘤等，青少年患者鉴别十分重要，可行MRI及活检），最终以病理确诊。今日来我院骨科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R20次/分，BP100/62mmHg。患肢：局部肿胀、膨隆（表浅骨的囊肿因皮质变薄而膨胀）、压痛（多无或轻微，合并骨折时疼痛明显）、病理性骨折（可见畸形、肿胀、瘀斑及活动受限）、肢体功能及邻近关节活动情况；全身骨骼检查（多骨病变可见于骨纤维结构不良及嗜酸性肉芽肿，需排查多发）；神经血管（深部病变可压迫神经血管）。","辅助检查":"【必做】X线为核心：单房性骨囊肿表现为干骺端中心性透亮囊性病灶，边界清晰，骨皮质变薄，无骨膜反应，为典型表现；动脉瘤样骨囊肿表现为偏心性、膨胀性、多房性肥皂泡样改变，可有骨膜反应；合并病理性骨折时可见骨折线经过囊肿处。【影像】MRI可判断囊肿内容（单房者呈水样信号；动脉瘤样者多囊，可见液-液平面，为特征性表现）并鉴别肿瘤；骨扫描（单房性骨囊肿多表现为冷区或边缘轻度增强；动脉瘤样骨囊肿摄取明显）；CT可精确评估皮质变薄与膨胀程度。【确诊】活检适用于诊断不明或疑为恶性者，可行穿刺或切开活检并送病理（单房性骨囊肿囊壁为纤维组织，动脉瘤样骨囊肿为多房血腔并见巨细胞，可确诊）；需与骨肉瘤鉴别（青少年、夜间痛、骨膜反应及Codman三角，MRI增强及活检十分重要）、骨巨细胞瘤（多位于骨骺，多见于20岁以上）及骨纤维结构不良（呈毛玻璃样改变，可为多骨受累）。【血液】碱性磷酸酶（骨肿瘤时可升高，但无特异性）；血钙、血磷及甲状旁腺功能（用于鉴别甲状旁腺功能亢进所致棕色瘤，较少见）。","初步诊断":"1. 骨囊肿（单房性骨囊肿，位于肱骨或股骨近端干骺端；或动脉瘤样骨囊肿；记录大小及部位；合并病理性骨折；需与骨肿瘤如骨肉瘤等鉴别）\n（注：治疗依类型、大小及有无骨折决定，可选保守或手术：①单房性骨囊肿：无骨折或病灶较小者可观察（部分病例随生长发育可自愈，即自发愈合，需观察并随访X线评估变化）；合并病理性骨折者，先待骨折愈合（保守治疗，以石膏或支具固定），骨折愈合后再处理囊肿；或同时处理囊肿与骨折（行刮除植骨及内固定以固定骨折）；囊肿的处理包括刮除植骨（病灶刮除后以自体或异体骨植骨，或用骨水泥填充，指征为大囊肿、反复骨折或位于负重骨）及囊内皮质类固醇注射（对部分单房性骨囊肿有效，为无创选择，但复发率较高），骨髓或骨移植注射为较新的方法；弹性髓内钉固定可防骨折，同时起到引流囊腔的作用；刮除术后复发率约20~30%，需随访X线。②动脉瘤样骨囊肿：行刮除植骨，因复发率高，可加用辅助处理（如酚烧灼、冷冻或骨水泥）以降低复发；选择性动脉栓塞可用于术前减少出血，或用于不能手术部位的治疗；放疗仅用于不能手术的部位，但放疗后有发生肉瘤的风险，应慎重、少用；复发者再行处理。③并发症：病理性骨折（可反复发生）、生长板损伤（干骺端病变邻近骨骺时可影响生长，需随访肢体长度）及关节功能障碍。④随访：X线观察每6~12个月复查，评估囊肿变化、愈合或进展；术后随访1~2年以监测复发；病理性骨折愈合后逐步负重并康复；若持续疼痛或肿块增大，需复查MRI及活检以鉴别恶性，十分重要。骨科处理：单房性者观察、注射或刮除，动脉瘤样者刮除加辅助治疗，注意复发与随访，并与骨肉瘤鉴别，十分重要。）","处理方案":"【药物治疗】\n1. 骨吸收抑制剂（首选，抑制囊肿壁破骨活性、降低复发率）：阿仑膦酸钠片70mg qw（每周1次，晨起空腹以200ml白水送服，服后保持直立至少30分钟，30分钟内勿进食或平卧），疗程3-6个月；或唑来膦酸注射液5mg静脉滴注，每年1次。\n2. 钙与维生素D基础补充（与双膦酸盐同步）：碳酸钙D3片0.6g bid口服；骨化三醇软胶囊0.25μg qd口服，长期维持，定期监测血钙。\n3. 对症镇痛（囊肿区酸胀疼痛明显时）：塞来昔布胶囊0.2g qd口服，餐后服用，疼痛缓解即停，连续使用不超过5天；病理性骨折急性疼痛者可加用曲马多缓释片50mg bid口服（肝肾功能不全者慎用）。\n4. 促进骨愈合（伴病理性骨折或术后骨缺损时）：骨肽片0.3g tid口服，4周为1疗程。\n【一般治疗及生活指导】\n1. 休息与负重：囊肿累及下肢承重骨（股骨、胫骨等）者，避免跑跳、球类运动及负重行走，必要时患肢扶拐或佩戴支具保护，防止病理性骨折；累及上肢者避免提举重物。\n2. 活动指导：可进行游泳、平地散步等低冲击活动，循序渐进；避免囊肿部位受直接撞击或剧烈扭转，定期复查X线评估病情。\n3. 饮食：增加牛奶、豆制品、深海鱼、蛋黄等富含钙及维生素D的食物摄入，戒烟限酒，少饮碳酸饮料，控制体重，维持骨代谢平衡。\n4. 禁忌：慎用糖皮质激素、抗癫痫药等影响骨代谢的药物；如局部疼痛加重、肿胀或出现畸形，及时就诊。\n【随诊要求】\n1. 每3-6个月门诊复查患肢X线正侧位片，评估囊肿大小、骨皮质变薄程度及有无病理性骨折征象；若囊肿进行性增大、皮质变薄超过50%或症状明显，建议转骨科专科评估手术或介入治疗。\n2. 长期服用双膦酸盐者，用药期间监测血钙、血磷及肝肾功能，每年复查骨密度。\n3. 出现局部疼痛加重、肿胀、关节活动受限或下肢畸形等病理性骨折先兆时，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1060,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5acbf1d73e2784f2fb07a5a03ee9762e7cb1e96b97514ab76f347da86e71cf23","pinyin":"gunangzhong","initials":"gnz","setting":"out","caseName":"门诊病历928","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历928",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-657dce738b7f4ccbb1b2","key":"v1-c9ccc21dfe2a3058|templates-657dce738b7f4ccbb1b2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨巨细胞瘤","category":"门诊病历模板","raw":{"name":"骨巨细胞瘤","category":"门诊病历模板","case":{"case_name":"门诊病历929","templates":{"主诉":"右膝关节上方隐痛伴肿胀3个月，加重1周。","现病史":"患者3个月前无明显诱因出现右股骨远端（膝关节上方）隐痛，为间歇性钝痛，活动后加重，未予重视；1个月来局部渐肿胀，可触及肿块，1周来疼痛加重，夜间痛，右膝活动轻度受限，无发热、无外伤史。既往体健。今日来我院门诊就诊。发病以来精神可，食欲、睡眠、大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 82次/分，R 18次/分，BP 122/80mmHg。神志清楚，查体合作。右股骨远端外侧可触及约4cm×3cm肿块，质硬，边界较清，轻压痛，局部皮温正常，皮肤无红肿、无浅静脉怒张；右膝关节活动轻度受限（屈曲约110°），无明显关节积液，浮髌试验（-）；足趾活动、感觉、末梢血运正常。","辅助检查":"检查计划：患者3个月前无明显诱因出现右股骨远端（膝关节上方）间歇性钝痛，活动后加重，1个月来局部渐肿胀并可触及肿块，1周来疼痛加重、夜间痛，右膝活动轻度受限，无发热及外伤史，临床考虑右股骨远端骨巨细胞瘤可能，入院即刻完善右股骨正侧位X线片，了解长骨骨端有无偏心性、膨胀性、溶骨性破坏，是否呈皂泡样改变、有无骨膜反应，明确病变性质与范围；完善血常规、血沉检查，排除感染性病变及血液系统疾病，为鉴别骨髓炎、尤文肉瘤等提供参考；完善血钙磷碱性磷酸酶检查，了解血钙、血磷水平及碱性磷酸酶活性，评估骨代谢与成骨活动情况，排除甲状旁腺功能异常，并辅助鉴别骨肉瘤等恶性骨肿瘤；完善局部MRI检查，明确肿瘤在髓腔内范围、有无关节及软组织侵犯，为手术边界与重建方式提供依据；因骨巨细胞瘤少数可发生肺转移，完善胸部CT检查，明确有无肺转移，作为分期与随访基线；确诊依赖病理，应完善穿刺活检病理检查，明确肿瘤组织学性质与分级，必要时加做免疫组化以鉴别动脉瘤样骨囊肿、骨肉瘤等；此外，术前完善凝血功能、肝肾功能、心电图及心脏超声检查，评估手术与麻醉耐受性，排除出血倾向及心肺功能不全，为瘤段切除或刮除植骨手术提供安全性保障；术后按骨肿瘤规范定期复查胸部CT及局部影像，评估有无复发与转移。\n\n（检查清单）\n【必做】右股骨正侧位X线片（典型表现为长骨骨端偏心性、膨胀性、溶骨性破坏，呈皂泡样改变，无骨膜反应）、血常规、血沉、血钙磷碱性磷酸酶；【影像学】局部MRI（肿瘤范围、关节及软组织侵犯）、胸部CT（肺转移筛查，骨巨细胞瘤少数可肺转移）；【确诊】穿刺活检病理。","初步诊断":"1. 右股骨远端骨巨细胞瘤？（待病理确诊）\n（注：骨巨细胞瘤好发于20~40岁长骨骨端，属交界性肿瘤（可复发、少数肺转移），确诊靠病理。治疗以手术刮除植骨/瘤段切除为主，不可切除或复发转移者可用地舒单抗，建议转骨肿瘤专科规范诊治。）","处理方案":"【药物治疗】\n1. 地舒单抗（安加维）120mg 皮下注射：第1个月第8天、第15天及此后每月1次，每次120mg。适用于不可手术切除、复发或转移性骨巨细胞瘤，亦用于术前新辅助治疗缩小病灶。用药前及用药期间常规口服钙剂（碳酸钙D3片600mg bid）及维生素D（骨化三醇胶囊0.25μg qd），持续整个治疗期并至末次给药后至少6个月。\n2. 疼痛对症治疗：塞来昔布胶囊200mg qd-bid，或对乙酰氨基酚片0.5g tid，餐后服用，疼痛缓解后即停，不宜长期联用；有胃病史者加用质子泵抑制剂护胃。\n3. 术前新辅助治疗后评估：地舒单抗治疗3-6个月后复查影像评估手术时机；若计划行刮除术，应评估病灶周边成骨反应后再决定手术方式。\n\n【一般治疗及生活指导】\n1. 患肢保护性制动：避免患肢负重、跑跳及剧烈运动，防止病理性骨折；下肢病灶者行走使用双拐或支具，上肢病灶者避免提举重物，脊柱病灶者避免弯腰负重及久坐。\n2. 饮食指导：均衡高蛋白、高钙饮食，每日钙摄入量1200mg，多吃牛奶、豆制品、深绿色蔬菜，多晒太阳，保证维生素D合成。\n3. 禁忌事项：避免对病灶区进行按摩、热敷、针灸及重手法推拿；避免外伤碰撞，沐浴活动注意防护，防止跌倒。\n4. 休息与作息：保证充足睡眠，避免熬夜；疼痛明显时卧床休息，缓解期适当进行健侧肢体功能锻炼，防止肌肉萎缩。\n\n【随诊要求】\n1. 治疗期间每月复诊1次，监测血钙、血磷、25-羟维生素D、肾功能及电解质，评估低钙血症及地舒单抗相关不良反应。\n2. 每3个月复查患处X线及CT，每6个月复查MRI，评估病灶大小、骨壳完整性及新骨形成情况。\n3. 每6个月行胸部CT检查筛查肺转移；肺转移者缩短至3个月复查。\n4. 出现患肢疼痛进行性加重、局部肿块增大、肢体畸形或突发剧痛（提示病理性骨折）时立即复诊。\n5. 停用地舒单抗后仍需每3个月随访复查血钙，警惕停药后反跳性高钙血症；术后患者长期随访至少5年，监测局部复发及远处转移。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1061,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"87c10cc31cd0e8d6412ebeff8724ca2b00570acfeb73cf58323580a13c00d79a","pinyin":"gujuxibaoliu","initials":"gjxbl","setting":"out","caseName":"门诊病历929","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历929",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b52adebdcab504088f01","key":"v1-c9ccc21dfe2a3058|templates-b52adebdcab504088f01","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"骨转移瘤","category":"门诊病历模板","raw":{"name":"骨转移瘤","category":"门诊病历模板","case":{"case_name":"门诊病历930","templates":{"主诉":"进行性骨痛1月","现病史":"患者有原发肿瘤病史（乳腺癌最为常见，可致溶骨或成骨性骨转移；前列腺癌多为成骨性转移；肺癌多为溶骨性；此外还有甲状腺癌、肾癌、多发性骨髓瘤（溶骨性、全身多发）、肝癌及结直肠癌），或为原发灶未明者（以骨转移为首发表现时需积极寻找原发灶，十分重要）；年龄多在50岁以上，新发骨痛者需排除转移瘤或骨髓瘤，十分重要。患者于1个月前出现骨痛（呈进行性，以夜间痛及静息痛为特点，负重后加重，持续存在），部位为脊柱（胸腰椎最为常见，可压迫脊髓，十分重要）、骨盆、肋骨、股骨近端及颅骨；可发生病理性骨折（轻微外伤甚至无外伤即可骨折，股骨等负重骨病理性骨折较常见，十分重要）；脊髓压迫表现为背痛伴下肢无力、麻木及大小便障碍，属急症，可致不可逆脊髓损伤，需急诊评估与减压，十分重要；高钙血症（溶骨性转移破坏骨质致血钙升高，可出现恶心、便秘、意识模糊，属急症）；全身表现有体重下降、乏力及恶病质；表浅骨受累处可触及肿块；神经根受压可致根性疼痛。另需了解原发肿瘤史（癌种、分期及治疗情况）、骨扫描随访情况、多发性骨髓瘤相关情况（贫血、肾功能异常、骨痛及M蛋白，需检查）及既往治疗（化疗、放疗、内分泌治疗或靶向治疗）。今日来我院骨科/肿瘤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P92次/分，R20次/分，BP108/68mmHg。骨：压痛（转移灶处局限压痛及叩击痛）、肿块（表浅骨可呈膨隆）、病理性骨折（可见部位畸形、肿胀、瘀斑及不能负重）；脊柱：压痛、叩击痛、后凸畸形，并做神经系统检查（肌力、感觉、反射，以评估脊髓压迫，十分重要；注意鞍区感觉及肛门括约肌功能，属急症）；神经根受压可见放射性疼痛及肌力下降；有无贫血貌；浅表淋巴结有无肿大（提示转移）；乳腺、甲状腺及前列腺查体（寻找原发灶）；肝脾及腹部检查；全身营养状态及有无恶病质；高钙血症时可出现肌张力下降及意识改变。","辅助检查":"【必做】X线可显示骨转移表现（溶骨性者呈透亮破坏，多见于乳腺癌、肺癌及肾癌；成骨性者呈硬化改变，多见于前列腺癌；也可为混合性），并观察肋骨、脊柱及骨盆转移。骨扫描为全身检查，锝标记核素显像敏感性高，可用于多发转移的筛选及广泛骨转移的评估，但无特异性，炎症或骨折可致假阳性，需以X线核实，十分重要。PET-CT可显示全身FDG代谢增高，对肿瘤转移敏感，有助于评估全身肿瘤负荷，十分重要。MRI用于脊柱转移（椎体信号异常提示骨髓浸润，并可评估脊髓压迫，十分重要，其敏感度早于X线）。CT可精确显示骨破坏并可引导活检。【血液】肿瘤标志物：癌胚抗原及CA15-3（乳腺癌）、前列腺特异抗原（前列腺癌，升高有重要意义）、碱性磷酸酶（骨转移时可升高，为骨形成标志）、血钙及血磷（监测高钙血症）、血常规（贫血可见于骨髓瘤）、肝肾功能、血清蛋白电泳及M蛋白（用于筛查骨髓瘤）及尿本周蛋白。【确诊】对骨转移灶行穿刺或切开活检，送病理以确诊转移，并通过免疫组化寻找原发组织来源（CK7、CK20及甲状腺、前列腺、乳腺相关标志物，用于判断原发部位不明者，十分重要）；骨髓穿刺用于诊断骨髓瘤。【原发灶筛查】胸腹盆CT、乳腺超声或钼靶、前列腺及甲状腺超声、肿瘤标志物全套，对原发灶未明者行系统筛查，十分重要。","初步诊断":"1. 骨转移瘤（溶骨性/成骨性/混合性；部位为脊柱、骨盆、股骨等；原发灶为乳腺、前列腺、肺等或待查；评估有无病理性骨折、脊髓压迫及高钙血症；并做肿瘤分期）\n（注：治疗以多学科协作、姑息与抗肿瘤并重、防治骨相关事件为原则，十分重要：①全身抗肿瘤治疗：针对原发肿瘤行化疗、内分泌治疗、靶向治疗或免疫治疗，依原发癌种控制进展，使骨转移病灶缩小或稳定；乳腺癌可行内分泌治疗（芳香化酶抑制剂或他莫昔芬）联合化疗或靶向治疗；前列腺癌行内分泌去势治疗，可选用阿比特龙或恩杂鲁胺；肺癌可行靶向或免疫治疗；肾癌可行靶向治疗（如舒尼替尼）；甲状腺癌可行碘131治疗。②骨保护治疗：双膦酸盐（唑来膦酸4mg静脉滴注，每3~4周1次）或地舒单抗120mg皮下注射，每4周1次，可抑制骨吸收、减少骨相关事件（病理性骨折、骨痛、高钙血症及需要放疗），十分重要，属标准治疗；用药需注意下颌骨坏死（用药前应先做牙科检查）、低钙血症（需补钙及维生素D并监测）及肾功能（唑来膦酸需注意，地舒单抗对肾功能影响较小）。③局部放疗：骨转移的姑息放疗可有效止痛、缓解骨痛（30Gy分10次或单次8Gy），对症状性骨痛、承重骨转移及脊髓压迫术后，十分重要；立体定向放疗适用于寡转移。④骨相关事件的处理：病理性骨折可行手术内固定（股骨可用髓内钉、关节置换或假体），术后辅以放疗；脊髓压迫属急症，经MRI诊断后应立即给予糖皮质激素（大剂量地塞米松）并放疗或手术减压，宜在24~48小时内进行，以防永久性瘫痪，十分重要；高钙血症应补液、利尿（肾功能良好者可用呋塞米），并使用双膦酸盐或地舒单抗、降钙素，属急症处理。⑤止痛：按WHO三阶梯原则用药（非甾体抗炎药、弱阿片类、强阿片类），并与放疗、双膦酸盐联合控制骨痛；神经病理性疼痛可加用加巴喷丁。⑥随访：评估原发肿瘤治疗反应及骨病灶影像变化，长期使用双膦酸盐以预防骨相关事件，并进行功能康复（骨折术后）及生存质量管理（姑息关怀，十分重要）。骨科/肿瘤科处理：多学科协作，患者骨保护药物（双膦酸盐或地舒单抗），放疗止痛，病理性骨折及脊髓压迫按急症处理，并重视原发肿瘤治疗，十分重要。）","处理方案":"【药物治疗】\n1. 骨改良治疗（首选）：唑来膦酸注射液4mg加入0.9%氯化钠注射液100ml静脉滴注，滴注时间不少于15分钟，每4周1次（用药前复查肾功能、血钙、血磷，肌酐清除率＜30ml/min或低钙未纠正者禁用）；或地舒单抗注射液120mg皮下注射，每4周1次（用药前必须纠正低钙血症）。用药期间常规联合碳酸钙D3片600mg qd及骨化三醇软胶囊0.25μg qd口服。\n2. 镇痛治疗（按NRS疼痛评分阶梯给药）：轻中度疼痛予塞来昔布胶囊200mg qd-bid餐后口服（注意胃肠道及心血管风险）；中重度疼痛予盐酸曲马多缓释片50-100mg q12h口服；重度疼痛予盐酸羟考酮缓释片10mg q12h口服，按疼痛评分逐步滴定，同时预防性使用乳果糖口服溶液15ml qd防治便秘。\n3. 原发肿瘤系统治疗：根据原发肿瘤类型（肺癌、乳腺癌、前列腺癌、甲状腺癌等）及分子分型，同步规范化疗、内分泌治疗、靶向治疗或免疫治疗，建议转肿瘤专科制定方案。\n\n【一般治疗及生活指导】\n1. 活动与防护：避免患肢负重、剧烈运动及提重物，行走时使用拐杖或助行器；脊柱转移者佩戴支具，避免弯腰、扭转及久坐久站，防止病理性骨折及脊髓压迫。\n2. 体位与护理：卧床者定期翻身（每2小时1次）并做踝泵运动，预防压疮、深静脉血栓及肺部感染；下肢转移者勿自行按摩、热敷病灶部位。\n3. 饮食：高蛋白、高钙、富含维生素D饮食（牛奶、豆制品、鱼类、瘦肉），多饮水（每日1500-2000ml），戒烟限酒。\n4. 疼痛管理教育：教会患者自我疼痛评分（NRS），按时规律服药，不可因担心成瘾自行停药或增减剂量。\n\n【随诊要求】\n1. 骨改良药物每4周1次治疗前复查血钙、血磷、肾功能（肌酐、尿素氮），长期用药者每6个月口腔检查1次，用药期间避免拔牙等有创牙科操作（预防颌骨坏死）。\n2. 每2-3个月复查影像学（X线、CT、MRI或全身骨显像ECT）评估病灶变化及疗效，每3-6个月复查骨密度。\n3. 每次复诊评估NRS疼痛评分、镇痛药物不良反应及生活自理能力，据此调整镇痛方案。\n4. 出现以下情况需立即就诊：新发或加重骨痛、肢体麻木无力、大小便功能障碍（警惕脊髓压迫）、病理性骨折、发热或注射部位红肿等。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1062,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a820269d89d80c17c71899431ee9a65a4b55b8428a282d8f05304e1c82935852","pinyin":"guzhuanyiliu","initials":"gzyl","setting":"out","caseName":"门诊病历930","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历930",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c6c6dca2b44b4b653f52","key":"v1-c9ccc21dfe2a3058|templates-c6c6dca2b44b4b653f52","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"软组织肿瘤","category":"门诊病历模板","raw":{"name":"软组织肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历931","templates":{"主诉":"发现软组织包块1月","现病史":"患者于6个月前发现软组织包块。部位方面：四肢（大腿最为常见，为软组织肉瘤好发部位）、躯干、腹膜后（肉瘤发现较晚，体积较大时症状才明显）、头颈，可为表浅皮下或深部肌层。生长情况：良性者生长缓慢，可数年大小稳定。质地：软（见于脂肪瘤或囊性病变）或实性、质硬（需警惕肉瘤）。边界：清楚、活动者多为良性；不清、固定者需警惕恶性。需注意软组织肉瘤的警示征象（对任何软组织包块均应警惕，十分重要）：位于深部（筋膜下、肌层）、体积大（超过5cm）、快速生长（数周至数月内增大）、疼痛或夜间痛、质地硬、固定或边界不清、复发，以及年龄（成人40岁以上肉瘤风险增加）；有无转移（肺为肉瘤主要血行转移部位，需评估咳嗽、咯血）；全身有无体重下降；既往有无放疗史（放疗后肉瘤潜伏期可长达10年以上）及遗传因素（神经纤维瘤病可致恶性周围神经鞘肿瘤、Li-Fraumeni综合征及家族史）；并注意深部、体积较大的包块。鉴别方面：良性肿瘤有脂肪瘤（质软、分叶）、纤维瘤、神经鞘瘤（沿神经分布，Tinel征阳性）、血管瘤（可压缩）及腱鞘囊肿（多见于腕背、透亮）；恶性肿瘤有软组织肉瘤（脂肪肉瘤、滑膜肉瘤、纤维肉瘤、横纹肌肉瘤等）及少见的软组织淋巴瘤。今日来我院骨科/普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP116/72mmHg。包块：记录部位、大小、深度（皮下、肌层或深部）、质地（软、实性或硬）、边界（清或不清）、活动度（活动或固定）、表面情况（皮温升高、静脉扩张提示肉瘤）、压痛及Tinel征（神经鞘瘤叩击可致放射痛）；透光试验（囊性病变阳性）及搏动或可压缩性（血管瘤）；有无多发（神经纤维瘤可多发）；区域淋巴结（肉瘤淋巴转移较少，以血行转移为主）；神经血管功能（深部病变可致压迫）；肺部检查（评估转移）及全身情况。","辅助检查":"【必做】超声可用于表浅包块的初筛（判断囊实性、脂肪、血管及深度），为首选初筛手段。【确诊/评估】MRI为软组织肉瘤影像学检查的金标准（可显示肌内病灶信号不均、强化及边界，明确肿瘤范围及其与解剖间室的关系，是制定手术计划的核心）；CT用于腹膜后病变及胸部（评估肺转移）；活检为核心手段，对深部、体积大或可疑的包块行粗针穿刺组织芯活检以获病理确诊，十分重要，应避免切除活检污染间室；细针穿刺适用于囊性或淋巴结病变；免疫组化可确定类型与分化（脂肪、平滑肌、横纹肌及神经源性肉瘤的分型，对治疗与预后有指导意义）；活检应遵循原则：沿最终手术切除的切口入路进行，使之可随肿瘤一并切除，十分重要，勿随意切口污染间室，应由肿瘤专科处理。【血液】血常规、肝肾功能，作为化疗基线。肿瘤分期按TNM，结合深度、大小、分级及有无转移，胸部CT评估肺转移。","初步诊断":"1. 软组织肿瘤（良性如脂肪瘤、纤维瘤等，或恶性如软组织肉瘤、类型待病理证实；记录部位、深度、大小、生长速度，评估警示征象及活检指征）\n（注：治疗依性质决定，良性者观察或切除，恶性肉瘤需多学科规范治疗：①良性（脂肪瘤、纤维瘤、神经鞘瘤）：无症状者可观察，或行切除（因症状、美观或诊断需要），切除标本应送病理以排除恶性，十分重要。②软组织肉瘤：疑有肉瘤者（深部、超过5cm、生长快速、质硬、疼痛）需行MRI加活检以确诊，十分重要，切勿当作良性脂肪瘤切除而误治。治疗需多学科在肉瘤中心进行：手术行扩大切除（完整切除肿瘤并保证安全切缘阴性，可行间室切除，十分重要；保肢手术为主，截肢极少采用，只要神经血管可保留并重建，保肢率可达90%以上；切缘阴性可降低复发，十分重要）；放疗（术前或术后辅助放疗，可降低局部复发，十分重要）；化疗（高危软组织肉瘤行术前或术后化疗，可用蒽环类及异环磷酰胺，亦用于转移治疗及肺转移灶切除）；靶向治疗（胃肠道间质瘤可用伊马替尼，靶向治疗有效；免疫治疗对部分亚型有效）；随访：监测复发（局部MRI，前2年每3~6个月复查，之后延长间隔）及肺转移（常规行胸部CT），处理远处转移，并做肢体功能康复；多学科协作（骨科、肿瘤科、放疗科、病理科）在肉瘤中心治疗，预后优于非中心治疗，十分重要。③随访教育：向患者说明包块的警示征象（深部、体积大、生长快、疼痛、质硬），出现时应及时就医，勿延误，十分重要，尤其四肢深部包块。骨科/软组织肿瘤专科处理：良性者切除并送病理，肉瘤行规范扩大切除加或不加放疗、化疗，保肢并随访，十分重要。）","处理方案":"【药物治疗】软组织肿瘤门诊处理以对症支持治疗为主，确诊及可疑恶性者转专科手术综合治疗，用药方案如下：\n1. 非甾体抗炎药（NSAIDs）镇痛：塞来昔布胶囊200mg po bid，或依托考昔片60mg po qd，餐后服用，疗程7~14天；用于肿物所致疼痛、炎症反应及术后镇痛，注意胃肠道及心血管风险，溃疡病史者慎用。\n2. 神经营养对症：甲钴胺片0.5mg po tid，疗程2~4周；用于肿瘤压迫神经所致肢体麻木、刺痛等周围神经症状，可联合维生素B1片10mg po tid。\n3. 软组织肉瘤辅助化疗（确诊恶性、转专科前过渡用药，需经病理及MDT评估）：如术前化疗常用表柔比星60~90mg/m²静脉滴注 d1，联合异环磷酰胺2.5g/m²静脉滴注 d1~d3，21天为一周期，每周期复查血常规、肝肾功能并调整剂量；该方案患者肿瘤专科医师指导下执行，门诊仅作转诊前交代。\n4. 合并感染或术后预防感染：头孢呋辛酯片0.25g po bid，疗程3~5天；青霉素过敏者改用阿奇霉素片0.5g po qd×3天。\n\n【一般治疗及生活指导】\n1. 休息与体位：避免肿物部位长期受压、摩擦及外力碰撞，防止外伤出血或继发感染；下肢肿物避免久站久行，休息时适当抬高患肢以减轻肿胀。\n2. 活动：非负重部位可行日常适度活动，但避免剧烈运动及对抗性运动（如跑步、球类、举重）以防肿物破裂、出血或恶变刺激；上肢肿物避免提举重物。\n3. 饮食：均衡营养，多摄入优质蛋白（瘦肉、蛋、奶、鱼虾）、新鲜蔬菜水果，保证维生素摄入；忌烟酒、辛辣刺激食物，肥胖者注意控制体重。\n4. 禁忌：严禁自行按摩、挤压、热敷、针灸、理疗及反复穿刺刺激肿物；不要盲目使用偏方外敷药物，以免刺激肿物生长或诱发恶变。\n\n【随诊要求】\n1. 良性软组织肿瘤（脂肪瘤、纤维瘤、血管瘤等）：每6~12个月复查超声1次，记录肿物大小变化；若3个月内体积增大超过原体积20%，或出现疼痛、活动受限、皮温升高、表面静脉曲张等，立即复诊。\n2. 可疑或确诊恶性软组织肿瘤（如肉瘤）：尽快完善增强MRI、增强CT及超声引导下穿刺活检明确病理分型及分期，及时转诊肿瘤外科/骨与软组织肿瘤专科评估手术切除及综合治疗方案。\n3. 术后患者：按医嘱定期复查，术后第1~2年每3个月随访1次，第3~5年每6个月1次，5年后每年1次，复查项目包括局部超声/MRI及胸部CT，监测局部复发及肺转移；出现伤口异常、肿物复发迹象随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1063,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"17c9dec6af5f044d7f93eb9f491c02e4ee42d76a0f04bc515e50fc49d916255e","pinyin":"ruanzuzhizhongliu","initials":"rzzzl","setting":"out","caseName":"门诊病历931","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历931",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-19a628038594fc08b55d","key":"v1-c9ccc21dfe2a3058|templates-19a628038594fc08b55d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂肪瘤","category":"门诊病历模板","raw":{"name":"脂肪瘤","category":"门诊病历模板","case":{"case_name":"门诊病历932","templates":{"主诉":"发现皮下无痛性包块1年","现病史":"患者于2年前（数月或数年不等）发现皮下包块。表现如下：位于皮下，无痛（多数患者无症状，常于体检或无意中发现）；质地软，呈分叶状，边界清楚，活动度好；部位多见于肩背、颈部、四肢及躯干皮下，深部者少见；大小自数毫米至数厘米，生长缓慢；可为多发（家族性多发性脂肪瘤为常染色体显性遗传，较少见）。另需了解有无疼痛（脂肪瘤多不痛，但压迫神经或筋膜时可痛，痛性脂肪瘤病即Dercum病可多发疼痛）、近期有无快速增大、质地变硬或固定（需警惕脂肪肉瘤，深部、超过5cm或位于肢体及腹膜后的肉瘤可能性较大，这一点很重要，需注意区分）、有无感染或破溃（脂肪瘤一般不感染）、有无神经压迫症状（深部病变邻近神经时）及体重变化（体重下降可见于全身脂肪萎缩或异常）；并了解既往脂肪瘤手术史（切除后复发少见）及脂肪肉瘤家族史。今日来我院普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P76次/分，R18次/分，BP118/74mmHg。包块：记录部位及大小（长径）、质地（软，呈橡皮样感、分叶状）、边界（清楚）、活动度（与皮肤不粘连，皮下可活动）、表面情况（皮肤正常、皮温不高）及压痛（无）；有无多发（记录数目及分布）；对深部较大包块，评估其与肌层的关系；区域淋巴结有无肿大；全身营养状态及脂肪分布有无异常，一并评估。","辅助检查":"【必做】以临床检查为主，典型的皮下、质软、分叶状包块即可诊断。【影像】超声可见皮下低回声、均质的脂肪性包块，可确认诊断（浅表而典型者可不需检查，但深部、体积大或疑为恶性者需行超声，以判断深部位置）；MRI或CT用于深部较大的（超过5cm）肢体深部脂肪源性肿瘤，与脂肪肉瘤鉴别（肉瘤强化不均、间隔增厚）及腹膜后脂肪源性肿瘤的评估。【确诊】活检或切除后病理：指征为诊断不明、疑为恶性（体积大、位置深、生长快速、质地变硬）或手术切除标本（可确诊脂肪瘤为良性）；细针穿刺用于深部或囊性病变的鉴别。","初步诊断":"1. 皮下脂肪瘤（单发或多发；记录部位及大小；为良性，并评估有无深部病变或脂肪肉瘤可能）\n（注：治疗上，良性者多无需治疗：①观察：无症状、体积小、表浅的脂肪瘤为良性，生长缓慢，告知患者随访即可（无需特殊处理，不必过度紧张），增大或出现症状时再行评估。②手术切除：指征为影响美观、有症状（疼痛或压迫神经）、体积大（超过5cm）或位于深部、诊断不明及疑为恶性（需警惕肉瘤）；手术可在门诊局麻下梭形切口完整切除（包膜完整切除以防复发，十分重要），标本送病理（以确诊良性并排除肉瘤，十分重要）；术后切口1~2周愈合拆线；若切除不完整可复发，但较少见，可再次切除。③深部或较大者需警惕脂肪肉瘤（深部、超过5cm，位于肢体或腹膜后，生长快、质硬者需行MRI评估，并手术扩大切除、送病理，按软组织肉瘤多学科治疗）。④随访：观察者定期注意包块变化，增大时就诊；术后病理为良性者不需随访；多发者（家族性）观察有无新发病灶；并进行教育，告知患者良性，勿恐慌，同时使其能识别异常变化，出现快速增大、变硬或疼痛时就医。普外科处理：良性者观察或切除，深部者与肉瘤鉴别，病理检查十分重要。）","处理方案":"【药物治疗】\n1. 局部麻醉药（手术切除为本病首选及根治性治疗，术前常规用药）：2%盐酸利多卡因注射液5～10ml，于瘤体周围及皮下浸润注射（单次总量不超过400mg），可加肾上腺素（1:100000～1:200000）以减少出血、延长麻醉时间。\n2. 术后预防感染（瘤体较大、切口较深或合并糖尿病等免疫低下者）：头孢呋辛酯片0.25g bid×3天，口服；对头孢菌素/青霉素过敏者改用阿奇霉素片0.5g qd×3天。一般小切口术后无需常规使用抗生素。\n3. 术后镇痛：布洛芬缓释胶囊0.3g bid，疼痛明显时口服，一般用2～3天，疼痛缓解即停用。\n4. 合并高脂血症者（对症治疗，不影响瘤体本身）：阿托伐他汀钙片20mg qn，长期口服，定期复查血脂及肝功能；脂肪瘤本身无特效口服消退药物，不建议盲目使用\"溶脂\"类及降脂药物。\n【一般治疗及生活指导】\n1. 术前避免反复挤压、揉搓或自行挑刺瘤体，防止局部感染、出血及瘤体增大；瘤体较大影响活动或美容者可择期手术切除。\n2. 术后48小时内保持切口干燥、避免沾水，遵医嘱按时换药，一般术后7～10天拆线；拆线前避免剧烈运动及切口部位过度牵拉、大量出汗。\n3. 饮食宜清淡均衡，减少动物脂肪、油炸及高糖食物摄入，多食新鲜蔬菜水果，控制体重，戒烟限酒，规律作息，避免长期大量饮酒（多发性脂肪瘤病与酒精代谢异常相关）。\n4. 多发性脂肪瘤者避免长期、反复物理刺激（如挤压、摩擦、热敷），并注意观察瘤体变化。\n【随诊要求】\n1. 术后7～10天门诊复诊拆线并评估切口愈合情况；术后2周内如出现切口红肿、疼痛加重、渗液或发热，随时门诊复诊。\n2. 切除标本常规送病理检查，术后1周左右门诊查看病理报告；如病理提示脂肪肉瘤或其他恶性改变（罕见），须立即至专科进一步诊疗。\n3. 单发且完整切除、病理为良性脂肪瘤者，治愈后一般无需特殊随访；多发性脂肪瘤者建议每6～12个月门诊复查，观察瘤体大小及数量变化。\n4. 随访期间如瘤体短期内明显增大、质地变硬、出现疼痛或活动受限，应及时复诊以排除恶变可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1064,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a68692baf78102eed66a48ace6d90e2c27daa8e6c4f5c63ca74a34c71f499fe9","pinyin":"zhifangliu","initials":"zfl","setting":"out","caseName":"门诊病历932","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历932",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d34cb07929249bf28163","key":"v1-c9ccc21dfe2a3058|templates-d34cb07929249bf28163","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"纤维瘤","category":"门诊病历模板","raw":{"name":"纤维瘤","category":"门诊病历模板","case":{"case_name":"门诊病历933","templates":{"主诉":"发现皮下硬结1周","现病史":"患者1周前无明显诱因出现纤维瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以发现皮下硬结1周为主诉就诊，考虑纤维瘤可能，需明确病变性质并排除软组织恶性肿瘤，入院即刻完善超声检查，了解皮下结节的位置、大小、边界、内部回声及血流信号，明确是囊性还是实性、有无侵犯周围组织；完善血常规、肝肾功能及电解质检查，排除感染、贫血及肝肾功能不全，为后续手术切除及麻醉提供安全性依据；完善凝血功能检查，排除凝血功能障碍及出血倾向，保障活检及手术安全；完善肿瘤标志物检查，作为鉴别软组织肉瘤等恶性病变的参考；必要时完善CT及MRI检查，明确肿物与深部肌肉、神经、血管及骨的关系，了解深部软组织病变范围，为手术切除范围提供依据；若临床高度怀疑恶性或存在多发结节、体重下降等表现，进一步查PET-CT，明确全身有无其他代谢活跃病灶，评估有无远处转移；确诊依赖病理，应完善病理活检检查，明确组织学类型及良恶性，必要时加做免疫组化以鉴别纤维肉瘤、隆突性皮肤纤维肉瘤等；对反复复发、多发或年轻患者，可加做基因检测，明确有无特征性基因改变，指导靶向治疗与遗传咨询；如病理提示恶性或需评估骨髓受累，必要时完善骨髓穿刺检查，明确骨髓有无肿瘤侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 纤维瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 纤维瘤属良性肿瘤，无特效消除药物，药物治疗仅作对症处理，根治手段为门诊手术完整切除并送病理；若术后病理为侵袭性纤维瘤病（韧带样型），转专科行系统性药物治疗（如他莫昔芬、塞来昔布等），不在门诊长期对症拖延。\n2. 病灶局部疼痛或伴炎症反应：非甾体抗炎药，布洛芬缓释胶囊0.3g po bid×5天，饭后服用，痛止即停；消化性溃疡活动期、严重肝肾功能不全及阿司匹林过敏者禁用。\n3. 皮肤纤维瘤伴明显瘙痒：抗组胺药，氯雷他定片10mg po qd×7天；瘙痒明显处可外涂外用糖皮质激素，如糠酸莫米松乳膏，薄涂bid×7天，不宜长期连续使用。\n4. 乳腺纤维腺瘤伴经前明显胀痛（合并乳腺增生症）：中成药，乳癖消片5～6片 po tid×2周，或逍遥丸（浓缩丸）8丸 po tid×2周，症状缓解即停，不能使瘤体消退。\n\n【一般治疗及生活指导】\n1. 避免反复揉捏、挤压、搔抓及摩擦病灶，衣物宜宽松柔软，防止局部损伤、感染及刺激生长。\n2. 每月固定角度拍照记录病灶大小、形态，动态对比观察；若短期内迅速增大、疼痛、破溃或出现多发新结节，及时就诊。\n3. 规律作息，避免熬夜，适度活动，避免病灶部位剧烈运动或直接碰撞；饮食均衡，多食新鲜蔬果，忌辛辣刺激及高脂饮食；乳腺纤维腺瘤患者避免服用含雌激素成分的保健品及丰胸类产品。\n4. 保持局部皮肤清洁干燥，出汗后及时清洗擦干；无明显症状者可正常生活工作，无需卧床休息。\n\n【随诊要求】\n1. 保守观察者每3～6个月门诊复查一次（专科查体+相应部位彩超评估病灶变化），连续1～2年稳定者可延长至每6～12个月复查一次。\n2. 手术切除者术后按医嘱拆线，1～3个月门诊复查伤口愈合情况；术后病理结果回报后携报告复诊，确诊良性者定期随访即可，若提示恶性变或侵袭性纤维瘤病，转专科制定后续方案。\n3. 观察或术后恢复期间，一旦出现病灶短期内明显增大、疼痛加重、破溃出血或新发多发结节，应立即复诊，勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1065,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd1b4e9f656ca658b2514f60c537c253a6032161c73a6c506a7d763ed7b2a583","pinyin":"xianweiliu","initials":"xwl","setting":"out","caseName":"门诊病历933","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历933",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d21dc681241d18c92d16","key":"v1-c9ccc21dfe2a3058|templates-d21dc681241d18c92d16","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"神经鞘瘤","category":"门诊病历模板","raw":{"name":"神经鞘瘤","category":"门诊病历模板","case":{"case_name":"门诊病历934","templates":{"主诉":"发现皮下包块伴疼痛1周","现病史":"患者1周前无明显诱因出现神经鞘瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以发现皮下包块伴疼痛1周为主诉就诊，考虑神经鞘瘤可能，需明确包块性质及其与神经的关系，入院即刻完善血常规、生化全项及凝血功能检查，排除感染、贫血、肝肾功能不全及凝血功能障碍，为穿刺活检或手术切除提供安全性依据；完善血糖、血脂及同型半胱氨酸检查，评估代谢及动脉粥样硬化危险因素，排除糖尿病及高同型半胱氨酸血症所致周围神经病变；患者包块伴疼痛提示神经受压可能，完善局部超声检查，了解包块的大小、边界、回声及与神经走行的关系，明确有无神经源性肿瘤特征；必要时完善MRI检查，明确肿瘤的范围、与神经干及周围血管肌肉的关系，鉴别神经纤维瘤、脂肪瘤及恶性外周神经鞘膜瘤；若包块位于颈部、纵隔或腹膜后等深部位置，或出现头痛、眩晕等神经系统症状，完善头颅CT/MRI检查，明确颅内有无病变及神经受压情况；完善颈动脉超声（颈部血管彩超）及经颅多普勒检查，评估颅内外血管有无狭窄、斑块及血流异常，排除血管性因素所致症状；完善心电图及心脏超声检查，排查栓子来源，排除心房颤动、附壁血栓及心源性栓塞；因其可能为神经纤维瘤病等遗传性疾病的表现，必要时完善皮肤及眼科相关检查与基因检测以明确诊断；若出现脑膜刺激征、颅内压增高或需鉴别感染性、炎性神经病变，必要时行腰椎穿刺检查，明确脑脊液压力、细胞数及蛋白水平。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 神经鞘瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 神经营养修复类：甲钴胺片0.5mg（500μg）tid×4周，口服；可联合维生素B1片10mg tid×4周，促进受累神经修复。\n2. 神经病理性疼痛对症：肿瘤压迫致疼痛明显者，加巴喷丁胶囊0.3g qn起始，耐受后3~7天内渐增至0.3g tid，疼痛缓解后逐渐减量停药。\n3. 炎性疼痛短期控制：塞来昔布胶囊200mg qd×5~7天，餐后服用，疼痛缓解即停，注意胃肠道及心血管不良反应。\n\n【一般治疗及生活指导】\n1. 神经鞘瘤多为良性、生长缓慢：无症状或体积小者可门诊定期观察；肿瘤出现压迫症状或短期内明显增大时，应转神经外科/骨科评估手术切除。\n2. 避免对肿瘤部位反复按压、揉搓、热敷、理疗及按摩，防止刺激肿瘤生长或诱发神经痛加重。\n3. 生活规律，保证充足睡眠，避免熬夜与精神紧张；适度活动，避免剧烈运动及肿瘤部位碰撞外伤。\n4. 饮食均衡，多食富含B族维生素食物（全谷物、瘦肉、蛋类、豆类、新鲜蔬果），戒烟限酒，保持二便通畅。\n\n【随诊要求】\n1. 观察随访者：每6~12个月复查MRI（或相应部位超声）评估肿瘤大小及与神经的关系，同时记录疼痛、麻木、肌力等神经功能变化。\n2. 术后患者：术后1~3个月复查手术部位影像并评估神经功能恢复情况；此后每6~12个月随访1次，连续2年，观察有无复发。\n3. 出现肿瘤快速增大、疼痛加重、肢体麻木无力进行性加重或新发神经功能障碍时，随时就诊，必要时转神经外科/骨科。\n4. 多发神经鞘瘤或合并NF2家族史者，建议行遗传咨询并至神经内科/神经外科长期专科随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1066,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"86efa8b32d0e4264ae21928aa339124881452c32d5530f6f8c7173e2306c5a84","pinyin":"shenjingqiaoliu","initials":"sjql","setting":"out","caseName":"门诊病历934","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历934",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6eac52f304e7f670f83b","key":"v1-c9ccc21dfe2a3058|templates-6eac52f304e7f670f83b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血管瘤","category":"门诊病历模板","raw":{"name":"血管瘤","category":"门诊病历模板","case":{"case_name":"门诊病历935","templates":{"主诉":"发现皮肤红色斑块1周","现病史":"患者1周前无明显诱因出现血管瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现皮肤红色斑块1周、逐渐加重并伴轻度乏力，需先完善血常规检查明确有无感染、贫血及血小板异常；因后续可能行硬化剂注射或手术切除，且病灶性质需与血管肉瘤等鉴别，完善肝肾功能检查评估肝脏代谢与肾脏排泄能力、了解有无肝内血管源性病变；完善电解质检查明确有无电解质紊乱，作为用药前的基线参考；完善凝血功能检查排除凝血机制异常，避免治疗中出血风险；为鉴别血管瘤与其他软组织肿瘤、评估有无远处转移，完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查明确病灶范围、边界及血流特征；完善MRI检查了解病灶与深部组织、神经血管束的关系，为治疗方式选择提供依据；完善CT检查了解深部及骨质有无受侵，完善PET-CT检查明确全身其他部位有无代谢异常活跃灶、排除多发病灶及远处转移；最终完善病理活检明确组织学类型以确诊，完善免疫组化检查鉴别血管源性标志物、明确病变性质，完善基因检测了解有无相关基因突变以指导后续靶向治疗；若病变广泛或疑有血液系统受累，必要时完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 血管瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部外用β受体阻滞剂（浅表、增殖期血管瘤首选）：0.5%马来酸噻吗洛尔滴眼液，每日2-3次外涂于瘤体表面，每次1-2滴均匀涂抹并轻按摩1分钟，疗程3-6个月，适用于表浅、面积较小且生长活跃的血管瘤，注意观察局部皮肤反应。\n2. 口服β受体阻滞剂（生长迅速、影响功能或局部治疗无效者）：盐酸普萘洛尔片10mg tid起始，用药前及用药中监测心率（静息心率不低于55次/分）、血压及血糖，如耐受可每2周递增剂量至20mg tid，疗程6-12个月；停药时须每2周减量1次缓慢撤药，避免反跳。\n3. 合并溃疡、破溃或继发感染者：局部清创后外用莫匹罗星软膏，涂于创面bid×7天，感染控制后停用；破溃明显者辅以无菌纱布覆盖换药，每日1次。\n【一般治疗及生活指导】\n1. 避免搔抓、摩擦、挤压或外力碰撞瘤体，洗澡时动作轻柔，防止破溃出血；穿宽松柔软棉质衣物，避免局部受压。\n2. 饮食清淡均衡，多食富含维生素C及蛋白质的食物；合并肝血管瘤者严格戒酒，避免辛辣刺激饮食及服用雌激素类、促凝类药物。\n3. 保持局部皮肤清洁干燥，破损处禁止热敷、艾灸或自行涂敷刺激性药物；避免剧烈运动及重体力劳动（尤其肝血管瘤、深部血管瘤患者）。\n4. 定期拍照记录瘤体大小、颜色、质地及边界变化，标记体表轮廓，以便复诊时对比生长速度。\n【随诊要求】\n1. 增殖期或正在口服普萘洛尔治疗者：每2-4周复诊1次，评估瘤体生长情况及药物反应，监测心率、血压、血糖；减量或停药阶段遵医嘱按时复查。\n2. 稳定期血管瘤：每3-6个月复诊1次；肝血管瘤每6-12个月行超声复查1次，瘤体直径≥5cm或近期增大明显者缩短复查间隔至3-6个月。\n3. 出现瘤体短期内迅速增大、破溃出血不止、疼痛、局部红肿热痛、肢体活动或功能障碍时，立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1067,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e29d6c20ee745a89095a43505268b28ed8070a309c8c2a8d03fe31085079b794","pinyin":"xueguanliu","initials":"xgl","setting":"out","caseName":"门诊病历935","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历935",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-04bdbc984ff082a9c886","key":"v1-c9ccc21dfe2a3058|templates-04bdbc984ff082a9c886","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋巴管瘤","category":"门诊病历模板","raw":{"name":"淋巴管瘤","category":"门诊病历模板","case":{"case_name":"门诊病历936","templates":{"主诉":"发现皮下囊性包块1周","现病史":"患者1周前无明显诱因出现淋巴管瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现皮下囊性包块1周、逐渐加重并伴轻度乏力，需先完善血常规检查明确有无感染、贫血及血小板异常；因淋巴管瘤可能行硬化治疗或手术切除，完善肝肾功能检查评估肝肾功能储备，指导治疗用药安全；完善电解质检查排除电解质紊乱；完善凝血功能检查排除凝血异常，避免穿刺或手术出血；为鉴别淋巴管瘤与淋巴结病变、软组织肿瘤，完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查明确囊性包块的大小、边界、内部回声及有无分隔、有无血流信号；完善MRI检查了解病灶与深部组织、神经血管束的关系，明确有无深部及纵隔、腹膜后蔓延；完善CT检查了解病灶与周围骨质、脏器关系，完善PET-CT检查明确全身有无其他代谢异常活跃灶、排除多发及远处病变；最终完善病理活检明确组织学类型以确诊，完善免疫组化检查鉴别淋巴管内皮标志物、明确病变性质，完善基因检测了解有无相关基因突变以指导治疗；若病变广泛或疑有血液系统受累，必要时完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 淋巴管瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 瘤腔内注射硬化治疗（局限性淋巴管瘤首选）：注射用盐酸平阳霉素8～16mg，以生理盐水2～4mL（可加2%利多卡因1mL）溶解，穿刺抽得囊液后行瘤腔内多点注射，注药前回抽确认无回血，注后局部压迫5分钟，每2～4周1次，3～5次为1疗程；亦可选用OK-432（沙培林）0.1～1.0KE瘤腔内注射，每2～4周1次。注药当日及次日可能出现发热，体温超过38.5℃予物理降温或布洛芬对症处理。\n2. 复杂性/难治性淋巴管瘤全身治疗：西罗莫司片2mg po qd（或每次0.8mg，每日2次），服药1～2周后检测血药谷浓度，调整剂量使谷浓度维持在10～15ng/mL，疗程6～12个月；用药期间每2～4周复查血常规、肝肾功能、血脂及空腹血糖。\n3. 瘤体合并继发感染时加用抗菌药物：阿莫西林克拉维酸钾片0.625g po tid，疗程5～7天；青霉素过敏者改用头孢呋辛酯片0.25g po bid，疗程5～7天，感染控制后即停药。\n\n【一般治疗及生活指导】\n1. 避免挤压、揉搓、碰撞瘤体及患处，防止瘤体破裂出血或继发感染；患处皮肤保持清洁干燥，洗澡时避免用力搓洗。\n2. 适当休息，避免患侧肢体剧烈运动、长时间受压及提重物；瘤体位于颈部、口底或咽部者需观察呼吸及吞咽情况，出现气促、声嘶、吞咽困难立即就诊。\n3. 均衡饮食，无特殊忌口；瘤体累及口腔、舌部者注意口腔清洁卫生，餐后漱口，避免辛辣刺激食物刺激病灶。\n\n【随诊要求】\n1. 硬化治疗期间每2～4周门诊复诊1次，评估瘤体缩小程度并安排下一次注射治疗。\n2. 疗程结束后分别于1、3、6个月复查患处彩色多普勒超声，必要时行MRI评估残留病灶及深部受累范围。\n3. 口服西罗莫司者每月复查血常规、肝肾功能、血脂、空腹血糖，并定期监测血药谷浓度。\n4. 治疗期间若瘤体短期内迅速增大、出现明显疼痛、局部红肿发热或破溃渗液，应随时就诊；术后患者同时注意观察切口愈合情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1068,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"454340a1ee0cc0659b70a08793d91db7f562d6df0d575efe000177ff1b58258d","pinyin":"linbaguanliu","initials":"lbgl","setting":"out","caseName":"门诊病历936","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历936",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d4aac4220ce321fc175c","key":"v1-c9ccc21dfe2a3058|templates-d4aac4220ce321fc175c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"滑膜肉瘤","category":"门诊病历模板","raw":{"name":"滑膜肉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历937","templates":{"主诉":"发现关节周围肿块1周","现病史":"患者1周前无明显诱因出现滑膜肉瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现关节周围肿块1周、逐渐加重并伴轻度乏力，滑膜肉瘤为高度恶性软组织肿瘤，需入院后尽快完善血常规检查明确有无感染、贫血及血小板异常；完善肝肾功能检查评估化疗药物的肝肾代谢与排泄能力，指导用药剂量；完善电解质检查排除电解质紊乱，防止化疗中加重；术前必须完善凝血功能检查排除凝血机制异常，避免活检或手术出血；完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查初步明确肿块大小、边界及血供情况；完善MRI检查明确肿瘤侵犯范围、与关节囊及神经血管束的关系，评估手术切除边界；完善CT检查了解有无肺及骨转移，完善PET-CT检查明确全身有无其他代谢异常活跃灶、排除多发及远处转移；最终完善病理活检明确组织学类型及恶性程度，完善免疫组化检查明确上皮及间叶标志物表达以确诊，完善基因检测检查有无SS18-SSX融合基因以指导诊断与靶向治疗；晚期或疑有转移者必要时完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 滑膜肉瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 靶向治疗（晚期或复发转移性滑膜肉瘤一线全身治疗可选）：安罗替尼胶囊 12mg 口服，每日1次，连续服用2周停药1周（服药d1-14），21天为1周期，长期服用至疾病进展或毒性不可耐受；用药期间每周监测血压，出现2级以上高血压或手足综合征时减量至10mg/d，必要时暂停。\n2. 靶向治疗（替代方案）：培唑帕尼片 800mg 口服，每日1次，餐前1小时空腹服用，持续至疾病进展或不可耐受毒性；用药前及用药期间定期复查肝功能、甲状腺功能、尿蛋白及血压。\n3. 姑息化疗（体能状况ECOG 0-1分、肝肾功能正常者，建议在日间病房或住院执行）：吉西他滨 900mg/m² 静脉滴注 d1、d8，联合多西他赛 75mg/m² 静脉滴注 d8，每21天为1周期；或一线选择多柔比星 60mg/m² 静脉滴注 d1，每21天为1周期，累积剂量达450-550mg/m²后停药并更换方案，化疗前常规予5-HT3受体拮抗剂止吐。\n4. 骨转移及骨痛管理：唑来膦酸 4mg 静脉滴注，每4周1次，用药前检查肾功能及血钙，全程常规补充钙剂 500-1000mg/d 及维生素D 400-800IU/d；中重度疼痛按WHO三阶梯原则予羟考酮缓释片 10mg 口服 q12h 起始，按疼痛评分滴定至无痛。\n【一般治疗及生活指导】\n1. 休息与活动：患肢避免过度负重及剧烈运动，休息时适当抬高患肢促进静脉回流；保肢术后按康复计划循序渐进行关节主动与被动活动锻炼，防止关节僵硬及肌肉萎缩，避免局部按摩、推拿及外力挤压，以防肿瘤出血或医源性播散。\n2. 饮食：高蛋白、高维生素、高热量易消化饮食，如鱼、蛋、瘦肉、奶制品、豆制品及新鲜蔬果；化疗期间注意饮食卫生，忌生冷、油腻及辛辣刺激食物，少量多餐。\n3. 皮肤与伤口护理：手术切口及放疗区域保持干燥清洁，避免搔抓、摩擦、暴晒、热敷及使用刺激性化妆品，每日观察有无红肿渗液、异常隆起或溃破，异常时及时就诊。\n4. 禁忌：戒烟限酒；避免使用含雌激素成分的药物及保健品；育龄期患者治疗期间及停药后6个月内采取有效避孕措施。\n【随诊要求】\n1. 术后及定期复查：术后2年内每3个月复查1次，第3-5年每6个月复查1次，5年后每年复查1次；复查项目包括患肢增强MRI或CT、胸部CT（重点筛查肺转移）、腹部超声及局部淋巴结超声。\n2. 治疗期间监测：靶向治疗者每月复查血常规、肝肾功能、尿蛋白、甲状腺功能并监测血压；化疗者每周期化疗前复查血常规、肝肾功能、心肌酶及心电图。\n3. 如出现患处新发疼痛或肿块、咯血、呼吸困难、不明原因发热、明显消瘦或夜间盗汗等，应立即返院就诊，必要时行PET-CT全面评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1069,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c0cd837dbcd555434dab5b01d78e6b3b656f5e381c81a0aaf17ae6b45e4efdb3","pinyin":"huamorouliu","initials":"hmrl","setting":"out","caseName":"门诊病历937","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历937",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-651d3a16a8ebdad66e09","key":"v1-c9ccc21dfe2a3058|templates-651d3a16a8ebdad66e09","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脂肪肉瘤","category":"门诊病历模板","raw":{"name":"脂肪肉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历938","templates":{"主诉":"发现肢体深部肿块1周","现病史":"患者1周前无明显诱因出现脂肪肉瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现肢体深部肿块1周、逐渐加重并伴轻度乏力，脂肪肉瘤为常见软组织肉瘤，需尽快完善血常规检查明确有无感染、贫血及血小板异常；完善肝肾功能检查评估化疗药物的肝肾代谢能力，指导用药剂量；完善电解质检查排除电解质紊乱；术前完善凝血功能检查排除凝血机制异常，避免手术及活检出血风险；完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查初步明确肿块回声、边界及血供；完善MRI检查明确肿瘤的部位、深度、范围及与神经血管束的关系，评估手术切除边界；完善CT检查了解肺部及骨质有无转移，完善PET-CT检查明确全身有无其他代谢异常活跃灶、排除多发及远处转移；最终完善病理活检明确组织学类型及分化程度以确诊，完善免疫组化检查鉴别脂肪源性标志物、明确病变性质，完善基因检测检查MDM2及CDK4扩增、明确有无去分化成分并指导靶向治疗；广泛病变者必要时完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 脂肪肉瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 靶向治疗（晚期或转移性、无法完整切除者）：安罗替尼胶囊12mg，口服，每日1次，早餐前服用，连服14天停药7天，21天为一周期；用药期间监测血压、尿蛋白及手足皮肤反应。\n2. 化疗（黏液样/圆细胞型脂肪肉瘤首选，或高危患者术后辅助）：表柔比星60mg/m²，静脉滴注，第1天；异环磷酰胺2.5g/m²，静脉滴注，第1～3天（同步使用美司钠解救并充分水化），每21天为1周期，由肿瘤科安排住院或日间病房实施。\n3. 二线化疗（蒽环类治疗失败后的去分化型/多形性型）：艾日布林1.4mg/m²，静脉注射，第1天及第8天，每21天为1周期。\n4. 对症止痛：轻度疼痛予塞来昔布胶囊0.2g，每日2次，口服；中重度疼痛予盐酸羟考酮缓释片10mg，每12小时1次，口服，按疼痛评分阶梯调整。\n【一般治疗及生活指导】\n1. 饮食：高蛋白、富含维生素饮食，适当增加瘦肉、蛋、奶及新鲜蔬果摄入；戒烟限酒，控制体重，避免肥胖。\n2. 活动：术后3个月内术区避免剧烈运动、提重物及过度牵拉，循序渐进进行关节功能锻炼，防止关节僵硬和肌肉萎缩。\n3. 局部护理：术区及肿物部位避免按摩、热敷、挤压及自行贴敷活血化瘀类膏药，防止局部出血、疼痛加重及肿瘤播散。\n4. 定期自查：每周自检体表及术区有无新发肿块、原有肿块有无增大或疼痛，发现异常及时就诊。\n【随诊要求】\n1. 术后随访：术后2年内每3个月复查1次，2～5年每6个月复查1次，5年后每年复查1次；复查项目包括术区超声或MRI、胸部CT（排除肺转移），高危亚型加做腹部及盆腔影像学检查。\n2. 化疗/靶向治疗期间：每2～3个周期评估影像学疗效及不良反应，定期复查血常规、肝肾功能、心肌酶谱及心电图（尤其患者蒽环类药物者）。\n3. 出现局部肿块增大、疼痛加剧、不明原因消瘦、发热或新发咳嗽胸痛等症状时，应随时就诊，必要时行穿刺活检明确有无复发或转移。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1070,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"25764725e8ad2ee63c53fef80c981160b00d91b08685d802e52388cb7702e723","pinyin":"zhifangrouliu","initials":"zfrl","setting":"out","caseName":"门诊病历938","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历938",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9eaf01b0fc1a687d4524","key":"v1-c9ccc21dfe2a3058|templates-9eaf01b0fc1a687d4524","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"纤维肉瘤","category":"门诊病历模板","raw":{"name":"纤维肉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历939","templates":{"主诉":"发现皮下质硬肿块1周","现病史":"患者1周前无明显诱因出现纤维肉瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现皮下质硬肿块1周、逐渐加重并伴轻度乏力，纤维肉瘤需与纤维瘤病及隆突性皮纤维肉瘤等鉴别，需尽快完善血常规检查明确有无感染、贫血及血小板异常；完善肝肾功能检查评估化疗药物代谢与排泄能力，指导用药剂量；完善电解质检查排除电解质紊乱；术前完善凝血功能检查排除凝血机制异常，避免活检及手术出血；完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查初步明确肿块大小、边界、质地及血流特征；完善MRI检查明确肿瘤侵犯范围及与深部组织、神经血管束的关系，评估手术切除边界；完善CT检查了解有无肺及骨转移，完善PET-CT检查明确全身有无其他代谢异常活跃灶、排除多发及远处转移；最终完善病理活检明确组织学类型及核分裂象以确诊，完善免疫组化检查排除其他梭形细胞肿瘤、明确病变性质，完善基因检测了解有无相关基因突变以指导后续治疗；疑有血液系统受累者必要时完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 纤维肉瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 术后辅助化疗（高危：切缘阳性、肿瘤深在、直径>5cm，需住院或日间化疗病房执行，门诊随访监测）：表柔比星60mg/m²静滴d1＋异环磷酰胺2g/m²静滴d1~d3（同步美司钠2g/m²静脉解救），21天为1周期，共4~6周期；每周期前复查血常规、肝肾功能、心电图，ANC≥1.5×10⁹/L、PLT≥100×10⁹/L方可进行。\n2. 靶向治疗（不可切除、转移性或辅助治疗后进展者）：安罗替尼12mg po qd，连服14天停7天，21天为1周期，直至疾病进展或不可耐受；或培唑帕尼800mg po qd，持续服用，注意监测血压、肝功能和甲状腺功能。\n3. 癌痛对症治疗：塞来昔布200mg po bid；疼痛控制不佳或中重度疼痛者加用盐酸曲马多缓释片100mg po bid（或q12h），必要时转疼痛科/安宁疗护评估阿片类药物方案。\n【一般治疗及生活指导】\n1. 患肢保护：术后3个月内患肢避免负重及剧烈运动，防跌倒、防病理性骨折，可佩戴支具；按康复科指导循序渐进进行关节活动度及肌力训练，避免过度牵拉。\n2. 饮食：高蛋白、高维生素、易消化饮食（鱼、蛋、瘦肉、乳制品、新鲜蔬果），保证充足热量；化疗期间清淡饮食、少食多餐，多饮水。\n3. 禁忌：严禁对肿瘤部位及手术区域按摩、挤压、热敷、理疗及针灸，避免剧烈冲撞和劳累；戒烟戒酒；保持切口及放疗区皮肤清洁干燥，避免摩擦、搔抓和暴晒，防止感染。\n4. 伤口护理：每日观察手术切口有无红肿、渗液、裂开，敷料渗湿及时更换；术后按医嘱定期换药拆线，出现异常及时就诊。\n【随诊要求】\n1. 术后2年内每3个月随诊1次，2~5年每6个月1次，5年后每年1次；行辅助化疗或靶向治疗者，每周期（3~4周）门诊复查血常规、肝肾功能、心电图及血压，必要时查甲状腺功能。\n2. 每次随诊复查原发部位局部MRI及胸部CT（肺为纤维肉瘤最常见转移部位），可疑骨转移者加做骨扫描；必要时PET-CT全身评估。\n3. 出现切口红肿渗液、患肢剧痛或肿胀、活动障碍，或不明原因发热、咳嗽、咯血、消瘦等，随时就诊，勿等定期复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1071,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b829df98c0c15e653451391b4f936cd5298cc53ea24e55046b123dec146479f0","pinyin":"xianweirouliu","initials":"xwrl","setting":"out","caseName":"门诊病历939","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历939",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-75ef886e9da61433b760","key":"v1-c9ccc21dfe2a3058|templates-75ef886e9da61433b760","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"横纹肌肉瘤","category":"门诊病历模板","raw":{"name":"横纹肌肉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历940","templates":{"主诉":"发现肢体肿块1周","现病史":"患者1周前无明显诱因出现横纹肌肉瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者主诉发现肢体肿块1周、逐渐加重并伴轻度乏力，横纹肌肉瘤多见于儿童及青少年、进展快且易早期转移，需尽快完善血常规检查明确有无感染、贫血及血小板异常；完善肝肾功能检查评估化疗药物的肝肾代谢与排泄能力，指导化疗方案及剂量；完善电解质检查排除电解质紊乱，防止化疗期间加重；术前完善凝血功能检查排除凝血机制异常，避免活检及手术出血；完善肿瘤标志物检查了解肿瘤负荷情况；完善超声检查初步明确肿块大小、边界及血供；完善MRI检查明确肿瘤侵犯范围及与神经血管束的关系，评估手术切除边界；完善CT检查了解有无肺转移，完善PET-CT检查明确全身有无其他代谢异常活跃灶、排除多发及远处转移；最终完善病理活检明确组织学类型及胚胎型、腺泡型分型以确诊，完善免疫组化检查明确肌源性标志物表达、明确病变性质，完善基因检测检查有无PAX3或PAX7-FOXO1融合基因以指导危险度分层与治疗；因该病易发生骨髓转移，必须完善骨髓穿刺检查明确有无骨髓侵犯。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 横纹肌肉瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 化疗（首选VAC方案，21天为一周期）：①长春新碱（VCR）1.4mg/m²（单次剂量不超过2mg），静脉推注，第1、8天；②放线菌素D（更生霉素，ACT-D）1.5mg/m²（单次剂量不超过2.5mg），静脉滴注，第1天；③环磷酰胺（CTX）2.2g/m²，静脉滴注，第1天。CTX用药当日及次日予美司钠（Mesna）解救（剂量为CTX的20%，于CTX输注后0、4、8小时静脉注射），同时充分水化（≥3000ml/d）并碱化尿液，预防出血性膀胱炎。低危组完成4～6周期，中高危组完成约12周期，具体周期数需结合手术与放疗时机个体化调整。\n2. 支持治疗：化疗结束后24～48小时起予重组人粒细胞集落刺激因子（rhG-CSF）5μg/kg，皮下注射，每日1次，直至中性粒细胞绝对值≥2.0×10⁹/L后停用；化疗前30分钟予昂丹司琼8mg静脉注射+地塞米松10mg静脉注射止吐，化疗后予昂丹司琼8mg口服，每日2次，连用3天。\n3. 感染防治：化疗期间每周复查血常规至少2次，若出现发热性中性粒细胞减少（体温≥38.3℃且中性粒细胞绝对值<0.5×10⁹/L），立即住院经验性抗感染治疗，如哌拉西林他唑巴坦4.5g静脉滴注，每6小时1次（肾功能不全者按肌酐清除率调整剂量），并复查血培养及感染指标。\n【一般治疗及生活指导】\n1. 休息：化疗后1周内适当卧床休息，保证每日睡眠≥8小时，避免熬夜及重体力劳动；发热、乏力明显时绝对卧床，减少探视以防交叉感染。\n2. 饮食：高蛋白、高热量、高维生素饮食（如鱼、蛋、瘦肉、乳制品、新鲜蔬果），每日饮水≥2000ml（化疗日≥3000ml）；化疗后恶心呕吐明显时少食多餐、进食清淡易消化食物，忌生冷、辛辣、油腻及隔夜不洁食物。\n3. 活动与防护：可进行散步等轻度活动，避免剧烈运动、对抗性运动及提重物，防止肿瘤部位（尤其侵犯骨或术后区域）外伤出血；体表肿瘤部位避免按压、揉搓、热敷及物理治疗。\n4. 禁忌：绝对戒烟戒酒；禁用含雌激素、雄激素成分的保健品及药物（性激素可刺激横纹肌肉瘤生长）；放化疗期间避免接种活疫苗；育龄期女性严格避孕。\n【随诊要求】\n1. 每周期化疗前复查血常规、肝肾功能、电解质、心电图及感染筛查（乙肝、丙肝、HIV），评估化疗耐受性并调整剂量。\n2. 治疗期间每2～3个月复查原发部位MRI或CT及胸部CT，评估疗效与远处转移情况，必要时行PET-CT。\n3. 完成治疗后定期随访：第1～2年每2～3个月、第3～5年每3～6个月、5年以上每年复查1次，项目包括原发部位影像学检查、胸部CT及血常规等。\n4. 随访期间出现发热（体温≥38℃）、出血、骨痛、呼吸困难、新发肿块或原有症状加重等，应立即到肿瘤科急诊就诊，不可等待预约复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1072,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"da381de1b165a02ca8e7ec5026f401e1a11ea0be9cd79d34e76b9dafac40f65e","pinyin":"hengwenjirouliu","initials":"hwjrl","setting":"out","caseName":"门诊病历940","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历940",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3cf0d9c9d1af16e1b6d9","key":"v1-c9ccc21dfe2a3058|templates-3cf0d9c9d1af16e1b6d9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"外阴阴道炎","category":"门诊病历模板","raw":{"name":"外阴阴道炎","category":"门诊病历模板","case":{"case_name":"门诊病历941","templates":{"主诉":"外阴瘙痒伴分泌物增多1周","现病史":"患者于3天前出现外阴瘙痒（注意程度，以夜间加重为特点）、灼痛及分泌物异常（量增多，颜色可为白、黄或绿色，性状可呈豆腐渣样（念珠菌感染）、泡沫状（滴虫感染）或稀薄并有鱼腥味（细菌性阴道病），可伴异味），并有外阴红肿、性交痛及尿痛（尿道刺激症状）。病因方面需考虑：阴道炎，包括念珠菌性阴道炎（白带呈豆腐渣样、瘙痒明显，即霉菌性阴道炎）、滴虫性阴道炎（白带黄绿色、泡沫状、有腥味）、细菌性阴道病（白带灰白、稀薄、有鱼腥味，由加德纳菌等致菌群失调）、萎缩性阴道炎（绝经后雌激素水平下降）、非特异性阴道炎；外阴炎，包括卫生状况不佳、尿液或粪便刺激（糖尿病尿糖可致）、过敏或刺激（卫生巾、化纤内裤、洗涤剂或沐浴露所致接触性皮炎）、蛲虫感染（儿童夜间肛周瘙痒）、念珠菌性外阴炎及前庭大腺炎；以及混合感染。全身因素需注意糖尿病（可致反复感染，十分重要，需查血糖）、免疫功能低下及长期使用抗生素（致菌群失调）。另需了解是否已行分泌物检测及自行用药情况（阴道冲洗或过度清洗会破坏正常菌群、加重病情）。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R18次/分，BP114/72mmHg。外阴：红肿、抓痕、糜烂及皲裂；分泌物：记录颜色、性状、量及气味；阴道：窥器检查见黏膜充血、点状出血，白带积于穹隆；检查宫颈及前庭大腺（红肿或脓肿）；儿童需检查肛周有无蛲虫；注意有无糖尿病相关皮肤表现及全身情况。","辅助检查":"检查计划：患者外阴瘙痒伴分泌物增多1周，夜间加重并伴灼痛、尿痛，需查白带常规明确阴道清洁度并了解有无菌群失调；以生理盐水湿片法及KOH法镜检滴虫及真菌，查找滴虫、真菌菌丝及芽孢以明确病原体；查线索细胞及pH值判断有无细菌性阴道病，行细菌性阴道病胺试验，若KOH试验后出现鱼腥味即为阳性；因患者分泌物性状多样、病程反复，需完善真菌培养以明确是否为念珠菌感染及具体菌种，用于反复发作或疑难病例；查滴虫检查，湿片见活动的滴虫即可确诊，湿片阴性而仍疑诊者行滴虫培养以提高检出率；查白带培养行需氧及厌氧细菌培养，明确有无混合感染并据药敏指导用药；若见脓性分泌物，需查宫颈衣原体及淋菌检查以排除宫颈炎及性传播感染；患者反复感染需评估诱因，查尿常规及血糖，糖尿病可致反复感染，为必查项目，十分重要；若为儿童患者夜间肛周瘙痒明显，需行蛲虫检查，可于夜间在肛周用胶带法取材。\n\n（检查清单）\n【必做】白带常规：查清洁度，镜检滴虫及真菌（湿片法或KOH法），查线索细胞（提示细菌性阴道病）及pH值；细菌性阴道病胺试验（KOH试验后出现鱼腥味为阳性）；真菌培养（用于反复发作或疑难病例）；滴虫检查（湿片见活动的滴虫，或行培养）；白带培养（需氧及厌氧细菌）；宫颈衣原体及淋菌检查（脓性分泌物者）；尿常规及血糖（糖尿病可致反复感染，为必查项目，十分重要）；蛲虫检查（儿童可于夜间在肛周用胶带法取材）。","初步诊断":"1. 外阴阴道炎（外阴炎或阴道炎（念珠菌性、滴虫性、细菌性、萎缩性）或混合性；病原体待查；评估诱因（卫生状况、糖尿病、过敏等））\n（注：治疗依病原体而定：①念珠菌性：可用克霉唑或咪康唑栓剂，或口服氟康唑150mg（参见霉菌性阴道炎）。滴虫性：口服甲硝唑或替硝唑2g单剂，性伴侣需同时治疗（参见滴虫性阴道炎）。细菌性阴道病：甲硝唑500mg bid×7天，或0.75%凝胶阴道用药，或克林霉素；性伴侣不需同治。萎缩性：局部患者雌激素软膏（参见老年性阴道炎）。非特异性或混合性：依培养结果针对性用药。②外阴炎：局部护理（温水清洗、坐浴，保持干燥，穿透气内裤）；依病原外用抗生素或抗真菌软膏（细菌用莫匹罗星，真菌用克霉唑）；过敏或炎症者短期外用弱效激素软膏（如氢化可的松）；避免刺激（停用致敏的卫生巾、洗涤剂或化纤内裤）；前庭大腺炎或脓肿需抗感染并行脓肿切开引流及造口。③卫生教育：正确清洗（每日温水清洗外阴，勿冲洗阴道内部，以免破坏正常菌群，十分重要）；内裤宜棉质、宽松、勤换并煮沸消毒；卫生巾及护垫勤换；便后由前向后擦拭（防止肛周细菌污染阴道，十分重要）。④诱因处理：糖尿病者控制血糖（反复感染者需查血糖，十分重要）；避免滥用抗生素（可致菌群失调）；增强免疫力。⑤随访：观察治疗后3~7天症状是否缓解；复发者（反复发作需查病原体、耐药情况及有无糖尿病）行培养及药敏检查；滴虫感染者性伴侣需同治；强调完成疗程、保证治疗依从性；妊娠期阴道炎与早产相关，需重视治疗。妇科处理：明确病原体、针对性治疗，做好卫生教育并控制诱因，十分重要。）","处理方案":"【药物治疗】\n1. 抗真菌治疗（外阴阴道假丝酵母菌病）：氟康唑胶囊150mg单次顿服；或克霉唑阴道片500mg，睡前阴道置入1片，单剂即可；重症或反复发作者氟康唑150mg，第1、4、7日各服1次。\n2. 抗滴虫及厌氧菌治疗（滴虫性阴道炎、细菌性阴道病）：甲硝唑片0.4g bid×7天；滴虫性阴道炎亦可用甲硝唑2g单次顿服，性伴侣需同时治疗。\n3. 局部联合用药：硝呋太尔制霉素阴道栓1枚，每晚睡前清洗外阴后阴道置入，连用6～7天；外阴瘙痒、灼痛明显者可同时外用克霉唑乳膏涂擦外阴，bid，连用7天。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，穿宽松棉质内裤，每日更换，内裤以沸水烫洗或阳光暴晒消毒；治疗期间避免性生活及盆浴。\n2. 注意休息，避免劳累，保证充足睡眠，多饮水，清淡饮食，忌辛辣刺激、油腻及甜腻食物。\n3. 避免自行阴道灌洗及使用刺激性洗液、卫生护垫，经期勤换卫生巾；合并糖尿病者需积极控制血糖。\n\n【随诊要求】\n1. 用药结束后1周复查白带常规，评估疗效；用药期间症状加重或3天无改善者及时复诊。\n2. 滴虫性阴道炎治疗后需在连续3次月经干净后复查白带常规均为阴性方视为治愈；症状反复发作或复诊仍阳性者，建议行阴道微生态检查及病原学培养＋药敏试验，调整治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1073,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"29688bb27301b16adef7c8c413ef6a9050440b80417c4512507140e6b7aa8dd8","pinyin":"waiyinyindaoyan","initials":"wyydy","setting":"out","caseName":"门诊病历941","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历941",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-90168b19b91df16d517f","key":"v1-c9ccc21dfe2a3058|templates-90168b19b91df16d517f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"滴虫性阴道炎","category":"门诊病历模板","raw":{"name":"滴虫性阴道炎","category":"门诊病历模板","case":{"case_name":"门诊病历942","templates":{"主诉":"外阴瘙痒伴白带增多1周","现病史":"患者于3天前出现外阴瘙痒（明显，伴灼痛）及白带增多（呈黄绿色、泡沫状，为滴虫感染的特征性表现，因滴虫产气所致；分泌物稀薄并有腥臭味，为滴虫感染所致异味；阴道分泌物刺激可致外阴红肿、灼热），并有性交痛及尿痛（尿道口受刺激，滴虫可累及尿道）。诱因及传播途径方面：性传播为主要途径，滴虫属性传播疾病，性伴侣需同时治疗，十分重要；间接传播（共用浴具、毛巾或马桶，滴虫在体外存活时间短，较少见，与卫生习惯有关）；月经后加重（滴虫在月经后阴道pH偏碱性时易于繁殖）；男性伴侣多无症状而带虫，为传染源，需同时治疗以防再感染，十分重要；妊娠期滴虫感染与早产及低出生体重相关，孕期需处理；并注意有无免疫力低下。复发方面，治疗不彻底或伴侣未治可致再感染，较为常见。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P86次/分，R18次/分，BP112/70mmHg。外阴：红肿、抓痕；阴道：窥器检查见黏膜充血、点状出血（草莓样宫颈为滴虫感染的特征性表现）；分泌物呈黄绿色、泡沫状、稀薄、量多，积于后穹隆；宫颈充血，呈草莓状；阴道pH升高，超过4.5；双合诊检查附件有无压痛（提示盆腔炎，滴虫上行感染较少见，需评估）；并检查尿道有无刺激症状及全身情况。","辅助检查":"检查计划：患者外阴瘙痒伴白带增多1周，白带呈黄绿色泡沫状并有腥臭味，伴性交痛及尿痛，首先完善白带湿片镜检，以生理盐水悬滴法在镜下观察活动的滴虫，呈梨形、有鞭毛并运动为特征性表现，可直接确诊，阳性率60~80%；查白带常规了解阴道清洁度及pH值，滴虫感染时pH多大于4.5；行革兰染色检查滴虫及阴道菌群情况，了解有无菌群失调；若湿片阴性而仍高度疑诊，需行滴虫培养，培养为金标准、敏感性高；可行聚合酶链反应检查，核酸检测敏感性高，为首选方法之一；因滴虫属性传播疾病、常合并其他感染，需完善性病筛查，包括淋病、衣原体、梅毒及HIV检查，合并感染需同时治疗，十分重要；患者有尿痛等尿道刺激症状，需查尿常规排查尿道炎；治疗期间及治愈后需复查白带以评估疗效，性伴侣亦应同时检查与治疗以防再感染。\n\n（检查清单）\n【必做】白带湿片镜检为核心：以生理盐水悬滴法在镜下观察活动的滴虫（呈梨形、有鞭毛并运动，为特征性表现，可确诊，阳性率60~80%）；白带常规（查清洁度及pH）；革兰染色（查滴虫及菌群情况）。【其他】培养（湿片阴性而疑诊者行培养，为金标准，敏感性高）；聚合酶链反应（敏感性高，核酸检测为首选方法之一）；性病筛查（淋病、衣原体、梅毒及HIV，滴虫为性传播疾病，合并感染需筛查，十分重要）；尿常规（排查尿道炎）。","初步诊断":"1. 滴虫性阴道炎（阴道毛滴虫感染，阴道pH>4.5，伴外阴炎或尿道炎，需评估性伴侣同治）\n（注：治疗以口服甲硝唑或替硝唑为核心，因滴虫可寄居于尿道及前庭大腺，局部用药不够，全身用药十分重要：①口服硝基咪唑类：甲硝唑2g单剂（首选，简便）或替硝唑2g单剂，或甲硝唑500mg bid×7天，治愈率85~95%；局部用药（甲硝唑栓阴道给药）可作辅助，但仍以口服为主，十分重要；耐药或治疗失败者应复查，考虑甲硝唑耐药，可改用替硝唑或加大剂量、延长疗程，必要时转专科。②性伴侣同治（必须进行，十分重要）：男性伴侣应同时口服甲硝唑2g单剂，否则可致再感染（治愈后再发多因伴侣未治，十分重要）；治疗期间禁止性生活，直至双方治疗完成。③孕妇：妊娠期滴虫感染可用甲硝唑（孕中期后患者，FDA B类，孕早期慎用；症状重者应处理，因与早产相关，治疗可减少早产）；哺乳期使用甲硝唑应暂停哺乳24小时（单剂治疗时），十分重要。④随访：治愈标准为症状消失且白带复查滴虫阴性（连续3次月经后复查阴性即为治愈，十分重要）；治疗后2~4周或下次月经后复查（复发多因再感染，需评估）；注意卫生（内裤煮沸消毒，浴具分开使用）；合并性病者需随访及治疗。妇科处理：口服甲硝唑加性伴侣同治，随访复查，防止复发，十分重要。）","处理方案":"【药物治疗】\n1. 硝基咪唑类（首选）：甲硝唑片400mg po bid，连用7天；亦可甲硝唑2g单次顿服。\n2. 硝基咪唑类阴道局部用药：甲硝唑阴道泡腾片0.2g，每晚1次置入阴道深部，连用7天，作为口服治疗的辅助或不能耐受口服者。\n3. 替硝唑片2g单次顿服（甲硝唑不耐受或疗效不佳时可选用）。\n4. 性伴侣同治：性伴侣同时口服甲硝唑400mg bid，连用7天；治疗期间及停药后24~48小时内禁酒，以防双硫仑样反应。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，勤换内裤；内裤、毛巾煮沸消毒或开水烫洗后阳光下暴晒。\n2. 治疗期间禁止性生活，避免交叉感染；性伴侣须同时检查并治疗，治愈前避免无保护性行为。\n3. 注意经期及性生活卫生，避免使用公共浴池、浴盆、坐式便器及不洁卫生用品，防止重复感染。\n4. 清淡饮食，忌辛辣刺激食物及饮酒，保证休息、避免劳累，增强机体免疫力。\n\n【随诊要求】\n1. 停药后于下次月经干净后3~7天复诊复查白带常规（生理盐水悬滴法找滴虫），连续3次月经后复查均为阴性方为治愈。\n2. 症状持续不缓解或反复发作者及时复诊，必要时行滴虫培养及药敏试验，调整治疗方案。\n3. 复诊时注意评估是否合并细菌性阴道病、外阴阴道假丝酵母菌病等混合感染及性传播疾病，予相应处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1074,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f96e713be6977fc36da667d42c00541e1d98aeca588ae247fa3181fed5784410","pinyin":"dichongxingyindaoyan","initials":"dcxydy","setting":"out","caseName":"门诊病历942","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历942",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c10625d3ba6103350967","key":"v1-c9ccc21dfe2a3058|templates-c10625d3ba6103350967","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"霉菌性阴道炎","category":"门诊病历模板","raw":{"name":"霉菌性阴道炎","category":"门诊病历模板","case":{"case_name":"门诊病历943","templates":{"主诉":"外阴瘙痒伴豆渣样白带1周","现病史":"患者于3天前出现外阴瘙痒（剧烈、难以忍受，以夜间加重，常因搔抓致皮肤破损）、灼痛（外阴红肿、灼热）及白带增多（呈白色稠厚、豆腐渣样或凝乳样，为其特征，可与滴虫性阴道炎（黄绿色、泡沫状、稀薄）及细菌性阴道病（灰白、有鱼腥味）相区别；多无臭味，这一点很重要，霉菌性阴道炎分泌物多无臭味），并有外阴红肿（小阴唇充血水肿）、性交痛及尿痛（尿道口刺激）。诱因方面：近期使用抗生素（广谱抗生素最为常见，可致菌群失调）、妊娠（高发，与激素及糖原变化有关）、糖尿病（血糖未控制者可致反复霉菌性阴道炎，为重要线索，需查血糖；反复发作者应警惕糖尿病，十分重要）、口服避孕药或激素治疗、免疫功能低下（如HIV感染或免疫抑制治疗）、紧身不透气内裤及不良卫生习惯（潮湿环境利于念珠菌生长）及月经前激素变化。分型方面：单纯性（偶发、轻中度，常规治疗即可）或复杂性（重度（外阴红肿皲裂）、复发性（1年内发作≥4次，需强化治疗）、妊娠期、合并糖尿病或免疫功能低下、非白念珠菌感染（如光滑念珠菌，可耐药，治疗不同）；复杂性者需延长治疗并查找诱因）。既往有无反复发作史（复发性外阴阴道念珠菌病需强化治疗加维持治疗；配偶一般不需同治，除非有龟头炎）及自行用药史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P82次/分，R18次/分，BP114/72mmHg。外阴：红肿（小阴唇充血水肿）、抓痕（搔抓所致）及皲裂（重度者可见）；白带：阴道口或阴道内可见白色稠厚豆腐渣样凝块；阴道窥器检查：阴道黏膜充血，附有白色膜状物（拭去后见黏膜潮红及糜烂点）；宫颈充血，表面覆有白带；双合诊无压痛，附件正常（除非上行感染，较少见）；并注意全身情况，如血糖升高相关的糖尿病皮肤表现。","辅助检查":"【必做】白带常规及湿片镜检（以盐水及10%氢氧化钾（KOH）溶解细胞后，镜下见假菌丝及孢子即可确诊，快速有效）、pH测定（正常或偏低，<4.5，可与细菌性阴道病（>4.5）及滴虫性阴道炎（>4.5）区别）；真菌培养（用于复发性或疑为非白念珠菌感染者，可行菌种鉴定及药敏，光滑念珠菌及克柔念珠菌可耐药）；复发性者需查找诱因（查血糖（糖尿病，十分重要）、HIV（反复发作者需评估免疫状态）、并评估能否停用抗生素）。【鉴别】滴虫性阴道炎（白带呈泡沫状、黄绿色，瘙痒，pH升高）、细菌性阴道病（白带灰白、稀薄，有鱼腥味）、萎缩性阴道炎（绝经后）及过敏性外阴炎（接触刺激物所致）。【其他】妊娠试验（hCG），妊娠期有症状者需处理。","初步诊断":"1. 外阴阴道假丝酵母菌病（霉菌性阴道炎；分为单纯性或复杂性（复发性、重度、妊娠期、合并糖尿病或非白念珠菌感染））\n（注：治疗以抗真菌为主，可局部或口服用药，单纯性者短程治疗：①单纯性：局部唑类（克霉唑栓500mg单次，或100mg连用7天，或用咪康唑栓）或口服氟康唑150mg单次（口服方便，与局部用药等效，为一线选择）；疗效约80~90%，症状数天内缓解。②复杂性：重度者延长治疗（局部用药7~14天，或氟康唑150mg间隔72小时连用2次）；复发性者（1年内发作≥4次）行强化加维持治疗，强化治疗（局部7~14天，或氟康唑150mg于第1、4、7天各1次），之后维持治疗（氟康唑150mg每周1次，连用6个月）以控制复发，长期用药可防复发，十分重要，维持治疗后需评估；同时须控制诱因（糖尿病者控糖是关键，停用不必要的抗生素，穿宽松棉质内裤并保持干燥）；非白念珠菌感染（光滑念珠菌对氟康唑耐药，多需局部患者硼酸或两性霉素，并做唑类耐药及培养药敏检查，转专科处理）。③妊娠期：局部唑类（克霉唑或咪康唑安全，疗程7天）；孕期不推荐口服氟康唑（孕早期慎用，十分重要）。④配偶：一般无需同时治疗（男性多无症状带菌，可不治疗；有龟头炎者需治疗）。⑤卫生：保持外阴干燥（不穿紧身或化纤内裤，宜棉质）；避免过度清洗或冲洗（会破坏正常菌群、导致复发）；浴巾分开使用并消毒。⑥随访：单纯性者症状缓解即可（不常规复查，治愈标准为症状消失）；复发性者维持治疗后随访6个月至1年，评估复发情况；妊娠期需产前治疗，以防新生儿经产道感染鹅口疮。妇科处理：单纯性者口服或局部用药一次多可治愈；复发性者行强化加维持治疗并查找诱因，十分重要。）","处理方案":"【药物治疗】\n1. 阴道局部用药（首选方案）：克霉唑阴道片（如凯妮汀）500mg，睡前阴道深部放置，单次给药；症状未完全缓解者4天后重复1次。亦可用克霉唑栓150mg，每晚1粒置入阴道，连用7天。\n2. 口服抗真菌药：氟康唑胶囊150mg，单次顿服，适用于单纯性外阴阴道假丝酵母菌病或不愿局部用药者。\n3. 局部外用药：克霉唑乳膏或咪康唑软膏，涂于外阴瘙痒及红肿部位，每日1-2次，连用7天，可缓解外阴症状。\n4. 复发性病例（1年内发作≥4次）：氟康唑胶囊150mg，第1、4、7天各服1次，症状控制后每周1次维持治疗6个月，医师指导下进行并定期监测肝功能。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，穿宽松、透气、棉质内裤并勤更换，内裤、毛巾用开水煮沸消毒或阳光暴晒，避免使用紧身化纤内裤及卫生护垫。\n2. 治疗期间避免性生活及阴道冲洗（冲洗可破坏阴道微生态、加重感染）；单纯性患者性伴侣无需常规治疗，但性伴侣有症状时应同步治疗。\n3. 避免滥用抗生素、糖皮质激素及免疫抑制剂；合并糖尿病者应积极控制血糖，将血糖控制在理想范围。\n4. 清淡饮食，少食甜食、高糖饮料及辛辣刺激食物，规律作息，适当运动，增强机体免疫力。\n\n【随诊要求】\n1. 单纯性患者治疗后症状消失者，无需常规复查；症状持续或反复发作者，应于治疗结束后1周复诊，行妇科检查及阴道分泌物真菌学检查以评估疗效。\n2. 复发性外阴阴道假丝酵母菌病患者，复诊时需评估并纠正诱因（血糖控制、抗生素及激素使用等），遵医嘱完成巩固治疗，并定期随访至少6个月，监测复发情况。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1075,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9afacdc50d1f8f7047f84ae1e83189ba4bd218306dd2e8e084a45166126f3ff7","pinyin":"meijunxingyindaoyan","initials":"mjxydy","setting":"out","caseName":"门诊病历943","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历943",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-107640ccda9c69aa69dd","key":"v1-c9ccc21dfe2a3058|templates-107640ccda9c69aa69dd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"老年性阴道炎","category":"门诊病历模板","raw":{"name":"老年性阴道炎","category":"门诊病历模板","case":{"case_name":"门诊病历944","templates":{"主诉":"绝经后阴道干涩伴瘙痒3月","现病史":"患者为绝经后女性（绝经后卵巢功能衰退，雌激素水平下降，阴道黏膜萎缩变薄，上皮糖原减少，阴道pH升高，乳酸杆菌减少，局部防御力下降，易发生感染，即萎缩性阴道炎，又称老年性阴道炎；此外，手术或放疗后卵巢切除、放疗所致人工绝经者亦可出现同样改变，哺乳期闭经、低雌激素状态者少见，老年女性（>60岁）最为常见）。患者绝经后症状逐渐出现并反复发作，主要表现为：阴道干涩（黏膜萎缩、分泌物减少所致）、瘙痒（外阴及阴道刺激症状）、灼痛（黏膜炎症所致）、分泌物增多（稀薄、淡黄色、水样，可带血丝，继发感染时可呈脓性）、性交痛（黏膜萎缩变薄，摩擦所致疼痛及出血）、尿频尿急（尿道黏膜萎缩刺激引起的尿路刺激症状）、阴道出血（黏膜脆弱，接触后出血或血性分泌物。绝经后出血为重要症状，需排除子宫内膜病变及宫颈肿瘤，注意鉴别）。需询问有无绝经后出血（必须排除器质性病变，如子宫内膜癌、宫颈癌、息肉等，超声检查子宫内膜，必要时行内膜活检，此为重要指征，切勿简单归因于阴道炎）、有无糖尿病（易合并念珠菌感染）、有无卫生习惯不良或过度清洗、阴道用药等刺激因素、有无滴虫或念珠菌等合并感染（需检查）、有无激素替代治疗、有无放疗史及手术史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP126/76mmHg。外阴萎缩，皮肤变薄、皱缩；阴道黏膜苍白或充血，可见点状出血点，黏膜菲薄，皱襞消失；分泌物稀薄，呈黄水样，可带血性；窥器插入时疼痛，黏膜脆弱，易出血，检查应轻柔；宫颈萎缩、光滑；双合诊子宫萎缩；阴道pH>4.5，偏碱性；盆腔检查附件区未及包块，注意除外其他病变。","辅助检查":"【必做】白带常规：清洁度、白细胞、pH（升高），滴虫及真菌镜检（排除合并感染，为重要项目）；宫颈细胞学检查（TCT）：绝经后出血或宫颈异常者筛查，为重要项目；盆腔超声：观察子宫内膜厚度（<5mm为萎缩，属正常；增厚提示内膜病变，为活检指征，为重要项目）、附件及子宫；阴道pH试纸。【其他】雌激素水平（促卵泡激素、雌二醇，用于确认绝经，非常规必要）；血常规（了解感染）；血糖（除外糖尿病）；尿常规；必要时行子宫内膜活检（内膜增厚或出血者）、宫颈活检（宫颈异常者）。","初步诊断":"1. 老年性阴道炎（萎缩性阴道炎，绝经后雌激素缺乏、阴道pH升高伴萎缩，已排除绝经后出血及器质性病变）\n（注：治疗原则为补充雌激素加局部抗炎以缓解症状。①局部雌激素（核心措施，用于恢复黏膜）：雌激素阴道软膏（雌三醇软膏或结合雌激素软膏），每晚1次阴道涂药，或每周2~3次，连用2~4周，症状缓解后维持治疗（每周1~2次）；亦可用雌三醇栓阴道局部用药，安全性好（低剂量局部用药血药浓度低，不需全身激素治疗，此点重要）。全身激素替代治疗适用于绝经后症状明显且有适应证者（如潮热、骨质疏松），需评估后使用，但单纯阴道炎局部用药已足够，全身用药需权衡乳腺等风险（参见绝经管理）。②抗感染：合并细菌、滴虫或真菌感染时，选用相应阴道抗菌药物（甲硝唑栓或克霉唑，依病原体选择），先局部抗炎（抗生素或抗真菌外用药，1周）。③对症及护理：润滑（性交时用水基润滑剂，减少摩擦痛）、保湿（阴道凝胶）、卫生（温水清洗外阴，勿过度清洗阴道，以免破坏菌群）、穿宽松棉质内裤。④随访：症状于2~4周缓解后评估；绝经后出血或血性分泌物持续者复查超声，观察子宫内膜，排除病变，此为重要环节，切勿忽视；本病为慢性萎缩性改变，易复发，需维持治疗，可间断长期局部使用雌激素；长期局部使用雌激素者应随访用药安全。妇科处理要点：局部雌激素加抗炎，排除器质性病变，随访，甚为重要。","处理方案":"【药物治疗】\n1. 局部雌激素制剂（增强阴道黏膜抵抗力）：普罗雌烯阴道胶囊（更宝芬）1粒（10mg）阴道放置 qd×10～14天；或结合雌激素软膏（倍美力软膏）0.5g 阴道涂抹 qn×10～14天。子宫及乳腺有肿瘤病史者禁用，用药前需评估。\n2. 局部抗菌治疗（抑制混合感染）：甲硝唑栓 200mg 阴道放置 qn×7～10天；合并严重混合感染或滴虫感染时，加用甲硝唑片 400mg po bid×7天。\n3. 症状明显或反复发作者，可联合阴道乳酸杆菌活菌胶囊 1粒 阴道放置 qd×10天，重建阴道微生态；雌激素制剂与抗菌药间隔2小时以上使用。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，每日温水（37℃左右）清洗外阴1次，避免热水烫洗、反复冲洗阴道及使用碱性肥皂、妇科洗液，以免破坏阴道正常菌群。\n2. 穿宽松、透气的纯棉内裤并勤更换，内裤宜煮沸或阳光暴晒消毒，避免穿化纤紧身裤及长期使用卫生护垫。\n3. 注意休息，保证睡眠，适当活动增强体质；饮食宜清淡、富含蛋白质和维生素，适量补充钙剂及维生素D，戒烟酒，避免辛辣刺激性食物。\n4. 治疗期间避免性生活及盆浴，必要时使用水性润滑剂；症状缓解后注意会阴部卫生，大便后从前向后擦拭，防止肛周菌群污染阴道。\n\n【随诊要求】\n1. 用药后1～2周门诊复诊，评估外阴瘙痒、灼痛及分泌物等症状改善情况，必要时复查阴道分泌物检查（白带常规+病原学）。\n2. 使用雌激素制剂者，建议每6～12个月行妇科超声检查子宫内膜，并定期行乳腺检查，监测雌激素相关不良反应。\n3. 如治疗2周后症状无缓解或反复发作、出现异常阴道出血、阴道灼痛加重、发热等情况，应及时就诊，进一步排除滴虫、真菌感染及外阴阴道恶性病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1076,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8cfe33c028125f3b233bc3cc8298191e732da51602da72cb0450f9c7b71fcd2d","pinyin":"laonianxingyindaoyan","initials":"lnxydy","setting":"out","caseName":"门诊病历944","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历944",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7db4b3f84d4c13cf5255","key":"v1-c9ccc21dfe2a3058|templates-7db4b3f84d4c13cf5255","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"宫颈糜烂","category":"门诊病历模板","raw":{"name":"宫颈糜烂","category":"门诊病历模板","case":{"case_name":"门诊病历945","templates":{"主诉":"体检发现宫颈柱状上皮异位1月","现病史":"患者为育龄期女性（宫颈糜烂样外观系鳞柱交界区柱状上皮外移，即宫颈柱状上皮异位，属生理现象，过去误称为糜烂，实为柱状上皮外移，并非真性糜烂，也不是疾病，此点需向患者科普，以消除过度治疗；激素水平影响明显，雌激素水平高时生育期柱状上皮外移明显，妊娠期加重，绝经后则退缩、宫颈表面转为光滑）。患者于体检或妇科检查时发现宫颈糜烂样外观，主要表现如下：多数无症状，因属生理性柱状上皮外移；部分有分泌物增多，但多与宫颈炎或阴道炎相关，而非糜烂本身所致；接触性出血者需查明原因（柱状上皮脆弱，可致出血，但需排除宫颈病变、息肉及癌，此点重要）；腰骶部不适多与盆腔病变无关。需鉴别真性宫颈炎（感染所致，宫颈脓性分泌物、红肿，需要治疗）、宫颈上皮内病变及宫颈癌（同房后出血者重要，宫颈癌筛查是排除的关键；宫颈糜烂样外观本身不等同于病变，但筛查仍必须进行）、宫颈息肉及肌瘤；并注意有无HPV感染（筛查有无合并）、宫颈癌筛查情况（无论外观如何，均应定期行TCT及HPV检查）。另需了解年龄（绝经后外观可消退）、既往筛查及治疗史（有无物理治疗史，如激光、冷冻等；以往过度治疗曾较普遍，现已规范，不应过度治疗）。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP118/72mmHg。妇科检查：窥器暴露宫颈，见宫颈糜烂样外观（宫颈口周围红色区域，系柱状上皮外移，表面光滑、色红，无真性糜烂及溃疡；碘试验不着色，符合柱状上皮），范围分轻、中、重三度（依面积判定）；观察分泌物量及性状；以棉签轻拭评估有无接触性出血；注意宫颈口有无息肉；双合诊检查子宫及附件，除外盆腔病变；检查阴道有无并存炎症。","辅助检查":"【必做】宫颈细胞学检查（TCT）筛查，必须进行（宫颈糜烂样外观不能判断良恶性，筛查可防止漏诊癌前病变及宫颈癌，为常规且重要的项目）；HPV检测（联合筛查，高危型HPV与宫颈癌相关，重要）；白带常规（评估有无阴道炎并存及宫颈炎）。【其他】阴道镜（TCT或HPV异常，或存在接触性出血时行阴道镜评估，为活检指征）；衣原体及淋菌检测（宫颈炎、脓性分泌物者）；宫颈活检（阴道镜下可疑病变，行组织学检查以确诊）。","初步诊断":"1. 宫颈柱状上皮异位（宫颈糜烂，属生理性鳞柱交界外移，无症状；宫颈癌筛查（TCT/HPV）结果未见异常；并评估有无宫颈炎及阴道炎）\n（注：治疗方面，生理性者无需治疗，此点须向患者科普，纠正“糜烂是病”的误区，防止过度治疗；物理治疗如激光、冷冻等对生理性柱状上皮异位并不需要，反而可能损伤宫颈、影响生育及分泌功能，此点重要。①观察：无症状的生理性异位无需任何治疗，定期筛查随访即可；告知患者宫颈糜烂是正常柱状上皮外移，不是疾病，也不是宫颈癌前兆，以消除焦虑，此点重要；但定期宫颈癌筛查必须坚持。②治疗并存宫颈炎：真性宫颈炎多由感染所致，表现为脓性分泌物，应检测病原体（衣原体、淋菌），选用多西环素或阿奇霉素，或头孢曲松，依病原体选择；合并阴道炎（滴虫、念珠菌、细菌性阴道病）者按病原体治疗。③筛查异常：TCT或HPV异常者行阴道镜及宫颈活检（参见宫颈上皮内病变、宫颈癌分级处理：低度病变可观察随访，高度病变行锥切治疗，此点重要，以防癌变）。④接触性出血：筛查正常而存在息肉者予以切除；柱状上皮脆弱所致出血可告知观察，若反复出血则再行阴道镜评估。⑤随访：宫颈癌筛查应定期进行（TCT及HPV，每1~3年1次，依年龄及结果而定，重要）；本病与激素相关，无复发之虞，无需处理；避免过度治疗，物理治疗指征极少，除症状性宫颈炎且药物治疗无效者外，现代观点基本不做物理治疗，此点重要。妇科处理要点：生理性者以科普为主，筛查为核心，不过度治疗，甚为重要。","处理方案":"【药物治疗】\n1. 抗菌药物（检测提示沙眼衣原体或淋球菌等病原体感染时使用）：阿奇霉素片 1g 单次顿服；或多西环素片 0.1g 每日2次口服，连用7天。\n2. 阴道局部抗炎治疗（合并宫颈炎、分泌物增多者）：保妇康栓（莪术油、冰片）1粒，每晚睡前清洗外阴后置入阴道深部，1次/日，连用14天。\n3. 促糜烂面修复及抗病毒（合并高危型HPV感染或糜烂面较深、白带量多者）：重组人干扰素α2b阴道栓/泡腾胶囊 10万IU，隔日1粒，每晚睡前阴道给药，共10次。\n4. 合并滴虫性阴道炎或细菌性阴道病时：甲硝唑栓 0.2g，每晚睡前阴道给药，连用7天；或甲硝唑片 0.4g 每日2次口服，连用7天。\n【一般治疗及生活指导】\n1. \"宫颈糜烂\"多为宫颈柱状上皮异位的生理性表现，无症状者无需特殊治疗、勿盲目用药；保持外阴清洁，每日温水清洗外阴即可，避免使用各类洗液反复冲洗阴道，以免破坏阴道微生态。\n2. 治疗期间禁止性生活及盆浴（可淋浴），注意经期卫生，勤换卫生巾及棉质内裤，保持局部干爽透气。\n3. 清淡均衡饮食，忌辛辣刺激、生冷油腻，戒烟限酒；适当休息，避免过度劳累及剧烈运动，增强机体免疫力。\n4. 有性生活女性应定期行宫颈癌筛查（TCT+HPV）；出现接触性出血、白带异味或腰骶部不适时及时就诊。\n【随诊要求】\n1. 药物治疗结束后2～4周复诊，行妇科检查及白带常规复查，评估糜烂面愈合及症状改善情况。\n2. 未完成宫颈癌筛查者建议完善TCT+HPV联合筛查，结果异常者按规范进一步行阴道镜检查及宫颈活检，并遵医嘱定期随访。\n3. 治疗期间出现下腹痛加重、发热、异常阴道出血等随时急诊复诊；症状无改善或反复发作者复诊，评估后必要时行物理治疗（激光、微波、冷冻）或LEEP手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1077,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b9bde2e63f6d7441bede648d39f6ee7095ac51cd75d1b7e43c3c8e461691e099","pinyin":"gongjingmilan","initials":"gjml","setting":"out","caseName":"门诊病历945","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历945",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bdc69cef2d3e8495fa80","key":"v1-c9ccc21dfe2a3058|templates-bdc69cef2d3e8495fa80","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"宫颈息肉","category":"门诊病历模板","raw":{"name":"宫颈息肉","category":"门诊病历模板","case":{"case_name":"门诊病历946","templates":{"主诉":"反复同房后阴道出血1月","现病史":"患者为育龄期女性，本病育龄期多见，多因慢性宫颈炎所致（宫颈管黏膜增生形成息肉，长期炎症刺激是主要因素），亦与雌激素水平有关（妊娠期息肉可长大，受激素刺激）。患者于体检发现或出现症状后就诊，主要表现为：接触性出血（同房后或妇科检查后有少量出血，为最常见症状）、月经间期出血（点滴状，不规则）、白带增多（黏稠，可带血丝，可有异味）、部分患者无症状（多数息肉较小，无症状，于体检时发现）。息肉多见于宫颈口，单个或多个，呈舌状，质软，色鲜红，有蒂，自宫颈管脱出至宫颈口；出血多因息肉摩擦、破溃所致。需鉴别以下疾病：宫颈癌（接触性出血、同房后出血与宫颈息肉症状相同，此点重要；凡有接触性出血者均需行宫颈癌筛查，包括TCT、HPV及阴道镜，以排除恶性病变，此为关键）、宫颈糜烂样外观即柱状上皮外移（属生理性）、宫颈肌瘤或黏膜下肌瘤（可脱出，需鉴别）、妊娠期宫颈充血及蜕膜息肉样改变、宫颈其他病变（筛查异常者需进一步评估）。绝经后出血虽可为息肉所致，但仍需排除子宫内膜及宫颈恶性病变，此点重要。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P80次/分，R18次/分，BP120/74mmHg。妇科检查：窥器暴露宫颈，见宫颈口息肉（记录大小、单个或多个、蒂的长短，呈舌状，色鲜红，质软，易出血）；宫颈可见糜烂样外观（柱状上皮外移）并存；阴道内可见出血及分泌物；双合诊检查子宫及附件，除外其他出血来源；注意息肉表面是否光滑，有无糜烂、坏死及感染；绝经者宫颈萎缩。","辅助检查":"【必做】宫颈细胞学检查（TCT，为常规项目，用于排除宫颈病变，重要；有接触性出血者必查）、HPV检测（高危型筛查，与TCT联合；同房后出血与HPV感染相关，重要）。【其他】息肉切除后送病理检查（排除恶性；息肉多为良性，但需经病理确诊，重要）、阴道镜（TCT或HPV异常，或息肉可疑时行阴道镜评估）、盆腔超声（了解子宫内膜有无息肉，即宫腔内膜息肉可同时存在，以及子宫、附件情况）、妊娠试验（育龄期月经异常者）。","初步诊断":"1. 宫颈息肉（宫颈口息肉，单发或多发，记录大小；由慢性宫颈炎所致，伴接触性出血；已行宫颈病变筛查（TCT/HPV），待病理确诊）\n（注：治疗以切除根除并送病理确诊为原则。①息肉切除：行宫颈息肉摘除术（门诊即可完成；小息肉可用蒂部钳夹旋转拧下，或行息肉电切并处理基底），切除物必须常规送病理检查，以排除恶性（息肉恶变极少，但需经病理确诊，此点重要）；术后少量出血属正常，有感染指征时方用抗生素，并随访创面愈合情况。②治疗宫颈炎（为基础治疗，控制慢性宫颈炎以防复发，息肉复发与炎症相关）：宫颈炎症可予局部抗炎，激光、冷冻、微波等物理治疗适用于慢性炎症较重者；现代观点多不主张过度治疗宫颈炎，因生理性柱状上皮外移并非疾病，仅在存在症状或感染时才有治疗指征。③随访：术后病理结果良性者告知患者预后良好；息肉复发较常见，需随访妇科检查，每年1次，并行宫颈刮片；定期宫颈癌筛查（TCT/HPV，每1~3年1次，依年龄及结果而定，重要）；切除后再发接触性出血者应复查，以排除其他病变。妇科处理要点：切除加病理，配合TCT/HPV筛查，防止漏诊宫颈癌，甚为重要。","处理方案":"【药物治疗】\n1. 宫颈息肉多合并慢性宫颈炎/阴道感染，伴白带增多、异味或镜检提示感染时：甲硝唑片0.4g bid×7天（滴虫/细菌性阴道病）；合并真菌感染改用克霉唑阴道片500mg，单次睡前阴道给药。\n2. 合并衣原体/淋球菌感染（分泌物支原体衣原体检测阳性）：阿奇霉素片0.5g qd×3天；或头孢曲松钠1g 肌注单次（淋球菌感染）。\n3. 息肉摘除术后预防创面感染（无头孢过敏史者）：头孢呋辛酯片0.25g bid×3天。\n4. 术后阴道少量出血、创面渗血：酚磺乙胺片0.5g tid×3天；或氨甲环酸片0.5g tid×3天。\n【一般治疗及生活指导】\n1. 息肉摘除后宫颈创面愈合约需1~2周，术后2周内禁止性生活和盆浴，可淋浴；保持外阴清洁干燥，每日温水清洗外阴，勤换内裤。\n2. 避免使用刺激性洗液或药水反复冲洗阴道，以免破坏阴道微生态、诱发炎症。\n3. 注意休息，避免重体力劳动、剧烈运动及长时间站立，防止创面出血。\n4. 饮食清淡，多食高蛋白及富含维生素食物（鱼、蛋、瘦肉、新鲜蔬果），忌辛辣、生冷及活血食物（如酒、辣椒），多饮水。\n【随诊要求】\n1. 术后2~4周门诊复查，检查宫颈创面愈合及出血情况。\n2. 息肉易复发，术后3个月、6个月各复查一次妇科检查，必要时行阴道镜检查。\n3. 摘除息肉标本常规送病理检查，如病理回报为恶性或癌前病变，须及时门诊就诊进一步处理。\n4. 术后出现阴道出血量多（超过月经量）、腹痛、发热或异常分泌物等，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1078,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"62d35c850cf09c3f068da1f478562dac9236ae8b238c5c17cbb82b6d1b32c38d","pinyin":"gongjingxirou","initials":"gjxr","setting":"out","caseName":"门诊病历946","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历946",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c73cc4e32981339430bd","key":"v1-c9ccc21dfe2a3058|templates-c73cc4e32981339430bd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"宫颈肥大","category":"门诊病历模板","raw":{"name":"宫颈肥大","category":"门诊病历模板","case":{"case_name":"门诊病历947","templates":{"主诉":"反复白带增多1周","现病史":"患者1周前无明显诱因出现宫颈肥大相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复白带增多1周为主诉就诊，伴轻度乏力，首先完善血常规检查，排除感染性疾病及贫血所致乏力；完善尿常规检查，排除泌尿系统感染，并了解有无尿糖、尿蛋白等异常；查白带常规明确阴道分泌物的病原学情况，判断有无细菌、滴虫、真菌等感染并指导后续用药；患者白带增多需排除宫颈病变，完善宫颈TCT+HPV联合筛查以明确宫颈有无上皮内病变及高危型人乳头瘤病毒感染，必要时转阴道镜检查；查妇科超声了解子宫、宫颈形态及大小、双侧附件有无包块及盆腔积液情况，评估宫颈肥大的程度与伴随病变；乳腺超声作为妇科门诊常规基线检查，了解乳腺有无结节、增生等异常；患者自觉乏力、白带改变，完善性激素六项检查了解卵巢内分泌功能，评估有无内分泌紊乱参与发病；完善血HCG检查排除妊娠相关疾病，避免药物及检查干扰；查肿瘤标志物（必要时）包括CA125、CA19-9，鉴别宫颈及附件的恶性病变。以上检查建议门诊当日完成血常规、尿常规、白带常规及血HCG，TCT+HPV及超声可于就诊后1周内安排，如提示异常应及时复诊并请妇科肿瘤专科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 宫颈肥大\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 合并病原体感染（沙眼衣原体/淋球菌等）时：多西环素胶囊0.1g bid×7天，或阿奇霉素片1g 单次顿服；\n2. 局部治疗：保妇康栓1枚，每晚睡前阴道纳药×7-14天，或苦参凝胶5g，每晚1次阴道给药×10天；\n3. 合并滴虫性阴道炎或细菌性阴道病时：甲硝唑片0.4g bid×7天；\n4. 伴急性宫颈炎表现（脓性分泌物、宫颈充血水肿）：头孢克肟胶囊0.1g bid×7天（需皮试者改用阿奇霉素）。\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥，经期勤换卫生巾，避免盆浴；治疗期间及停药3天内避免性生活与阴道冲洗；\n2. 注意经期卫生，避免经期性交，减少不洁性行为及多个性伴侣；\n3. 规律作息、均衡饮食、适当运动，增强机体免疫力；避免长期久坐及穿过紧不透气内裤；\n4. 尽量避免人工流产、诊断性刮宫等宫腔操作，减少宫颈机械性损伤。\n【随诊要求】\n1. 用药结束后2周门诊复诊，复查白带常规及妇科检查，评估症状缓解与宫颈情况；\n2. 每年定期行宫颈TCT+HPV联合筛查，排除宫颈上皮内病变及早期宫颈癌；\n3. 若出现白带增多、异味、外阴瘙痒、接触性出血或下腹坠痛加重，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1079,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ea287c0fb10a6bd7c7232e0f74d9d33060a410aa47e5f490ea9448aeb7ff01a7","pinyin":"gongjingfeida","initials":"gjfd","setting":"out","caseName":"门诊病历947","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历947",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fe1fb8448319ecce9e00","key":"v1-c9ccc21dfe2a3058|templates-fe1fb8448319ecce9e00","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫内膜炎","category":"门诊病历模板","raw":{"name":"子宫内膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历948","templates":{"主诉":"下腹痛伴发热3天","现病史":"患者存在以下易感因素：产褥期（产后或流产后发生子宫内膜炎，为产褥感染最常见类型，多因胎盘残留或流产不全继发感染）；宫腔操作后（近期行人工流产、诊断性刮宫、取环或宫腔镜等操作，感染可沿生殖道上行）；经期性交；盆腔炎（炎症自子宫上行至附件）；病原体以厌氧菌及革兰阴性菌为主（产褥期多为混合感染），亦可为衣原体、淋菌（性传播，上行感染，多见于年轻患者），宫腔内残留物常为感染源。患者3天前出现以下症状：下腹痛（位于中下腹，持续性隐痛或胀痛，活动后加重）、发热（体温升高，可伴寒战；产褥期高热提示产褥感染，属急症）、异常分泌物（脓性或血性，有异味，多为厌氧菌所致）、阴道出血（恶露有异味或持续时间延长，多见于产褥期；亦可为经后出血）、腰骶部疼痛、全身乏力不适。需警惕并发症：宫腔粘连（Asherman综合征，感染致内膜损伤，远期可致闭经、不孕，重要）、输卵管炎及盆腔炎（炎症上行扩散至附件）、败血症（严重产褥感染、脓毒症，属急症）、胎盘残留（产后大出血，需超声检查）、继发不孕。另需了解产褥及宫腔操作史（分娩、流产、刮宫的时间及过程）、阴道操作史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.6℃，P102次/分，R22次/分，BP110/68mmHg。腹部：下腹压痛，伴反跳痛（提示腹膜刺激，见于盆腔炎）；妇科检查：子宫增大、质软（产褥期子宫复旧不良），压痛（++），子宫压痛为本病核心体征；宫颈举痛，宫口可见脓性或血性分泌物，有异味；双合诊附件区压痛（提示合并输卵管炎）；产后恶露有异味；阴道内见脓性分泌物；全身情况注意有无发热、中毒表现，警惕败血症，需予评估。","辅助检查":"【必做】血常规（白细胞升高）、CRP及降钙素原、宫腔及宫颈分泌物培养（病原体需做需氧加厌氧培养及药敏）、血培养（高热、疑脓毒症者）、超声（观察宫腔有无残留物（产褥期及流产后重要，可见不均匀残留回声）、有无宫腔积脓（脓液呈液性暗区）、内膜增厚等炎症改变、附件有无脓肿、盆腔有无积液）、尿常规及妊娠试验（排除妊娠）。【其他】宫腔镜（用于慢性子宫内膜炎的诊断及粘连评估）、子宫内膜活检（慢性内膜炎可见浆细胞，可确诊）、结核筛查（慢性生殖器结核可致子宫内膜炎，难治，结核流行区应评估）。","初步诊断":"1. 子宫内膜炎（急性（产褥期、宫腔操作后或上行性感染）或慢性；病原体待培养；并发症包括宫腔粘连、盆腔炎、败血症；需评估有无宫腔残留）\n（注：治疗原则为抗感染加清除残留或引流，产后重症者需住院。①抗生素：经验性广谱用药，覆盖革兰阴性菌及厌氧菌（产褥期子宫内膜炎多为混合菌感染，经典方案为克林霉素加庆大霉素，可覆盖厌氧菌及革兰阴性菌），或哌拉西林他唑巴坦、头孢类加甲硝唑；年轻、性活跃者需覆盖衣原体及淋菌（头孢曲松加多西环素），依病原培养结果调整；疗程为静脉用药至退热48小时后改口服，总疗程10~14天。②清除感染源：宫腔残留者（超声证实有残留物）行清宫，可在抗感染控制后或同时进行，清宫时须静脉用抗生素覆盖，此点重要，残留物是感染源，不清除则难以治愈；宫腔积脓者扩张宫颈引流排脓。③产后处理：产褥感染者住院治疗（重症、败血症者予静脉广谱抗生素及支持治疗，补液，并用缩宫素促进子宫收缩、排出恶露），注意休息与营养。④对症：退热、止痛、补液，注意隔离与卫生。⑤并发症处理：盆腔炎及脓肿（参见盆腔炎、脓肿引流的处理）、败血症（血培养，重症者按脓毒症处理，必要时入ICU）、宫腔粘连（远期因慢性内膜炎所致，可行宫腔镜下分离并予激素治疗，随访不孕情况）。⑥随访：治疗后48~72小时评估退热及腹痛缓解情况；完成疗程；复查超声了解宫腔恢复及残留物是否清除；复发者（慢性内膜炎反复发作）行宫腔镜及内膜活检，必要时评估结核；有生育要求者应评估远期宫腔环境，备孕前检查。妇科处理要点：抗生素加清除残留，重症者住院，防止粘连及不孕，甚为重要。","处理方案":"【药物治疗】\n1. 头孢呋辛酯片（广谱头孢，覆盖需氧革兰阳性/阴性菌）：0.25g，口服，bid，连用7天。\n2. 甲硝唑片（覆盖厌氧菌）：0.4g，口服，tid，连用7天；与头孢类联用覆盖需氧菌+厌氧菌混合感染。\n3. 左氧氟沙星片（青霉素/头孢过敏者替代方案）：0.5g，口服，qd，连用7天；联用甲硝唑0.4g tid×7天。\n4. 多西环素片（疑支原体/衣原体感染或术后感染史者）：0.1g，口服，bid，连用14天。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，取半卧位，以利于宫腔分泌物引流；发热者多饮水，体温≥38.5℃时对症退热处理。\n2. 饮食宜高蛋白、高维生素、富铁易消化食物（如瘦肉、蛋、豆制品、新鲜蔬果），忌辛辣刺激及生冷食物，忌饮酒。\n3. 保持外阴清洁干燥，勤换消毒内裤及卫生巾，治疗期间禁盆浴、禁坐浴、禁性生活，避免冲洗阴道。\n4. 经期避免剧烈运动、重体力劳动及劳累，注意保暖，防止受凉诱发感染加重。\n\n【随诊要求】\n1. 用药7天疗程结束后复诊，复查妇科检查、血常规及C反应蛋白评估疗效；症状未完全缓解者需复查宫腔分泌物细菌培养及药敏试验，据药敏调整抗菌药物。\n2. 治疗期间如出现持续高热、下腹痛加剧、异常阴道出血或分泌物增多、药物过敏（皮疹、瘙痒等）等，应立即复诊或急诊就诊。\n3. 治疗结束后1个月复查妇科B超及宫颈分泌物检查，评估内膜修复情况；3个月内如出现月经异常、经期延长或经间期出血，及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1080,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cef663ef258074a843e483f5416f36c738d9a26b3c9b3a7747d0a8ff84ed77f4","pinyin":"zigongneimoyan","initials":"zgnmy","setting":"out","caseName":"门诊病历948","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历948",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7891a0d9fae0c5ef4bb3","key":"v1-c9ccc21dfe2a3058|templates-7891a0d9fae0c5ef4bb3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫肌炎","category":"门诊病历模板","raw":{"name":"子宫肌炎","category":"门诊病历模板","case":{"case_name":"门诊病历949","templates":{"主诉":"下腹痛伴发热1周","现病史":"患者1周前无明显诱因出现子宫肌炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以下腹痛伴发热1周为主诉就诊，伴轻度乏力，首先急诊完善血常规检查，了解白细胞及中性粒细胞比例，明确感染的严重程度以指导抗感染方案；完善尿常规检查，排除泌尿系统感染及结石等可引起下腹痛的疾病；查白带常规明确阴道及宫颈分泌物的病原体，判断有无厌氧菌、淋球菌等上行感染；完善宫颈TCT+HPV检查，排除宫颈上皮内病变及高危型人乳头瘤病毒感染；查妇科超声了解子宫肌层回声、宫腔积液及双侧附件情况，明确有无宫腔积脓、输卵管卵巢受累及盆腔积液，评估炎症范围；乳腺超声作为妇科门诊常规基线检查，了解乳腺有无结节及增生；完善性激素六项检查了解卵巢内分泌功能，评估有无内分泌因素影响子宫修复；完善血HCG检查排除妊娠及异位妊娠等需紧急处理的情况；查肿瘤标志物（必要时）包括CA125，鉴别子宫内膜癌、子宫肉瘤等恶性病变。若发热持续不退，建议完善炎症指标及血培养，必要时行诊断性刮宫或宫腔镜检查取内膜病理，明确炎症性质并排除恶性病变。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 子宫肌炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（覆盖需氧菌及厌氧菌，首选）：头孢克肟胶囊0.1g 口服 bid×14天，联合甲硝唑片0.4g 口服 bid×14天；对头孢菌素类过敏者，改用左氧氟沙星片0.5g 口服 qd×14天，联合甲硝唑片0.4g 口服 bid×14天。\n2. 疑沙眼衣原体或支原体感染（近期有流产、分娩或宫腔操作史）：多西环素片0.1g 口服 bid×14天，与上述抗菌药物联合患者。\n3. 对症退热止痛：布洛芬缓释胶囊0.3g 口服 bid，体温>38.5℃或下腹疼痛明显时加用，退热止痛后停用，不超过3～5天。\n【一般治疗及生活指导】\n1. 急性期卧床休息，采取半卧位，利于宫腔及盆腔分泌物引流，减轻盆腔充血，缓解腹痛。\n2. 清淡、高蛋白、易消化饮食，多饮水，忌辛辣刺激及生冷食物，忌饮酒，保持大便通畅。\n3. 治疗期间及症状完全消失前禁止性生活、盆浴及阴道冲洗上药，注意经期及产后卫生，勤换内裤，保持外阴清洁干燥。\n4. 避免劳累、剧烈活动及受凉，注意保暖，保证充足睡眠；症状缓解后1个月内避免重体力劳动。\n【随诊要求】\n1. 用药3～5天后复诊，复查血常规、CRP评估疗效；若高热不退、腹痛加剧或阴道异常排液增多，应立即复诊或急诊就诊。\n2. 完成14天疗程后复诊，行妇科检查及盆腔超声，评估子宫复旧与炎症吸收情况；经医生确认痊愈后方可恢复性生活。\n3. 近期有分娩、流产或宫腔操作史者，复诊时应复查盆腔超声排除宫腔组织残留，必要时行宫腔分泌物培养及药敏试验以指导后续治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1081,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cc5af4a875a5b7de8ac35dd153f549be34aa03f4dd635379fa525952f5050400","pinyin":"zigongjiyan","initials":"zgjy","setting":"out","caseName":"门诊病历949","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历949",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-832a924466aed41eaa99","key":"v1-c9ccc21dfe2a3058|templates-832a924466aed41eaa99","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输卵管炎","category":"门诊病历模板","raw":{"name":"输卵管炎","category":"门诊病历模板","case":{"case_name":"门诊病历950","templates":{"主诉":"下腹痛伴发热3天","现病史":"患者为育龄期、性活跃女性，病原体多经生殖道上行感染（以衣原体、淋菌最为常见，属性传播感染，此点重要；亦可为内源性厌氧菌及革兰阴性菌群感染）；存在宫腔操作史（近期行人工流产、取放环等）、经期性交、多个性伴侣、既往盆腔炎史（易复发）等易感因素。患者5天前出现以下症状：下腹痛（位于双侧下腹，持续性钝痛或胀痛，活动及性交后加重）、发热（体温升高）、白带增多（脓性）、月经异常（经间期点滴出血、经量增多）、腰骶部疼痛、性交痛、尿频（膀胱刺激症状）、恶心（腹膜刺激症状）。需警惕并发症及后遗症：输卵管阻塞（可致不孕，为最重要的远期后果，不孕率约50%，与输卵管炎发作次数呈正相关，此点重要）、异位妊娠（输卵管纤毛损伤、蠕动异常，宫外孕风险升高6~10倍，此点重要）、慢性盆腔痛（粘连所致）、输卵管积水（炎性积液致输卵管扩张，超声呈腊肠样）、输卵管卵巢脓肿、肝周炎（Fitz-Hugh-Curtis综合征，衣原体感染可致右上腹痛）；慢性者表现为反复下腹痛超过3个月，多因盆腔炎后粘连所致。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP112/70mmHg。下腹部压痛，伴反跳痛；妇科检查：宫颈举痛（移动痛），子宫压痛，附件区压痛，双侧附件增厚，可及包块（输卵管积水或脓肿）；双合诊及三合诊宫骶韧带压痛；宫颈口可见脓性分泌物（已取拭子送检）；伴发热。","辅助检查":"【必做】宫颈拭子衣原体及淋球菌核酸检测（聚合酶链反应，敏感度高，为病原学检查核心）、白带常规、血常规（白细胞）、CRP及血沉（炎症指标）、妊娠试验（排除异位妊娠，属急腹症，重要）、尿常规（与尿路感染鉴别）。【影像】盆腔超声（观察输卵管有无增粗或积水（呈腊肠样无回声管状结构）、卵巢有无脓肿并见、盆腔有无积液、附件有无包块）、MRI或CT（复杂脓肿、范围评估）、腹腔镜（确诊金标准，可见输卵管红肿、脓性分泌物及粘连，并可同时治疗，行粘连松解或引流，但属有创检查，临床以诊断为主）。【其他】HIV及梅毒筛查（性传播疾病合并感染筛查）。","初步诊断":"1. 输卵管炎（急性或慢性，考虑衣原体、淋菌等感染，需评估有无输卵管积水及卵巢脓肿，注意远期不孕及异位妊娠风险，评估住院指征）\n（注：治疗原则为尽早、足程使用抗生素，防止输卵管发生不可逆损伤，此点重要。①抗生素：门诊适用于轻中度患者，方案为头孢曲松1g肌注单剂加多西环素100mg bid×14天加甲硝唑500mg bid×14天（可覆盖淋菌、衣原体及厌氧菌，为标准方案），或左氧氟沙星加甲硝唑（依耐药情况选择）；住院指征为高热、脓肿、妊娠、腹膜炎或门诊治疗失败者，方案为头孢替坦或头孢西丁加多西环素，或克林霉素加庆大霉素，静脉用药48小时好转后改口服，总疗程14天。②脓肿及积水：输卵管卵巢脓肿需住院，予静脉广谱抗生素72小时后评估，必要时行引流（超声引导下穿刺、腹腔镜或手术）；输卵管积水属慢性病变，可行手术（输卵管造口或切除；体外受精前切除积水可提高着床率，此点重要）。③性伴侣：需同时治疗（衣原体、淋菌感染者的性伴侣应检查并治疗，防止再感染），治疗期间禁止性生活。④随访：治疗后48~72小时复查（观察退热及腹痛缓解情况）；完成14天疗程，不可提前停药；衣原体及淋菌于治疗后3周复查是否治愈；远期需关注生育计划（必要时行子宫输卵管造影评估输卵管，属不孕检查项目）及异位妊娠风险（妊娠早期应超声排除宫外孕，此点重要，患者），慢性疼痛者按粘连处理。预防方面，应进行安全性行为教育，使用安全套以预防性传播疾病及盆腔炎。妇科处理要点：早期、足程使用抗生素，防止输卵管损伤所致不孕及宫外孕，甚为重要。","处理方案":"【药物治疗】\n1. 抗感染治疗（首选方案）：输卵管炎常见病原体为淋病奈瑟菌、沙眼衣原体及需氧/厌氧菌混合感染，门诊成人推荐联合方案：头孢曲松钠1g单次肌注，联合多西环素100mg po bid×14天；或左氧氟沙星500mg po qd，联合甲硝唑400mg po bid，共14天，覆盖淋球菌、衣原体及厌氧菌。\n2. 辅助中成药：康妇炎胶囊1.2g po tid×14天，或妇科千金片6片 po tid×14天，辅助清热解毒、化瘀止痛。\n3. 对症处理：下腹疼痛明显者予布洛芬缓释胶囊0.3g po bid，疼痛缓解后停用，一般3~5天。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，取半卧位，以利炎症局限及渗出液引流，避免劳累及久站久坐。\n2. 清淡、高蛋白、易消化饮食，多饮水，保持大便通畅，忌辛辣刺激及生冷食物。\n3. 治疗期间及症状未完全缓解前禁性生活、盆浴及阴道冲洗，勤换内裤，保持外阴清洁干燥。\n4. 注意经期卫生，经期勤换卫生巾、避免游泳及剧烈运动，防止逆行感染复发。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效，症状无缓解或加重者及时复诊调整抗感染方案。\n2. 完成14天疗程后复诊，复查妇科双合诊、白带常规，必要时复查妇科B超评估盆腔炎症吸收情况。\n3. 治疗期间如出现高热（≥38.5℃）、腹痛加剧、恶心呕吐或阴道异常排液增多，应立即急诊就诊，警惕盆腔脓肿及腹膜炎。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1082,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5eaf8dc9b4b5f877f694465514b93d7c3cb8a031b11345380277d26b6fe1b68c","pinyin":"shuluanguanyan","initials":"slgy","setting":"out","caseName":"门诊病历950","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历950",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dbe2e1baea8739a1f68e","key":"v1-c9ccc21dfe2a3058|templates-dbe2e1baea8739a1f68e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"卵巢炎","category":"门诊病历模板","raw":{"name":"卵巢炎","category":"门诊病历模板","case":{"case_name":"门诊病历951","templates":{"主诉":"下腹疼痛伴发热1周","现病史":"患者1周前无明显诱因出现卵巢炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以下腹疼痛伴发热1周为主诉就诊，伴轻度乏力，首先完善血常规检查，了解白细胞及中性粒细胞计数，评估感染程度并指导抗感染治疗；完善尿常规检查，排除泌尿系感染、输尿管结石等可引起下腹疼痛的疾病；查白带常规明确阴道及宫颈病原体，判断有无沙眼衣原体、淋球菌等上行感染导致卵巢炎；完善宫颈TCT+HPV检查排除宫颈上皮内病变及高危型人乳头瘤病毒感染；查妇科超声了解双侧卵巢大小、回声及有无输卵管增粗、盆腔积液、输卵管卵巢脓肿形成，评估炎症累及范围；乳腺超声作为妇科门诊常规基线检查，了解乳腺有无异常；完善性激素六项检查了解卵巢储备及内分泌功能，评估炎症对卵巢功能的影响；完善血HCG检查排除异位妊娠、妊娠相关疾病等急腹症；查肿瘤标志物（必要时）包括CA125、HE4，鉴别卵巢肿瘤及卵巢脓肿。若抗感染治疗效果欠佳或出现附件包块增大，应及时复查超声并请妇科肿瘤专科评估，必要时行腹腔镜探查明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 卵巢炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染（首选头孢类+四环素类联合方案，覆盖淋球菌、衣原体及混合厌氧菌感染）：头孢曲松钠1g 单次肌注（或头孢克肟胶囊0.2g bid×14天），联合多西环素片0.1g bid×14天。\n2. 加用抗厌氧菌药：甲硝唑片0.4g bid×14天（与头孢+多西环素联合，覆盖盆腔厌氧菌）。\n3. 对症止痛：布洛芬缓释胶囊0.3g bid（或双氯芬酸钠缓释片75mg qd），疼痛缓解后停药，一般3-5天。\n4. 辅助中成药（症状缓解期或慢性期）：妇科千金片0.8g（4片）tid×14天，或金刚藤胶囊2粒 tid×14天，宜与抗生素间隔1小时服用。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，取半卧位，利于炎性渗出物局限积聚于盆腔，避免扩散；症状缓解后可适当下床活动，但避免剧烈运动及久站久坐。\n2. 饮食宜高蛋白、高维生素、易消化，多饮水，多食鱼、蛋、瘦肉及新鲜蔬果；忌辛辣、油腻、生冷及刺激性食物，戒烟酒。\n3. 治疗期间及停药后1周内禁止性生活、盆浴及阴道冲洗，避免逆行感染加重病情。\n4. 注意个人卫生，勤换内裤及卫生巾，保持外阴清洁干燥；经期避免劳累、受凉及剧烈活动，防止经期感染复发。\n\n【随诊要求】\n1. 用药后3-5天复诊，评估下腹痛、发热、白带异常等症状缓解情况，必要时调整方案。\n2. 完成14天足疗程后复诊，复查妇科双合诊、血常规、C反应蛋白，必要时复查盆腔彩超评估附件区包块及积液吸收情况。\n3. 若疗程中出现高热不退（体温≥38.5℃）、腹痛进行性加重、恶心呕吐或出现腹膜刺激征，应立即急诊就诊，警惕盆腔脓肿或输卵管卵巢脓肿形成。\n4. 有性生活者，性伴侣应同时检查并治疗（尤其衣原体、淋球菌感染者），治疗期间避免无保护性行为，以防交叉感染及反复发作。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1083,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b64173f045296ba86d2d8fe301c732c44a62f5777c323e28deaf0e0bab915e7c","pinyin":"luanchaoyan","initials":"lcy","setting":"out","caseName":"门诊病历951","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历951",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7aee5728e72fb1f0fc83","key":"v1-c9ccc21dfe2a3058|templates-7aee5728e72fb1f0fc83","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"盆腔脓肿","category":"门诊病历模板","raw":{"name":"盆腔脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历952","templates":{"主诉":"下腹痛伴发热1周","现病史":"患者1周前无明显诱因出现盆腔脓肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以下腹痛伴发热1周为主诉就诊，考虑盆腔脓肿，入院即刻完善血常规检查，了解白细胞及中性粒细胞比例、血红蛋白水平，评估感染严重程度并排除贫血；完善凝血功能检查，评估凝血状态，为可能的手术或穿刺引流做准备；完善肝肾功能检查，因抗感染治疗用药需经肝肾代谢，排除肝肾功能不全以免影响用药选择与剂量；查电解质了解有无电解质紊乱，评估是否需要纠正后再行治疗；完善血糖检查排除糖尿病等导致感染难以控制的基础疾病；完善血型鉴定，为输血或急诊手术做好备血准备；查CRP及降钙素原，动态评估感染及炎症反应程度，指导抗生素疗程。影像学方面，查妇科超声作为首选筛查手段，明确脓肿部位、大小、性质及有无盆腔积液；完善盆腔CT检查进一步明确脓肿范围及其与周围肠管、输尿管的关系，必要时行MRI检查鉴别脓肿与肿瘤性病变；X线片了解有无肠梗阻、消化道穿孔等外科急腹症表现；胸部X线片排除肺部感染及肺结核；完善心电图评估心脏基础状态，为手术麻醉提供依据；查肿瘤标志物（必要时）包括CA125，鉴别盆腔脓肿与卵巢肿瘤。若脓肿局限且直径较大，建议在超声或CT引导下行穿刺引流并送细菌培养及药敏。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 盆腔脓肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（首选方案，覆盖需氧菌及厌氧菌，足量足疗程14天）：左氧氟沙星片0.5g po qd×14天，联合甲硝唑片0.4g po tid×14天（餐后服）。\n2. 备选方案（喹诺酮类过敏或不耐受者）：头孢呋辛酯片0.25g po bid×14天，联合甲硝唑片0.4g po tid×14天；必要时加用多西环素片0.1g po bid×14天（覆盖衣原体、支原体感染）。\n3. 对症处理：发热（体温≥38.5℃）或下腹痛明显者，予布洛芬缓释胶囊0.3g po bid（餐后服，疼痛缓解后停药）。\n4. 用药注意事项：服用甲硝唑期间及停药后7天内禁酒（防双硫仑样反应）；喹诺酮类避免与含钙、铁、锌制剂同服；多西环素应大量饮水送服，避免卧位服药。\n【一般治疗及生活指导】\n1. 卧床休息，取半卧位，以利于脓液积聚于盆腔最低位而局限、引流；避免劳累、久站久坐及剧烈运动。\n2. 饮食予高蛋白、高维生素、易消化饮食，多饮水，保持大便通畅；忌辛辣刺激、生冷油腻食物。\n3. 急性期禁性生活、盆浴、阴道冲洗及阴道内置药，保持外阴清洁干燥，勤换内裤；注意保暖，避免受凉。\n4. 发热时注意休息，可行温水擦浴物理降温，多饮温水；注意观察腹痛及体温变化，勿自行热敷下腹部。\n【随诊要求】\n1. 用药后48~72小时复诊评估疗效；若仍发热不退、腹痛加重或盆腔包块增大，及时复诊，必要时住院行超声/CT引导下穿刺引流或手术。\n2. 完成14天全程疗程（症状消失后不可自行停药），疗程结束后复诊复查妇科B超、血常规及CRP，评估脓肿吸收情况。\n3. 若脓肿直径≥5cm或保守治疗无效，应转住院行超声引导下经阴道/直肠穿刺引流或腹腔镜手术；随访期间出现寒战高热、剧烈腹痛、血压下降等脓毒症表现，立即急诊就诊。\n4. 治愈后1~3个月复查妇科B超，确认脓肿完全吸收无复发；若反复发作，建议进一步排查盆腔粘连及不孕风险，必要时转妇科专科门诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1084,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"23551e00566cfd099572d800a5c1488b32551bf8ee6f9ff4e25edd21c5d2a937","pinyin":"penqiangnongzhong","initials":"pqnz","setting":"out","caseName":"门诊病历952","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历952",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ee504d6e5cbe525918ba","key":"v1-c9ccc21dfe2a3058|templates-ee504d6e5cbe525918ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"生殖器结核","category":"门诊病历模板","raw":{"name":"生殖器结核","category":"门诊病历模板","case":{"case_name":"门诊病历953","templates":{"主诉":"反复下腹隐痛伴低热1周","现病史":"患者1周前无明显诱因出现生殖器结核相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复下腹隐痛伴低热1周为主诉就诊，伴轻度乏力，考虑生殖器结核可能，首先完善血常规检查，了解有无贫血及感染血象，辅助判断慢性消耗性疾病；查CRP及降钙素原，评估体内炎症活动程度，动态观察抗结核治疗反应；完善胸部X线片或胸部CT检查，了解有无肺结核病灶及胸膜受累，因生殖器结核多为肺结核血行播散所致，是寻找原发灶的关键；完善痰培养+药敏检查，明确有无结核分枝杆菌感染及其耐药情况，为制定抗结核方案提供依据；患者有低热、乏力等全身症状，完善血气分析（必要时）评估氧合及酸碱状态，判断有无肺部病变导致的通气或换气功能障碍；肺功能检查建议于病情稳定后进行，了解肺通气功能储备；此外应完善结核菌素试验、γ干扰素释放试验（T-SPOT）等特异性免疫学检查，提高结核诊断的敏感性；完善盆腔超声了解子宫内膜、输卵管有无增厚、积水及包裹性积液，评估生殖器官受累范围，必要时行宫腔镜或腹腔镜检查并取内膜、腹膜活检送病理，以明确诊断。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 生殖器结核\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗结核化疗（全程督导、联合、适量、规律、足疗程）：首选2HRZE/4HR方案，即强化期2个月异烟肼片0.3g qd+利福平胶囊0.45g qd+吡嗪酰胺片1.5g qd（分1-2次口服）+乙胺丁醇片0.75g qd，晨起空腹顿服；巩固期4个月异烟肼片0.3g qd+利福平胶囊0.45g qd，总疗程6-9个月（伴耐药或病变广泛者延长至9-12个月）。\n2. 保肝辅助：水飞蓟宾胶囊70mg tid口服，疗程随抗结核全程，治疗期间每2-4周复查肝功能、血常规，异常时及时调整方案。\n3. 对症处理：盆腔结核伴下腹痛明显者，可予布洛芬缓释胶囊0.3g bid×3-5天缓解症状；如为结核性腹膜炎/大量腹水者，建议住院行抗结核治疗并评估腹腔穿刺引流。\n【一般治疗及生活指导】\n1. 充分休息，急性期卧床休息，避免劳累及熬夜，保证充足睡眠以增强机体免疫力。\n2. 加强营养，予高蛋白、高维生素、易消化饮食（如鱼、蛋、奶、瘦肉、新鲜蔬菜水果），戒烟酒。\n3. 保持外阴及经期卫生，治疗期间建议避孕，避免妊娠（妊娠可加重病情并影响胎儿）；已婚患者男方应同时排查泌尿生殖系统结核。\n4. 注意呼吸道防护，咳嗽、喷嚏时掩口鼻，餐具、被褥单人使用，防止家庭内传播。\n【随诊要求】\n1. 抗结核治疗期间每2-4周门诊复诊，复查血常规、肝功能、肾功能；服乙胺丁醇期间如出现视力下降、色觉异常，立即停药并急诊就诊。\n2. 强化期结束后（2个月）门诊复查，评估症状缓解及病灶变化，必要时复查妇科B超、盆腔MRI；遵医嘱调整巩固期方案。\n3. 完成全程化疗后，每3-6个月门诊随访至少2年，重点评估月经恢复、妊娠情况；有生育要求者疗程结束后行子宫输卵管造影评估输卵管通畅度，必要时转生殖中心。\n4. 治疗期间如出现发热、盗汗加重、腹痛加剧或阴道排液增多，及时随诊，警惕耐药或腹腔播散。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1085,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b6213f98fafcc93bc9a1f93c878d268f31405962f383fbd3e62583a2c385dc5f","pinyin":"shengzhiqijiehe","initials":"szqjh","setting":"out","caseName":"门诊病历953","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历953",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-76cd21e5bf24f2df5cb4","key":"v1-c9ccc21dfe2a3058|templates-76cd21e5bf24f2df5cb4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"性传播疾病","category":"门诊病历模板","raw":{"name":"性传播疾病","category":"门诊病历模板","case":{"case_name":"门诊病历954","templates":{"主诉":"生殖器溃疡伴分泌物增多1周","现病史":"患者1周前无明显诱因出现性传播疾病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以生殖器溃疡伴分泌物增多1周为主诉就诊，伴轻度乏力，首先完善血常规检查，了解有无感染血象及贫血；完善尿常规检查，排除泌尿系统感染，因性传播疾病常合并尿道炎；完善便常规检查，排除肠道感染及寄生虫病，评估有无肠道受累；完善肝肾功能检查，性传播疾病治疗多需长期使用抗生素，排除肝肾功能不全以指导用药；查血糖了解有无糖尿病，糖尿病患者生殖道感染发生率明显升高且不易控制；查血脂了解脂代谢情况，评估心血管基础风险；完善电解质检查排除电解质紊乱；完善心电图评估心脏基础状态，为用药安全提供参考；胸部X线片排除肺结核及肺部感染；腹部超声了解肝脾、腹腔淋巴结及有无腹腔积液。此外应针对病原学完善专项检查：取生殖器溃疡分泌物行梅毒血清学（RPR+TPPA）、单纯疱疹病毒核酸检测，分泌物涂片及培养明确淋球菌、沙眼衣原体、支原体感染，必要时行HIV抗体筛查，根据药敏结果选择敏感抗生素；其余检查根据病情需要选择相应检查，如出现关节痛、皮疹等表现时加查相应项目，同时建议性伴侣同步检查与治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 性传播疾病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 淋病（淋病奈瑟菌感染）：头孢曲松钠注射液 1g 单次肌注（首选方案）；同时予阿奇霉素片 1g 单次口服，覆盖可能的沙眼衣原体合并感染。\n2. 沙眼衣原体感染（非淋菌性尿道炎/宫颈炎）：多西环素片 100mg 口服 bid×7天；或阿奇霉素片 1g 单次顿服。\n3. 梅毒（早期）：苄星青霉素注射液 240万U 分两侧臀部深部肌注，每周1次，连续2-3次；青霉素过敏者予多西环素片 100mg 口服 bid×14天。\n4. 生殖器疱疹（初发）：伐昔洛韦片 500mg 口服 bid×7天；尖锐湿疣以激光、冷冻等物理治疗去除疣体，配合外用咪喹莫特乳膏 5%，每周3次，睡前涂于疣体，次日晨清洗。\n\n【一般治疗及生活指导】\n1. 治疗期间禁止性生活，性伴侣应同时检查并接受规范治疗（性伴同治），避免交叉感染与再感染。\n2. 注意休息，避免熬夜及过度劳累，忌酒及辛辣刺激性饮食，多饮水；保持外阴清洁干燥，穿宽松棉质内裤，勤换洗。\n3. 个人物品（毛巾、浴巾、内衣裤）分开使用并煮沸消毒，不与他人共用浴盆、坐便器及注射器具。\n4. 避免搔抓、摩擦生殖器疱疹及尖锐湿疣皮损，防止自身接种播散；梅毒皮损未消退前避免密切接触。\n\n【随诊要求】\n1. 淋病及衣原体感染：治疗后2周复查病原学（淋球菌培养/核酸、沙眼衣原体核酸）确认治愈，症状未缓解者及时复诊。\n2. 梅毒：治疗后第3、6、12个月复查非梅毒螺旋体血清学试验（RPR/TRUST）滴度以评估疗效，晚期梅毒随访2-3年；滴度不降或上升者进一步评估并处理。\n3. 生殖器疱疹：初发患者治疗结束后1周复诊评估皮损愈合情况；频繁复发（每年≥6次）者建议长期抑制治疗，伐昔洛韦片 500mg 口服 qd，疗程6-12个月。\n4. 尖锐湿疣：治疗后每月复诊，连续3-6个月无新发皮损视为治愈；合并高危型HPV感染者按宫颈癌筛查规范定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1086,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"27aff69080719276a36518f41a9a13beb6090411801abe7b6b7db10f71a8ce3e","pinyin":"xingchuanbojibing","initials":"xcbjb","setting":"out","caseName":"门诊病历954","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历954",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-05c963dd76cca5418223","key":"v1-c9ccc21dfe2a3058|templates-05c963dd76cca5418223","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"衣原体感染","category":"门诊病历模板","raw":{"name":"衣原体感染","category":"门诊病历模板","case":{"case_name":"门诊病历955","templates":{"主诉":"尿痛伴尿道分泌物1周","现病史":"患者为性活跃人群（沙眼衣原体为最常见的细菌性性传播感染病原体，我国以青少年及青年高发），存在多个性伴侣或无保护性行为，年龄<25岁属高危因素。患者多在感染后1~3周潜伏期后发病，或于筛查时发现，具体表现如下：无症状（多数感染者无症状，约70~80%女性及50%男性无症状，此点重要，为隐匿性传染源）、男性表现（尿道炎，尿痛，尿道分泌物稀薄、清亮或呈脓性；可并发睾丸附睾炎；肛交者可致直肠炎；亦可有咽炎）、女性表现（宫颈炎，分泌物增多、异常出血；尿道炎，尿频、尿痛；感染上行可致子宫内膜炎、输卵管炎、盆腔炎，出现腹痛、发热，此点重要；盆腔炎远期可致输卵管瘢痕形成、不孕及异位妊娠，此点重要）、新生儿表现（经产道感染可致结膜炎，于生后1~2周出现脓性眼分泌物，此点重要；亦可致肺炎，于生后1~3个月出现间质性肺炎、百日咳样咳嗽）。需注意并发症：女性可见盆腔炎、不孕及宫外孕，为最主要的后遗危害，重复感染会增加风险；男性可见附睾炎；Reiter综合征（尿道炎、结膜炎及关节炎三联征，属反应性关节炎）；常合并淋病（约30~50%共感染，此点重要，治疗需覆盖两种病原体）；合并HIV感染可增加传播风险。另需了解性伴侣情况（应通知并同治，防止再感染，此点重要）、孕产史（妊娠期衣原体感染可致流产、早产，新生儿经产道感染，故孕期筛查及治疗重要）、既往性病史。今日来我院皮肤性病科或妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P82次/分，R18次/分，BP116/72mmHg。男性：尿道口红肿，可见分泌物；附睾肿痛。女性：宫颈充血，宫颈口可见黏液脓性分泌物，以拭子擦拭易出血（宫颈脆性增加）；子宫及附件区压痛（提示感染上行致盆腔炎），行双合诊检查。肛周及直肠检查（了解有无肛交所致病变）。眼部检查（结膜炎，见于新生儿及成人）。关节检查（注意Reiter综合征）。全身浅表淋巴结检查。","辅助检查":"【必做】核酸扩增检测（聚合酶链反应，为核心首选方法；男性取首段尿，女性取宫颈或尿道拭子，敏感度高、特异度强，为沙眼衣原体诊断标准）、淋球菌检测（合并感染须同时检查，此点重要，可行核酸联合检测）、白带常规、尿常规（尿道炎）、HIV及梅毒筛查（性传播疾病合并感染，重要）。【其他】治疗后复查（核酸检测阴转，于3~4周复查，用于评估治愈）、盆腔炎评估（超声检查附件有无脓肿）、新生儿结膜炎（眼拭子行衣原体检测）、性伴侣检测与治疗。","初步诊断":"1. 沙眼衣原体生殖道感染（临床类型为尿道炎、宫颈炎、无症状（筛查发现）或并发附睾炎、盆腔炎、新生儿结膜炎及肺炎；需筛查有无合并淋病及HIV；评估性伴侣同治）\n（注：治疗原则为抗生素治疗，用药简单有效，是防止并发症的关键，筛查发现的无症状感染者也应治疗。①抗生素：多西环素100mg bid×7天（首选一线方案），或阿奇霉素1g单剂顿服（口服依从性好，妊娠期可用）；替代药物为左氧氟沙星、红霉素、阿莫西林（妊娠期用阿奇霉素或阿莫西林）；应完成7天疗程，此点重要（阿奇霉素单剂依从性较好）。合并淋病者用头孢曲松1g肌注单剂（针对淋菌）加多西环素或阿奇霉素（针对衣原体），联合覆盖两种病原体，此点重要。②性伴侣：应通知并治疗（近60天内的性伴侣均需检查治疗，防止再感染，重要）；治疗期间禁止性生活（至症状消失且治疗完成7天后）；治疗后再感染（治疗后复查阳性多为再感染，需评估性伴侣是否未治）。③孕妇：孕期应筛查（早孕期常规行衣原体检测，我国对高危孕妇应筛查）；治疗用阿奇霉素1g单剂或阿莫西林500mg tid×7天（孕期安全；多西环素禁用，四环素类可影响胎儿牙齿及骨骼，此点重要）；复查于治疗后3~4周行核酸检测确认阴转，以评估治愈，此点重要，可防止新生儿经产道感染；新生儿结膜炎于出生后出现眼红、脓性分泌物，取眼拭子检测，治疗用红霉素口服加眼膏，须全身治疗以预防肺炎，此点重要。④并发症：盆腔炎（按住院或门诊方案治疗，参见盆腔炎处理，防止输卵管损伤及不孕）、附睾炎（多西环素加头孢曲松，14天）、Reiter综合征（对症处理，关节炎用非甾体抗炎药，并处理眼部病变）。⑤随访：治愈标准为治疗完成后症状消失、核酸检测阴转（于3~4周复查，此点重要；但无症状者治愈随访可视情况而定，多西环素7天方案治愈率高达95%以上）；复发及再感染（性伴侣同治可预防）；远期（女性已患盆腔炎者应随访不孕风险及生育计划）。皮肤性病科、妇科及泌尿科处理要点：对性活跃人群、<25岁者每年检测，因无症状传染源重要；以多西环素或阿奇霉素治疗，性伴侣同治，孕妇筛查，防止新生儿并发症，甚为重要。","处理方案":"【药物治疗】\n1. 多西环素胶囊 0.1g bid 口服，连用7天（首选方案）。服药时以足量水送服，服后勿立即平卧，以减少食管刺激。\n2. 阿奇霉素片 1g 单次顿服（或首日0.5g、第2-3天各0.25g口服），为无并发症生殖道衣原体感染的有效替代方案。\n3. 左氧氟沙星片 0.5g qd 口服，连用7天（替代方案；未满18岁、妊娠及哺乳期禁用）。\n4. 妊娠期患者：阿莫西林胶囊 0.5g tid 口服，连用7天（或红霉素肠溶片 0.5g qid 口服，连用7天）。\n\n【一般治疗及生活指导】\n1. 治疗期间禁止性生活，性伴侣应同时接受检查与治疗，治愈前避免无保护性行为，防止交叉再感染。\n2. 注意个人卫生：勤换洗内裤，内衣裤单独清洗后煮沸或阳光暴晒消毒，避免与他人共用毛巾、浴具。\n3. 多饮水，清淡易消化饮食，忌辛辣刺激食物及饮酒；服用多西环素期间避免日光暴晒，以防光敏反应。\n4. 保证充足休息、避免劳累；女性出现下腹痛、发热等盆腔感染征象时应及时就医。\n\n【随诊要求】\n1. 完成治疗停药2-4周后复诊，复查衣原体核酸/抗原检测，确认病原学治愈。\n2. 尿道刺激症状或分泌物异常未缓解、或停药后复发者，随时复诊，必要时行药敏评估并调整方案。\n3. 女性患者治疗后3-6个月内复查，评估有无盆腔炎、输卵管阻塞等远期并发症；性伴侣同治者建议同步复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1087,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1a9a7b00d310d4ad0527721a7e7ce9253b5becc848bdaa7aa58178186c51965e","pinyin":"yiyuantiganran","initials":"yytgr","setting":"out","caseName":"门诊病历955","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历955",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6a8cc25efbb794c46c76","key":"v1-c9ccc21dfe2a3058|templates-6a8cc25efbb794c46c76","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"支原体感染","category":"门诊病历模板","raw":{"name":"支原体感染","category":"门诊病历模板","case":{"case_name":"门诊病历956","templates":{"主诉":"尿痛伴尿道分泌物1周","现病史":"患者为性活跃人群（生殖道支原体包括解脲支原体及人型支原体，属泌尿生殖道定植菌，多数感染者无症状，健康女性定植率高达40~80%，此点重要，定植不等于致病，须避免过度治疗）；其致病性方面，尿道炎（非淋菌性尿道炎与解脲支原体部分相关，尚有争议）、阴道炎及宫颈炎、盆腔炎（感染上行，与人型支原体相关）、细菌性阴道病相关、孕产相关（早产及胎膜早破的相关性证据有限）、男性（前列腺炎及附睾炎的相关性较弱）。患者于筛查或出现症状后发现支原体阳性，具体表现如下：无症状（多数为定植，无任何症状，无需治疗，此点重要）、尿道炎（尿痛、尿频，尿道分泌物，属非淋菌性尿道炎）、阴道分泌物增多、下腹不适。需注意相关咨询事项：体检发现支原体阳性者常有焦虑，应告知定植常见、无症状者无需治疗，避免过度使用抗生素，此点重要；肺炎支原体为呼吸道不同病原体，【住址】，不可混淆；合并其他性传播疾病者需筛查衣原体、淋菌；孕产方面，孕前检查发现支原体阳性者多数无需治疗，有症状或流产史者需评估，但处理证据有限。今日来我院皮肤性病科或妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP114/70mmHg。尿道口红肿，可见分泌物；宫颈及阴道分泌物增多，提示炎症；附睾及睾丸检查；盆腔压痛（提示感染上行）；全身情况：单纯定植或尿道炎多无发热。","辅助检查":"【必做】支原体检测（培养或核酸检测，可检出解脲支原体、人型支原体及生殖道支原体；但关键在于结合临床，因定植常见，阳性不等于致病，此点重要，切勿仅凭阳性结果即予治疗）、衣原体及淋菌检测（非淋菌性尿道炎常见病原体中衣原体更为重要，应筛查）、白带及尿常规（了解炎症）、细菌性阴道病评估。【其他】耐药检测（支原体对大环内酯类耐药呈上升趋势，反复发作或治疗无效者应依培养药敏结果选药）、孕产相关（有反复流产或早产史者应评估，但证据有限）、性伴侣（多无症状定植，不常规同治；有尿道炎症状者应治疗）。","初步诊断":"1. 生殖道支原体（解脲支原体或人型支原体）检测阳性（临床类型为无症状定植、非淋菌性尿道炎、阴道炎或盆腔炎；应注意鉴别定植与感染，避免过度治疗）\n（注：治疗关键在于区分定植与感染，无症状者不治疗，以避免抗生素滥用，此点重要。①无症状定植：健康人群生殖道支原体定植率高，无感染者症状者无需治疗（重要，切勿因体检阳性而使用抗生素，过度治疗无益且增加耐药风险）；并向患者解释定植常见、属良性，勿焦虑。②有症状的感染：非淋菌性尿道炎、阴道炎或宫颈炎者，在排除衣原体、淋菌后考虑与支原体相关，治疗用多西环素100mg bid×7~14天，或阿奇霉素1g单剂，或左氧氟沙星500mg qd×7天，依药敏结果选择；盆腔炎者按盆腔炎方案治疗，需覆盖人型支原体，选用含克林霉素的方案；性伴侣有尿道炎症状者同治，无症状定植者不常规治疗。③孕妇：妊娠期支原体阳性而无症状者不需常规治疗（证据不足以支持常规筛查及治疗以预防早产）；有症状感染者应治疗（红霉素或阿奇霉素孕期安全，多西环素禁用）；有反复流产或早产史者应综合评估其他病因。④随访：治疗后评估症状缓解即可，常规不需复查培养，因定植者可再次阳性，无临床意义；治疗无效者行培养及药敏，调整用药；进行卫生及安全性行为教育，预防性传播疾病；应特别强调避免过度治疗，抗生素滥用可致支原体耐药率上升，属公共卫生问题，此点重要。皮肤性病科、妇科及泌尿科处理要点：定植者不治，感染者才治，避免过度使用抗生素，甚为重要。","处理方案":"【药物治疗】\n1. 大环内酯类（首选）：阿奇霉素片0.5g qd口服×3天（或首日0.5g，继以0.25g qd×4天，总疗程5天）；也可选用克拉霉素片0.25g bid×7天。\n2. 成人耐药或疗效不佳时选用呼吸喹诺酮类：左氧氟沙星片0.5g qd×7天；或多西环素片0.1g bid×7～10天（餐后服，多饮水）。\n3. 对症退热：体温≥38.5℃时予布洛芬缓释胶囊0.3g po q12h（必要时），退热后停药；剧烈干咳影响休息时予右美沙芬片15mg tid，连用不超过1周。\n4. 化痰排痰：盐酸氨溴索片30mg tid×5～7天，与镇咳药避免同服（痰多时以化痰为主）。\n【一般治疗及生活指导】\n1. 急性期卧床休息，保证充足睡眠，避免劳累、熬夜，直至退热及咳嗽明显缓解后再逐渐恢复活动。\n2. 多饮水（每日1500～2000ml），清淡易消化高蛋白饮食，忌辛辣、油腻、生冷食物，戒烟戒酒。\n3. 做好呼吸道隔离：佩戴口罩、勤洗手、居室定时通风，避免与他人密切接触及前往人群密集场所，防止交叉感染（潜伏期1～3周，传染期可持续数周）。\n4. 暂停剧烈运动和游泳，天气变化时注意保暖，避免受凉诱发或加重咳嗽。\n【随诊要求】\n1. 服药后3～5天复诊，评估发热、咳嗽症状缓解情况；若48小时高热不退、咳嗽加重，或出现胸痛、呼吸困难、咯血、皮疹等，立即复诊或急诊就诊。\n2. 支原体肺炎者疗程结束后2～4周复查胸部影像学，观察病灶吸收情况；症状迁延不愈或有基础疾病者务必复查。\n3. 咳嗽可能持续2～4周属正常恢复过程，若超过4周仍不缓解，或出现再发热，需复诊进一步检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1088,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f555076a96a4dc4be6e52f29cf37edcea376bbf771ebf809526ab2fe65572b6e","pinyin":"zhiyuantiganran","initials":"zytgr","setting":"out","caseName":"门诊病历956","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历956",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7fa2e39122189940d9b1","key":"v1-c9ccc21dfe2a3058|templates-7fa2e39122189940d9b1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"月经过多","category":"门诊病历模板","raw":{"name":"月经过多","category":"门诊病历模板","case":{"case_name":"门诊病历957","templates":{"主诉":"月经量增多伴经期延长6月","现病史":"患者年龄方面：青春期者因下丘脑-垂体-卵巢轴功能尚未成熟，无排卵所致者多见；育龄期以器质性病变多见；围绝经期排卵障碍与器质性病变并存，需排除恶性病变，此点重要。患者症状逐渐出现，表现为：经量增多（>80ml/周期，或主观上影响生活，如卫生巾湿透、更换频繁，每1~2小时即需更换）、经期延长（>7天）、大血块（直径>2~3cm）、贫血症状（乏力、头晕、心悸、面色苍白，此点重要，因经量多致慢性失血可引起贫血）、经间期出血、痛经（合并子宫腺肌症时出现）。需明确病因：器质性病因包括子宫肌瘤（黏膜下肌瘤最常见，可致经量增多）、子宫腺肌症（经量增多伴进行性痛经）、子宫内膜息肉、子宫内膜炎、宫内节育器（放置后经量增多）、子宫内膜增生及子宫内膜癌（围绝经期异常出血者重要，需排除；年龄>45岁有出血者应行内膜活检评估）；凝血障碍（血管性血友病、血小板异常，自幼有出血倾向，月经量多，青春期大出血者应筛查，重要）；功能性病因包括排卵障碍（无排卵致雌激素持续作用，内膜增厚，脱落时出血量多）、黄体功能异常、甲状腺功能异常（甲减可致经量增多）、全身性疾病（肝病、肾病）。同时应评估贫血情况、出血量及速度（湿透速度快、大出血者需急诊处理，贫血重者需输血），并了解既往出血史、刮宫及宫腔镜史、家族凝血病史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP108/68mmHg。注意有无贫血貌（睑结膜苍白）；妇科检查：子宫增大、质地异常（肌瘤或腺肌症），附件区包块或压痛，宫颈有无息肉及病变，窥器检查判断出血来源（宫腔出血）；全身检查：皮肤瘀斑（提示凝血障碍）、血压偏低（大出血时）、甲状腺体征（甲减）。","辅助检查":"【必做】血常规（评估贫血程度，观察血红蛋白）、凝血功能（血小板及凝血障碍筛查；青春期大出血者必查）、铁蛋白（了解有无缺铁）、甲状腺功能、妊娠试验（育龄期排除妊娠相关出血）。【影像】盆腔超声（为核心检查，观察子宫有无肌瘤（黏膜下者表现为宫腔占位）、有无腺肌症（肌层增厚、回声不均）、内膜厚度及有无息肉、宫腔有无占位、附件有无囊肿；经阴道超声对宫腔异常显示准确）、宫腔镜检查（对黏膜下肌瘤、息肉及内膜病变可直接观察，为确诊金标准，并可同时切除）、超声造影（生理盐水宫腔造影，可显示宫腔占位）。【内膜评估】子宫内膜活检或诊断性刮宫（指征为年龄>40~45岁、异常出血持续、内膜增厚或药物治疗无效，用于排除内膜增生及内膜癌，重要，围绝经期尤须注意）。【其他】凝血全套（血管性血友病筛查，月经量多的女性诊断中重要）。","初步诊断":"1. 月经过多（异常子宫出血，病因为器质性（子宫肌瘤、腺肌症、息肉）或功能性（排卵障碍），伴贫血，需结合年龄评估恶性风险）\n（注：治疗原则为止血、纠正贫血及针对病因治疗，依年龄、生育要求及病因选择。①急性大出血：急诊处理，药物止血（大剂量高效孕激素，如炔诺酮，或短效口服避孕药，每6~8小时1次），或行刮宫（可迅速止血并同时行内膜活检，重要）；血红蛋白<70g/L或大出血者予输血，并补铁。②药物治疗（非急诊，依病因选择）：氨甲环酸（抗纤溶药，可减少经量30~50%，经期口服，有效且安全，可作一线选择）、非甾体抗炎药（经期使用，可减轻经量及痛经）、短效口服避孕药（调节周期、减少经量，适用于育龄期且有避孕需求者）、孕激素（后半周期或全周期用药，调节内膜脱落，使月经规律）、左炔诺孕酮宫内缓释系统（曼月乐，为核心措施，可显著减少经量约90%，兼具避孕作用，可长期使用5年，为治疗月经过多的首选之一，适用于无生育要求的育龄期及围绝经期患者，为良好选择，此点重要）、戈舍瑞林（GnRH激动剂，用于肌瘤或腺肌症，可暂时造成闭经，用于术前或体外受精前短期治疗）。③手术治疗（依病因及生育要求选择）：宫腔镜切除（息肉及黏膜下肌瘤行宫腔镜电切，可保留子宫及生育功能）、子宫肌瘤剔除（保留生育功能）、子宫内膜消融（适用于无生育要求、难治性月经过多，术后需避孕）、子宫切除（无生育要求、药物治疗无效的重度肌瘤或腺肌症患者，为根治性措施及最后选择，患者充分讨论）、血管栓塞（肌瘤的介入治疗选择）。④纠正贫血：补铁（硫酸亚铁，服用3~6个月至铁蛋白恢复，此点重要，月经过多常合并缺铁性贫血，应予治疗）、重度贫血者输血。⑤随访：治疗后评估月经周期及经量（如月经过多是否消失、贫血是否纠正）、停药后评估复发情况、评估用药安全（口服避孕药的血栓风险）、围绝经期患者刮宫或内膜活检后应长期用药预防内膜癌并随访、复查血红蛋白及铁蛋白。妇科处理要点：明确病因诊断（宫腔镜及超声）、药物治疗（曼月乐为核心）、依生育要求选择手术、补铁，甚为重要。","处理方案":"【药物治疗】\n1. 抗纤溶药（首选）：氨甲环酸片（妥塞敏）1.0g 口服 tid，于月经第1天开始服用，连用3-5天，可减少经量约40%-50%；肾功能不全者需减量。\n2. 非甾体抗炎药：布洛芬缓释胶囊 0.3g 口服 bid，经期第1天起服用，饭后服，连用3-5天，可减少经量并缓解痛经；消化性溃疡及阿司匹林过敏者禁用。\n3. 孕激素后半周期治疗（适用于排卵障碍性出血）：地屈孕酮片 10mg 口服 bid，于月经周期第11-25天服用，连用3个周期，可减少经量并调整周期。\n4. 短效复方口服避孕药（适用于需避孕或经量过多者）：屈螺酮炔雌醇片（优思明）1片 口服 qd，于月经第1-5天开始服用，连服21天停药7天，连用3-6个周期；吸烟＞35岁、有血栓病史及高血压者禁用。\n\n【一般治疗及生活指导】\n1. 注意休息，保证充足睡眠，经期避免剧烈运动、重体力劳动及长时间站立，防止经量进一步增多。\n2. 加强营养，多食富含铁剂及优质蛋白的食物（如瘦红肉、动物肝脏、蛋黄、菠菜、红枣等），必要时口服铁剂纠正缺铁性贫血。\n3. 保持外阴清洁干燥，勤换卫生巾及内裤，经期禁止盆浴、游泳及性生活，预防上行感染。\n4. 注意经期保暖，避免受凉、淋雨及进食生冷、辛辣刺激性食物，戒烟限酒。\n\n【随诊要求】\n建议用药后1-3个月经周期复诊，评估经量减少情况、周期变化及贫血纠正程度；若经量持续过多、贫血加重或出现经期延长、经间期出血、腹痛加剧等异常，应及时复诊，必要时行血常规、妇科B超及宫腔镜检查进一步明确病因；使用激素类药物者需定期复查肝肾功能，长期用药者注意监测血压及凝血功能，并评估后续治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1089,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f477407e0956518ebeca1900426f34a4339e6f2d7e3828389f084ed83deceb89","pinyin":"yuejingguoduo","initials":"yjgd","setting":"out","caseName":"门诊病历957","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历957",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5e2eb0084ef7e8c08396","key":"v1-c9ccc21dfe2a3058|templates-5e2eb0084ef7e8c08396","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"月经过少","category":"门诊病历模板","raw":{"name":"月经过少","category":"门诊病历模板","case":{"case_name":"门诊病历958","templates":{"主诉":"月经量减少6月","现病史":"患者年龄方面：青春期者初潮后1~2年内排卵功能尚未成熟，经量偏少属正常；育龄期需寻找病因；围绝经期者卵巢功能减退，经量渐少属正常生理过程。诱因方面：近期有流产、人工流产或清宫史者，应注意宫腔粘连（Asherman综合征，内膜损伤，刮宫后经量明显减少甚至闭经，此点重要，须详细询问）；既往有宫腔操作史（诊断性刮宫、宫腔镜）；口服避孕药（复方口服避孕药可使内膜变薄、经量减少，属药物性，为正常现象）；放置曼月乐（左炔诺孕酮宫内缓释系统可使内膜萎缩、经量减少甚至闭经，属预期内的正常反应）；子宫内膜结核或感染（可致内膜破坏）；卵巢功能减退及早衰（围绝经期）；内分泌疾病（甲减、多囊卵巢综合征、高泌乳素血症）；应激、体重变化及运动因素（下丘脑功能受影响）；全身性疾病。患者3个月前出现月经量明显减少，表现为：经量减少（<20ml/周期，或较前明显减少，主观上表现为卫生巾湿透片数明显减少、经期天数缩短）、颜色可偏深或呈褐色、周期正常或延长。需鉴别：妊娠（先兆流产或异位妊娠可表现为少量出血，易误认为经量减少，育龄期必查血hCG，此点重要）、围绝经期（年龄>45岁，卵巢功能减退，属生理性）、闭经前兆（经量进行性减少直至闭经，见于卵巢功能衰竭）、手术史、用药史、宫腔操作史、宫腔粘连（经量骤减伴人工流产后不孕、月经量少，需宫腔镜诊断，重要）、内膜薄（超声示卵泡期内膜<5~7mm）。同时应了解生育计划及既往妊娠、流产史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P76次/分，R18次/分，BP112/70mmHg。妇科双合诊检查子宫及附件，多元异常；检查宫颈；注意体重（消瘦见于厌食症，肥胖见于多囊卵巢综合征）、有无多毛及痤疮（提示多囊卵巢综合征或高雄激素）、有无溢乳（提示高泌乳素血症）、甲状腺体征、第二性征发育情况、有无全身慢性病及贫血。","辅助检查":"【必做】妊娠试验（育龄期排除妊娠，重要）、性激素（促卵泡激素、黄体生成素、雌二醇（评估卵巢功能，早衰者促卵泡激素升高，围绝经期亦升高）、孕酮、催乳素、睾酮（多囊卵巢综合征）、甲状腺功能）、经阴道超声（观察子宫内膜厚度（卵泡期内膜薄，<5mm，为经量减少的原因）、宫腔有无粘连或积液、卵巢情况）、宫腔镜（诊断并治疗宫腔粘连（Asherman综合征），对有刮宫或人工流产史且经量骤减者重要）、内膜活检（评估结核及慢性内膜炎）。【其他】卵巢储备功能（抗缪勒管激素）、内分泌评估（下丘脑及垂体功能，必要时行促性腺激素释放激素试验）、宫腔造影或超声造影（评估粘连）、染色体检查（年轻患者疑卵巢早衰时）。","初步诊断":"1. 月经过少（经量<20ml或较前明显减少；病因包括宫腔粘连、卵巢功能减退、内分泌异常、药物性及生理性；需评估内膜厚度及宫腔情况，排除妊娠及器质性病变）\n（注：治疗依病因而定，生理性者不需治疗。①生理性：青春期、围绝经期、口服避孕药及放置曼月乐所致经量减少属正常生理现象，应告知患者不需处理，此点重要，并予解释安抚。②宫腔粘连：行宫腔镜下分离（粘连电切或钝性分离），术后宫腔内放置球囊或防粘连材料，并用雌激素治疗（雌孕激素周期治疗，促进内膜再生修复，此点重要），术后复查宫腔镜评估；粘连复发者（重度者需反复分离），分离后妊娠率可改善。③卵巢功能减退及围绝经期：评估激素替代治疗（早衰者（<40岁）应激素替代至50岁，参见卵巢早衰）；围绝经期经量少属生理现象，但如有潮热等症状应评估激素治疗；有生育需求者可行辅助生殖（供卵）。④内分泌治疗：甲减用左甲状腺素；高泌乳素血症用溴隐亭或卡麦角林；多囊卵巢综合征予调经（孕激素或复方口服避孕药，参见多囊卵巢综合征）。⑤慢性内膜炎及结核：予抗感染或抗结核治疗，防止粘连加重。⑥随访：治疗后评估经量、宫腔镜术后复查有无粘连复发、了解生育计划、超声随访内膜厚度；应告知患者生理性者勿焦虑，如出现经量进行性减少伴痛经（宫腔粘连）或闭经前兆应及时就医。妇科处理要点：明确病因诊断（宫腔镜诊断粘连），生理性者不治疗，病理性者针对粘连行分离，甚为重要。","处理方案":"【药物治疗】\n1. 雌孕激素序贯疗法（人工周期）：戊酸雌二醇片2mg qd，自月经第5天起连服21天，服药第12天起加用地屈孕酮片10mg bid（或黄体酮胶囊100mg bid×10天），两药同时服完停药，等待撤退性出血；于撤退性出血第5天开始下一周期，连用3个周期。适用于卵巢储备功能减退、子宫内膜偏薄所致月经过少者。\n2. 中成药（气血亏虚证）：八珍益母丸9g bid（或乌鸡白凤丸1丸bid），自经前1周开始连服至经净，连用3个月经周期，月经量正常后停药。\n3. 中成药（气滞血瘀证）：桂枝茯苓丸6g tid（或血府逐瘀胶囊6粒tid），经前1周开始服用至经期第3天，连用3个周期，经量增多后随诊调整。\n4. 黄体功能不足者：地屈孕酮片10mg bid，自月经周期第12～14天起连服10～14天，连用3个周期，以改善经量及周期规律性。\n\n【一般治疗及生活指导】\n1. 规律作息，保证每日7～8小时睡眠，避免熬夜及过度劳累；注意情绪调畅，减轻工作与生活压力，避免紧张焦虑诱发内分泌紊乱。\n2. 均衡营养，适当增加优质蛋白及含铁补血食物（瘦肉、动物肝脏、蛋类、红枣、桂圆等），避免节食减肥导致气血亏虚；经期忌食生冷、辛辣刺激及寒凉食物。\n3. 适度有氧运动（快走、瑜伽等，每周3～5次、每次30分钟），增强体质；经期避免剧烈运动、游泳及盆浴，注意腰腹保暖、避免受凉。\n4. 保持外阴清洁，经期勤换卫生巾，避免经期性生活和盆浴；有宫腔操作（人流、刮宫等）史者注意观察术后月经变化，如有异常及时就医。\n\n【随诊要求】\n完成3个周期治疗（或连续服药3个月）后复诊，复查妇科B超（含子宫内膜厚度）并评估月经量及周期变化；若经量仍持续减少，或伴月经稀发、闭经，建议进一步行性激素六项、甲状腺功能检查，必要时行宫腔镜检查以排除宫腔粘连、子宫内膜损伤及器质性病变；服药期间如出现异常子宫出血、经量过多不止或剧烈腹痛，应及时随诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1090,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f60b5a61ae7ecf5f8d2373fc80d4edbc90943592ae7ac57cf5bf0791b7e2400a","pinyin":"yuejingguoshao","initials":"yjgs","setting":"out","caseName":"门诊病历958","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历958",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e0b3fb3876e6434922ba","key":"v1-c9ccc21dfe2a3058|templates-e0b3fb3876e6434922ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"闭经","category":"门诊病历模板","raw":{"name":"闭经","category":"门诊病历模板","case":{"case_name":"门诊病历959","templates":{"主诉":"月经停止6月","现病史":"患者方面，原发性闭经指16岁仍无月经来潮，或14岁无月经来潮且无第二性征发育，需进一步评估；继发性闭经指曾有过正常月经，此后停经≥3个月（或原周期稀发者≥6个月无月经）。患者出现月经停止6个月，具体表现如下：停经时间明确，需了解此前月经是否规律。需鉴别以下病因：妊娠（首要排除，育龄期必查血hCG，此点重要）、哺乳（哺乳期闭经属生理性）、围绝经期（年龄>45~50岁卵巢功能衰竭属生理性，但<40岁者应考虑卵巢早衰，属异常）、体重及饮食因素（神经性厌食，体重下降>15%，属下丘脑性）、运动因素（过度运动，如运动员所致闭经）、精神压力（应激可致下丘脑性闭经）、多囊卵巢综合征（月经稀发或闭经，伴多毛、痤疮、肥胖，参见多囊卵巢综合征）、高泌乳素血症（伴泌乳，可为垂体泌乳素瘤，参见相关专项）、甲状腺疾病（甲减或甲亢）、卵巢功能方面（卵巢早衰，<40岁，促卵泡激素升高，伴潮热、出汗；Turner综合征，原发性闭经，身材矮小、蹼颈）、雄激素因素（高雄激素见于多囊卵巢综合征或肿瘤）、宫腔粘连（Asherman综合征，人工流产后闭经，有刮宫史，此点重要）、下丘脑及垂体病变（肿瘤、Sheehan综合征，有产后大出血史）、药物因素（长效避孕药停用后闭经，多可恢复；抗精神病药可致泌乳素升高）。同时应了解第二性征发育情况（发育正常者多为继发性闭经，原发性闭经伴发育异常者提示先天异常）、有无溢乳（提示高泌乳素血症）、多毛（提示多囊卵巢综合征或高雄激素）、潮热（提示卵巢功能衰竭）、体重变化、头痛及视野改变（垂体瘤占位压迫，如泌乳素瘤）、产后出血史。今日来我院妇科或内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP112/70mmHg，BMI21.5kg/m²。发育情况：评估第二性征（乳房Tanner分期、体毛分布）、身高（Turner综合征者矮小）、体重（消瘦见于神经性厌食，肥胖见于多囊卵巢综合征）；挤压乳房了解有无溢乳；注意有无多毛及痤疮（提示雄激素升高）；妇科检查：外阴发育、阴道、子宫大小及是否存在、处女膜有无闭锁（可致经血潴留，属原发性闭经）、卵巢触诊、甲状腺检查；视野检查（垂体肿瘤可致颞侧偏盲）；皮肤（干燥提示甲减，黑棘皮提示胰岛素抵抗）。","辅助检查":"【必做】妊娠试验（首要检查，检测hCG排除妊娠，必查且重要）、性激素六项（基础值，月经周期第2~4天测定，闭经者可随时查：促卵泡激素及黄体生成素（促卵泡激素>25~40IU/L提示卵巢衰竭，如卵巢早衰或绝经）、雌二醇（降低提示卵巢性）、黄体生成素与促卵泡激素比值（>2提示多囊卵巢综合征）、睾酮（升高提示多囊卵巢综合征或高雄激素肿瘤）、孕酮（提示无排卵）、催乳素（升高者须2次以上复查，考虑高泌乳素血症及泌乳素瘤，需排除）、促甲状腺激素及甲状腺功能）、肾上腺雄激素（硫酸脱氢表雄酮，升高提示肾上腺肿瘤或先天性肾上腺皮质增生）、盆腔超声（观察子宫、卵巢（多囊卵巢综合征者呈多囊样改变）、内膜厚度、有无卵巢肿瘤，并评估宫腔粘连）。【进一步检查】孕激素试验（用黄体酮后撤退性出血，阳性提示体内有雌激素且为无排卵，见于下丘脑性或多囊卵巢综合征；阴性提示无雌激素，病变在卵巢、垂体或下丘脑，病情较重）、雌孕激素序贯试验（撤退性出血提示子宫正常，再行GnRH试验以定位垂体或下丘脑病变）、促卵泡激素及雌二醇（促卵泡激素升高提示卵巢衰竭）、促性腺激素释放激素试验（评估垂体功能）、染色体核型（原发性闭经伴发育异常者，排除Turner综合征）、垂体MRI（催乳素升高或伴头痛、视野异常者，排除泌乳素瘤）、宫腔镜（排除宫腔粘连、Asherman综合征）、骨密度（低雌激素状态可致骨质疏松，需评估）。","初步诊断":"1. 闭经（按类型分为原发性或继发性；按部位分为下丘脑性、垂体性、卵巢性、子宫性及妊娠等；性激素定位（促卵泡激素、黄体生成素、催乳素及孕激素试验）提示；病因待查）\n（注：治疗依病因、激素水平及生育需求而定。①功能性闭经：因下丘脑性体重、运动及压力因素所致者，予纠正（增加体重（神经性厌食者需营养恢复以恢复月经）、减少运动量、减压、改善睡眠），多数可恢复，可观察。②多囊卵巢综合征：调经（孕激素周期治疗或口服避孕药）、减重、改善代谢（二甲双胍），有生育要求者促排卵（参见多囊卵巢综合征）。③高泌乳素血症：用溴隐亭或卡麦角林（泌乳素瘤首选药物，多巴胺激动剂可缩小肿瘤并恢复月经），手术适用于大腺瘤药物治疗无效或出现视神经压迫者，可行经蝶入路，参见相关专项。④卵巢早衰及绝经：<40岁者行激素替代（雌孕激素，可预防骨质疏松、缓解潮热，并注意心血管长期评估，重要），有生育要求者评估供卵及辅助生殖；监测骨密度。⑤甲状腺及肾上腺疾病：治疗原发病，甲减用左甲状腺素，月经可恢复。⑥子宫性闭经：宫腔粘连者行宫腔镜下分离，加用雌激素促进内膜生长，宫腔内放置球囊防止再粘连；内膜损伤严重者治疗困难，需评估。⑦垂体肿瘤：泌乳素瘤用药物或手术治疗，其他垂体占位转神经外科评估；Sheehan综合征者行多轴激素替代。⑧原发性闭经：解剖异常（处女膜闭锁或阴道横隔者行切开，子宫发育异常者评估）、Turner综合征（用生长激素及激素替代，青春期诱导雌激素，重要）、染色体异常者相应处理。⑨随访：评估月经恢复及周期情况、监测激素并调整治疗、了解生育需求（促排卵或辅助生殖）、长期监测骨密度（低雌激素者）、给予心理支持（闭经及焦虑，重要）。妇科及内分泌科处理要点：先排除妊娠，行激素定位，明确病因，治疗结合生育需求个体化，甚为重要。","处理方案":"【药物治疗】\n1. 孕激素试验（闭经初筛首选方案）：地屈孕酮片10mg bid×10天，或黄体酮注射液20mg im qd×5天；停药后观察3-7天有无撤退性出血，阳性提示内源性雌激素水平正常。\n2. 雌孕激素序贯疗法（适用于低雌激素性闭经）：戊酸雌二醇片1-2mg qd，连服21天，第11-21天加服地屈孕酮片10mg bid，两药同时停用等待撤退性出血，于出血第5天开始下一周期，连用3-6个周期。\n3. 有生育要求者促排卵治疗：氯米芬片50mg qd×5天，于撤退性出血第5天起服，连用3-5天后超声监测卵泡；若无排卵下一周期可增至100mg qd。\n4. 高泌乳素血症性闭经：溴隐亭片1.25mg qd起始（晚餐时服），3天后增至2.5mg bid，根据血清PRL水平调整剂量，PRL正常后缓慢减量维持。\n\n【一般治疗及生活指导】\n1. 规律作息，避免熬夜及过度劳累，保持心情舒畅，缓解精神压力。\n2. 均衡营养：体重过轻者（BMI<18.5）增加优质蛋白与适量脂肪摄入；超重/肥胖者（BMI≥24）控制总热量，减重5%-10%即可恢复月经。\n3. 适当中等强度有氧运动（每周3-5次，每次30-40分钟），避免剧烈运动及过度训练。\n4. 禁忌：避免自行长期或滥用避孕药、糖皮质激素等药物；避免过度节食减肥；注意保暖及经期卫生，避免冒雨涉水、受凉。\n\n【随诊要求】\n1. 孕激素试验停药后3-7天内记录有无撤退性出血，并及时复诊反馈结果。\n2. 激素治疗期间每3-6个月复诊1次，复查性激素六项及妇科超声（观察子宫内膜厚度及卵巢形态），评估疗效并调整方案。\n3. 服药期间如出现阴道异常出血、乳房胀痛加重、头痛或视物异常等，随时就诊。\n4. 有生育要求者连续促排卵治疗3-6个周期仍未妊娠，或闭经持续1年以上，需进一步行垂体MRI、染色体核型及宫腔镜检查明确病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1091,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e97b8713e8ef6ccd3311e798689c233f0f2c4cf10b84f3cb7105c2c65ebdac70","pinyin":"bijing","initials":"bj","setting":"out","caseName":"门诊病历959","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历959",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7c8e7b413ef1d40e78de","key":"v1-c9ccc21dfe2a3058|templates-7c8e7b413ef1d40e78de","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"功能失调性子宫出血","category":"门诊病历模板","raw":{"name":"功能失调性子宫出血","category":"门诊病历模板","case":{"case_name":"门诊病历960","templates":{"主诉":"反复阴道不规则出血6月","现病史":"患者方面：青春期者下丘脑-垂体-卵巢轴尚未成熟，无排卵者多见；育龄期以排卵障碍为主（压力、体重变化、多囊卵巢综合征可致无排卵或黄体功能不足）；围绝经期卵巢功能衰退，无排卵者常见。患者6个月前出现以下症状：月经周期紊乱（延长、缩短或不规则）、经期延长（>7天或淋漓不尽）、经量增多（大出血可致贫血，出现乏力、头晕，亦可经量减少）、阴道不规则出血（非经期点滴或大量出血，出血模式多样）、无排卵性者表现为周期完全紊乱、无规律，出血量不定，或闭经后大量出血；排卵性者周期规律，但可出现经间期出血（黄体功能不足，经前点滴出血）或经期延长（黄体萎缩不全）、大出血（出血量大，需急诊止血，防止休克及贫血）、长期出血（可致贫血，表现为乏力、面色苍白）。需排除器质性病变：妊娠（先兆流产或异位妊娠，育龄期必查hCG）、子宫肌瘤、腺肌症、息肉及内膜病变（超声检查）、宫颈病变（接触性出血）、甲状腺疾病及凝血障碍（甲减或凝血障碍，青春期大出血者应筛查）。按PALM-COEIN分类（异常子宫出血分类：息肉、腺肌症、肌瘤、恶性肿瘤与增生属器质性因素；凝血障碍、排卵障碍、子宫内膜因素、医源性及未分类属非器质性因素），本例为排卵障碍性异常子宫出血（AUB-O，即功能失调性子宫出血，最常见，因无排卵致雌孕激素失衡）。同时应评估贫血程度（观察血红蛋白，乏力、头晕、心悸等症状的轻重）。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P92次/分，R18次/分，BP104/66mmHg。注意有无贫血貌（睑结膜及口唇苍白，见于大出血或长期出血者）；外阴及阴道检查评估出血量，窥器检查宫颈（判断血来自宫腔，排除宫颈及阴道病变）；子宫大小（正常者多为功能性出血，如子宫增大应考虑肌瘤）、附件有无压痛及包块（排除其他病变）；全身检查：甲状腺体征（甲减）、皮肤瘀斑（提示凝血障碍）、体重（肥胖见于多囊卵巢综合征）、多毛及痤疮（提示多囊卵巢综合征、雄激素升高）、生命体征（大出血者可有低血压、心率增快，应评估休克）。","辅助检查":"【必做】血常规（评估贫血（血红蛋白，大出血或长期出血者）及血小板（凝血））、人绒毛膜促性腺激素（hCG，育龄期必须排除妊娠，重要）、甲状腺功能（甲减可致排卵障碍）、凝血功能（青春期大出血者应筛查凝血因子，排除血管性血友病）、性激素六项（月经周期第2~4天测基础值：促卵泡激素及黄体生成素（围绝经期促卵泡激素升高）、雌二醇、孕酮（黄体期测定可评估排卵，无排卵者孕酮低）、雄激素（多囊卵巢综合征者升高）、泌乳素）、血糖。【影像】盆腔超声（为核心检查，观察子宫内膜厚度、宫腔有无息肉或肌瘤、卵巢（多囊卵巢综合征者卵泡数增多），排除器质性病变；育龄期可行经阴道超声）、宫腔声学造影或宫腔镜（超声疑似内膜息肉或黏膜下肌瘤者，宫腔镜为确诊金标准）。【内膜评估】诊断性刮宫或宫腔镜加内膜活检（指征：年龄>45岁（排除内膜增生及内膜癌，重要；异常子宫出血的围绝经期及绝经后患者，内膜癌筛查是关键）、长期无排卵（雌激素持续作用致内膜增生，需评估癌变风险）、药物治疗无效者）。【其他】出血量大者急诊检查血型及交叉配血。","初步诊断":"1. 排卵障碍性异常子宫出血（功能失调性子宫出血，AUB-O，类型为无排卵性或排卵性（黄体功能不足），年龄组为青春期、育龄期或围绝经期，伴贫血）\n（注：治疗原则为止血加调整周期，结合年龄及生育要求，防止贫血及内膜病变。①急性大出血止血：属急诊，出血量大伴贫血者予药物止血（大剂量孕激素，如高效孕激素炔诺酮5~10mg每6小时1次，血止后逐渐减量维持并调整周期），或短效口服避孕药（每6~8小时1片，血止后逐渐减至每日1片，维持21天），出血量大者行刮宫（诊断性刮宫可迅速止血并同时行内膜活检，为围绝经期及大出血者的首选，兼具止血与诊断作用，重要）；大出血致休克者予补液及输血。②调整周期：青春期用雌孕激素周期序贯（如戊酸雌二醇加孕激素，建立周期）或复方口服避孕药（无性生活者亦可使用，止血后维持3~6个周期），或用孕激素后半周期（黄体酮或地屈孕酮，每月10~14天，于月经后半期使用，以调整周期，无排卵者定期撤退出血可防止内膜增生，重要）；育龄期有生育要求者促排卵（克罗米芬或来曲唑诱导排卵，用于备孕的无排卵不孕者，重要）或调整周期（孕激素周期），无生育要求者用复方口服避孕药或孕激素周期，或放置曼月乐（左炔诺孕酮宫内缓释系统可减少出血、防止内膜增生，适宜长期使用，为围绝经期的良好选择）；围绝经期用孕激素后半周期（每月）或曼月乐以预防内膜增生，刮宫排除病变后，年龄>35岁吸烟者慎用复方口服避孕药（血栓风险）。③贫血：补铁（硫酸亚铁，血止后服用3~6个月以补足储存铁，复查血红蛋白，重要），重度贫血（血红蛋白<60~70g/L）或大出血者输血。④随访：调整周期后评估月经是否规律、长期无排卵及围绝经期者定期超声监测内膜以防增生，异常者行活检、补铁后复查血红蛋白以评估恢复情况。妇科处理要点：止血并调整周期，防止贫血，围绝经期刮宫防癌，长期管理，甚为重要。","处理方案":"【药物治疗】\n1. 大出血止血（内膜萎缩法，适用于出血量大或Hb<80g/L）：炔诺酮片（妇康片）5mg q8h口服，血止后每3日递减1/3剂量，至维持量2.5mg qd，连续用药21日；亦可选用去氧孕烯炔雌醇片（妈富隆）1片 q8h，血止后每3日减1片至1片 qd，共21日。\n2. 轻中度出血止血（内膜脱落法，Hb≥80g/L）：地屈孕酮10mg bid，连服10日，停药后3~7天出现撤退性出血；或黄体酮注射液20mg im qd×3~5日。\n3. 调整周期（止血后后半周期孕激素法）：地屈孕酮10mg bid，自月经周期第11~15日起连服12~14日，每月1疗程，连续3~6个周期以建立规律月经。\n4. 纠正贫血：琥珀酸亚铁片0.1g tid，同时口服维生素C 0.1g tid促进铁吸收，血止后继续服药2~3个月以补足储存铁。\n\n【一般治疗及生活指导】\n1. 出血期适当卧床休息，避免剧烈运动、重体力劳动及长途跋涉，防止晕厥及加重出血。\n2. 加强营养，多食高蛋白、富含铁及维生素的食物（瘦肉、动物肝脏、蛋黄、红枣、绿叶蔬菜），忌辛辣刺激及生冷饮食。\n3. 保持外阴清洁，勤换卫生巾，出血期间禁止盆浴、游泳及性生活，预防逆行感染。\n4. 规律作息，避免熬夜、过度劳累及精神紧张，保持情绪稳定，必要时给予心理疏导。\n\n【随诊要求】\n1. 用药期间记录月经量及周期变化，血止后每月复诊1次评估疗效及药物反应；出现突破性出血或撤退性出血量过多时及时就诊。\n2. 连续用药3~6个周期后复诊评估月经是否恢复正常；若停药后再次出现不规则出血或药物治疗无效，应行诊断性刮宫并送病理，必要时行宫腔镜检查排除子宫内膜病变。\n3. 围绝经期患者或药物治疗6个月仍反复异常出血者，建议诊刮送病理检查，必要时转诊行宫腔镜检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1092,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7ec15d7f85ffc769dc6534af432d0f117e4410eecc292469f0f4fb01ae444f5e","pinyin":"gongnengshitiaoxingzigongchuxie","initials":"gnstxzgcx","setting":"out","caseName":"门诊病历960","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历960",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1e0215c4bcaf88b49e4a","key":"v1-c9ccc21dfe2a3058|templates-1e0215c4bcaf88b49e4a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"多囊卵巢综合征","category":"门诊病历模板","raw":{"name":"多囊卵巢综合征","category":"门诊病历模板","case":{"case_name":"门诊病历961","templates":{"主诉":"月经稀发伴多毛2年","现病史":"患者为育龄期女性，本病常见（发病率5~10%），多于青春期起病（初潮后出现月经不调）。患者病史较长，2年来出现以下表现：月经异常（月经稀发，周期>35天，为最常见表现；闭经，>3~6个月；不规则子宫出血。因无排卵或稀发排卵所致，为本病核心表现）、高雄激素表现（多毛，分布于上唇、下颌、胸部、腹中线及大腿内侧，呈男性型分布，可采用Ferriman-Gallwey评分；痤疮，顽固性炎性痤疮，多见于下颌、胸部及背部；脱发，呈雄激素性脱发，位于头顶；黑棘皮病，颈及腋部色素沉着呈天鹅绒样，为胰岛素抵抗的特征性表现）、肥胖（约50~80%患者存在，多为腹型，BMI升高，伴胰岛素抵抗及代谢综合征）、不孕（因无排卵所致，为最常见的不孕原因，此点重要，是本例就诊原因）、卵巢多囊改变（超声示卵巢增大，外周可见多个小卵泡，>12个，直径2~9mm，呈项链征）。诊断标准采用鹿特丹标准（以下三项中至少具备两项：稀发排卵或无排卵、高雄激素（临床或生化）、超声示多囊卵巢，并排除其他病因，如甲状腺疾病、高泌乳素血症、先天性肾上腺皮质增生）。同时需注意胰岛素抵抗（肥胖者易出现糖耐量异常，2型糖尿病风险增高，此点重要，属远期风险）、代谢异常（血脂异常、高血压、脂肪肝，构成代谢综合征，属远期心血管风险，应筛查）、子宫内膜癌风险（长期无排卵致雌激素持续作用，可致内膜增生，癌变风险升高，此点长期重要，需用孕激素定期撤退以预防）。今日来我院妇科或内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P80次/分，R18次/分，BP122/78mmHg，BMI27.4kg/m²。体型：肥胖，呈腹型，测量腰围；多毛（评分，观察上唇、颏、胸、腹及四肢等雄激素敏感区）；痤疮；黑棘皮病（颈后、腋窝及腹股沟色素沉着，呈天鹅绒样，提示胰岛素抵抗）；脱发（头顶）；乳房发育情况；妇科检查：子宫及附件，超声观察卵巢；注意阴蒂有无肥大（罕见，见于严重高雄激素，需与先天性肾上腺皮质增生鉴别）。","辅助检查":"【必做】性激素六项（月经周期第2~4天测定：促黄体生成素与促卵泡激素比值（LH/FSH>2~3，为典型表现但非诊断必需）、雄激素（总睾酮及游离雄激素指数升高，提示生化高雄激素）、雌二醇、孕酮（无排卵者低）、泌乳素（排除高泌乳素血症，用于月经不调的鉴别）、甲状腺功能（排除甲减）、硫酸脱氢表雄酮及17-羟孕酮（排除肾上腺疾病及先天性肾上腺皮质增生，17-羟孕酮升高者重要）、血糖及糖化血红蛋白（评估糖代谢及胰岛素抵抗，用于糖尿病筛查）、胰岛素（空腹测定，计算HOMA-IR评估胰岛素抵抗）、血脂（胆固醇及甘油三酯，代谢筛查）、肝功能（排除脂肪肝）、25-羟维生素D（本病常降低）。【影像】盆腔超声（观察卵巢是否呈多囊改变（一侧或双侧卵泡数>12个或卵巢体积>10ml，呈项链征，排除卵巢肿瘤）、子宫内膜厚度（长期无排卵者应评估内膜增生，重要）；长期无排卵或内膜增厚者行宫腔镜或内膜活检，排除增生以防癌变，为活检指征）。【其他】妊娠试验（月经不调者排除妊娠）。","初步诊断":"1. 多囊卵巢综合征（PCOS，表型分类：A型为月经稀发加高雄激素加多囊卵巢，B型为稀发加高雄激素，C型为稀发加多囊卵巢，D型为高雄激素加多囊卵巢而无月经异常；伴胰岛素抵抗、肥胖及代谢综合征，需评估）\n（注：治疗依需求而定（调整月经、改善高雄激素、促进生育、改善代谢），应个体化并长期管理，防止远期并发症。①生活方式干预：为基础治疗及一线措施，适用于所有患者，尤其肥胖者，包括减重（体重下降5~10%可显著改善，部分患者恢复排卵并可自然妊娠，改善胰岛素抵抗、降低雄激素，使月经规律，为核心措施，重要）、运动（每周≥150分钟，有氧运动加抗阻训练）、饮食（低升糖指数，控制糖类摄入，减少精制碳水，改善胰岛素抵抗）。②调整月经（无生育要求者）：孕激素后半周期治疗（地屈孕酮10mg bid×10~14天，每月1次，定期撤退出血以预防内膜增生，长期患者重要），或短效口服避孕药（如达英-35、优思明，可调整周期并降低雄激素，改善痤疮及多毛，治疗6个月至数年；注意血栓风险，肥胖或吸烟且年龄>35岁者慎用），或放置曼月乐（左炔诺孕酮宫内缓释系统，可保护内膜，适宜长期使用，适用于围绝经期及不愿口服者）。③高雄激素表现：痤疮及多毛者首选复方口服避孕药（含抗雄激素作用的孕激素，如环丙孕酮或屈螺酮，用药6~12个月，多毛改善较慢，需长期治疗）；螺内酯（抗雄激素辅助用药，用于复方口服避孕药禁忌者，注意高钾血症及致畸风险，用药期间需避孕）；多毛者可行激光脱毛等美容处理。④生育需求：促排卵为一线治疗（克罗米芬50~100mg，自月经第5天起连用5天，或来曲唑2.5~5mg，近年作为一线，排卵率高、单卵泡发育好），超声监测卵泡并指导同房；二甲双胍（500mg tid，适用于胰岛素抵抗或克罗米芬抵抗者，辅助排卵及减重）；促排卵失败者行超促排卵加体外受精（二线，转生殖中心）；卵巢打孔术少用。⑤代谢管理：胰岛素抵抗及糖尿病者用二甲双胍（一线，改善胰岛素敏感性及血糖，长期患者）、血脂异常者用他汀类药物、高血压者降压，长期管理以预防糖尿病及心血管疾病。⑥内膜保护：长期无排卵者定期用孕激素撤退（每月）或复方口服避孕药、曼月乐，预防内膜增生及癌变，此点关键，并随访超声观察内膜。⑦随访：调整后评估月经是否规律、减重效果、血糖（每年筛查糖尿病，胰岛素抵抗者监测糖化血红蛋白）、血脂及血压（代谢综合征者每年检查）、超声（定期观察内膜及卵巢）、多毛及痤疮（评估复方口服避孕药疗效）、心理支持（PCOS患者常有焦虑、抑郁及不孕、体像困扰，应予支持）。妇科及内分泌科处理要点：长期管理，减重、调经及代谢治疗，依需求个体化，防止远期糖尿病、内膜癌及心血管疾病，甚为重要。","处理方案":"【药物治疗】\n1. 调整月经周期/降低雄激素：复方短效口服避孕药（炔雌醇环丙孕酮片）1片 qd×21天，停药7天后开始下一周期，连用3～6个周期。\n2. 改善胰岛素抵抗：盐酸二甲双胍片0.5g bid（随餐服）×3个月，需逐渐加量以减少胃肠道反应。\n3. 孕激素后半周期疗法（无高雄表现、仅需调经）：地屈孕酮片10mg bid，自月经周期第14天起连用14天。\n4. 促排卵（有生育要求）：来曲唑片2.5mg qd，自月经周期第3～5天起连用5天，超声监测卵泡发育。\n\n【一般治疗及生活指导】\n1. 控制体重：超重或肥胖者（BMI≥24kg/m²）目标减重5%～10%，可显著改善排卵及代谢异常。\n2. 饮食：低糖低脂、高膳食纤维饮食，减少精制碳水化合物及含糖饮料，适当增加优质蛋白和蔬菜。\n3. 运动：每周至少150分钟中等强度有氧运动（快走、慢跑、游泳、骑自行车等），每周3～5次，可配合每周2次抗阻训练。\n4. 生活方式：规律作息、避免熬夜，戒烟限酒，保持情绪平稳，避免精神紧张加重内分泌紊乱。\n\n【随诊要求】\n1. 每3个月复诊，记录月经周期、体重及腰围变化，评估治疗效果。\n2. 用药期间每3～6个月复查性激素六项、妇科超声（子宫内膜厚度及卵巢形态），并监测肝肾功能。\n3. 伴胰岛素抵抗者定期复查空腹血糖、空腹胰岛素（计算HOMA-IR），必要时复查血脂。\n4. 有生育要求者促排卵治疗6个周期仍未妊娠，或闭经、不规则出血久治不愈，需及时复诊评估并排除子宫内膜病变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1093,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a12509cb90fd1e65f6989ac128ea9cea528295b5cc0cc5da026a584ea105ee16","pinyin":"duonangluanchaozonghezheng","initials":"dnlczhz","setting":"out","caseName":"门诊病历961","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历961",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ef23a516b09db84c7dd2","key":"v1-c9ccc21dfe2a3058|templates-ef23a516b09db84c7dd2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"卵巢早衰","category":"门诊病历模板","raw":{"name":"卵巢早衰","category":"门诊病历模板","case":{"case_name":"门诊病历962","templates":{"主诉":"月经稀发伴潮热出汗1年","现病史":"患者年龄<40岁，发生卵巢功能衰竭（呈绝经状态），即卵巢早衰。病因方面：特发性者居多，原因不明；遗传因素包括X染色体异常、Turner综合征、脆性X综合征（FMR1前突变，家族史重要）；自身免疫因素包括卵巢抗体阳性，常合并自身免疫性甲状腺炎（桥本甲状腺炎，此点重要，属自身免疫多腺体综合征）；医源性因素包括化疗（烷化剂如环磷酰胺有卵巢毒性）、放疗（盆腔照射）、手术（双侧卵巢切除或单侧囊肿剔除致部分损伤）；感染因素如腮腺炎性卵巢炎（少见）；酶缺陷如半乳糖血症；环境因素及吸烟可增加早绝经风险；另有早绝经家族史。患者于40岁前出现以下表现：月经紊乱（由稀发渐至闭经，呈进行性加重，为最常见表现，首先表现为月经周期延长，逐渐闭经）、围绝经期症状（潮热，表现为突发面部、颈部及胸部潮红、出汗，呈阵发性，为典型症状；出汗及盗汗；睡眠障碍，失眠、易醒；情绪改变，烦躁、焦虑、抑郁、易激惹；阴道干涩，黏膜萎缩，性交痛；性欲减退；泌尿系统症状，尿频，尿道及阴道萎缩；皮肤干燥、弹性下降；骨质疏松，长期低雌激素可致骨量下降，骨折风险增高，属远期危害；心血管疾病风险增高，属远期危害；认知功能下降，记忆力减退）。同时需注意：自身免疫疾病（桥本甲状腺炎可致甲减，表现为乏力、怕冷；Addison病可有色素沉着；糖尿病应筛查）、脆性X综合征家族史（家族中有智力障碍或早绝经者）、化疗及放疗史、手术史、腮腺炎病史、吸烟史。生育方面，因卵巢储备功能下降，不孕，自然妊娠率低（但并非为零，可有间歇性排卵，部分患者仍可妊娠，约5~10%）；长期雌激素缺乏危害较大，激素替代治疗重要。今日来我院妇科或内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P74次/分，R18次/分，BP110/70mmHg。乳房萎缩；外阴及阴道萎缩、干涩；子宫萎缩、偏小；卵巢触诊不可及；身高（Turner综合征者矮小、蹼颈）；甲状腺（桥本甲状腺炎可致肿大）；皮肤干燥；测量体重；挤压乳房排除溢乳（除外高泌乳素血症）；评估第二性征。","辅助检查":"【必做】性激素：促卵泡激素（升高，>25~40IU/L，两次测定间隔1个月，为卵巢衰竭诊断的核心指标）、雌二醇（降低）、黄体生成素（升高）、抗缪勒管激素（反映卵巢储备，显著降低，<1ng/ml，支持诊断）、抑制素B（降低）、催乳素（排除高泌乳素血症）、促甲状腺激素及甲状腺功能（筛查自身免疫性甲状腺疾病）、血糖、肾上腺皮质醇及促肾上腺皮质激素（筛查Addison病，属自身免疫多腺体综合征）、卵巢抗体及肾上腺抗体（评估自身免疫性卵巢炎）、染色体核型（排除Turner综合征）、脆性X基因（FMR1）检测（有家族史或年轻患者）、盆腔超声（卵巢小、无卵泡，内膜薄）、骨密度（作为骨质疏松基线，长期随访重要）、血脂及心血管风险评估。","初步诊断":"1. 卵巢早衰（卵巢功能不全，40岁前发病，两次促卵泡激素>40IU/L，病因为特发性、遗传性、自身免疫性或医源性，伴雌激素缺乏症状，需评估生育及长期健康）\n（注：治疗包括激素替代、生育管理及长期健康维护。①激素替代治疗（核心治疗）：年轻女性卵巢早衰者长期缺乏雌激素，出现症状（潮热、萎缩、骨质疏松），需激素替代直至自然绝经年龄（约50岁）并评估：有子宫者用雌孕激素联合（雌激素加孕激素以保护内膜），无子宫者单用雌激素，可口服或经皮（贴片、凝胶），从小剂量起始；疗效为改善潮热及阴道干涩、保护骨密度、预防骨质疏松，此点重要；有乳腺癌及血栓风险者应评估禁忌证；随访每年行乳腺及妇科超声检查。②生育方面：自然妊娠率低（约5~10%，可有间歇性排卵），有生育要求者行辅助生殖（供卵体外受精，赠卵妊娠率高）、卵子冻存（于早诊、卵巢功能尚未完全衰竭前考虑生育力保存）、给予心理支持（卵巢早衰所致不孕打击较大，此点重要）。③自身免疫相关：筛查甲状腺、Addison病及糖尿病并治疗原发病，监测血钙（甲状旁腺受累者）。④长期健康：补充钙剂及维生素D、运动、随访骨密度以防治骨质疏松；评估心血管风险（激素替代可降低风险，不用激素者心血管风险升高）；关注认知功能（雌激素的作用）；泌尿生殖道萎缩症状（性交痛）可局部使用雌激素阴道软膏；给予心理支持（卵巢早衰的心理冲击较大，应提供咨询，此点重要）。⑤随访：调整激素替代剂量并评估症状、每1~2年复查骨密度、每年行乳腺及妇科筛查、治疗中促卵泡激素的临床意义有限、约50岁后评估停药、复诊评估症状缓解及整体健康。妇科及内分泌科处理要点：激素替代至50岁，生育可行供卵，重视心理及长期健康，甚为重要。","处理方案":"【药物治疗】\n1. 激素补充治疗（HRT）：无禁忌证者首选雌二醇片/雌二醇地屈孕酮片复合包装（芬吗通）1片 qd，连续服用28天为一个周期，周期间不停药，序贯服用；或戊酸雌二醇片（补佳乐）1mg qd，连用21天，于第11～21天加用地屈孕酮片（达芙通）10mg bid，停药后撤退性出血，于出血第5天起重复下一周期。如无禁忌证，建议持续HRT至平均绝经年龄（约50岁）以保护骨量与心血管健康。\n2. 补钙及维生素D：碳酸钙D3片（钙尔奇D，含元素钙600mg/维生素D3 125IU）1片 qd，长期服用；同时加用维生素D滴剂400～800IU qd，以预防低雌激素性骨质疏松。\n3. 有生育需求者：根据卵巢储备评估，在专科指导下行促性腺激素促排卵或辅助生殖技术（如赠卵体外受精-胚胎移植）助孕，具体方案由生殖专科制定。\n【一般治疗及生活指导】\n1. 规律作息，避免熬夜，保证每晚7～8小时睡眠；坚持每周≥150分钟中等强度有氧运动（快走、慢跑、游泳、瑜伽等），避免久坐及过度剧烈运动，维持健康体重。\n2. 均衡饮食：适当增加豆制品（豆浆、豆腐等，含植物雌激素）、优质蛋白及富钙食物（牛奶、酸奶、虾皮、绿叶蔬菜）摄入，戒烟限酒，避免过度节食减肥。\n3. 保持情绪稳定，避免焦虑、紧张等不良情绪，必要时接受心理疏导或咨询，家人给予支持。\n4. 注意阴道干涩、性交不适者可使用水溶性润滑剂，必要时在医生指导下短期局部使用雌激素软膏；有生育需求者尽早咨询生殖专科，把握助孕时机。\n【随诊要求】\n1. 用药期间每3～6个月复诊1次，评估潮热、出汗、月经等改善情况及用药依从性；每年至少1次全面评估，包括妇科超声、乳腺超声或钼靶、肝肾功能、血脂、凝血功能及骨密度检查，根据结果调整方案。\n2. 用药期间出现不规则阴道出血、乳房胀痛持续不缓解、下肢单侧肿痛、胸痛或突发呼吸困难等，应立即就诊；出现恶心、头痛等不良反应时及时复诊调整剂量。\n3. 停经后即使无生育要求也应坚持定期随访，监测骨质疏松、心血管疾病及泌尿生殖道萎缩等远期并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1094,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d078872fff32f22e2560ee16f4f5ec51136c36916b0f7d025012ad80766a56de","pinyin":"luanchaozaoshuai","initials":"lczs","setting":"out","caseName":"门诊病历962","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历962",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-dda2b63e9e87ba8793a3","key":"v1-c9ccc21dfe2a3058|templates-dda2b63e9e87ba8793a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高泌乳素血症","category":"门诊病历模板","raw":{"name":"高泌乳素血症","category":"门诊病历模板","case":{"case_name":"门诊病历963","templates":{"主诉":"月经稀发伴溢乳1年","现病史":"本病女性多见（以月经紊乱、溢乳为常见就诊原因），男性亦可发生（表现为性欲减退、阳痿、乳房发育，溢乳少见）。患者出现以下表现：溢乳（挤压双侧乳房可见乳汁样分泌，非哺乳期，此点重要，但多数高泌乳素血症患者并无溢乳，约占1/3）、月经紊乱（月经稀发或闭经，因催乳素抑制促性腺激素，致卵巢功能下降，为最常见的月经异常表现；亦可表现为黄体功能不足）、不孕（因无排卵所致）、性欲减退（男女均可出现）、男性表现（阳痿、精子减少）、头痛（大腺瘤压迫所致）、视力及视野障碍（垂体大腺瘤，>1cm，向上压迫视交叉，可致双颞侧偏盲，此点重要，需急诊行神经及眼科评估）、占位相关症状（垂体卒中可突发头痛及视力下降，属急症）。需明确病因：生理性因素（妊娠、哺乳、乳头刺激、睡眠、运动、应激、性交）、药物性因素（常见，如抗精神病药（利培酮、氟哌啶醇、氯丙嗪等多巴胺D2受体拮抗剂，为最常见原因）、甲氧氯普胺（胃复安）、多潘立酮、止吐药、降压药（α甲基多巴）、雌激素）、病理性因素（垂体泌乳素瘤（微腺瘤<1cm最常见，亦有大腺瘤，均可致催乳素升高）、下丘脑病变（压迫垂体柄，使泌乳素抑制减弱）、甲状腺功能减退（促甲状腺激素释放激素升高致催乳素升高，此点重要）、慢性肾衰竭、肝硬化、空蝶鞍）、特发性因素。另需了解妊娠及哺乳史、用药史（详细询问，重要）、有无甲减症状。今日来我院内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P78次/分，R18次/分，BP116/72mmHg。乳房：挤压可见溢乳，呈乳汁样，注意单侧或双侧；甲状腺（甲减者可肿大）；视野（大腺瘤可致双颞侧偏盲，行粗测或视野计检查）；视力；神经系统（颅神经检查，评估大腺瘤有无侵犯）；皮肤干燥（甲减）；第二性征及妇科检查（低雌激素可致萎缩）；男性检查有无乳房发育及睾丸异常；测量体重、血压。","辅助检查":"【必做】催乳素（为核心检查，观察是否升高；>100ng/ml多提示泌乳素瘤，>200ng/ml者几乎均为大腺瘤；单次升高者应复查，采血前需休息，以排除应激因素影响）、巨催乳素（生物活性低，为大分子复合物，可致假性升高，必要时筛查）、促甲状腺激素及甲状腺功能（甲减必查，重要）、性激素（雌二醇降低或睾酮降低，提示低促性腺激素状态）、孕酮及排卵情况、肝肾功能、血糖。【影像】垂体MRI增强（用于泌乳素瘤定位，判断微腺瘤或大腺瘤、大小及有无视交叉压迫，为诊断核心；亦用于排除其他鞍区占位；微腺瘤需行动态增强扫描）。【其他】停用致催乳素升高的药物并评估（抗精神病药不能停用者可换用对催乳素影响小的药物，如阿立哌唑，属多巴胺部分激动剂）、视野检查（大腺瘤者）、骨密度（低雌激素可致骨质疏松）。","初步诊断":"1. 高泌乳素血症（催乳素升高；病因为生理性、药物性、病理性（泌乳素瘤，微腺瘤或大腺瘤）、甲减或特发性；伴溢乳、月经紊乱及不孕等症状；大腺瘤需评估有无视交叉压迫）\n（注：治疗依病因、症状及腺瘤情况而定。①药物性：停用致病药物（需与精神科协作换药），停药4周后复查催乳素，多可恢复。②甲减：用左甲状腺素替代，催乳素可恢复正常。③泌乳素瘤：药物治疗为首选，多巴胺激动剂如卡麦角林0.25~0.5mg每周2次（为首选，疗效好、副作用小），或溴隐亭1.25~2.5mg每日2~3次，从小剂量起始逐渐加量，晚饭时随餐服用（可减轻恶心）；疗效为催乳素于2~4周内恢复正常，腺瘤缩小（大腺瘤80%以上可缩小），月经及溢乳恢复，并可生育；副作用有恶心、头晕及体位性低血压，故起始应缓慢并逐步滴定。妊娠方面，微腺瘤者妊娠后通常可停用溴隐亭（卡麦角林在妊娠期的安全性数据有限，应与内分泌科讨论用药），并监测视野及头痛；大腺瘤者妊娠期应继续用溴隐亭，以防腺瘤生长压迫视交叉，此点重要。手术为经蝶窦入路，指征为药物不耐受或耐药（卡麦角林耐药者<10%）、大腺瘤致视神经压迫且药物不能缓解（属急症，需手术减压）、囊肿或卒中、年轻且有根治意愿者，微腺瘤手术治愈率约50~60%。放疗用于残留或难治病例，较少使用，有垂体功能减退风险。④特发性：观察随访（每6~12个月复查催乳素，并复查MRI随访微腺瘤有无进展）。⑤症状处理：月经紊乱及不孕者于恢复排卵后可妊娠；绝经前因溢乳及闭经致雌激素降低者，可行激素替代或于治疗恢复后缓解；男性性欲减退者恢复后可予睾酮替代（必要时）。⑥随访：治疗期间每1~3个月复查催乳素，正常后可延长间隔；大腺瘤治疗后6~12个月复查MRI，缩小后可延长间隔；大腺瘤累及视交叉者复查视野；以最小有效剂量长期维持，多数需长期治疗，停药后复发率高；微腺瘤治疗2年正常者可试行减停，大腺瘤需长期用药；监测骨密度（低雌激素者）；妊娠期由内分泌科及产科共同监测。内分泌科处理要点：药物性者停药，泌乳素瘤以多巴胺激动剂（卡麦角林首选）治疗，大腺瘤致视交叉压迫属急症需手术，重视随访，甚为重要。","处理方案":"【药物治疗】\n1. 溴隐亭片：起始1.25mg qn餐中服，3～5天后加至2.5mg bid，维持剂量2.5mg bid，最大可至5mg bid；血清泌乳素降至正常后继续维持3～6个月，总疗程至少6～12个月，停药前应逐渐减量。\n2. 卡麦角林片：起始0.25mg qw餐后服，根据泌乳素水平每4周加量0.25mg，常用维持量0.25～0.5mg qw（最大1mg qw）；泌乳素正常后维持3～6个月再考虑减量，适用于溴隐亭不耐受或大腺瘤患者。\n3. 泌乳素瘤患者：上述药物需长期维持治疗，肿瘤缩小及泌乳素稳定正常后每3～6个月评估一次，遵医嘱逐渐减量至最小有效剂量长期维持，不可自行停药。\n【一般治疗及生活指导】\n1. 规律作息，保证充足睡眠，避免熬夜、过度劳累及精神紧张应激；睡眠障碍可加重泌乳素升高，必要时对症处理。\n2. 避免服用可致泌乳素升高的药物（如甲氧氯普胺、多潘立酮等胃动力药，抗精神病药、雌激素类避孕药及保健品），确需使用者患者医生指导下权衡；避免含雌激素成分的保健品和化妆品。\n3. 避免过度乳房刺激（如频繁按摩、过紧胸罩压迫）及剧烈运动；保持情绪平稳，戒烟限酒。\n4. 合并不孕需求者应同时进行排卵监测及配偶精液检查，在泌乳素降至正常并规律排卵后尽早规划妊娠，妊娠期及哺乳期在专科医师指导下调整用药。\n【随诊要求】\n1. 用药初期每2～4周复查血清泌乳素（同一时间点抽血），据水平调整剂量；泌乳素降至正常后每1～3个月复查一次。\n2. 每3～6个月复查泌乳素并评估症状（溢乳、月经恢复、性功能）变化；泌乳素大腺瘤患者每6～12个月复查垂体MRI，观察肿瘤大小变化。\n3. 用药期间监测不良反应（恶心、头晕、体位性低血压等），出现不能耐受时及时就诊调整药物；绝经前女性注意月经恢复情况，长期闭经者需监测骨密度。\n4. 减量或停药必医师指导下进行，停药后1～3个月复查泌乳素，若复发需重新治疗并进一步查找病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1095,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f2952e33d1d8ac009a1de68e5c3df3b00ac99526155ad79f796f148967d1b211","pinyin":"gaomirusuxuezheng","initials":"gmrsxz","setting":"out","caseName":"门诊病历963","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历963",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-96c6a3fbd27c6d86c550","key":"v1-c9ccc21dfe2a3058|templates-96c6a3fbd27c6d86c550","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"经前期综合征","category":"门诊病历模板","raw":{"name":"经前期综合征","category":"门诊病历模板","case":{"case_name":"门诊病历964","templates":{"主诉":"经前烦躁伴乳房胀痛1年","现病史":"患者为育龄期女性，经前期综合征常见，约占育龄女性的20~40%，症状于黄体期出现（排卵后至月经前出现，月经来潮后减轻或消失，呈周期性，为本病特征，此点重要）；经前焦虑障碍（PMDD）为其严重形式，约占5~8%，以情绪症状为主，程度重，影响社会功能。患者1年来于月经前1~2周出现以下症状：情绪症状（烦躁、易怒，为最常见及核心症状；情绪波动；焦虑、紧张；抑郁、悲伤、情绪低落；哭泣；失眠）、躯体症状（乳房胀痛，常见；腹胀、水肿，因水钠潴留所致；头痛；疲劳；食欲增加，嗜甜食；体重增加（水肿）；痤疮；关节及肌肉疼痛）、行为改变（注意力下降、工作效率降低、社交回避、对日常活动兴趣减退）。需评估严重程度：轻度者影响小，中重度者影响工作及生活，需治疗；经前焦虑障碍者情绪症状严重，可有烦躁、抑郁、愤怒，应评估有无自伤意念，此点重要。本病于月经后症状完全消失，呈周期性，为诊断关键，需连续2~3个周期行症状日记记录。需鉴别经期加重的基础疾病（偏头痛、肠易激综合征、抑郁及焦虑障碍于月经期加重，应注意区别并相应治疗）、围绝经期及甲状腺疾病。诱因包括压力及生活事件、遗传因素、年龄30~40岁、产后史。症状日记（连续记录2~3个月经周期，以确认周期性规律，为诊断的核心工具，重要）。今日来我院妇科或精神科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP114/72mmHg。乳房：胀痛，可及结节（乳腺增生）；腹部胀满；轻度水肿；测量体重；甲状腺检查；全身及妇科检查（排除器质性病变）；精神状态评估（评估情绪、抑郁及焦虑，并评估有无自伤意念，此点重要）；记录月经史。","辅助检查":"【必做】经前期症状日记（为核心检查，连续2~3个周期记录，症状于黄体期出现、经期缓解或消失，呈周期性规律，为诊断核心，此点重要，并用于与其他情绪及躯体障碍鉴别）、甲状腺功能（甲减或甲亢可模拟经前期综合征症状，应排除）、血常规（贫血可致乏力）、妇科超声（排除器质性病变）、抑郁及焦虑量表（评估情绪障碍共病，经前焦虑障碍需评估PHQ-9及GAD-7）、经前焦虑障碍专用量表。","初步诊断":"1. 经前期综合征（PMS，黄体期周期性出现情绪及躯体症状，经症状日记确认≥2个周期，程度为轻度、中度或重度；需评估经前焦虑障碍（PMDD）；与经期加重的情绪及躯体疾病鉴别）\n（注：治疗依严重程度而定，轻度者予生活方式调整，中重度者予药物治疗。①生活方式（适用于轻度者，为基础治疗）：规律有氧运动（改善情绪及水钠潴留）、饮食调整（低盐（减轻水肿）、减少咖啡因、酒精及糖类摄入、增加复合碳水化合物以提升血清素水平）、补充钙剂1200mg/d（可改善经前期综合征症状，有证据支持，此点重要）、补充镁及维生素B6（辅助）、保证充足睡眠、压力管理（放松训练、正念、瑜伽）、记录症状日记以利管理。②心理及行为治疗：认知行为疗法（有助于情绪管理及改善应对，有效）。③药物治疗（中重度者）：SSRI类选择性5-羟色胺再摄取抑制剂为一线（如艾司西酞普兰、舍曲林，可连续服用或仅于黄体期用药（月经前14天用至经期停），对情绪症状改善显著，有效且重要，经前焦虑障碍者SSRI为一线，尤须使用）、口服避孕药（连续或延长周期服用，抑制排卵、稳定激素水平以改善症状；含屈螺酮的复方口服避孕药已获批准用于治疗经前焦虑障碍，因含利尿成分可改善水肿，为重要选择）、利尿剂（螺内酯，用于水肿、腹胀等水钠潴留明显者）、非甾体抗炎药（用于疼痛及头痛）、GnRH激动剂（用于严重顽固病例，通过药物性卵巢抑制，但有绝经样副作用，需加用反向添加疗法，应评估，极少使用）。④随访：治疗前后以症状日记按周期评估疗效、症状严重程度改善后调整药物、经前焦虑障碍者评估自伤意念并保障安全，必要时转精神科，此点重要、计划妊娠者停用复方口服避孕药并评估、与共病抑郁鉴别（全年持续有症状者需持续治疗，转精神科）。妇科及精神科处理要点：以日记确诊，轻度者调整生活方式、补钙及运动；中重度者用SSRI或含屈螺酮的复方口服避孕药；经前焦虑障碍需评估自伤风险，甚为重要。","处理方案":"【药物治疗】\n1. 首选选择性5-羟色胺再摄取抑制剂（SSRIs）：氟西汀20mg qd，自月经周期第14天（黄体期）开始口服，连续服至月经来潮日，连用2-3个月经周期；症状严重者亦可全周期服用。\n2. 复方短效口服避孕药：炔雌醇屈螺酮片（优思明）1片 qd，自月经周期第1天起连服21天，停药7天为一周期，连用3-6个月经周期，可显著改善情绪及躯体症状。\n3. 对症治疗：以乳房胀痛、头痛等躯体症状为主者，加用布洛芬缓释胶囊0.3g bid，疼痛时服用；辅以维生素B6片20mg tid，自经前期开始服至月经来潮。\n\n【一般治疗及生活指导】\n1. 心理疏导，保持情绪稳定，规律作息，保证每日睡眠7-8小时，避免熬夜及精神紧张。\n2. 经前期低盐低脂饮食，限制咖啡因、酒精及辛辣刺激食物摄入；适量补充钙剂（碳酸钙D3片600mg qd）及富含维生素B6食物（如香蕉、鱼类）。\n3. 坚持适度有氧运动（快走、瑜伽、慢跑等）每周3-5次、每次30分钟，有助于缓解焦虑、腹胀、乏力等不适。\n4. 经前期避免过劳和剧烈活动，注意保暖，避免受凉；鼓励家属理解与支持，减少冲突诱因。\n\n【随诊要求】\n用药2-4周后复诊评估疗效及药物不良反应；若症状改善不明显或加重，及时复诊调整治疗方案；症状持续3个以上月经周期仍无缓解者，建议转诊妇科或心理科进一步评估。若出现明显情绪低落加重、自伤或自杀观念，须立即就近就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1096,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"288b9cae35f668717559f96d8d86f9183b4158b4eaa3d53126bb239bf9ba83b6","pinyin":"jingqianqizonghezheng","initials":"jqqzhz","setting":"out","caseName":"门诊病历964","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历964",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-022b738a4c4fd92cd559","key":"v1-c9ccc21dfe2a3058|templates-022b738a4c4fd92cd559","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"绝经后出血","category":"门诊病历模板","raw":{"name":"绝经后出血","category":"门诊病历模板","case":{"case_name":"门诊病历965","templates":{"主诉":"绝经后阴道出血1月","现病史":"患者绝经后（停经≥12个月后）出现阴道出血。年龄因素：绝经早期（围绝经期过渡期）的不规律出血属正常现象，但绝经≥1年后的出血均需评估。病因方面：①良性病因包括萎缩性阴道炎（阴道黏膜萎缩变脆而出血，最为常见）、子宫内膜或宫颈息肉、萎缩性子宫内膜炎、宫颈柱状上皮异位或息肉、激素替代治疗（HRT方案不当所致突破性出血）、他莫昔芬（乳腺癌治疗中对内膜的刺激，可致内膜增生、息肉及出血）；②恶性病因包括子宫内膜癌（最重要，绝经后出血者约10~15%为内膜癌，年龄越大风险越高，占绝经后出血恶性病因的首位）、宫颈癌（多表现为接触性出血）、子宫肉瘤、阴道或外阴癌（较少见）；③医源性病因包括宫内节育器残留。同时需了解出血量（点滴状、褐色或大量）、出血为单次或反复发作。还需询问有无激素替代使用情况（方案及依从性）、他莫昔芬用药史（乳腺癌史）、肥胖及糖尿病、高血压（为内膜癌高危因素三联征，甚为重要）、无排卵史（长期雌激素刺激子宫内膜，既往月经不规则）、息肉史、家族史（结直肠癌或内膜癌、Lynch林奇综合征）、抗凝药使用情况，并分辨出血来源（阴道、宫颈或宫腔）。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。妇科检查：窥器检查见阴道黏膜萎缩变脆、有出血点，符合阴道炎表现；宫颈可见息肉、糜烂等病变，有触血；观察出血来源，可见宫腔血性分泌物。双合诊：子宫大小及质地，若增大需评估内膜癌；附件有无包块（卵巢肿瘤）；宫颈有无举痛。腹部检查有无腹块。全身检查注意有无肥胖、乳腺情况（是否用他莫昔芬或HRT）、有无贫血（失血所致）。","辅助检查":"【必做】妊娠试验（虽罕见，但围绝经期可迟发排卵，需排除）、盆腔超声（为核心检查）：子宫内膜厚度，绝经后<4~5mm（萎缩变薄，属正常），增厚（>4~5mm）为异常，需进一步行内膜评估，甚为重要，经阴道超声更敏感；并观察宫腔有无占位、息肉或积液，子宫有无肌瘤，附件情况；宫颈细胞学（TCT，排除宫颈病变）、HPV检测（出血者筛查）。【确诊】子宫内膜评估（核心）：诊断性刮宫或宫腔镜+内膜活检，指征为绝经后出血且内膜>4~5mm，必须取得内膜组织行组织学病理检查，以排除内膜癌或内膜增生，甚为重要，为金标准；宫腔镜可直视、定位病变，行息肉或内膜切除并活检，准确度高；门诊内膜取样（Pipelle细管吸引内膜组织）。若内膜薄（<4~5mm）而出血，多为萎缩性改变或阴道炎所致，可观察，但反复出血者仍需评估，甚为重要。【其他】血常规（了解贫血）、影像学检查（如疑内膜癌，术前分期必要时行MRI评估）、他莫昔芬用药者的内膜超声随访、凝血功能检查（抗凝治疗者）。","初步诊断":"1. 绝经后出血（绝经≥1年阴道出血，需排除子宫内膜癌（约10~15%）。病因包括萎缩性阴道炎、息肉、内膜增生、内膜癌等。需评估内膜厚度（超声）及明确内膜组织学评估指征）\n（注：治疗原则为病因诊断与恶性病变的早期诊断和治疗）：①评估为先（超声测内膜厚度为核心。内膜<4~5mm且萎缩者多为良性，出血多来自阴道或宫颈，可局部处理；内膜增厚（>4~5mm）者应行宫腔镜或刮宫取内膜活检，行组织学确诊，甚为重要，勿经验性用药掩盖病情）；②良性病因（萎缩性阴道炎：局部雌激素软膏、抗炎，见老年性阴道炎；内膜或宫颈息肉：宫腔镜或阴道镜切除并送病理；萎缩性子宫内膜炎：抗感染并局部雌激素；激素替代相关：调整方案（评估雌、孕激素比例及用药方式），并行绝经管理咨询；他莫昔芬相关：内膜增厚或息肉者行宫腔镜评估，并与肿瘤科讨论继续用药或以芳香化酶抑制剂替代，权衡利弊）；③恶性病变（子宫内膜癌：组织学确诊后分期，行手术治疗（全子宫+双附件切除及分期手术，淋巴结清扫评估），依分期及高危因素辅以放疗或化疗，预后方面早期内膜癌5年生存率>90%，故早诊断甚为重要，绝经后出血及时就医是关键；宫颈癌或肉瘤行相应治疗（见专项），并转妇科肿瘤专科）；④随访（良性病因治疗后：出血停止后复查超声观察内膜；复发出血者再次评估，行宫腔镜；恶性病变术后由肿瘤科随访复查；子宫内膜增生尤其不典型者，予孕激素或手术管理，预防癌变，见内膜增生章节；筛查教育：绝经后任何一次出血均需评估，勿拖延，甚为重要，且绝经后妇女应定期行妇科检查及超声）；妇科超声+内膜活检排除恶性，良性病因予治疗并随访，甚为重要。","处理方案":"【药物治疗】\n1. 萎缩性阴道炎所致点滴出血：普罗雌烯阴道用软膏（更宝芬）1g 阴道上药，每日1次，连用7-10天；或雌三醇软膏（欧维婷）0.5g 阴道上药，每日1次×2周，后改每周2次维持。\n2. 子宫内膜增生（无不典型增生）逆转治疗：醋酸甲羟孕酮片10mg 口服，每日1次，连用12-14天（月经周期后半期），每周期1次，连用3-6个周期；或地屈孕酮片10mg 口服，每日2次，同周期后半期方案。\n3. 出血量稍多且无血栓禁忌者：氨甲环酸片0.5g 口服，每日3次×3天止血，同时监测血红蛋白。\n4. 合并阴道混合感染：甲硝唑栓0.2g 塞阴道，每晚1次×7天（须排除滴虫、真菌感染后使用）。\n注：本方案适用于排除子宫内膜癌等恶性病变、经阴道超声及子宫内膜活检明确为良性疾病者；内膜增厚（>4-5mm）或持续出血者首选宫腔镜检查+子宫内膜活检明确诊断，不推荐盲目止血掩盖病情。\n【一般治疗及生活指导】\n1. 合理膳食：低脂、高蛋白、富含钙及维生素D饮食（牛奶、豆制品、绿叶蔬菜），每日钙摄入800-1000mg；戒烟限酒，避免服用含雌激素的保健品、蜂王浆及不明成分中成药。\n2. 适度运动：坚持快走、瑜伽等有氧运动，每周≥3次、每次30分钟，控制体重，改善代谢并维持骨密度。\n3. 注意外阴卫生：每日温水清洗外阴、保持干燥，穿棉质宽松内裤；出血停止并经复查明确诊断前避免盆浴、游泳及性生活。\n4. 避免劳累、熬夜及精神紧张，保证充足睡眠；若出血量增多或伴腹痛、发热，及时就诊，勿自行使用止血或激素类药物。\n【随诊要求】\n1. 行宫腔镜或子宫内膜活检者：3-7天内复诊领取病理报告，明确病变性质。\n2. 良性病变（萎缩性阴道炎/子宫内膜增生）者：1-3个月复查经阴道超声观察内膜厚度；激素治疗者按周期随诊，用药3-6个周期后复评疗效，评估是否停药或调整方案。\n3. 治疗期间若再次出血、出血量增多、伴腹痛或消瘦等异常，随时复诊。\n4. 病理确诊恶性病变或内膜不典型增生者，立即转妇科肿瘤专科进一步手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1097,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8d92e7013ab6c504357c17a0cdc1d8345abaef7e1fcd1d80bb906bc74152698d","pinyin":"juejinghouchuxie","initials":"jjhcx","setting":"out","caseName":"门诊病历965","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历965",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2c26e450ce308218aa8e","key":"v1-c9ccc21dfe2a3058|templates-2c26e450ce308218aa8e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"不孕症","category":"门诊病历模板","raw":{"name":"不孕症","category":"门诊病历模板","case":{"case_name":"门诊病历966","templates":{"主诉":"未避孕未孕1年","现病史":"夫妻规律无避孕性生活≥12个月（女性≥35岁者为≥6个月）未孕（不孕定义为原发：从未妊娠；或继发：曾妊娠后未孕。年龄方面女性>35岁生育力下降，评估应提前，男性>40岁亦需注意）。于试孕12个月未孕，评估如下：女方因素包括排卵情况（月经周期规律，28±7天者多有排卵；稀发或闭经者无排卵，多见于多囊卵巢、卵巢因素、高泌乳素血症、甲状腺功能减退）、年龄（卵巢储备下降、卵子质量降低）、盆腔因素（输卵管因素，如盆腔炎、宫外孕、流产或腹部手术致输卵管阻塞，甚为重要，约占30~40%；子宫内膜异位症，常有痛经及不孕）、子宫因素（肌瘤、内膜息肉或粘连）、宫颈因素。男方因素约占40%，包括精液异常（少精、弱精、无精）、性功能障碍、隐睾、精索静脉曲张、腮腺炎睾丸炎史。双方因素包括免疫性抗精子抗体。不明原因约占20%。生活方式方面：体重（肥胖或过瘦均影响排卵）、吸烟、饮酒、咖啡因、精神压力、过度运动、性交频率与时机（排卵期隔日同房）、润滑剂（有杀精作用应避免）、药物（影响精子或排卵）。既往史需了解孕产史、人工流产、宫外孕、手术史（腹部、盆腔或阴囊）、盆腔炎、性病史、化疗或放疗史、腮腺炎史、甲状腺或糖尿病等慢性病。今日来我院生殖科或妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg，并测体重指数（BMI）。女性检查：发育情况，有无多毛或痤疮（提示多囊）、溢乳（提示高泌乳素）、甲状腺异常；妇科检查子宫、附件有无包块或压痛（提示盆腔炎）、阴道及宫颈情况、卵巢情况。男性检查：睾丸大小、有无隐睾，附睾及精索有无静脉曲张，阴茎及尿道，乳房发育有无异常，第二性征，以及全身慢性病相关体征。","辅助检查":"【必做】男方精液分析（为核心项目，首先进行且简单，禁欲2~7天后查精液常规，包括精子浓度、活力、形态，按WHO标准判读，异常者复查）、性激素（异常者提示低促性腺激素）、超声（精索静脉曲张、睾丸）、遗传学检查（无精者查染色体或基因）。女方排卵评估：基础体温（双相提示有排卵）、排卵试纸（测黄体生成素峰）、黄体期孕酮（月经前7天>16nmol/L提示有排卵）、月经周期情况；性激素六项（月经第2~4天查促卵泡激素、黄体生成素、雌二醇，评估卵巢储备）、抗缪勒管激素（评估卵巢储备）、甲状腺功能、催乳素；经阴道超声（卵泡监测以判断排卵、卵巢有无多囊、子宫及内膜有无息肉或肌瘤）；输卵管通畅度检查（子宫输卵管造影，经碘油X线检查，为评估通畅度的金标准，可检出通而不畅或阻塞，甚为重要；超声造影为新方法；宫腔镜或腹腔镜可确诊宫腔及盆腔因素并具治疗指征，诊断不明确时采用）；衣原体或淋病筛查（感染可致输卵管病变）。【其他】男方抗精子抗体（阳性较少，意义有限）、双方遗传咨询（反复流产或异常者）。","初步诊断":"1. 不孕症（分型待定：原发或继发；试孕12个月；女方因素为排卵、输卵管、盆腔或年龄因素，男方因素为精液异常，或为双方因素，或为不明原因，需评估年龄及生育力）\n（注：治疗以病因为导向、分级进行，女方年龄为关键，高龄应尽早行辅助生殖）：①男方因素（精索静脉曲张行手术、激素异常予治疗、严重少精或无精行辅助生殖（卵胞浆内单精子注射，即第二代体外受精）、不可治的无精者可行供精、并调整生活方式，戒烟酒，避免高温环境如桑拿及紧身裤）；②排卵障碍（促排卵：克罗米芬或来曲唑口服为首选，监测卵泡并指导同房；二甲双胍用于多囊伴胰岛素抵抗者；促性腺激素注射用促卵泡激素，用于口服药物无效者；多囊患者减重；高泌乳素者用溴隐亭；甲状腺功能减退者补充甲状腺素）；③输卵管或盆腔因素（输卵管阻塞：介入再通，适用于近端阻塞；腹腔镜下行粘连松解或造口；输卵管积水：切除后行体外受精可提高成功率；内异症：腹腔镜切除病灶，术后自然妊娠窗口为6~12个月，其后可行体外受精）；④不明原因或轻中度因素（期待治疗，年轻者可观察后再试；促排卵+宫腔内人工授精，夫精人工授精3个周期未孕者转体外受精）；⑤辅助生殖（体外受精或卵胞浆内单精子注射，即体外受精、体外受精-胚胎移植，指征为输卵管阻塞、严重男方因素、重度内异症、人工授精失败、>35岁高龄需缩短时间，甚为重要；体外受精成功率以活产率计，40岁前约40~50%/周期，随年龄下降；胚胎移植、冻胚移植、单胚移植以减少多胎）；卵子、胚胎或精子捐赠（用于卵巢衰竭或遗传病者）；遗传学筛查（遗传病者行植入前检测）；⑥生活方式（双方戒烟酒，体重保持正常，限制咖啡因，排卵期同房（隔日，排卵前）、放松减压，男性避免高温，女性备孕补充叶酸0.4mg以预防神经管缺陷，甚为重要）；⑦随访（评估疗程，按年龄及病因进展调整辅助生殖级别；妊娠后早期超声并转产科管理；未孕者按周期评估后再治疗；予心理支持，不孕所致焦虑与压力需重视并予咨询；反复失败者评估胚胎、着床及免疫因素，转诊生殖中心）；生殖科或妇科应夫妻同查，男方精液检查先行，输卵管造影，分级治疗，人工授精至体外受精，年龄为关键，甚为重要。","处理方案":"【药物治疗】\n1. 促排卵治疗：来曲唑片2.5mg qd，于月经周期第3～5天开始口服，连用5天；或枸橼酸氯米芬片50mg qd，于月经第3～5天起口服，连用5天（两者任选其一，须配合B超监测卵泡发育）。\n2. 黄体支持：地屈孕酮片10mg bid，于B超确认排卵后口服，连用10～14天；确认妊娠后遵医嘱继续用药至孕12周，停药需逐渐减量。\n3. 男方因素（弱精子症、少精子症等）：左卡尼汀口服溶液10ml bid，口服，连用3个月，可联合维生素E软胶囊100mg tid同服。\n4. 合并高泌乳素血症：溴隐亭片1.25mg qn起始，餐中口服，每3～5天递增1.25mg，至2.5mg bid维持，复查血PRL正常后逐渐减量至维持剂量。\n\n【一般治疗及生活指导】\n1. 生活方式：规律作息，保证充足睡眠，避免熬夜；戒烟、限酒（男方建议戒烟至少3个月），避免被动吸烟及咖啡因过量摄入。\n2. 饮食与体重：均衡营养，多食优质蛋白、新鲜蔬果及富含锌、硒的食物；控制体重指数（BMI）于18.5～24kg/m²，超重/肥胖者减重5%～10%，消瘦者适当增重，均有助于恢复排卵及精子质量。\n3. 同房指导：月经规律者于排卵前1～2天及排卵日隔日同房1次，可联合排卵试纸或基础体温监测排卵以提高受孕概率。\n4. 禁忌：男方避免桑拿、泡温泉、久坐、穿紧身裤等高温环境；双方避免接触放射线、重金属及有毒化学物；备孕期间避免自行服用影响生育的药物。\n\n【随诊要求】\n1. 促排卵周期自月经第10～12天起行阴道B超监测卵泡发育，隔日或每日监测至成熟卵泡排出，据此指导同房时间及黄体支持用药。\n2. 每1～3个月经周期复诊评估疗效并调整方案；<35岁连续促排卵6个周期或≥35岁促排卵3个周期未孕者，建议转诊生殖医学中心行输卵管造影、宫腔镜等进一步检查及辅助生殖咨询。\n3. 复诊时携带月经周期记录、基础体温表及既往检查报告；用药期间出现腹胀、腹痛、尿少等卵巢过度刺激症状或异常阴道出血，须及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1098,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1bf11792621d4afaf5bfa8d1bc94da290c56e28de9b875a86fd0d2c19b6294c2","pinyin":"buyunzheng","initials":"byz","setting":"out","caseName":"门诊病历966","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历966",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-50b71d2cf965e6bdbc2d","key":"v1-c9ccc21dfe2a3058|templates-50b71d2cf965e6bdbc2d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫内膜异位症","category":"门诊病历模板","raw":{"name":"子宫内膜异位症","category":"门诊病历模板","case":{"case_name":"门诊病历967","templates":{"主诉":"进行性痛经伴不孕3年","现病史":"患者为育龄期女性（25~45岁为常见发病年龄，不孕女性中约30~50%合并子宫内膜异位症，为重要提示），异位内膜可位于卵巢（巧克力囊肿，即内膜异位囊肿，最为常见）、盆腔腹膜（骶韧带、子宫直肠陷凹，为最常见种植部位）、子宫肌层（子宫腺肌症，属特殊类型，另见相关章节）、其他部位（膀胱、肠道、肺，较少见），引起周期性出血、炎症及粘连。患者于月经初潮后8年出现下列表现：痛经（继发性痛经，进行性加重为其特征，多于经前1~2天开始，经期第1~2天最重，持续整个经期，经后缓解，服止痛药无效或需逐渐加量）、深部性交痛（性交时深部疼痛，经前加重，与骶韧带异位灶有关）、不孕（约30~50%的患者合并不孕，与盆腔粘连、卵巢功能及免疫因素有关，为重要提示，行不孕相关检查时需注意发现内异症）、月经异常（经量增多、经期延长或经间期出血）、慢性盆腔痛（非经期下腹坠痛，经前明显）、急腹痛（巧克力囊肿破裂时可突发剧痛，属急症，需注意鉴别）、肠道及泌尿系统症状（经期便血、尿血、排便痛，提示肠道或膀胱异位）、腰骶痛。既往情况：痛经史（自初潮后渐进加重）、不孕治疗史（曾行相关检查及腹腔镜检查而诊断）、手术史（曾行卵巢囊肿剥除术，为巧克力囊肿，有复发可能；剖宫产或会阴侧切者切口内异症少见）；家族史（内异症有家族聚集倾向）。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。妇科检查（双合诊或三合诊）：子宫后倾固定（因粘连致活动受限，为骶韧带异位特征）、附件区可及囊性包块（巧克力囊肿，活动差，有压痛）、子宫直肠陷凹及骶韧带可及触痛结节（痛性结节为特征性体征，提示内异症异位灶），触痛明显；阴道后穹隆及宫颈可见紫蓝色结节（少见），宫颈举痛。腹部检查：需警惕急腹症，囊肿破裂时有压痛及反跳痛；可见贫血貌（因经量多、长期失血所致）；结合不孕相关评估。","辅助检查":"【必做】盆腔超声（可发现巧克力囊肿，为卵巢囊肿，囊内见细密点状回声，提示陈旧血，为特征性表现，囊壁厚，可呈多房；子宫腺肌症表现为子宫增大、肌层回声不均，另见相关章节；盆腔积液，用于初筛）。【血清】CA125（可升高，提示内异症处于活动期，但为非特异性指标，炎症或肿瘤时也可升高，用于辅助诊断及随访，治疗后可见下降）；癌抗原199。【确诊】腹腔镜（为金标准，可直视盆腔，见腹膜异位灶呈蓝紫色、黑色或火焰状，为典型表现，并可见卵巢巧克力囊肿及粘连；同时可行活检，经病理确诊，并行治疗，如病灶切除或烧灼，以及按rASRM评分分期）。【影像】MRI（用于深部内异症，评估骶韧带及直肠情况，为术前疑难病例的评估手段）；肠道或膀胱内异症可行相应内镜检查（必要时）。【其他】痛经的鉴别（需与原发性痛经，即无器质性病变者、盆腔炎后遗症、子宫腺肌症相鉴别）；妊娠试验（育龄期女性出现月经异常时用于排除妊娠）。","初步诊断":"1. 子宫内膜异位症（卵巢部位：巧克力囊肿；腹膜部位：骶韧带、子宫直肠陷凹；深部浸润，按rASRM评分分期，伴痛经及不孕，子宫腺肌症一并评估）\n（注：治疗原则为按症状、年龄及生育需求，采取药物加手术的长期管理）：①药物治疗（通过抑制卵巢功能使异位内膜萎缩，缓解痛经，但对不孕效果有限）：非甾体抗炎药（用于痛经对症治疗，为一线用药）、短效口服避孕药（连续或周期服用，抑制排卵，使内膜萎缩，缓解痛经，可长期使用，为一线选择）、孕激素（地诺孕素2mg qd，为专门用于内异症的药物，高效抑制病灶，缓解疼痛，可长期使用，副作用为出血，但较少）、左炔诺孕酮宫内缓释系统（曼月乐，抑制内膜，缓解痛经，兼有避孕作用，可长期使用，有效期5年）、GnRH激动剂（戈舍瑞林或亮丙瑞林，3.75mg每月，抑制卵巢功能，造成药物性绝经，使病灶萎缩，缓解症状，但用药3~6个月，需加用反加疗法以防骨质丢失及绝经症状，为重要措施，多用于术前或IVF前短期用药）、达那唑（属雄激素类，副作用较多，现已少用）；②手术（指征：药物治疗无效、囊肿较大（>4~5cm）、不孕（行腹腔镜病灶切除及囊肿剥除，可提高自然妊娠率，为重要手段）、深部内异症（疼痛明显者行病灶切除）；方式：腹腔镜（行囊肿剥除，应尽量保留卵巢，复发率较切开引流低）、腹膜病灶切除或烧灼、粘连松解；不孕者术后应尽早妊娠（因有复发可能，术后1年为最佳妊娠窗，为重要提示）；全子宫加双附件切除（用于重症或无生育要求者，可根治，但术后进入绝经状态，需考虑激素补充治疗并权衡利弊）；③不孕处理（腹腔镜病灶切除后可行自然试孕6~12个月，仍未孕者行辅助生殖，体外受精为内异症不孕的有效手段，尤其适用于输卵管受累或高龄者，经GnRH降调后行IVF可提高成功率）；④复发（较常见，术后5年复发率40~50%，可予药物治疗，长期使用地诺孕素、COC或曼月乐抑制病灶以防复发，术后长期用药为重要措施；复发囊肿经评估后可再次手术）；⑤疼痛管理（长期、阶梯式用药：NSAIDs→COC或孕激素→GnRH→手术，做到个体化；辅以神经阻滞及心理支持，用于慢性疼痛）；⑥随访（药物治疗者每3~6个月评估疼痛；术后定期超声监测复发，每6~12个月检查囊肿；有生育计划者关注妊娠；长期随访需注意内异症患者卵巢癌风险轻度升高，以透明细胞癌及子宫内膜样癌为主，虽少见，但应长期随访，囊肿性质变化时需警惕）；妇科长期管理应药物与手术结合，生育计划个体化，复发者需长期药物维持，甚为重要。","处理方案":"【药物治疗】\n1. 非甾体抗炎药止痛：布洛芬缓释胶囊0.3g bid，于经前1-2天开始服用至经期结束，用于缓解痛经及盆腔疼痛（有胃溃疡、出血倾向者慎用）。\n2. 口服短效避孕药：屈螺酮炔雌醇片（优思明）1片 qd，连服21天、停药7天，周期性服用至少6个月，适用于有避孕需求或症状较轻者，可抑制异位内膜生长、减轻疼痛。\n3. 孕激素：地诺孕素片10mg qd，持续口服6个月以上（长期管理可用至24个月），为子宫内膜异位症长期治疗一线药物，常见不良反应为不规则阴道出血。\n4. GnRH-a：醋酸亮丙瑞林微球3.75mg 皮下注射，每4周1次，疗程3-6个月；若用药超过3个月建议联合\"反加疗法\"（如替勃龙或雌孕激素）预防骨质丢失，用于中重度或术后巩固治疗。\n\n【一般治疗及生活指导】\n1. 休息与活动：经期适当休息，避免剧烈运动、重体力劳动及经期同房，以免加重盆腔充血与疼痛；疼痛明显时下腹热敷或温水泡脚缓解。\n2. 饮食：清淡低脂饮食，多食富含膳食纤维、维生素及Omega-3脂肪酸食物（如蔬菜、水果、深海鱼），避免辛辣刺激、生冷及咖啡因、酒精类饮品，减少炎症反应。\n3. 保暖与情绪：注意腹部及足部保暖，避免受凉；保持规律作息，避免熬夜，适度进行游泳、瑜伽等有氧运动，保持情绪稳定以减轻痛经。\n4. 生育与避孕：有生育要求者建议尽早妊娠，妊娠期异位内膜萎缩可缓解症状；无生育要求者建议采用口服避孕药或放置曼月乐环（左炔诺孕酮宫内缓释系统）长期管理，避免不必要的人工流产及宫腔操作。\n\n【随诊要求】\n1. 治疗期间每1-3个月复诊1次，评估痛经、疼痛缓解情况及不规则出血、药物不良反应，并监测肝肾功能、凝血功能。\n2. GnRH-a治疗超过3个月者，用药期间定期监测骨密度，及时加用反加疗法；口服避孕药及地诺孕素治疗者每年复查妇科B超及乳腺检查。\n3. 治疗结束后每3-6个月随访1次，复查妇科B超及血清CA125；若症状复发或进行性加重，需及时就诊评估是否再次干预或手术治疗。\n4. 治疗期间如出现剧烈腹痛、阴道大量出血、发热或疑似妊娠，应立即就近就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1099,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"48dae1fd88170564e75760a190f5e53320cfa444e6a86c5e5669367b7b461212","pinyin":"zigongneimoyiweizheng","initials":"zgnmywz","setting":"out","caseName":"门诊病历967","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历967",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-81355f75951691d4801a","key":"v1-c9ccc21dfe2a3058|templates-81355f75951691d4801a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫腺肌病","category":"门诊病历模板","raw":{"name":"子宫腺肌病","category":"门诊病历模板","case":{"case_name":"门诊病历968","templates":{"主诉":"进行性痛经伴月经量增多3年","现病史":"患者为育龄期女性（30~50岁，经产妇多见），病因与内膜基底层侵入肌层有关，并与分娩、刮宫、剖宫产相关，亦与雌激素有关；常合并子宫内膜异位症（约半数病例有卵巢巧克力囊肿并存，见内异症相关章节）。患者于月经初潮后8年出现：痛经（继发性，进行性加重为其特征，每年加重，止痛药逐渐无效），经前及经期疼痛（经期第1~2天最重，持续整个经期）、月经过多（经量增多，可见大血块，为最常见表现，与肌层受累范围相关）、经期延长、贫血（因经量多致慢性失血）、不孕（腺肌症可影响宫腔环境，进而影响着床）、性交痛（合并内异症时出现）、慢性盆腔痛、经间期点滴出血、子宫均匀增大（呈球形，质硬，活动度可）。鉴别诊断：子宫肌瘤（表现为局限性结节状回声）、子宫内膜异位症（有盆腔痛性结节）、子宫内膜病变（异常出血者需排除）、原发性痛经（无器质性病变，多见于青春期）；同时了解既往分娩及刮宫史；生育计划对治疗选择有影响。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。妇科检查：子宫均匀性增大（呈球形，如孕2~3月大小，质硬，有压痛，经期明显），活动好（无粘连、无局限）；附件区注意合并内异症及巧克力囊肿可能；宫颈未见异常；可见贫血貌（因经量多所致）；有痛经相关表现。","辅助检查":"【必做】盆腔超声（为核心检查）：子宫增大，肌层回声不均（呈粗糙颗粒状，为弥漫性病灶表现），肌壁可见小囊性无回声区（为出血灶，具特征性），病灶呈弥漫性或局限性（腺肌瘤为结节，其回声与肌瘤不同，无包膜），子宫前后壁不对称，后壁增厚；并可行彩色多普勒检查。CA125（可升高，无特异性，内异症及腺肌症均可升高）、血常规（可发现贫血）、卵巢评估（注意合并内异症）。【确诊】MRI（肌层结合带增厚>12mm为腺肌症特征，敏感性高，属非手术诊断的金标准，病灶在T2序列呈低信号）、宫腔镜（观察宫腔形态及内膜有无异常，以排除其他疾病）、诊断性刮宫或内膜活检（用于排除内膜病变，适用于有异常出血者）。【鉴别】与肌瘤经超声鉴别；子宫内膜异常出血者若年龄>40岁应行内膜活检以排除恶性病变，甚为重要。","初步诊断":"1. 子宫腺肌病（弥漫性，腺肌瘤为局灶性表现；子宫增大如孕周大小；伴痛经及月经过多、贫血；并子宫内膜异位症需评估；有生育需求）\n（注：治疗依症状、年龄及生育要求，选择药物或手术）：①药物治疗（用于缓解痛经及经量增多）：非甾体抗炎药（针对痛经对症治疗）、短效口服避孕药（可减少经量、缓解痛经，可长期使用）、孕激素（地诺孕素2mg qd，为专门治疗内异症及腺肌症的药物，可抑制病灶，疗效确切，可长期使用）、左炔诺孕酮宫内缓释系统（曼月乐，为核心治疗，通过局部释放孕激素显著减少经量（达90%），改善痛经，兼有避孕作用，有效期5年，无生育要求者为首选，为重要手段）、GnRH激动剂（戈舍瑞林或亮丙瑞林，可暂时造成闭经，使病灶萎缩，用于术前缩小子宫以做好手术准备，或用于IVF前及严重痛经者短期用药3~6个月，并加用反加疗法以防骨质丢失）、氨甲环酸（可减少经量）、止痛阶梯治疗；②手术（指征：症状严重且药物治疗无效、贫血难以纠正、无生育要求、年龄>40岁。子宫切除：全子宫切除可根治腺肌症，因病灶位于肌层，剔除困难，此为唯一彻底的治愈方法，但手术较大，属最后选择，需充分讨论；子宫腺肌症病灶剔除：可保留子宫，适用于有生育要求者，但病灶边界不清，剔除常不完全，复发率高，适用于局限性病灶或腺肌瘤；内膜消融：不适合腺肌症，因病灶位于深部肌层，效果差；血管栓塞：即子宫动脉栓塞，属可选方法，但现有数据有限）；③不孕（腺肌症合并不孕者可行辅助生殖，经GnRH激动剂降调后行体外受精，可提高着床率，属可选方案；病灶剔除可获部分改善；生育年龄影响治疗选择）；④随访（评估症状：治疗后痛经及经量的改善情况；纠正贫血，补充铁剂；曼月乐使用5年后需更换；长期药物治疗者需告知地诺孕素可致出血模式变化；术后行子宫切除标本的病理检查；保守治疗停药后复发常见，需长期管理）；妇科治疗以曼月乐为一线保守治疗；切除可根治，有生育要求者应保留子宫，手术须个体化；贫血应予纠正，甚为重要。","处理方案":"【药物治疗】\n1. 非甾体抗炎药缓解痛经：布洛芬缓释胶囊0.3g bid，月经来潮前1-2天开始口服，连用3-5天（或萘普生钠片0.275g tid，餐后服用）。\n2. 地诺孕素片10mg qd，每日固定时间口服，连续服用6个月，抑制子宫内膜异位病灶生长、缓解疼痛。\n3. 复方口服避孕药（无吸烟、血栓病史等禁忌者）：屈螺酮炔雌醇片1片 qd×21天，停药7天后续服下一周期，连用3-6个月。\n4. 症状重、子宫明显增大或合并不孕者：亮丙瑞林微球3.75mg皮下注射，每28天1次，连用3-6个月，待病灶萎缩后根据患者具体情况制定个体化方案序贯曼月乐（左炔诺孕酮宫内缓释系统）维持治疗。\n【一般治疗及生活指导】\n1. 经期适当休息、避免劳累及剧烈运动，注意腹部保暖，可局部热敷缓解痛经。\n2. 饮食清淡、富含铁及优质蛋白（瘦肉、动物肝脏、绿叶蔬菜），忌生冷、辛辣刺激食物；避免服用蜂王浆、雪蛤等含雌激素保健品，戒烟限酒。\n3. 经期禁性生活、盆浴及游泳，注意会阴卫生，勤换卫生巾，防止逆行感染。\n4. 规律作息，保持情绪稳定，避免精神紧张焦虑（不良情绪可加重痛经）；肥胖者适当控制体重。\n【随诊要求】\n1. 用药期间每3-6个月门诊复诊，复查妇科B超评估子宫大小、病灶及内膜变化，监测疗效。\n2. 痛经进行性加重、经量明显增多或出现非经期异常出血、贫血时，及时复诊，必要时复查血常规及CA125。\n3. 使用GnRH-a者，疗程结束前后评估低雌激素症状及骨密度，需按医嘱序贯维持治疗，不可擅自停药。\n4. 有生育要求者于停药后尽早门诊评估生育时机；无生育要求且症状复发者，评估曼月乐或手术治疗方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1100,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"05a583bf2f38634dd0cbbfc08ebed6bab80188edf28f55d10d87862e3214eae1","pinyin":"zigongxianjibing","initials":"zgxjb","setting":"out","caseName":"门诊病历968","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历968",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3a99e817da3b908f54fd","key":"v1-c9ccc21dfe2a3058|templates-3a99e817da3b908f54fd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫肉瘤","category":"门诊病历模板","raw":{"name":"子宫肉瘤","category":"门诊病历模板","case":{"case_name":"门诊病历969","templates":{"主诉":"反复下腹坠痛、阴道不规则流血1周","现病史":"患者1周前无明显诱因出现子宫肉瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复下腹坠痛、阴道不规则流血1周为主诉就诊，伴轻度乏力，首先完善血常规检查，了解有无贫血及其程度，评估异常子宫出血导致的失血情况；完善尿常规检查排除泌尿系统感染及损伤；完善白带常规检查，明确阴道分泌物病原体，排除合并生殖道感染；查宫颈TCT+HPV排除宫颈上皮内病变及高危型人乳头瘤病毒感染导致的出血；完善妇科超声检查，了解子宫肌层回声、宫腔内占位大小与血流信号，评估有无肌瘤变性、内膜增厚或肉瘤可能，是子宫肉瘤初步筛查的重要依据；乳腺超声作为妇科门诊常规基线检查，了解乳腺有无异常；完善性激素六项检查了解内分泌状态，评估异常出血是否与内分泌紊乱相关；完善血HCG检查排除妊娠相关疾病；查肿瘤标志物（必要时）包括CA125、LDH，辅助鉴别子宫肉瘤与子宫肌瘤，动态监测病情变化。因子宫肉瘤恶性程度较高，必要时建议完善盆腔MRI明确病变浸润深度及范围，并考虑宫腔镜或诊断性刮宫取组织病理及免疫组化，以明确诊断并指导手术范围。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 子宫肉瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 化疗（术后辅助或晚期一线，尤适用于平滑肌肉瘤）：吉西他滨 900mg/m² 静脉滴注 d1、d8，多西他赛 100mg/m² 静脉滴注 d8，21天为1周期，共4~6周期；每周期化疗前后复查血常规、肝肾功能，白细胞<3.0×10⁹/L或血小板<75×10⁹/L时推迟化疗，必要时予重组人粒细胞集落刺激因子150μg皮下注射升白细胞（化疗患者具备资质的医疗机构门诊日间化疗病房执行）。\n2. 靶向治疗（晚期或复发转移性子宫平滑肌肉瘤）：培唑帕尼 800mg 口服 每日1次，空腹服用，持续用药至疾病进展或出现不可耐受毒性；用药期间每2~4周监测血压、肝功能、尿蛋白。\n3. 内分泌治疗（低级别子宫内膜间质肉瘤或雌激素/孕激素受体阳性者）：来曲唑 2.5mg 口服 每日1次，或醋酸甲地孕酮 160mg 口服 每日1次，长期维持；用药期间每3~6个月复查肝肾功能及盆腔影像学。\n4. 对症支持治疗：疼痛者按NRS评分予盐酸羟考酮缓释片 10mg 口服 每12小时1次，依据疼痛评分逐步滴定；贫血者予琥珀酸亚铁 0.1g 口服 每日3次；化疗相关恶心呕吐者予昂丹司琼 8mg 口服 每日2次。\n\n【一般治疗及生活指导】\n1. 休息与活动：术后3个月内避免重体力劳动、剧烈运动及提举重物，避免用力排便、久蹲等增加腹压动作，咳嗽时按压腹部保护切口；循序渐进恢复日常活动，保证充足睡眠，术后早期床上行踝泵运动预防下肢静脉血栓。\n2. 饮食：进食高蛋白、高维生素、易消化饮食（瘦肉、鱼、蛋、奶、豆制品及新鲜蔬果），少食多餐，保证每日饮水1500~2000ml以促进代谢与创面愈合；化疗期间避免生冷、辛辣刺激食物，注意饮食卫生，预防感染。\n3. 禁忌：严禁自行服用雌激素类药物及含雌激素成分的保健品（如蜂王浆、雪蛤、大豆异黄酮类产品），以免刺激肿瘤生长；不得擅自使用激素替代治疗或服用成分不明的中药、偏方，围绝经期症状患者专科医师指导下处理。\n4. 心理与自我监测：保持情绪平稳、规律作息，戒烟限酒；居家每日监测体温，观察切口敷料有无渗液，若出现发热、切口异常渗液、异常阴道流血、腹痛腹胀、咳嗽咯血、下肢肿胀等及时就诊。\n\n【随诊要求】\n1. 术后第1~2年每3个月复诊1次，第3~5年每6个月复诊1次，5年后每年复诊1次，需终身随访。\n2. 每次复诊行妇科检查（含三合诊）、肿瘤标志物（CA125、HE4）及盆腔超声或CT/MRI；高危患者每6~12个月行胸部CT除外肺转移。\n3. 化疗或靶向治疗期间每2~4周复查血常规、肝肾功能、心电图及血压；内分泌治疗期间每3~6个月复查肝肾功能及盆腔影像学，动态评估疗效与毒性。\n4. 保留子宫或保留生育功能者（仅限极早期低危类型并经多学科团队评估）需更密切随访监测，完成生育后建议限期行根治性手术；任何异常症状随时就诊，不等待常规复诊时间。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1101,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cad0a663a18da90e1455e76fd8512b8487965e75e5951907237387e23ddf8ea6","pinyin":"zigongrouliu","initials":"zgrl","setting":"out","caseName":"门诊病历969","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历969",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3807ec42f94626717486","key":"v1-c9ccc21dfe2a3058|templates-3807ec42f94626717486","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"卵巢肿瘤","category":"门诊病历模板","raw":{"name":"卵巢肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历970","templates":{"主诉":"月经异常6月","现病史":"患者年龄不限，任何年龄均可发病，育龄期以功能性囊肿（滤泡囊肿或黄体囊肿）常见，多属良性，可自行消退；绝经后卵巢肿瘤更需警惕恶性，绝经后新发囊肿评估甚为重要。家族中有卵巢癌或乳腺癌史者，BRCA突变携带属遗传性卵巢癌高危，遗传咨询重要。生育及排卵因素：未产、不育、促排卵、多产、哺乳、口服避孕药等，其中哺乳及口服避孕药为保护因素。既往子宫内膜异位症者可有巧克力囊肿。CA125可作参考。患者于体检或超声发现，或出现症状后发现：无症状者多数为功能性或良性囊肿，超声偶然发现；下腹不适或胀，见于大囊肿压迫；腹部包块，见于大卵巢肿瘤；月经异常，因功能性囊肿影响周期；急腹症包括囊肿扭转（突发下腹剧痛、恶心呕吐，体位改变后发生蒂扭转，属急症，需手术以防卵巢坏死，甚为重要）、囊肿破裂（突发腹痛、腹腔出血、休克，属急症）、出血（黄体破裂所致急腹症）；内分泌表现见于颗粒细胞瘤（雌激素升高、性早熟或绝经后出血）、支持间质细胞瘤（雄激素升高、多毛）；压迫症状有尿频、便秘；恶性警示包括绝经后新发囊肿、囊实性或实性成分、囊壁厚、乳头及分隔、生长快、腹水、CA125升高、固定或盆腔结节、消瘦，均提示卵巢癌风险。卵巢癌被称为沉默杀手，早期无症状，发现晚（70%为晚期），常因腹胀、食欲差、消瘦、腹水就诊时已属晚期，高危人群需筛查（家族史、BRCA者监测），并涉及分期与治疗。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。腹部：包块（注意大小、活动度、囊实性），腹水征（移动性浊音，恶性常见），压痛（扭转或破裂时呈急腹症）。妇科：双合诊或三合诊检查附件（囊肿大小、囊壁光滑或结节、活动度（固定提示恶性）、子宫直肠窝（结节提示恶性种植）、压痛（扭转）、对侧卵巢）；全身检查：乳腺、淋巴结（锁骨上）、消瘦及恶病质。","辅助检查":"【必做】盆腔超声（为核心，观察附件包块（囊实性、壁厚薄及光滑、分隔或乳头（恶性征象）、大小、双侧）、腹水、多普勒血流）；肿瘤标志物（CA125（升高提示恶性，但非特异，子宫内膜异位症或盆腔炎可升高），绝经后女性CA125特异性较高，人附睾蛋白4（HE4）更为特异，ROMA指数（CA125与HE4联合评估恶性风险），甲胎蛋白及β-人绒毛膜促性腺激素（生殖细胞肿瘤在年轻女性中重要，如畸胎瘤、内胚窦瘤），抑制素B（颗粒细胞瘤），雌二醇及睾酮（功能性内分泌肿瘤））。【确诊】恶性评估行CT或MRI（附件包块恶性特征如实性强化、腹膜种植、腹水、转移，并评估分期）；手术病理（卵巢肿瘤行分期手术（全子宫及双附件切除、大网膜及阑尾切除、腹膜活检、淋巴结清扫，进行全面分期），病理区分良性、交界性或恶性（上皮性卵巢癌最常见，以浆液性为主））；遗传方面行BRCA检测（卵巢癌或乳腺癌家族史者行遗传咨询，甚为重要，PARP抑制剂靶向治疗适用于BRCA突变者）。【其他】妊娠试验（育龄期囊性包块）、胸片或CT（评估肺转移）、胃肠镜（Krukenberg瘤为胃转移至卵巢，少见）；鉴别诊断包括输卵管积水、盆腔炎性包块、带蒂子宫肌瘤。","初步诊断":"1. 卵巢肿瘤（具体性质待定：功能性囊肿、良性肿瘤（畸胎瘤、浆液性等）、交界性或恶性肿瘤（卵巢癌，待病理）；需评估大小及单双侧、囊实性及恶性征象、并发症（扭转或破裂）、CA125及HE4与遗传风险）\n（注：治疗依性质、年龄及生育要求而定：①功能性囊肿（滤泡囊肿或黄体囊肿，生育年龄可观察，多数可自行消退，1~2个月经周期后复查超声多可消退，不需处理；口服避孕药可抑制排卵、减少新囊肿形成；>5cm且持续不消者需手术评估）；②良性肿瘤（畸胎瘤、浆液性或黏液性囊腺瘤，行卵巢囊肿剥除，以保留卵巢组织，对年轻者尤为重要；或行附件切除，适用于绝经后或肿瘤较大者；标本送病理以确诊良性）；③并发症（扭转属急症，需手术复位以恢复血供、保留卵巢，若已坏死则切除，年轻者优先保留；破裂或出血可观察或手术，依出血量及休克情况决定）；④交界性或恶性（卵巢癌行手术分期或减瘤（全子宫及双附件、大网膜、阑尾、腹膜活检加淋巴结清扫，早期进行全面分期），晚期行肿瘤细胞减灭术（减瘤满意为残留<1cm，对预后重要）；化疗以紫杉醇加卡铂为一线，为卵巢癌标准化疗，共6个周期；靶向治疗包括贝伐珠单抗抗血管维持、PARP抑制剂（奥拉帕利或尼拉帕利），用于BRCA突变或铂敏感复发维持，甚为重要，需检测BRCA基因；复发者以CA125监测及影像随访；预后方面晚期卵巢癌5年生存率30~40%，早期>90%，早诊断虽难，但症状（腹胀、食欲下降）持续时及时就医检查很重要；遗传方面BRCA1/2携带者可行预防性切除（输卵管及卵巢）以降低风险，需咨询）；⑤随访（良性囊肿观察消退后定期妇科检查及超声，每年1次；术后依病理随访；恶性者由肿瘤科随访，CA125每3个月1次共2年，之后延长间隔）；健康教育（绝经后附件包块需警惕恶性，及时就医，勿拖延，甚为重要）；总体处理为妇科超声评估，功能性者观察，肿瘤者手术，卵巢癌行分期或减瘤加化疗，并重视遗传咨询。","处理方案":"【药物治疗】\n1. 抗肿瘤化学治疗（上皮性卵巢癌一线方案）：紫杉醇注射液175mg/m²静脉滴注3小时，联合卡铂（AUC 5）静脉滴注，第1天给药，每21天为1周期，共6周期（于门诊日间化疗执行，化疗前后常规止吐、水化及监测血常规）。\n2. 抗血管生成维持治疗（晚期高危或铂敏感复发者）：贝伐珠单抗15mg/kg静脉滴注，每3周1次，与化疗联用并序贯维持，累计最长22周期。\n3. 激素抑制治疗（子宫内膜异位囊肿/巧克力囊肿，术前缩瘤或术后防复发）：亮丙瑞林微球3.75mg皮下注射，每28天1次，疗程3～6个月。\n4. 抗感染治疗（囊肿合并感染、发热或盆腔炎性包块）：头孢呋辛酯片0.25g bid，连用5～7天；青霉素过敏者改左氧氟沙星片0.5g qd，连用5～7天。\n\n【一般治疗及生活指导】\n1. 休息与活动：日常可适度活动，但应避免剧烈运动、长时间骑车及提重物，防止肿瘤蒂扭转；囊肿直径≥5cm者尤需注意。\n2. 饮食：高蛋白、高维生素、易消化饮食，适量补充瘦肉、蛋奶及新鲜蔬果；避免辛辣、油腻、生冷刺激食物，戒烟限酒。\n3. 病情观察与自我监测：记录月经及腹痛情况；如出现突发单侧下腹剧痛、恶心呕吐（警惕蒂扭转），发热、腹痛（警惕感染或破裂），或短期内腹围增大、腹胀、消瘦（警惕恶变），须立即就诊。\n4. 心理与生活方式：保持情绪平稳、作息规律、避免熬夜；不擅自服用含雌激素成分的保健品或药物，围绝经期及高危人群定期妇科查体。\n\n【随诊要求】\n1. 良性卵巢囊肿（无手术指征）：每3～6个月复查妇科超声及CA125，连续2年无变化者可延长至每年1次。\n2. 术后患者：术后1个月复查；其后2年内每3个月、3～5年每6个月、5年以上每年1次，复查妇科双合诊、盆腔超声及CA125/HE4等肿瘤标志物。\n3. 化疗期间：每周期化疗前复查血常规、肝肾功能及肿瘤标志物，评估化疗反应与骨髓毒性；化疗结束后2年内每3个月、3～5年每6个月随访。\n4. 出现异常阴道出血、腹胀加重、腹痛、发热或腹部包块增大等异常，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1102,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"52ff07a8c50a2ffc7b6fde97cbaf35a024f75cf9f3f841d51757d2d4536a866b","pinyin":"luanchaozhongliu","initials":"lczl","setting":"out","caseName":"门诊病历970","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历970",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-756497cc7b61ae9b8e3c","key":"v1-c9ccc21dfe2a3058|templates-756497cc7b61ae9b8e3c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输卵管癌","category":"门诊病历模板","raw":{"name":"输卵管癌","category":"门诊病历模板","case":{"case_name":"门诊病历971","templates":{"主诉":"反复下腹隐痛、阴道排液1周","现病史":"患者1周前无明显诱因出现输卵管癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复下腹隐痛、阴道排液1周为主诉就诊，伴轻度乏力，首先完善血常规检查，了解有无贫血及感染血象；完善肝肾功能检查，为后续手术及化疗用药提供基线，排除肝肾功能不全；完善电解质检查，了解有无低钠、低钾等紊乱，评估营养与代谢状态；完善凝血功能检查，评估凝血状态，为手术安全性提供依据；完善肿瘤标志物检查，重点包括CA125、HE4、CA19-9、CEA，动态监测对输卵管癌诊断及疗效评估具有重要价值。影像学方面，完善妇科超声作为初筛，了解附件区包块、盆腔积液及输卵管形态；完善盆腔CT及MRI检查明确肿块范围、与周围组织关系及有无腹膜、淋巴结转移，是术前分期的主要依据；PET-CT（必要时）用于评估全身有无远处转移及复发灶。病理诊断方面，完善病理活检及免疫组化明确组织学类型，是确诊的金标准；完善基因检测（如BRCA1/2）指导靶向治疗及遗传咨询；骨髓穿刺仅在怀疑骨髓转移或需鉴别血液系统疾病时进行。建议尽早请妇科肿瘤专科会诊，制定手术及后续综合治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 输卵管癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 一线化疗（术后辅助化疗或晚期一线）：紫杉醇注射液175mg/m²+卡铂AUC 5～6，均于第1天静脉滴注，每3周1次，共6周期（注意紫杉醇前常规预处理：地塞米松、苯海拉明、西咪替丁，防过敏反应）。\n2. 不能耐受紫杉醇者：多西他赛注射液75mg/m²+卡铂AUC 5，第1天静脉滴注，每3周1次，共6周期（化疗前地塞米松8mg bid×3天预防水钠潴留及过敏）。\n3. 靶向维持治疗：贝伐珠单抗注射液15mg/kg，第1天静脉滴注，每3周1次，用于一线含铂化疗达到完全或部分缓解者，维持治疗至疾病进展或不可耐受毒性（有出血、血栓史者慎用）。\n4. 化疗支持治疗：帕洛诺司琼注射液0.25mg化疗前静脉滴注止吐；如出现Ⅱ度以上骨髓抑制，予重组人粒细胞集落刺激因子（G-CSF）5μg/kg皮下注射，每日1次，直至中性粒细胞恢复。\n【一般治疗及生活指导】\n1. 保证充足休息，避免劳累及熬夜；化疗期间注意保暖，避免受凉感冒，减少去人群密集场所，防感染。\n2. 加强营养：高蛋白、高维生素、易消化饮食（如鱼、蛋、瘦肉、新鲜蔬果），少量多餐；忌辛辣、生冷、油腻及腌制食品，戒烟限酒。\n3. 适度活动：化疗间期可进行散步等缓和的体力活动，术后3个月内避免剧烈运动、提重物及重体力劳动。\n4. 保持外阴清洁干燥，勤换内衣裤，禁止盆浴及性生活（治疗期间及术后恢复期），注意观察有无阴道异常排液或出血。\n【随诊要求】\n1. 初始治疗完成后：第1～2年每2～3个月复查1次，第3～5年每3～6个月复查1次，5年后每年1次，长期随访。\n2. 每次复查项目：妇科检查、肿瘤标志物（CA125、HE4）、盆腹腔超声；每年行胸腹部CT（必要时PET-CT）评估有无远处转移。\n3. 出现腹胀、腹痛、腹围增大、阴道异常出血或排液、发热、下肢水肿等不适，或复查CA125持续升高、影像学新发病灶时，应及时就诊，评估复发及后续治疗。\n4. 长期随访中注意化疗远期不良反应（神经毒性、肾功能、骨髓功能），定期复查血常规、肝肾功能及电解质。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1103,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bb81ae56965d7de0fc8dd3e0428ca8d30140dd7c90b700a33a48503092c3634c","pinyin":"shuluanguanai","initials":"slga","setting":"out","caseName":"门诊病历971","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历971",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-9a901f5cb57b44fe46e4","key":"v1-c9ccc21dfe2a3058|templates-9a901f5cb57b44fe46e4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"葡萄胎","category":"门诊病历模板","raw":{"name":"葡萄胎","category":"门诊病历模板","case":{"case_name":"门诊病历972","templates":{"主诉":"停经6周后阴道流血","现病史":"患者为葡萄胎妊娠，完全性葡萄胎染色体为父源双倍体、无胎儿、HCG极高，恶变风险15~20%；部分性葡萄胎为三倍体、可有胎儿成分，恶变风险低（<5%），孕早期多表现为流产。患者于停经3个月（10周）出现：阴道出血（停经6~8周后出现不规则暗红色出血，量多少不一、可反复，占90%以上，为最常见表现）、子宫异常增大（大于停经孕周，完全性葡萄胎因绒毛水肿、宫腔充满水泡致子宫增大快，可触及；部分性葡萄胎子宫可小于孕周）、妊娠剧吐（出现早、程度重，与HCG高有关）、腹痛（子宫胀痛，葡萄胎排出前或黄素化囊肿扭转时可呈急腹症）、子痫前期（孕早期（<20周）出现高血压、蛋白尿，为葡萄胎警示，正常妊娠不会这么早出现，甚为重要）、甲状腺功能亢进（HCG高有类TSH作用，可致心动过速，少见）、贫血（因出血所致）、黄素化囊肿（双侧卵巢受HCG刺激呈囊性增大，可扭转）、无胎心胎动（完全性葡萄胎无胎儿）；人绒毛膜促性腺激素显著升高，超过正常孕周水平，>10万mIU/ml为其特征；超声见宫腔内落雪状或蜂窝状改变、无胎囊及胎心，为完全性葡萄胎，部分性葡萄胎可有胎囊但异常；既往有葡萄胎史者再次葡萄胎风险高（1~2%），年龄<20岁或>40岁者风险高，另有流产或不孕史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R20次/分，BP135/85mmHg（血压监测，警惕子痫前期）。贫血貌（因出血所致）；子宫：注意大小（大于停经孕周，检查腹围及宫高并与孕周对比）、质软；附件：黄素化囊肿（双侧囊性包块，注意大小）；阴道：出血，可有组织物排出（水泡状葡萄样组织，为典型表现，应留取送病理）；腹部：压痛（见于排出或感染时）；全身：甲状腺及心动过速等甲亢征象（少见）、肺部（滋养细胞转移可致咳嗽、咯血，为晚期表现，需评估）。","辅助检查":"【必做】人绒毛膜促性腺激素：血HCG可显著升高（完全性葡萄胎常>10万mIU/ml），并需定量动态监测（为诊断及随访核心）；超声（经阴道检查宫腔，见蜂窝状或落雪状改变为葡萄胎特征，无胎囊及胎心见于完全性葡萄胎，部分性葡萄胎可及胎儿及异常水泡状胎盘，并可见黄素化囊肿）；血常规（评估贫血）、肝肾功能、甲状腺功能（HCG高者可合并甲亢，必要时评估）、凝血功能（清宫前）、胸片（肺转移为滋养细胞疾病初筛，清宫前应查，甚为重要，HCG高时肺转移可能，胸片列为常规）。【确诊】清宫组织病理（清宫后见绒毛水肿、滋养细胞增生即可确诊，并区分完全性或部分性，对分型及恶变风险评估甚为重要）。【随访】清宫后严密监测HCG以及时发现恶变（如侵蚀性葡萄胎或绒毛膜癌，需另行专项处理；HCG不降或上升提示恶变，需化疗，详见相关专项诊疗规范）。","初步诊断":"1. 葡萄胎（分型：完全性或部分性；血HCG>10万mIU/ml；并发症（妊娠剧吐、子痫前期、黄素化囊肿）；需行恶变风险评估）\n（注：治疗以清宫为核心，加术后HCG监测以防恶变：①清宫（确诊后尽快清宫，吸宫术为首选；葡萄胎子宫大，清宫术前需备血（因出血及子宫软、穿孔风险），缩宫素患者扩张宫颈后使用，以防将水泡挤入血管导致肺栓塞；Rh阴性者予抗D免疫球蛋白以抗Rh，预防致敏，甚为重要；组织送病理以确诊及分型；一次清宫多不需二次，除非超声提示残留，可考虑宫腔镜）；②高危因素（年龄>40岁、HCG极高（>10万）、子宫明显大于孕周、黄素化囊肿>6cm、清宫后HCG下降慢或持续不降者，恶变风险高，可行预防性化疗；预防性化疗对高危者仍有争议，多不常规使用，以随访监测为主，清宫彻底即可早期发现恶变，化疗效果良好）；③术后随访（核心是防恶变：血HCG于清宫后每周1次，至连续3次阴性后改为每月1次共6个月，之后每2个月1次共6个月，再每半年1次共1年，总随访至少1~2年（WHO建议HCG正常后随访6~12个月），因恶变多发生于1年内，随访为关键；随访异常者（HCG不降、呈平台、上升或再次升高）提示恶变，如侵蚀性葡萄胎，需化疗，甚为重要，勿漏诊；避孕方面，随访期间应严格避孕1~2年，以防再次妊娠混淆HCG，甚为重要，避孕方式可选避孕套或复方口服避孕药，宫内节育器暂缓放置（可致出血并混淆判断）；月经多于清宫后4~8周恢复）；④恶变处理（侵蚀性葡萄胎或绒毛膜癌需另行处理；HCG监测异常时应全面评估，行肺CT及头颅MRI以排查转移，并予化疗：低危者用甲氨蝶呤或放线菌素D单药，高危者用EMA-CO等联合方案；滋养细胞肿瘤对化疗敏感，治愈率高（>90%），即使已有转移亦然，甚为重要）；⑤再孕（随访期满且HCG正常者可再孕；再次葡萄胎风险1~2%，高于常人，早孕时应行超声及HCG检查，以早诊断，甚为重要）；总体处理为妇科清宫加HCG严格随访，防恶变、避孕，随访期满后再孕，甚为重要。","处理方案":"【药物治疗】\n1. 预防感染：头孢呋辛酯片 0.25g bid 口服×5天（青霉素过敏者改用阿奇霉素片 0.5g qd 口服×3天），清宫术后当日起服用。\n2. 促进子宫收缩复旧、减少术后出血：益母草颗粒 15g（1袋）bid 口服×7天。\n3. 纠正清宫失血所致贫血：琥珀酸亚铁片 0.1g bid 口服，连用至血红蛋白恢复正常后继续巩固2个月，可加服维生素C片 0.1g tid 促进铁吸收。\n4. 备孕前准备：叶酸片 0.4mg qd 口服，持续服用（建议于停用避孕措施前3个月开始）。\n【一般治疗及生活指导】\n1. 清宫术后全休2周，术后2-3个月内避免重体力劳动及剧烈运动；术后1个月内禁止性生活、盆浴及游泳，保持外阴清洁，防止逆行感染。\n2. 饮食以高蛋白、高维生素、富含铁质且易消化食物为主（如瘦肉、鱼、蛋、奶、动物肝脏、绿叶蔬菜），忌辛辣刺激及生冷饮食，多饮水。\n3. 严格避孕至少1年，推荐避孕套或复方口服避孕药，随访期间禁用宫内节育器，以免影响子宫复旧并掩盖异常出血。\n4. 术后少量阴道流血或血性分泌物属正常现象；若出血量多于月经量或伴腹痛、发热，应立即就诊。\n【随诊要求】\n1. 术后每周检测血β-hCG直至连续3次阴性，其后每月1次连测6个月，再每2个月1次连测6个月，总随访时间至少1年（高危葡萄胎或恶变者随访2年）。\n2. 每次随访同时记录月经恢复及阴道出血情况，注意有无咳嗽、咯血、头痛、呕吐、视物模糊等转移相关症状，出现异常及时就诊。\n3. 随访期间严格避孕至少1年，β-hCG连续阴性且月经恢复正常后方可考虑再次妊娠。\n4. 若β-hCG持续不降、下降缓慢或转阴后再次升高，应立即复诊行妇科B超及胸部X线检查，必要时收入院进一步化疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1104,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e7c92faa24fd99e2eaf430d7d2ff74990876c30eef41109cc23d177f7cee4922","pinyin":"putaotai","initials":"ptt","setting":"out","caseName":"门诊病历972","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历972",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2918b14324ade36344bb","key":"v1-c9ccc21dfe2a3058|templates-2918b14324ade36344bb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"侵蚀性葡萄胎","category":"门诊病历模板","raw":{"name":"侵蚀性葡萄胎","category":"门诊病历模板","case":{"case_name":"门诊病历973","templates":{"主诉":"清宫后阴道不规则流血3周","现病史":"患者（既往有葡萄胎清宫术后随访血HCG监测中发现的病史，或直接以现症表现就诊，完整病史详见葡萄胎相关记录；年龄及清宫时间结合病史）于葡萄胎清宫后3个月出现：阴道出血，表现为清宫后持续或间断不规则出血，或出血停止后再次出现；血HCG异常，表现为清宫后血HCG持续不降（平台期超过3周）或下降后再次升高，此为复发监测的核心项目，甚为重要。随访要求清宫后每周监测血HCG下降规律（一般于4~8周转为阴性），若血HCG不降或升高，应高度考虑侵蚀性葡萄胎并进一步评估。可伴有转移症状：侵蚀性葡萄胎局部浸润子宫肌层，可穿破子宫引起出血、腹痛等急症表现；肺转移可出现咳嗽、咯血、胸痛；阴道转移可见紫蓝色结节，破溃后出血；脑转移可出现头痛、抽搐等急症表现；亦可累及肝脏。此外可见子宫增大、复旧不良，腹痛，卵巢黄素化囊肿持续存在。辅助评估包括血HCG水平及其下降曲线、清宫病理（完全性葡萄胎或部分性葡萄胎，其中完全性葡萄胎恶变风险高）、转移灶评估以及既往化疗史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R20次/分，BP135/85mmHg。妇科检查：子宫增大、质软、有压痛、复旧不良；阴道可见出血并评估出血量，阴道壁可见转移结节（呈紫蓝色）；宫颈、附件区检查注意有无黄素化囊肿及其大小；腹部检查注意有无包块；肺部听诊注意有无啰音以评估肺转移；神经系统检查注意有无脑转移体征；注意有无贫血貌（与出血相关）；全身状况注意有无恶病质等转移晚期表现。","辅助检查":"【必做】血HCG（为核心项目，动态监测清宫后下降情况，评估是否持续处于平台期或升高，此为侵蚀性葡萄胎的警示指标，甚为重要）；妇科超声（观察子宫肌层有无局灶性不均回声侵蚀病灶，病灶血流丰富，彩色多普勒呈高流速、低阻型，为恶性滋养细胞肿瘤的特征性表现；同时观察子宫壁破坏及浆膜穿破情况、宫腔残留、黄素化囊肿）。【转移评估】胸部X线或CT（评估肺转移，肺转移最为常见，多呈结节状）；头颅MRI（评估脑转移，注意有无神经症状）；腹部CT或超声（评估肝转移）；盆腔MRI（评估肌层浸润深度）。【确诊】清宫病理（提示葡萄胎）；侵蚀性葡萄胎的临床诊断依据为血HCG不降或升高，结合影像学显示肌层浸润或远处转移；组织学诊断需手术标本证实绒毛侵入肌层，但多数病例依据临床即可诊断并开始化疗；血常规、肝肾功能（化疗前评估）；脑脊液HCG（用于脑转移评估）。","初步诊断":"1. 侵蚀性葡萄胎（葡萄胎清宫后血HCG持续不降或升高，伴子宫肌层浸润或转移（肺、阴道等），需行FIGO分期及预后评分以明确化疗指征）\n（注：治疗以化疗为核心，恶性滋养细胞肿瘤对化疗敏感，治愈率高（>90%，即使已有转移）：①化疗：单药方案用于低危病例（FIGO预后评分≤6分），可选用甲氨蝶呤或放线菌素D单药化疗，疗程至血HCG正常后再巩固2~3个疗程以防复发，甚为重要；联合化疗用于高危病例（评分≥7分或转移广泛），采用EMA-CO方案（依托泊苷+甲氨蝶呤+放线菌素D，联合环磷酰胺+长春新碱），疗程至血HCG正常后再行巩固；化疗期间需监测血常规、肝肾功能，及时处理毒性反应。②手术：子宫切除的指征为化疗耐药或顽固局灶病灶，或为大出血控制及子宫穿破急症处理；年轻、有保留生育要求者以化疗为主，手术仅在必要时施行；肺或脑转移病灶手术适用于大出血或耐药孤立病灶，需评估后决定；子宫穿破致大出血属急症，可行手术切除或介入栓塞止血。③转移灶处理：肺转移对化疗敏感，注意咯血的处理；脑转移采用化疗联合全脑放疗，或行鞘内化疗，脑水肿时予甘露醇脱水；阴道转移结节破溃出血时行填塞或切除。④随访：血HCG为关键指标，化疗后每周检测至正常，其后3周后改为每月1次，共12个月，之后每3~6个月1次，共1年，总随访2年，血HCG正常后可延长随访，以监测复发，甚为重要；注意避孕2年，化疗后防止妊娠混淆血HCG结果，这一点很重要；同时观察月经情况，化疗后卵巢功能多数可以恢复，化疗后应评估生育能力。⑤预后：侵蚀性葡萄胎化疗治愈率极高（>95%，低危病例单药治疗几乎达100%），早期诊断、规范化疗与随访甚为重要；本病属妇科肿瘤中对化疗敏感、治愈率高的病种，血HCG随访与避孕非常重要。","处理方案":"【药物治疗】\n1. 化学治疗（首选方案）：低危侵蚀性葡萄胎首选单药化疗。甲氨蝶呤（MTX）注射液0.4mg/(kg·d)，肌内注射，每日1次，连用5天为1个疗程，疗程间隔2周（间隔依血常规及血β-hCG恢复情况调整），疗程持续至血β-hCG连续3周正常后再巩固1～2个疗程。\n2. 替代方案（对MTX耐药或不能耐受者）：放线菌素D（更生霉素）注射液10～12μg/(kg·d)，加入5%葡萄糖注射液500ml静脉滴注，每日1次，连用5天为1个疗程，疗程间隔2周。\n3. 化疗支持用药：每疗程化疗前30分钟予昂丹司琼8mg口服或静脉注射止吐；化疗期间多饮水、每日补液量≥2000ml以促药物排泄；复查血常规提示白细胞＜3.0×10⁹/L或中性粒细胞＜1.5×10⁹/L时，予重组人粒细胞集落刺激因子150μg皮下注射，每日1次，直至血象恢复正常。\n【一般治疗及生活指导】\n1. 休息：阴道出血期间绝对卧床休息，减少下床活动；出血停止后仍需注意休息，避免劳累、剧烈运动及重体力劳动，保证充足睡眠。\n2. 饮食：予高蛋白、高维生素、含铁丰富饮食（瘦肉、蛋、奶、动物肝脏、绿叶蔬菜等）以纠正贫血；化疗期间禁服含叶酸的保健品或药物（MTX为叶酸拮抗剂，亚叶酸钙解救除外），并每日饮水2000ml以上。\n3. 卫生防护：保持外阴清洁干燥，勤换内裤及卫生护垫，禁盆浴、禁游泳；化疗期间及白细胞低下时避免去人群密集场所，注意保暖，防止呼吸道感染。\n4. 禁忌：治疗及随访期间严格避孕，推荐避孕套避孕至少1年（建议2年），禁止放置宫内节育器（易致子宫穿孔及混淆出血原因）；禁烟、禁酒。\n【随诊要求】\n1. 化疗期间每疗程前复查血常规、肝肾功能及血β-hCG，动态监测疗效与毒性反应。\n2. 化疗结束后随访：血β-hCG第1年每月复查1次，第2年每3个月1次，以后每半年至1年1次，共随访至少2年；有肺转移等高危因素者延长随访至5年。\n3. 每2～3个疗程复查盆腔超声及胸部X线（或CT），直至病灶完全消退；化疗后子宫内残留病灶者，按医嘱择期行子宫病灶切除术并继续随访。\n4. 随访期间出现阴道不规则出血、腹痛、咯血、胸痛、头痛、抽搐或视力异常等，须立即就诊，警惕远处转移及出血并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1105,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d8ddae3b8fd631f6655a4f058abbf603a676c5b9b1cc71b1263366d112f13033","pinyin":"qinshixingputaotai","initials":"qsxptt","setting":"out","caseName":"门诊病历973","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历973",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-29f875d1fdcc78bcff6a","key":"v1-c9ccc21dfe2a3058|templates-29f875d1fdcc78bcff6a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"绒毛膜癌","category":"门诊病历模板","raw":{"name":"绒毛膜癌","category":"门诊病历模板","case":{"case_name":"门诊病历974","templates":{"主诉":"妊娠终止后阴道不规则流血1月，伴咳嗽1周","现病史":"患者（继发于葡萄胎，此为最常见情况，约50%的绒毛膜癌发生于葡萄胎之后；或继发于流产、异位妊娠后，约占25%；或继发于足月妊娠后，约占25%，产后出现不规则出血应警惕；年龄、潜伏期（葡萄胎后数月至数年发病，足月产后则近期发病）及妊娠史结合病史）于葡萄胎后6个月出现：阴道出血，表现为产后、流产后或葡萄胎后持续不规则出血，此为最常见、最重要的首发症状，产后淋漓出血应警惕绒毛膜癌；血HCG升高，表现为妊娠终止后血HCG不降或升高，为核心诊断线索；转移症状包括肺转移（最常见，约占60%，可见咳嗽、咯血、胸痛、呼吸困难）、阴道转移（可见紫蓝色结节并出血）、脑转移（可见头痛、抽搐、偏瘫等急症表现，甚至颅内出血）、肝转移（可见上腹痛）、肾及消化道转移（较少见）；此外可见子宫增大、质软，腹痛，贫血，晚期出现恶病质，以及假孕反应（血HCG高所致乳腺胀痛、卵巢黄素化囊肿）。鉴别方面需考虑侵蚀性葡萄胎（绒毛膜癌无绒毛结构，恶性程度更高，但两者治疗相似，均对化疗敏感，同属妊娠滋养细胞肿瘤）、异位妊娠（表现为急腹症、早孕、血HCG升高）、不全流产，并注意既往有无葡萄胎妊娠史。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P88次/分，R20次/分，BP135/85mmHg。妇科检查：子宫增大、质软；阴道可见出血并评估出血量；阴道壁可见转移结节（呈紫蓝色，可破溃）；附件区注意有无囊肿。肺部听诊注意有无啰音以评估肺转移；神经系统检查注意有无脑转移体征（如局灶性体征或意识改变）；注意肝脏有无增大；腹部检查；注意有无贫血貌及恶病质表现。","辅助检查":"【必做】血HCG（为核心项目，可见显著升高，可>10万，用于动态监测、诊断及疗效评估）；超声（观察子宫肌层病灶，呈不均回声、血流丰富，并观察宫腔情况）；胸部X线或CT（评估肺转移，多呈结节状、棉絮样或球形，肺转移最常见，对分期很重要）；头颅MRI（评估脑转移）；腹部CT或超声（评估肝转移）；盆腔MRI（评估肌层浸润及穿破情况）。【确诊】病理检查（清宫或切除组织可见绒毛膜癌细胞，滋养细胞增生且无绒毛结构，可明确诊断）；但临床诊断依据血HCG升高结合转移影像学即可确诊并开始化疗，这一点很重要，组织学检查并非必须，除非存在风险；脑脊液HCG（用于脑转移评估，血与脑脊液HCG比值<60支持脑转移）。【评估】血常规、肝肾功能（化疗前评估）、血型（备血）、输血前传染病筛查。","初步诊断":"1. 绒毛膜癌（恶性妊娠滋养细胞肿瘤，葡萄胎或流产后血HCG显著升高，伴转移（肺、脑、肝等），需行FIGO分期及预后评分以明确化疗指征）\n（注：治疗以化疗为核心，绒毛膜癌对化疗高度敏感，即使已广泛转移，治愈率仍高（>90%，低危病例可达100%，高危病例达80%以上），这一点很重要，不可放弃治疗）：①化疗分层：低危病例（预后评分≤6分）采用单药甲氨蝶呤或放线菌素D，治愈率几乎达100%；高危病例（评分≥7分）采用联合化疗（EMA-CO方案或EMA-EP方案），治愈率80~90%；极高危病例（脑或肝转移、评分≥12分）需采用更强方案并加强支持治疗；疗程为血HCG正常后再巩固2~3个疗程，此为防复发的关键。②手术：作为辅助治疗，用于化疗耐药、孤立病灶，可行子宫切除（适用于无生育要求或大出血者）；肺转移耐药的孤立病灶可行肺叶切除；脑转移出血者可行手术减压。③转移灶处理：脑转移可行鞘内化疗（甲氨蝶呤）、全脑放疗，并以甘露醇脱水处理脑水肿症状，此为急症处理；肺转移大咯血可行支气管动脉栓塞，属急症处理；阴道转移出血可行填塞止血。④支持治疗：贫血者输血，预防感染，加强营养，处理化疗毒副反应（骨髓抑制、止吐等）。⑤随访：血HCG为核心指标，化疗后每周检测至正常，共3周，之后每月1次共12个月，再每3~6个月1次共1年，其后每年随访，总随访2~3年甚至更长；影像学随访观察转移病灶消退情况；复发时血HCG升高需再次治疗；注意避孕2年，防止妊娠混淆血HCG结果；观察月经及生育情况，化疗后卵巢功能多可恢复，多数可以生育，妊娠前应咨询（复发风险低，化疗后多可治愈），再孕后绒毛膜癌复发风险极低；本病属妇科肿瘤中对化疗敏感、治愈率高的病种，血HCG严格随访甚为重要。","处理方案":"【药物治疗】\n1. 首选化疗（低危，FIGO评分≤6分）单药：甲氨蝶呤（MTX）注射液1mg/kg（单次不超过50mg），肌肉注射，每日1次，连用5天为1疗程，间歇2周后重复；每疗程前后复查血β-hCG，直至连续3周正常后巩固1～2个疗程。\n2. 联合化疗（高危，FIGO评分≥7分）EMA-CO方案：依托泊苷100mg/m²静脉滴注每日1次+放线菌素D（更生霉素）0.5mg静脉滴注每日1次，第1、2天；甲氨蝶呤300mg/m²静脉滴注（12小时）并于结束后24小时起四氢叶酸钙15mg肌注解救，每6小时1次共4次，第1天；长春新碱1mg/m²静脉注射+环磷酰胺600mg/m²静脉滴注，第8天；每2周重复1疗程，疗程间监测血β-hCG直至连续3次正常后巩固2个疗程。\n3. 化疗对症支持：昂丹司琼8mg静脉注射，化疗前30分钟及化疗后每日2次，防治恶心呕吐；化疗后复查血常规，白细胞<3.0×10⁹/L或血小板<50×10⁹/L时暂停化疗，予重组人粒细胞集落刺激因子150μg皮下注射每日1次，待血象恢复后再继续。\n\n【一般治疗及生活指导】\n1. 充分休息，避免劳累及剧烈活动，阴道出血期间卧床休息、禁盆浴及性生活；保证每日睡眠7小时以上，保持情绪平稳。\n2. 加强营养，予高蛋白、高维生素、易消化饮食（鸡蛋、瘦肉、鱼类、新鲜蔬果），少量多餐，化疗恶心时注意补充水分，避免生冷、辛辣刺激食物。\n3. 化疗期间及化疗结束后至少1年内严格避孕，推荐避孕套屏障避孕，禁用宫内节育器及激素类避孕药，以免干扰血β-hCG监测并增加子宫出血风险。\n4. 密切观察阴道出血、腹痛、咯血、头痛及视力改变等症状，异常时立即就诊；化疗期间注意口腔卫生、勤洗手、避免去人群密集场所，预防感染。\n\n【随诊要求】\n1. 化疗期间每周复查血β-hCG直至连续3次正常；正常后1年内每月复查1次，第2年每2～3个月1次，此后每半年1次，至少随访5年。\n2. 定期行胸部X线/CT及盆腔超声检查，化疗结束后每3～6个月1次，持续至少2年，以监测肺、肝、脑等转移灶变化。\n3. 随访期间如出现不规则阴道流血、咯血、头痛、视力障碍或进行性消瘦，立即就诊；每次复诊须携带既往病历及化疗方案记录，由妇科肿瘤专科医师评估疗效并制定后续方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1106,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7dd97a463b68dcddf22a223c4572c80c9d0160a1a7d6e635665621cd8be187b6","pinyin":"rongmaomoai","initials":"rmma","setting":"out","caseName":"门诊病历974","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历974",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8a55b6066e56020d00c2","key":"v1-c9ccc21dfe2a3058|templates-8a55b6066e56020d00c2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫脱垂","category":"门诊病历模板","raw":{"name":"子宫脱垂","category":"门诊病历模板","case":{"case_name":"门诊病历975","templates":{"主诉":"阴道脱出肿物5年，伴腰骶坠胀2年","现病史":"患者存在多产或产伤（最常见为阴道分娩致盆底损伤，尤其产钳助产、巨大儿、多产）、绝经（雌激素水平低致盆底组织萎缩，可加重病情）、慢性腹压增高（慢性咳嗽（如慢支）、便秘（长期用力排便）、重体力劳动、肥胖）、盆底手术史等高危因素，于绝经后5年出现：阴道脱出物（自觉阴道口有物脱出，站立、用力、咳嗽后明显，平卧、休息后可回纳，属Ⅰ~Ⅱ度；不能回纳者属Ⅲ~Ⅳ度，可脱出阴道口外）、肿物（脱出后摩擦可致破溃、出血、分泌物增多）、腰骶部坠胀感（久站、劳累后加重，平卧后减轻）、排尿异常（压力性尿失禁，咳嗽大笑时漏尿；或排尿困难，因脱垂致尿道扭曲，可致尿潴留、反复感染）、排便异常（便秘、直肠膨出致排便困难，需手助）、性交不适、脱出物较大影响行走、脱垂需手还纳。分度依据POP-Q分期（国际盆腔器官脱垂定量，Ⅰ~Ⅳ度，依脱出最远处与处女膜关系）及临床分度（轻：阴道内；中：处女膜处；重：脱出阴道口外）。既往需询问绝经及手术史：子宫切除史（术后阴道穹隆脱垂少见）、盆底康复（Kegel训练是否做过）、激素替代治疗情况。今日来我院妇科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。妇科检查：取膀胱截石位，嘱患者屏气用力（Valsalva动作）使脱垂达最大程度后评估。阴道：前后壁膨出（膀胱膨出见于前壁；直肠膨出见于后壁）；子宫：记录脱垂程度，行POP-Q分期，测量Aa、Ba、C点等并记录；宫颈：可见糜烂，因脱出摩擦可致溃疡；会阴：陈旧性裂伤，评估盆底；盆底肌力：评估收缩并分级。排尿：压力试验（嘱患者咳嗽时观察有无漏尿，提示压力性尿失禁）、残余尿测定（导尿或超声，判断有无尿潴留）。直肠：指诊评估直肠膨出及排便情况。","辅助检查":"【必做】妇科检查（为核心项目，行POP-Q分期以明确分度）；【评估】残余尿测定（排尿困难或反复感染者提示尿潴留）、尿动力学检查（合并尿失禁或排尿障碍时评估压力性或急迫性尿失禁，指导治疗选择）、盆底超声或MRI（评估盆底结构及脱垂情况，疑难病例必要时）；【其他】宫颈细胞学（脱垂宫颈长期摩擦者需排除病变，应定期检查）、分泌物检查（糜烂感染者）、肾功能（严重尿潴留长期存在可影响上尿路，少见）。","初步诊断":"1. 盆腔器官脱垂：子宫脱垂（POP-QⅡ度），伴阴道前壁（膀胱膨出）、后壁（直肠膨出），合并压力性尿失禁或排尿障碍，需评估。\n（注：治疗依分度、症状、年龄及生育要求选择保守或手术：①保守治疗适用于轻中度、不愿手术或未完成生育者：盆底肌训练（Kegel训练为核心，主动收缩盆底肌，每日进行，坚持3~6个月可改善，对轻中度有效，甚为重要），加生物反馈或电刺激（盆底康复，可增强疗效）；子宫托（阴道子宫托支撑，适用于中重度保守治疗者，可自行取放，定期清洁防感染，适合不愿手术或手术禁忌者）；生活方式调整（避免提重物及慢性咳嗽，积极治咳嗽；防治便秘，通便、高纤维饮食；减重；雌激素，绝经后可局部用雌激素软膏改善盆底组织，作为辅助，不用系统激素）。②手术指征：重度（Ⅲ~Ⅳ度，脱出阴道口，影响生活）、保守治疗无效的症状性脱垂、无生育要求者。手术方式：阴道子宫切除加盆底重建（传统术式为子宫切除加阴道前后壁修补加骶韧带悬吊），或保留子宫行子宫悬吊术（年轻、保留生育者，近年倾向此术式）；盆底重建（网片，包括生物或合成网片，用于前盆腔重建，即TVM，可加强盆底，但网片有侵蚀、疼痛等并发症，FDA曾警告合成网片用于阴道存在争议，应谨慎、个体化）；骶骨固定术（顶端脱垂，用网片，经腹腔镜或开腹，效果好）；闭孔或经闭孔吊带（合并尿失禁时可同时处理）。术后需防复发：避免负重，控制咳嗽、便秘，坚持盆底训练。③尿失禁处理：合并压力性尿失禁者可与手术同时行吊带术（中段尿道吊带，即TVT或TOT，疗效好，常用），或保守治疗（盆底肌训练，适用于轻度）。④随访：保守治疗者用子宫托需定期随访、清洁；手术者术后随访恢复情况及脱垂复发（盆底重建术后复发率10~30%，需远期随访）、网片并发症监测；局部激素长期使用需随访。⑤预防：产前产后盆底训练（孕期Kegel训练，产后行盆底康复，对防脱垂重要，多产者尤其患者产后42天评估盆底）、避免产后过早从事重体力劳动、控制慢性咳嗽与便秘。建议妇科或盆底专科就诊，依分度个体化治疗。Kegel训练是基础，中重度者以手术及盆底重建为主，需防复发，甚为重要。","处理方案":"【药物治疗】\n1. 盆底支持组织改善用药（绝经后患者首选）：雌三醇软膏（欧维婷）0.5g 阴道涂布，qd×2周，之后改每周2次维持，疗程4-8周；或结合雌激素软膏（倍美力软膏）0.5g 阴道涂布 qd，连用3周停1周为1周期。用药前排除雌激素禁忌证（乳腺癌、子宫内膜癌病史、不明原因阴道出血等）。\n2. 中成药辅助治疗：补中益气丸（浓缩丸）8丸 tid 口服，4周为1疗程，适用于轻度脱垂及气虚下陷证候。\n3. 合并阴道黏膜溃疡、糜烂或感染时：甲硝唑栓 0.2g 阴道给药 qn×7天，同时用1:5000高锰酸钾溶液坐浴 bid×7天，待溃疡愈合后再行雌激素局部治疗。\n\n【一般治疗及生活指导】\n1. 避免一切增加腹压的行为：避免久站、久蹲、负重及提重物，积极治疗慢性咳嗽、便秘等诱因，保持大便通畅，如厕勿过度屏气用力。\n2. 盆底肌锻炼（Kegel运动）：每日3组，每组10-15次，每次持续收缩盆底肌5-10秒后放松，坚持3-6个月，可配合电刺激、生物反馈等物理康复治疗。\n3. 合理膳食：多食富含膳食纤维的蔬菜、水果及粗粮，保证充足饮水，戒烟限酒，控制体重，加强营养。\n4. 适当卧床休息，避免剧烈运动及性生活直至症状缓解；老年患者可配合使用子宫托，须每日取出清洗、定期更换，防止嵌顿及感染。\n\n【随诊要求】\n1. 用药及康复治疗2-4周后复诊，评估脱垂症状及阴道溃疡、感染情况，调整治疗方案。\n2. 此后每3-6个月门诊随访1次，行妇科检查评估脱垂分度变化及阴道黏膜状况；长期使用雌激素软膏者每年评估乳腺及子宫内膜安全性。\n3. 治疗期间若出现排尿困难、尿潴留、反复泌尿系感染、阴道出血或脱出物嵌顿、剧痛等，应立即就诊。\n4. 保守治疗3-6个月症状无改善或脱垂程度加重者，建议转诊行手术治疗评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1107,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5b25d2d7f95fb6198cd7e2d4d1ccbf07e0507772eb82acc3c63ddd54d3b4b357","pinyin":"zigongtuochui","initials":"zgtc","setting":"out","caseName":"门诊病历975","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历975",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-77c1d518d4c39023bafa","key":"v1-c9ccc21dfe2a3058|templates-77c1d518d4c39023bafa","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴道前后壁膨出","category":"门诊病历模板","raw":{"name":"阴道前后壁膨出","category":"门诊病历模板","case":{"case_name":"门诊病历976","templates":{"主诉":"阴道肿物脱出1周","现病史":"患者1周前无明显诱因出现阴道前后壁膨出相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴道肿物脱出1周为主诉，病程中逐渐加重并伴轻度乏力，需完善血常规检查排除感染、贫血所致乏力；患者盆底支持结构松弛，常合并膀胱膨出与排尿不尽，完善尿常规检查排除泌尿系感染；完善便常规检查排除消化道出血，为后续可能的盆底修补手术做好术前准备；患者拟行手术治疗且既往否认高血压、糖尿病、冠心病等慢性病史，完善心电图检查评估心脏基本情况，排除手术禁忌；完善肝肾功能检查了解肝肾代谢及储备功能，为麻醉用药与围手术期用药提供依据；完善血糖检查排除隐匿性糖尿病，避免术后切口愈合不良；完善血脂检查了解血脂水平，指导围手术期及长期血管风险管理；完善电解质检查排除因乏力所致的电解质紊乱；完善胸部X线片检查排除肺部感染及心肺合并症，评估麻醉耐受情况；完善腹部超声检查了解盆腹腔脏器情况，排除盆腔占位性病变，并协助判断有无肾积水等泌尿系统受压表现。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 阴道前后壁膨出\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 绝经后患者首选局部雌激素治疗：雌三醇软膏（欧维婷）0.5g 阴道给药 qn，连用2周后改为每周2次维持，或结合雌激素软膏（倍美力软膏）0.5g 阴道给药 qn×2周后每周1-2次维持，疗程2-3个月，促进阴道黏膜增厚、改善组织支持力。\n2. 合并萎缩性阴道炎或分泌物增多者：甲硝唑阴道泡腾片0.2g 阴道给药 qn×7天，症状缓解后停用，勿长期使用。\n3. 中老年患者气虚下陷者：补中益气丸6g po tid×4周，辅助提升盆底支持。\n4. 合并便秘者（后壁膨出常见）：乳果糖口服溶液10ml po qd-bid×2周，保持大便软化，避免用力排便加重膨出。\n\n【一般治疗及生活指导】\n1. 坚持盆底肌（Kegel）训练：收缩肛门及阴道括约肌，每次持续5-10秒后放松，10-15次/组，每日3-5组，长期坚持。\n2. 避免一切增加腹压的行为：避免久站、久蹲、提重物、慢性咳嗽、用力排便及屏气动作，肥胖者控制体重。\n3. 高纤维饮食：多食新鲜蔬菜、水果、粗粮，每日饮水1500-2000ml，保持大便通畅，忌辛辣刺激饮食。\n4. 适度活动，避免剧烈运动及重体力劳动；急性症状期避免性生活及阴道内器械操作。\n\n【随诊要求】\n1. 用药2-4周后复诊，评估阴道干涩、灼热等不适改善情况及阴道黏膜萎缩变化，调整雌激素用药方案。\n2. 每3-6个月定期妇科检查，评估膨出程度及有无进展，记录排尿、排便及下坠感变化。\n3. 如出现排尿困难、压力性尿失禁加重、排便梗阻感明显、阴道脱出物增大或摩擦出血，及时复诊。\n4. 保守治疗3-6个月效果不佳或症状进行性加重者，复诊评估转诊，考虑子宫托治疗或盆底重建手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1108,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5b3b5bd2ad6c29ae3b3350edbc2d1703a01c2e29426ae858926c06b1dd9cc51b","pinyin":"yindaoqianhoubipengchu","initials":"ydqhbpc","setting":"out","caseName":"门诊病历976","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历976",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8cb8feb3041d46e18d54","key":"v1-c9ccc21dfe2a3058|templates-8cb8feb3041d46e18d54","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"压力性尿失禁","category":"门诊病历模板","raw":{"name":"压力性尿失禁","category":"门诊病历模板","case":{"case_name":"门诊病历977","templates":{"主诉":"腹压增高时漏尿5年","现病史":"患者为女性（该病常见，尤其经产妇及绝经后女性），相关因素包括：分娩（阴道分娩可致盆底肌、筋膜、韧带损伤，多产、巨大儿、产钳助产者风险高）、绝经（雌激素水平低致尿道支持组织萎缩）、肥胖（腹压增高）、慢性咳嗽或便秘（长期腹压增高）、盆底手术或放疗史。于产后3年逐渐出现并进行性加重：压力性漏尿（咳嗽、打喷嚏、大笑、跑跳、提重物、下蹲起立等腹压增高时不自主漏尿，量少，可为滴沥，也可较多）、无尿急（此点重要，压力性尿失禁为无尿意即漏，与急迫性尿失禁鉴别：后者为尿急后忍不住而漏，见于膀胱过度活动症）、与活动相关（运动或变换体位、站立时加重，卧位时漏尿少）、漏尿致社交尴尬、需使用护垫、夜尿（多无，若合并膀胱过度活动症则为混合性尿失禁，临床常见）、对生活的影响（社交活动受限）。分型：单纯压力性（腹压增高时漏尿）或混合性（压力性与急迫性并存，常见，处理时应先治急迫症状）。诱因方面，近期咳嗽加重或提重物后症状加重。排尿情况正常，无排尿困难（需除外脱垂致尿道扭曲引起尿潴留）。既往需询问分娩史及产次、盆腔手术史、子宫切除史并评估。今日来我院妇科或泌尿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。妇科及泌尿检查：取膀胱截石位，行压力试验（嘱患者咳嗽或用力，观察尿道口有无漏尿，为确认压力性尿失禁的重要方法）、棉签试验（Q-tip试验，评估尿道活动度，活动度>30°支持诊断）、盆底肌力（收缩评估，多减弱）、盆腔器官脱垂（评估有无合并脱垂，如前后壁膨出或子宫脱垂，二者常合并）、阴道萎缩（绝经后可见）、残余尿（导尿或超声测定，正常<50ml，用以除外尿潴留）、神经检查（骶神经及会阴感觉，多正常，用以除外神经源性）。","辅助检查":"【必做】压力试验（为核心项目，床旁诱发漏尿即可确认）、残余尿测定（排除排尿困难及尿潴留）、尿常规（排除尿路感染，感染可致急迫性症状而造成混淆）；【评估】尿动力学检查，指征包括：复杂或混合性尿失禁（以急迫为主，疑膀胱过度活动、逼尿肌过度活动者需评估）、手术前（确认单纯压力性尿失禁，除外逼尿肌功能障碍，以预估术后效果）、既往手术失败者，并可用于压力性尿失禁分型及评估括约肌功能；排尿日记（记录漏尿频率、诱因、尿量，评估简单而重要）、盆底超声（评估膀胱颈活动度，必要时）、咳嗽漏尿点压测定（属尿动力学检查，用于评估括约肌功能）；【其他】血糖（糖尿病可致多尿及神经源性膀胱，需评估）。","初步诊断":"1. 压力性尿失禁（中度：轻度为咳嗽喷嚏时偶有漏尿，中度为运动跑跳时漏尿、需用护垫，重度为站立或体位变化即漏尿；本例为单纯性或混合性（伴急迫性），需评估盆底肌力及有无脱垂）\n（注：治疗遵循阶梯原则，即保守治疗至手术治疗，个体化选择：①保守治疗（轻中度者为首选）：盆底肌训练（Kegel训练为核心，需正确收缩，即缩肛、提肛动作，每日3组×10~15次，每次持续收缩5~10秒，坚持3~6个月，有效率50~70%，对轻中度者有效，甚为重要），加生物反馈或电刺激（盆底康复治疗，可增强疗效，需仪器辅助）；生活方式调整（减重，肥胖者尤为重要，减重5~10%即可改善；治慢性咳嗽、便秘，以减少腹压；避免提重物；戒烟，因吸烟可致慢性咳嗽；液体管理，适量饮水，不憋尿，定时排尿）；子宫托或阴道托（盆底支撑，可改善部分症状，属保守治疗）；绝经后可用局部雌激素（阴道软膏，改善尿道黏膜萎缩，作为辅助，短期使用）。②药物治疗（压力性尿失禁药物疗效有限：度洛西汀为SNRI，可改善症状，但有恶心等副作用，少用；α受体激动剂亦少用；药物主要用于急迫性尿失禁，如抗胆碱能药，合并急迫者应先治急迫症状，混合性尿失禁者尤应注意）。③手术（指征：中重度、影响生活，保守治疗3~6个月无效者）：中段尿道吊带（TVT或TVT-O，经闭孔，为金标准术式，微创，疗效好，长期有效率80~90%，首选）、耻骨后膀胱颈悬吊（Burch手术，经腹腔镜或开腹，用于吊带失败者）、尿道周围填充（注射治疗，适用于括约肌功能不全的轻度患者及老年人，微创，疗效有限，可重复注射）、人工尿道括约肌（用于重症、复杂病例，少用）。④术前准备：尿动力学检查（确认单纯压力性，除外急迫，甚为重要）、抗生素预防感染、合并盆腔器官脱垂者同时行盆底重建手术。⑤随访：保守治疗者3~6个月评估疗效，无效者考虑手术；术后随访排尿情况（吊带术后尿潴留或排尿困难，短期常见，观察后多自行缓解，持续存在者需处理）、急迫性症状（术后新发者部分需处理）、复发（需远期随访）、护垫使用情况（评估改善程度）。建议妇科或泌尿妇科就诊。轻中度者以Kegel训练加生活方式调整为主，中重度者行吊带手术，疗效个体化，需防复发，甚为重要。","处理方案":"【药物治疗】\n1. 盆底肌训练为一线基础治疗，药物仅作辅助。α1肾上腺素受体激动剂：盐酸米多君片2.5mg po tid，4周为1疗程，可连用2～3个疗程；用药期间每日监测血压，高血压、甲亢、青光眼患者禁用（国内说明书适应症为直立性低血压，用于尿失禁属超说明书用药，需知情同意）。\n2. 5-羟色胺-去甲肾上腺素再摄取抑制剂（SNRI）：度洛西汀肠溶胶囊20mg po bid起始，1周后加量至40mg bid，疗程8～12周；餐后服用以减轻恶心、口干等不良反应，停药需在1～2周内逐渐减量（国内属超说明书用药，需知情同意）。\n3. 绝经后女性：阴道局部雌激素制剂，如雌三醇软膏0.5g（含雌三醇1mg）阴道给药qn，连用2～3周后改每周1～2次维持，总疗程3个月；可改善尿道黏膜萎缩、增加尿道闭合压。乳腺癌病史、不明原因阴道出血者禁用；不推荐全身性雌激素治疗（可加重尿失禁）。\n\n【一般治疗及生活指导】\n1. 超重者减重至BMI＜25，目标减重5%～10%即可明显改善漏尿；戒烟，积极治疗慢性咳嗽、便秘等增加腹压的疾病。\n2. 坚持盆底肌训练（Kegel训练）：每日3组，每组收缩10～15次，每次收缩持续5～10秒后充分放松，至少坚持6个月；可至盆底康复门诊行生物反馈或电刺激辅助治疗。\n3. 饮食：适量饮水保证每日尿量，避免一次性大量饮水及咖啡、浓茶、酒精、辛辣食物等膀胱刺激物；增加膳食纤维摄入防治便秘，避免排便时屏气用力。\n4. 活动：避免提重物、久站、跳跃、深蹲等增加腹压的动作；不憋尿、避免用力排尿；必要时使用集尿垫防止外出窘迫，保持会阴部清洁干燥。\n\n【随诊要求】\n1. 保守治疗2～3个月门诊复诊，复查排尿日记、1小时尿垫试验并评估症状改善程度，据此调整治疗方案。\n2. 盆底肌训练及药物治疗3～6个月症状无明显改善或加重者，转诊盆底专科评估手术指征（如经闭孔/耻骨后中段尿道吊带术）。\n3. 用药期间出现血压升高（米多君）、恶心呕吐（度洛西汀）、阴道出血（雌激素）等不良反应时，及时复诊调整用药。\n4. 出现新发尿频、尿急、排尿痛或肉眼血尿，随时复诊，除外尿路感染等合并症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1109,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4b7217a274e28a9bdc36b7da3bb757e8e1bff19f513d0403cbc6b37a7349e671","pinyin":"yalixingniaoshijin","initials":"ylxnsj","setting":"out","caseName":"门诊病历977","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历977",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d3edef24a25f2669b0ea","key":"v1-c9ccc21dfe2a3058|templates-d3edef24a25f2669b0ea","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"生殖道瘘","category":"门诊病历模板","raw":{"name":"生殖道瘘","category":"门诊病历模板","case":{"case_name":"门诊病历978","templates":{"主诉":"阴道漏尿3周","现病史":"患者1周前无明显诱因出现生殖道瘘相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴道漏尿3周为主诉，长期尿液浸渍易继发感染，完善血常规检查排除泌尿系感染及贫血所致乏力；完善尿常规检查明确有无白细胞、亚硝酸盐及红细胞，评估尿路感染情况；完善便常规检查鉴别是否存在直肠阴道瘘所致的粪质污染；完善肝肾功能检查了解肝肾功能储备，为后续修补手术及用药提供依据；完善血糖检查排除糖尿病，因糖尿病是生殖道瘘愈合不良与术后复发的重要危险因素；完善血脂检查了解血脂水平，评估围手术期血管风险；完善电解质检查排除长期漏尿导致的电解质紊乱；患者长期漏尿、精神及体力消耗较大，完善心电图检查评估心脏基本情况，排除手术与麻醉禁忌；完善胸部X线片检查排除肺部感染及心肺合并症；完善腹部超声检查了解泌尿系与盆腔情况，排除肾积水、输尿管扩张及盆腔占位，协助判断瘘孔部位与上尿路受累程度。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 生殖道瘘\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗：首选第二、三代头孢菌素联合抗厌氧菌药物控制瘘口周围感染，头孢呋辛酯片0.25g bid口服×7天，联合甲硝唑片0.4g tid口服×7天（直肠阴道瘘或考虑合并厌氧菌感染者必用）。\n2. 泌尿系感染防治（膀胱阴道瘘）：左氧氟沙星片0.5g qd口服×7天，或头孢克肟胶囊0.1g bid口服×7天；用药前查尿常规，反复感染者行尿培养+药敏后调整方案。\n3. 绝经后患者促组织修复：戊酸雌二醇片1mg qd口服，连用2-4周（排除雌激素使用禁忌者），改善阴道黏膜血供、促进瘘口周围组织修复。\n4. 对症处理：布洛芬缓释胶囊0.3g bid口服，疼痛或局部炎症明显时临时使用。\n\n【一般治疗及生活指导】\n1. 保持外阴及会阴部清洁干燥：勤更换无菌护垫/尿垫，每日温水清洗外阴1-2次，避免尿液长期浸渍皮肤；可温水坐浴每日1-2次、每次15-20分钟，减轻局部炎症刺激。\n2. 膀胱阴道瘘近期形成者（产后、妇科或泌尿术后）可先试行保守治疗：持续留置导尿管并接闭式引流，保持膀胱持续排空4-6周，同时多饮水（每日2000ml以上）稀释尿液、减少对瘘口的刺激，部分小瘘口可自行愈合。\n3. 保持大便通畅，避免用力排便及久蹲：多食富含膳食纤维的食物（新鲜蔬菜、水果、粗粮），必要时口服乳果糖口服溶液15ml qd，防止干硬粪便反复摩擦损伤瘘口。\n4. 禁止性生活、盆浴、阴道冲洗及重体力劳动；加强营养，进食高蛋白、高维生素饮食，保证充分休息，提高组织愈合能力。\n\n【随诊要求】\n1. 保守治疗期间每2周门诊复诊1次，复查尿常规、评估漏尿/漏粪症状变化及瘘口愈合情况；留置导尿管者每2周更换导尿管，监测有无泌尿系感染。\n2. 停用药物或拔除导尿管后2周、4周各复诊1次，行阴道指检、探针检查及美蓝（亚甲蓝）试验评估瘘口闭合情况，必要时行膀胱镜或直肠镜检查明确瘘口位置与大小。\n3. 保守治疗3个月瘘口仍未愈合或症状无改善者，转诊妇科、泌尿外科或肛肠外科评估手术修补时机；行修补术者按医嘱于术后1个月、3个月、6个月定期随访复查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1110,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"adf8ebbd0603c7bbbf565fa0e84d910232bd60e1c15ed6bd65cf47e66bde3d6c","pinyin":"shengzhidaolou","initials":"szdl","setting":"out","caseName":"门诊病历978","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历978",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7ff979f0d93a5f1b4797","key":"v1-c9ccc21dfe2a3058|templates-7ff979f0d93a5f1b4797","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"外阴白斑","category":"门诊病历模板","raw":{"name":"外阴白斑","category":"门诊病历模板","case":{"case_name":"门诊病历979","templates":{"主诉":"外阴瘙痒伴皮肤变白5年","现病史":"患者因外阴白色病变（旧称外阴白斑，现分类为外阴色素减退性疾病：硬化性苔藓（最常见，自身免疫相关，绝经前后女性、任何年龄均可发病，儿童亦可受累）、外阴慢性单纯性苔藓（神经性皮炎，与搔抓有关）、扁平苔藓；萎缩性改变多由硬化性苔藓所致）于1年余前（渐进、慢性起病）出现以下表现：外阴瘙痒（顽固、剧烈，夜间加重，搔抓后加重）、灼痛、白色病变（外阴皮肤变白，呈象牙白色）、萎缩（皮肤变薄、皱缩）、硬化（呈羊皮纸样、皲裂）、小阴唇萎缩、粘连（晚期）、阴道口狭窄（致性交困难）、肛周受累（呈8字形，为硬化性苔藓的特征性分布）、皲裂、糜烂出血、排尿烧灼感、性交痛；儿童患者可表现为便秘、排尿痛，瘙痒易被误认为卫生问题。需与以下疾病鉴别：外阴白斑癌变（硬化性苔藓存在外阴癌风险，约3%~5%，长期未治者鳞癌风险升高，故随访及活检指征为不典型病变、久治不愈的溃疡或结节，甚为重要）、白化病或白癜风（无症状、无萎缩）、念珠菌感染、接触性皮炎或脂溢性皮炎、外阴上皮内病变（VIN，癌前病变）、扁平苔藓（糜烂型，可致阴道受累、粘连）；恶变警示：出现肿块、溃疡不愈、结节、出血时需活检，甚为重要；另需考虑绝经及自身免疫相关因素（甲状腺疾病或斑秃相关）。无外阴活检史。今日来我院妇科或皮肤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P80次/分，R18次/分，BP118/76mmHg。外阴：视诊可见白色病变（记录部位、分布、大小）、萎缩（小阴唇萎缩、粘连，阴道口狭窄）、硬化及皲裂、搔抓痕迹与皲裂、糜烂、溃疡（经久不愈者需警惕恶变）、结节、肿块（癌变警示）；肛周受累呈8字形分布，色素减退；触诊评估皮肤弹性及萎缩程度。阴道及宫颈：窥器检查有无扁平苔藓所致的糜烂、粘连。全身皮肤：检查硬化性苔藓是否累及躯干等其他部位，以及甲状腺、自身免疫相关表现。","辅助检查":"【必做】以临床检查为主。【确诊】外阴活检。指征：诊断不明、不典型病变、久治不愈（>4~6周正规治疗）、糜烂、溃疡、结节、硬结等可疑恶变（排除鳞癌，甚为重要）、萎缩明显、粘连需评估。活检由皮肤科行切除或钻孔活检，病理见角化过度、表皮萎缩、真皮透明化及淋巴细胞浸润即可确诊硬化性苔藓。阴道分泌物检查（涂片鉴别真菌感染）、血糖（糖尿病者易反复）、甲状腺功能及抗体（自身免疫相关）、过敏原（接触性）。","初步诊断":"1. 外阴白斑（外阴色素减退性疾病，分型：硬化性苔藓；需评估萎缩、粘连及恶性风险（外阴鳞癌），掌握活检指征）\n（注：治疗依诊断、症状控制、防癌变及随访而定：①硬化性苔藓：一线为强效糖皮质激素（外用氯倍他索0.05%软膏，每晚涂外阴，2~4周症状明显缓解后减量，改为每周1~3次长期维持，以防复发及萎缩进展，甚为重要）；疗效判断为瘙痒缓解，2~4周缓解后维持治疗；钙调神经磷酸酶抑制剂（他克莫司软膏）用于激素无效或不能长期使用激素者的替代，效果好；严重粘连、狭窄者行手术粘连松解及阴道口扩张；儿童予弱效激素短期控制；随访需长期定期行外阴检查，癌变监测甚为重要。②慢性单纯性苔藓：以搔抓、止痒为主（激素软膏短期外用，口服抗组胺药止痒），避免刺激（搔抓、化纤、洗涤剂），并按神经性皮炎处理。③扁平苔藓：激素外用，顽固或糜烂型者评估全身激素或免疫抑制剂（羟氯喹），阴道粘连者行扩张。④手术与恶变：鳞癌经活检确诊后按外阴癌行根治性切除（见外阴癌）；癌前病变（外阴上皮内病变）行切除或激光，以防癌变。⑤一般护理：温水清洗外阴（勿用热水、肥皂刺激），穿宽松棉质内裤，保湿（润肤霜或凡士林），避免刺激物，瘙痒时冷敷而非搔抓。⑥随访：定期随访（每3~6个月评估症状控制、病变变化及萎缩、粘连进展；6~12个月长期随访，癌变监测是关键，硬化性苔藓长期存在风险，需终身随访），不典型病变需活检排除癌变；激素长期使用安全性（是否加重萎缩？应以最小有效剂量维持）。妇科或皮肤科：强效激素一线，缓解后维持，癌变监测及活检指征甚为重要。","处理方案":"【药物治疗】\n1. 强效糖皮质激素类（一线首选）：0.05%丙酸氯倍他索软膏，每晚睡前外涂患处1次，连续4周后改为每周2次维持，总疗程8-12周；症状缓解后换用0.05%糠酸莫米松乳膏（中效）维持，疗程4-8周。注意强效激素连续使用不超过12周，避免皮肤萎缩、色素减退等不良反应。\n2. 钙调磷酸酶抑制剂（激素不耐受或需长期维持者）：0.1%他克莫司软膏，每日2次外涂患处，疗程8-12周；局部有烧灼感者可先以0.03%浓度起始。用药期间避免强光照射，注意局部刺激反应。\n3. 保湿润肤及角质软化剂：10%尿素软膏或维生素E乳膏，每日1-2次外涂，与激素类药物交替使用，缓解干燥、瘙痒，修复皮肤屏障。\n4. 抗组胺药（瘙痒剧烈影响睡眠者）：氯雷他定片10mg qn口服，疗程1-2周；或西替利嗪片10mg qn，疗程同前，以控制夜间瘙痒、改善睡眠。\n\n【一般治疗及生活指导】\n1. 保持外阴清洁干燥：每日用温水（37℃左右）轻柔清洗外阴1次，避免肥皂、沐浴露、消毒液等刺激性洗剂，忌热水烫洗及搔抓，浴后及时拭干。\n2. 衣着与卫生习惯：穿宽松透气棉质内裤并每日更换，忌化纤、紧身衣物；避免长期使用卫生护垫，经期勤换卫生巾；避免久坐，适当活动，控制体重。\n3. 饮食宜清淡，忌辛辣刺激、酒精、浓茶、咖啡等易诱发瘙痒之品；多食富含维生素A、维生素E及优质蛋白的食物（如新鲜蔬果、鱼、蛋、奶）；合并糖尿病者应严格控制血糖。\n4. 避免性交摩擦过度及局部滥用药物、民间偏方；本病有恶变潜能（恶变率约3%-5%），务必遵医嘱规范治疗与定期随访，出现皮损变化及时就诊。\n\n【随诊要求】\n1. 治疗开始后2-4周复诊1次，评估疗效及激素相关不良反应，调整用药方案。\n2. 症状缓解后每3-6个月门诊复查1次，长期患者每年至少行1次妇科检查。\n3. 若局部出现溃疡、糜烂、结节、疣状增生或皮损长期不愈、瘙痒加重，应立即复诊，必要时行外阴皮肤活检以排除恶变。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1111,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fd2dc88969875ed223203b87dd4e50f7aebcd2c9b9138a44e05137c11ceb36d2","pinyin":"waiyinbaiban","initials":"wybb","setting":"out","caseName":"门诊病历979","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历979",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8b7224e5da0782bf60d4","key":"v1-c9ccc21dfe2a3058|templates-8b7224e5da0782bf60d4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"外阴癌","category":"门诊病历模板","raw":{"name":"外阴癌","category":"门诊病历模板","case":{"case_name":"门诊病历980","templates":{"主诉":"反复外阴瘙痒、溃烂1周","现病史":"患者1周前无明显诱因出现外阴癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因反复外阴瘙痒、溃烂1周就诊，伴轻度乏力，完善血常规检查排除局部溃烂继发感染及恶性肿瘤消耗所致贫血；患者拟行手术治疗或放化疗，完善肝肾功能检查了解肝肾储备功能，为化疗药物选择及剂量调整提供依据；完善电解质检查排除慢性消耗及进食减少所致电解质紊乱；患者需行外阴病灶活检及手术治疗，完善凝血功能检查排除凝血机制障碍，避免活检及术中出血风险；完善肿瘤标志物检查了解肿瘤负荷，为疗效评价提供基线参考；查外阴及腹股沟超声检查了解病灶范围及区域淋巴结情况；完善盆腔MRI检查明确病灶大小、浸润深度及有无侵犯尿道、阴道、肛门等邻近结构，指导手术范围制定；完善盆腔及腹股沟CT检查了解淋巴结转移及远处转移情况；必要时完善PET-CT检查进一步明确全身转移范围；完善病理活检及免疫组化检查明确组织学类型与分子分型，指导后续个体化治疗；必要时完善基因检测为靶向及免疫治疗提供依据；骨髓穿刺仅在怀疑骨髓转移或血液系统受累时进行，以明确有无骨髓浸润。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 外阴癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染（门诊活检/术前准备）：头孢呋辛酯片0.25g bid×3天（用前确认无青霉素/头孢过敏史）；青霉素过敏者改用左氧氟沙星片0.5g qd×3天。\n2. 局部坐浴消毒：1:5000高锰酸钾溶液温水坐浴，每次15～20分钟，bid；活检术后48小时内暂缓坐浴以免出血，创面每日以碘伏棉签消毒后外涂莫匹罗星软膏，tid。\n3. 止痒对症（外阴瘙痒明显者）：氯雷他定片10mg qd×7天；瘙痒周围正常皮肤可短期外涂丁酸氢化可的松乳膏，qd，连续不超过1周（勿涂于可疑病灶本身以免掩盖病情）。\n4. 镇痛（活检后创面疼痛）：布洛芬缓释胶囊0.3g bid，餐后服，疼痛缓解即停。\n\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠，避免久坐、骑自行车、长距离行走等压迫摩擦外阴的活动；确诊及术前禁止性生活及阴道内任何操作。\n2. 饮食：高蛋白、高维生素、易消化饮食（鱼、蛋、瘦肉、新鲜蔬果），多饮水，保持大便通畅，忌辛辣刺激食物及烟酒。\n3. 局部护理：保持外阴清洁干燥，每日温水清洗外阴1次，穿宽松透气棉质内裤并每日更换；严禁搔抓、热水烫洗及使用刺激性洗液。\n4. 禁忌：停用一切成分不明的外阴药膏、洗液及民间偏方；避免自行长期使用含激素制剂掩盖病灶。\n\n【随诊要求】\n1. 尽快于妇科肿瘤专科行阴道镜检查+外阴病灶多点活检，明确病理类型与分期。\n2. 确诊后尽早住院行根治性治疗（外阴病灶扩大切除/外阴切除术，根据分期决定是否行腹股沟淋巴结清扫术）；术后依据病理分期及切缘情况决定辅助放化疗方案。\n3. 术后2年内每3个月复查1次（外阴视诊+腹股沟淋巴结触诊+必要时盆腔影像学），3～5年每6个月1次，5年后每年1次，长期随访。\n4. 期间出现外阴新生物、溃疡经久不愈、出血、疼痛加重、腹股沟肿块或下肢水肿，立即复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1112,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"275dc10d945facf2c42765837c7951c2c6b390a507ae2323cca0074e69f8b1de","pinyin":"waiyinai","initials":"wya","setting":"out","caseName":"门诊病历980","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历980",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5143d054d23e3f074a31","key":"v1-c9ccc21dfe2a3058|templates-5143d054d23e3f074a31","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴道癌","category":"门诊病历模板","raw":{"name":"阴道癌","category":"门诊病历模板","case":{"case_name":"门诊病历981","templates":{"主诉":"阴道不规则流血3月","现病史":"患者1周前无明显诱因出现阴道癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴道不规则流血3月为主诉，病程较长且伴轻度乏力，完善血常规检查排除长期失血性贫血及感染；患者阴道流血需与凝血机制异常鉴别，完善凝血功能检查排除凝血功能障碍所致出血，同时为活检及手术做准备；完善肝肾功能检查了解肝肾功能储备，为放化疗方案制定提供依据；完善电解质检查排除慢性消耗所致电解质紊乱；完善肿瘤标志物检查了解肿瘤负荷，为疗效评价提供基线；完善盆腔MRI检查明确阴道病灶部位、大小、浸润深度及与尿道、膀胱、直肠的关系，明确临床分期；完善CT检查了解盆腔淋巴结及远处转移情况；必要时完善PET-CT检查进一步明确全身转移范围；完善妇科超声检查初步了解病灶及盆腔情况；完善病理活检及免疫组化检查明确组织学类型，指导个体化治疗；必要时完善基因检测为靶向治疗提供线索；骨髓穿刺仅在怀疑骨髓转移时进行，以明确有无骨髓浸润。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 阴道癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 同步放化疗首选（局部晚期或复发转移）：顺铂注射液40mg/m²静脉滴注，每周1次，与盆腔放疗同步（放疗增敏），化疗前予水化、利尿及昂丹司琼8mg静脉注射预防呕吐，治疗期间监测血常规及肾功能。\n2. 全身化疗（复发转移/不耐受放疗）：紫杉醇注射液135-175mg/m²静脉滴注3小时+卡铂（AUC 5）静脉滴注，每3周1次为一疗程，共4-6疗程；用药前30分钟予地塞米松、苯海拉明及H2受体拮抗剂预处理预防过敏反应。\n3. 联合化疗备选：氟尿嘧啶注射液（5-FU）750-1000mg/m²持续静脉滴注96小时（第1-4天）+顺铂40mg/m²静脉滴注第1天，每4周1疗程，注意口腔黏膜炎及骨髓抑制监测。\n4. 对症支持：放疗后阴道黏膜干燥、萎缩、性交困难者，予结合雌激素软膏（倍美力软膏）阴道局部涂抹，每晚1次，连用2周后改为每周2次维持；合并感染时按分泌物培养及药敏结果选用抗生素。\n\n【一般治疗及生活指导】\n1. 休息与卫生：保证充分休息与睡眠，避免劳累及熬夜；保持外阴及会阴部清洁干燥，每日温水清洗，勤换宽松棉质内裤，避免使用刺激性洗液及长时间使用不透气卫生护垫。\n2. 饮食：进食高蛋白、高维生素、易消化均衡饮食（鱼、蛋、瘦肉、新鲜蔬果），放疗期间每日饮水2000ml以上以减轻放射性膀胱炎、直肠炎反应；忌辛辣、油腻、腌制及过烫食物。\n3. 活动与禁忌：适当散步等轻度活动，避免久坐、骑跨动作及剧烈运动，减少阴道及会阴区摩擦压迫；治疗期间及放疗结束后3个月内禁性生活，戒烟戒酒，保持大便通畅、避免用力排便。\n\n【随诊要求】\n1. 随访频率：治疗结束后第1-2年每3个月复查1次，第3-5年每6个月1次，5年后每年1次，需终身随访。\n2. 复查内容：妇科双合诊及三合诊、阴道脱落细胞学检查（液基细胞学/巴氏涂片）、盆腔MRI、胸部CT、肿瘤标志物（SCC-Ag、CEA），必要时行阴道镜检查及活检。\n3. 放疗后患者坚持阴道扩张器扩张或保持规律性生活，以预防阴道粘连及狭窄；出现阴道异常出血、异常排液、疼痛，或腰腿痛、下肢水肿、体重下降等，及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1113,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1bf381405e001ec3846979acf7702d9695d111ff5b0a985f4593e6ef3bc1f096","pinyin":"yindaoai","initials":"yda","setting":"out","caseName":"门诊病历981","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历981",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3a14348325ddc1ec1a96","key":"v1-c9ccc21dfe2a3058|templates-3a14348325ddc1ec1a96","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"子宫发育异常","category":"门诊病历模板","raw":{"name":"子宫发育异常","category":"门诊病历模板","case":{"case_name":"门诊病历982","templates":{"主诉":"月经量少、经期腹痛5年","现病史":"患者1周前无明显诱因出现子宫发育异常相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以月经量少、经期腹痛5年为主诉，需完善妇科超声检查了解子宫形态、宫腔结构及有无子宫畸形、积血与内膜情况，明确月经异常的解剖学原因；完善性激素六项检查评估卵巢储备与内分泌功能，了解月经量少是否源于内分泌轴异常；完善血HCG检查排除妊娠相关疾病所致的异常出血与腹痛；完善宫颈TCT及HPV检查排除宫颈病变，为后续可能的手术或宫腔操作做准备；完善白带常规检查排除阴道及宫颈感染，避免宫腔操作后上行感染；完善血常规检查排除贫血与感染；完善尿常规检查排除泌尿系感染，因部分子宫发育异常常合并泌尿系畸形；患者因月经异常需了解乳腺情况，完善乳腺超声检查评估乳腺组织，为激素类药物使用提供参考；必要时完善肿瘤标志物检查排除合并妇科恶性肿瘤。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、白带常规、宫颈TCT+HPV\n\n【影像学检查】\n妇科超声、乳腺超声\n\n【其他检查】\n性激素六项、血HCG、肿瘤标志物（必要时）","初步诊断":"1. 子宫发育异常\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 雌孕激素序贯疗法（人工周期，适用于幼稚子宫、子宫发育不良伴月经稀发/闭经者）：戊酸雌二醇片（补佳乐）1mg 口服 qd，于月经周期第5天起连服21天，后10天加用地屈孕酮片10mg 口服 bid（或黄体酮胶囊200mg 口服 qd），两药同时停药等待撤退性出血，于撤退性出血第5天开始下一周期，连用3～6个周期为一疗程，以促进子宫发育并建立规律月经。\n2. 促排卵治疗（适用于子宫发育异常合并排卵障碍、有生育要求者）：来曲唑片2.5mg 口服 qd，于月经第3～5天起连用5天（或枸橼酸氯米芬片50mg 口服 qd×5天），月经第10～12天起B超监测卵泡及子宫内膜厚度，指导受孕时机；用药期间如内膜偏薄（<7mm）可加用戊酸雌二醇片1mg qd改善内膜。\n3. 宫腔镜子宫纵隔切除术等术后预防感染及促进内膜修复：头孢呋辛酯片0.25g 口服 bid×5天（青霉素过敏者改用阿奇霉素片0.25g qd×5天），同时术后第1～3天起予戊酸雌二醇片2mg qd×21天、后10天加地屈孕酮片10mg bid，促进创面内膜上皮化、减少宫腔粘连。\n\n【一般治疗及生活指导】\n1. 均衡营养，保证优质蛋白及含铁食物摄入，适度运动（如慢跑、瑜伽、游泳），控制体重，避免久坐、过度节食及剧烈运动。\n2. 规律作息、避免熬夜及精神紧张，经期注意保暖、避免劳累，禁盆浴、禁经期性生活及游泳，勤换卫生巾保持外阴清洁干燥，预防感染。\n3. 合并原发性闭经、周期性腹痛但无月经来潮者（如宫颈闭锁、残角子宫积血），应及时告知医师评估手术干预时机，勿自行服用活血或止痛药物掩盖症状。\n4. 有生育要求者宜尽早行子宫输卵管造影、三维超声及必要时宫腔镜/腹腔镜评估，在专科指导下选择受孕方式；已妊娠者尽早产科建卡评估宫颈机能。\n\n【随诊要求】\n1. 雌孕激素序贯治疗期间每周期末复诊1次，每3～6个周期复查妇科B超评估子宫大小、内膜厚度及月经建立情况，动态调整方案。\n2. 促排卵周期中按医嘱B超监测卵泡发育及排卵，未妊娠者连续3个促排周期无效需复诊重新评估；妊娠后尽早产科建卡，评估宫颈机能，必要时行孕期宫颈环扎术，预防晚期流产及早产。\n3. 宫腔镜等手术后1个月复查宫腔镜或三维B超评估宫腔形态及有无粘连，术后3～6个月评估后可计划妊娠。\n4. 平时每6～12个月复查妇科B超动态观察子宫形态；出现腹痛、异常阴道流血或排液、闭经加重等异常及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1114,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0369efa87375ff0d4fb68e1eb24607098b10780c474eb2b51c7a24d0c3f0eb65","pinyin":"zigongfayuyichang","initials":"zgfyyc","setting":"out","caseName":"门诊病历982","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历982",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a47e8d0eafaee89ec7e8","key":"v1-c9ccc21dfe2a3058|templates-a47e8d0eafaee89ec7e8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"处女膜闭锁","category":"门诊病历模板","raw":{"name":"处女膜闭锁","category":"门诊病历模板","case":{"case_name":"门诊病历983","templates":{"主诉":"周期性下腹痛3月，加重1周","现病史":"患者1周前无明显诱因出现处女膜闭锁相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以周期性下腹痛3月、加重1周为主诉，考虑经血流出受阻、宫腔及阴道积血，完善妇科超声检查明确子宫及阴道内积血的部位与程度，了解有无宫腔积血及输卵管积血，协助明确诊断；完善腹部超声检查了解盆腔及泌尿系统情况，排除合并肾积水及泌尿系畸形；患者需行处女膜切开引流手术，完善血常规检查排除感染与贫血；完善尿常规检查排除泌尿系感染，因积血压迫尿道易致排尿不畅与感染；完善便常规检查排除消化道疾病，并了解排便情况；完善肝肾功能检查了解肝肾储备，为麻醉与手术用药提供依据；完善血糖检查排除糖尿病，评估切口愈合风险；完善血脂检查了解血脂水平，评估围手术期血管风险；完善电解质检查排除因反复腹痛、进食减少所致的电解质紊乱；完善心电图检查评估心脏基本情况；完善胸部X线片检查排除肺部感染及心肺合并症，评估手术耐受性。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 处女膜闭锁\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 镇痛：布洛芬缓释胶囊0.3g，口服，每日2次，经期腹痛明显时服用，连用不超过3天。\n2. 预防感染：头孢呋辛酯片0.25g，口服，每日2次，连用3~5天；青霉素过敏者改服阿奇霉素片0.5g，每日1次，连用3天。\n3. 合并感染（阴道积脓、发热、血象升高）：甲硝唑片0.4g，口服，每日3次，联合头孢呋辛酯片0.25g每日2次，连用7天。\n\n【一般治疗及生活指导】\n1. 确诊后建议尽早安排处女膜切开引流术，术前避免剧烈运动及腹部按压，防止经血逆流入盆腔。\n2. 注意外阴清洁卫生：每日温水清洗外阴，勤换内裤，保持局部干燥；术后1个月内禁止盆浴、游泳及阴道冲洗，可淋浴。\n3. 术后1个月内禁止性生活及阴道内操作；适当休息，避免重体力劳动及剧烈运动。\n4. 饮食清淡、易消化，多饮水，多食新鲜蔬菜水果以保持大便通畅，避免辛辣刺激食物及用力排便。\n\n【随诊要求】\n1. 术后1周门诊复查，观察切口愈合及积血引流情况。\n2. 术后1个月复查，评估月经是否规律来潮、经血排出是否通畅。\n3. 术后首次月经来潮后1~2周复查妇科B超，了解宫腔及阴道内积血是否排净、有无宫腔粘连。\n4. 若出现发热、腹痛加剧、阴道异常流血增多等情况随时就诊；此后每3~6个月随访月经情况至少半年。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1115,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cfd775aca05163c74a25e28c08e4e1a3e88f6462b1639a9dce73159b2c165f1f","pinyin":"chunvmobisuo","initials":"cnmbs","setting":"out","caseName":"门诊病历983","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历983",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a561f5159ac6328de751","key":"v1-c9ccc21dfe2a3058|templates-a561f5159ac6328de751","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴道闭锁","category":"门诊病历模板","raw":{"name":"阴道闭锁","category":"门诊病历模板","case":{"case_name":"门诊病历984","templates":{"主诉":"周期性下腹痛3月","现病史":"患者1周前无明显诱因出现阴道闭锁相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以周期性下腹痛3月为主诉，考虑经血流出道梗阻、宫腔及阴道积血，完善妇科超声检查明确闭锁平面、积血部位与程度，了解有无宫腔积血及子宫内膜情况，协助明确诊断并指导手术方式选择；完善腹部超声检查了解盆腔及泌尿系统情况，排除肾积水及泌尿系畸形；患者需行阴道成形或切开引流手术，完善血常规检查排除感染与贫血；完善尿常规检查排除泌尿系感染；完善便常规检查排除消化道疾病并了解排便情况；完善肝肾功能检查了解肝肾功能储备，为麻醉及围手术期用药提供依据；完善血糖检查排除糖尿病，评估术后切口愈合风险；完善血脂检查了解血脂水平，评估围手术期血管风险；完善电解质检查排除因腹痛、进食减少所致电解质紊乱；完善心电图检查评估心脏基本情况，排除手术禁忌；完善胸部X线片检查排除肺部感染及心肺合并症。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 阴道闭锁\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防术后感染（阴道成形术后常规）：头孢呋辛酯片 0.25g bid，口服，连用5～7天；同时联合甲硝唑片 0.4g bid，口服，连用5～7天，覆盖厌氧菌。青霉素或头孢过敏者改用左氧氟沙星片 0.5g qd，口服，连用5天。\n2. 术后镇痛：布洛芬缓释胶囊 0.3g bid，口服，术后疼痛明显时服用，连用3～5天；疼痛剧烈者可短期加用对乙酰氨基酚片 0.5g prn，间隔不少于6小时。\n3. 促进新建阴道创面上皮化：结合雌激素软膏（如倍美力软膏）适量外涂于阴道创面及模具表面，qd，睡前使用，持续2～4周，以促进创面上皮生长。\n4. 预防便秘、减少腹压：乳果糖口服溶液 15ml qd，口服，术后即开始，保持大便通畅，避免用力排便牵拉重建阴道。\n【一般治疗及生活指导】\n1. 术后卧床休息1～2天，留置导尿管期间注意会阴部清洁，勤换护理垫；拔管后鼓励下床适量活动，但避免久坐、深蹲、骑跨及剧烈运动，至少持续6～8周。\n2. 饮食：术后第1天进流质，逐步过渡至半流质、普通饮食；多饮水，多食富含膳食纤维的蔬菜水果，忌辛辣、油腻及刺激性食物，保持大便通畅。\n3. 术后严格遵医嘱佩戴阴道模具（扩张器），每日更换并清洗，坚持规律扩张或佩戴，术后3～6个月不得中断，防止再造阴道挛缩狭窄；模具松紧或不适时及时复诊调整。\n4. 保持会阴清洁干燥，观察阴道分泌物性状，若出现发热、腹痛、异常分泌物、排尿困难或阴道流血量多，应立即就医；术后6～8周内禁止性生活及盆浴。\n【随诊要求】\n1. 术后2周门诊复查切口愈合情况，1个月、3个月、6个月定期复查，评估新建阴道长度、宽度及上皮化程度，指导模具佩戴及扩张频率。\n2. 如为阴道下段闭锁伴积血者，术后密切随访月经情况，注意经血排出是否通畅；出现周期性下腹痛、经血潴留或闭经应及时就诊。\n3. 有生育需求者，术后评估子宫、宫颈发育及输卵管情况，必要时转生殖医学中心进一步评估助孕方案；长期随访监测是否合并子宫内膜异位症等经血逆流相关并发症。\n4. 每3～6个月行妇科检查及阴道镜检查，动态监测阴道通畅性与上皮状态，出现狭窄趋向及早行扩张或再次手术干预。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1116,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bb6e058b8522de97e833e29d1bbc1f2b545a30fab77a98c52c8ff2bb8bab678d","pinyin":"yindaobisuo","initials":"ydbs","setting":"out","caseName":"门诊病历984","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历984",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-820c55b8ef78e6607838","key":"v1-c9ccc21dfe2a3058|templates-820c55b8ef78e6607838","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"新生儿窒息","category":"门诊病历模板","raw":{"name":"新生儿窒息","category":"门诊病历模板","case":{"case_name":"门诊病历985","templates":{"主诉":"出生时无呼吸、心率慢、肌张力低","现病史":"新生儿存在围产期高危因素：产前因素（母亲妊娠高血压、子痫、糖尿病、胎盘功能不全（IUGR，即生长受限）、过期妊娠、感染）、产时因素（脐带脱垂、绕颈、受压，胎盘早剥、前置，胎位异常如臀位，产程延长或急产，胎心异常（晚期减速或变异减速，为缺氧征象），羊水粪染，早产）、胎龄（早产或足月）。于出生时评估：出生窒息表现（呼吸：无呼吸，可为原发性呼吸暂停或继发性呼吸暂停，后者呈喘息样呼吸，属濒死状态；心率：<100次/分（正常>100次/分，心率为复苏决策的核心）；肌张力：低、松弛；反应：刺激后反应差或无反应；肤色：苍白或发绀；Apgar评分：1分钟4分、5分钟6分、10分钟8分（0~3分为重度窒息，4~7分为轻度窒息，8~10分为正常，分别于生后1分钟、5分钟、10分钟评估，以判断出生窒息程度）；脐动脉血气：pH 7.10（pH<7.0提示代谢性酸中毒，为缺氧证据）；复苏过程：记录是否复苏及正压通气、胸外按压、气管插管、药物等复苏过程；并发症：缺氧缺血性脑病（HIE，见专项，可表现为惊厥、意识障碍）、胎粪吸入（羊水粪染，需清理气道）、多器官损伤（心肌缺血、心衰；肾损伤、少尿；肺出血；DIC；低血糖，需重视，缺氧应激可致糖消耗增加）、呼吸窘迫（持续性新生儿呼吸窘迫综合征或肺炎））。母亲高危因素、胎心监测、羊水粪染及复苏史已如上述。今日来我院新生儿科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"患儿系第2胎第1产，足月顺产，出生体重3.2kg，生后有窒息复苏抢救史。母乳喂养，暂未添加辅食，预防接种按国家计划进行。生长发育与同龄儿相仿。","体格检查":"T36.8℃，P140次/分（复苏中持续监测心率，需>100次/分），R45次/分，BP65/40mmHg，SpO2 92%。复苏中观察：呼吸（正压通气时胸廓起伏情况）、心率（听诊或监护，亦可触脐带搏动，为复苏核心评估指标）、肤色（是否转红润）、肌张力及反应（恢复情况评估）、Apgar评分（记录）。复苏后观察：意识、反应及肌张力（评估HIE，可行Sarnat分级）、囟门张力（判断脑水肿）、瞳孔、有无惊厥（密切观察）、呼吸（节律、有无窘迫或呼吸暂停）、心肺（心音，判断心衰；肺部啰音，提示吸入）、腹部肝脾、脐带血管（插管情况）、体温（易低，保暖为核心，复苏中保暖甚为重要）、血糖（监测低血糖）、肤色（有无黄疸）。","辅助检查":"【必做】血气分析（脐动脉或生后采血，测pH，pH<7.0提示酸中毒，可判断窒息严重度）、血常规、血糖（低血糖在窒息后常见，需重视并监测）、电解质（钠、钙）、肝肾功能（评估多器官受累）、心肌肌钙蛋白或心肌酶（评估心肌缺血）、凝血功能（评估DIC）、乳酸、血培养（除外并存感染）；【影像】胸片（胎粪吸入可见斑片影及肺气肿，并用于诊断肺炎、肺透明膜病）、头颅超声（床旁检查，早期发现脑水肿或出血）、头颅MRI（用于HIE，宜于生后3~7天检查，可判断缺氧损伤模式，如分水岭或基底节损伤，对预后评估甚为重要）、振幅整合脑电图（aEEG，监测脑功能及惊厥，评估背景活动，对HIE评估甚为重要）；【其他】多器官超声（肾或心脏）、听力检查、眼底检查。","初步诊断":"1. 新生儿窒息（Apgar评分（1分钟、5分钟、10分钟）4分、6分、8分，脐动脉血气pH 7.10，为轻度窒息，复苏过程（正压通气、胸外按压、气管插管、药物），并发症（HIE、胎粪吸入、多器官损伤、低血糖）需评估）\n（注：治疗以复苏为核心，遵循黄金一分钟原则，分秒必争，按产房新生儿复苏方案（NRP）的ABC步骤进行：①快速评估（出生时问三问：足月吗？羊水清吗？有呼吸或哭声吗？肌张力好吗？据此决定复苏路径）、保暖（置辐射保暖台，擦干，给予刺激）、气道管理（清理口鼻；对羊水粪染且无活力（肌张力低或呼吸弱）者行气管插管吸引胎粪，甚为重要）、正压通气（无呼吸或喘息，或心率<100次/分者给正压通气，可用气囊面罩或T组合复苏器，30秒后评估心率）、胸外按压（正压通气30秒后心率<60次/分者行胸外按压，采用拇指法，频率90次/分，按压与通气比3:1，需双人配合）、药物（胸外按压后心率仍<60次/分者给肾上腺素0.1~0.3ml/kg（1:10000，即0.01~0.03mg/kg），经静脉或气管推注，可每3~5分钟重复，并行扩容（低血容量者给生理盐水10ml/kg，纠正休克））、评估循环（每30秒评估心率，据此决策与调整复苏，为核心环节）。②复苏后处理：稳定后转入新生儿监护室（维持体温甚为重要）、通气支持（呼吸窘迫者给氧疗、持续气道正压通气或机械通气）、循环支持（心衰者给正性肌力药如多巴胺，纠正低血压）、血糖（监测并纠正低血糖，输注葡萄糖，防止脑损伤，甚为重要）、脑保护（评估HIE，中重度者行亚低温治疗，于生后6小时内开始，维持33.5~34.5℃共72小时，可改善神经预后，甚为重要，参见HIE处理；惊厥者用苯巴比妥；并监测电解质）、多器官支持（肾：监测尿量；胃肠：延迟喂养，防坏死性小肠结肠炎；凝血功能）。③并发症处理：胎粪吸入综合征（清理气道加呼吸支持，必要时用肺表面活性物质）、HIE、低血糖、缺氧性心肌、肾、肝损伤，均需监测并处理。④随访：神经发育（窒息及HIE为高危儿，需随访至学龄期，评估脑瘫、认知功能，早期干预甚为重要）、听力与视力、多器官功能恢复、母乳喂养支持。建议产科与新生儿科协作，复苏团队应把握黄金一分钟，按ABC评估，重视循环评估及HIE，中重度者行亚低温治疗，并坚持随访，甚为重要。","处理方案":"【药物治疗】\n1. 维生素K1注射液1mg，肌内注射，每日1次，连用3天：窒息缺氧可致凝血因子合成障碍，预防新生儿出血症。\n2. 10%葡萄糖注射液5ml/kg，静脉缓慢推注（速度1～2ml/min），并根据血糖监测结果（目标血糖≥2.2mmol/L）调整用量及次数：纠正窒息后继发低血糖。\n3. 苯巴比妥钠注射液：若出现惊厥，予负荷量20mg/kg静脉滴注（速度≤1mg/kg/min），12小时后按维持量3～5mg/kg/d分1～2次静脉给药，疗程至惊厥控制后渐减量，用药期间监测呼吸与意识状态。\n4. 纳洛酮注射液0.1mg/kg静脉推注，可间隔2～3分钟重复：仅用于母亲分娩前4小时内使用阿片类药物且新生儿存在明显呼吸抑制者，用药后密切观察呼吸恢复情况。\n\n【一般治疗及生活指导】\n1. 保暖：置于中性温度环境，维持肛温36.5～37.5℃，避免寒冷刺激加重缺氧及代谢性酸中毒，同时避免过度捂热。\n2. 体位与呼吸道管理：保持头偏向一侧、侧卧位，及时清除口鼻分泌物，防止呕吐误吸；密切观察呼吸频率、节律及面色、肤色、反应变化。\n3. 喂养：惊厥停止且生命体征平稳后开始喂养，首选母乳，评估吸吮-吞咽-呼吸协调性，少量多次、缓慢喂养，防止呛奶窒息；喂养后竖抱拍嗝并取右侧卧位。\n4. 禁忌：避免剧烈摇晃、频繁搬动及捂热发汗；母亲及照护者禁烟（含二手烟暴露）；未经医师指导不得自行使用任何药物（含中药、退热药及民间偏方）。\n\n【随诊要求】\n1. 就诊后第3天、第7天复诊，评估呼吸、喂养、黄疸及神经系统表现；此后按儿保计划于生后1月、2月、4月、6月定期随访。\n2. 生后1月内完成新生儿神经行为测定（NBNA）、听力筛查及眼底检查，评估窒息后脑损伤及视网膜病变风险。\n3. 每次复诊监测体重、身长、头围及神经发育里程碑；若出现拒奶、嗜睡、反应差、抽搐、呼吸暂停、发绀或惊厥，须立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":1117,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6ffa16f55f82c354a166534aeca8c7a1320c3140accc7be4ba01105028d269f9","pinyin":"xinshengerzhixi","initials":"xsezx","setting":"out","caseName":"门诊病历985","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历985",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);